// ============ Robot avatar helper ============
// Centralised resolver — every place that builds a /static/robots/...
// URL goes through this so PNG-vs-SVG dispatch is consistent.
//
// Mapping mirrors robots.json on the server. When a new icon is added
// in PNG format, append its role id here. Other ids fall back to .svg.
// (.svg fallbacks are kept for: designer, pm, tester, data — no PNG
// generated yet.)
var _ROBOT_PNG_IDS = new Set([
  'ceo','cto','coder','reviewer','researcher','architect','devops',
  'general','marketing','media','meeting','specialist','product_architect',
  'pm','designer','tester','data','tech_expert',
]);

// Accepts: 'robot_general' / 'general' / 'robot_general.png' / undefined.
// Returns: '/static/robots/robot_<id>.<ext>'.
function _robotIconUrl(ref) {
  if (!ref) return '/static/robots/robot_general.png';
  // Already a complete filename with extension — pass through.
  if (/\.(png|svg|webp|jpg|jpeg)$/i.test(ref)) {
    return '/static/robots/' + ref;
  }
  // Strip "robot_" prefix to extract the role id.
  var role = String(ref).replace(/^robot_/, '');
  var ext = _ROBOT_PNG_IDS.has(role) ? 'png' : 'svg';
  return '/static/robots/robot_' + role + '.' + ext;
}

// ============ State ============
let agents = [], nodes = [], messages = [], approvals = [], auditLog = [], tokens = [], providers = [], projects = [];
let currentView = 'dashboard';
let currentAgent = null;
// Mirror to window so console diagnostics + cross-script handlers can
// read the currently-open agent id without relying on module scope.
Object.defineProperty(window, 'currentAgent', {
  configurable: true,
  enumerable: true,
  get: function() { return currentAgent; },
  set: function(v) { currentAgent = v; },
});
let currentProject = null;
let _renderEpoch = 0; // Guard: incremented on every view change to prevent async overwrites
// Admin context
let _adminCtx = { user_id: '', username: '', role: '', display_name: '', agent_ids: [], is_super: false };
let _settingsSubTab = 'providers'; // Current sub-tab inside Settings view
let _agentsSubTab = null; // Current node tab inside Agents view (null = first node)

// ============ Branding (site name + logo) ============
// Single TudouClaw deployment = one company; admin can override the
// header in Settings → 品牌. Fetched once on portal boot; cached on
// window._branding so the next tab switch doesn't refetch.

window._branding = window._branding || {site_name: 'Tudou Claws', site_subtitle: 'Admin Console', logo_url: ''};

async function _loadBranding() {
  try {
    var r = await fetch('/api/portal/branding', {credentials: 'include'});
    if (!r.ok) return;
    var d = await r.json();
    window._branding = d || window._branding;
    _applyBranding();
  } catch (e) { /* fall back to defaults */ }
}

function _applyBranding() {
  var b = window._branding || {};
  var nameEl = document.getElementById('brand-site-name');
  var subEl = document.getElementById('node-info');
  var logoImg = document.getElementById('brand-logo-img');
  var logoFallback = document.getElementById('brand-logo-fallback');
  if (nameEl) nameEl.textContent = b.site_name || 'Tudou Claws';
  if (subEl && b.site_subtitle) subEl.textContent = b.site_subtitle;
  if (logoImg && logoFallback) {
    if (b.logo_url) {
      logoImg.src = b.logo_url;
      logoImg.style.display = 'block';
      logoFallback.style.display = 'none';
    } else {
      logoImg.style.display = 'none';
      logoFallback.style.display = '';
    }
  }
  // Page title too
  if (b.site_name && document.title) {
    document.title = b.site_name + ' Portal';
  }
}

// Run early — fire-and-forget; the header has sensible defaults so
// even if this fails the page is usable.
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', _loadBranding);
} else {
  _loadBranding();
}

// ─── Desktop floater integration (Phase A1+A2, 2026-05-02) ───
//
// The Mac floater app exposes a tiny HTTP server on 127.0.0.1:9192
// for everyday signalling, and a `tudouclaw://` URL scheme for
// cold-launching when the app isn't running yet.
//
//   page load
//   ├─ check /agents/desktop has at least one enabled agent (else no-op)
//   ├─ probe http://127.0.0.1:9192/health (timeout 800ms)
//   │     ├─ alive  → POST /show (no jarring scheme dialog)
//   │     └─ dead   → click hidden <a href="tudouclaw://open"> (URL scheme)
//   └─ start 10 s heartbeat → POST /heartbeat (silent if app down)
//
// Floater watchdog hides itself after 30 s without a heartbeat — that's
// our "browser closed the portal" signal, and survives crashes / SIGKILL.
// `/show` is gated by sessionStorage so internal page navigation doesn't
// re-pop a hidden window the user just dismissed.
const _FLOATER_BASE = 'http://127.0.0.1:9192';
const _FLOATER_HEARTBEAT_MS = 10000;
let _floaterHeartbeatTimer = null;

function _floaterFire(method, path) {
  // mode:'no-cors' → fire-and-forget; we don't read the response, and
  // the Tauri server replies with permissive CORS anyway. The catch
  // swallows network errors when the app isn't up.
  return fetch(_FLOATER_BASE + path, { method, mode: 'no-cors' }).catch(() => {});
}

async function _floaterIsAlive() {
  try {
    const ctrl = new AbortController();
    const t = setTimeout(() => ctrl.abort(), 800);
    const r = await fetch(_FLOATER_BASE + '/health', { signal: ctrl.signal });
    clearTimeout(t);
    return r.ok;
  } catch (_) { return false; }
}

function _startFloaterHeartbeat() {
  // 2026-05-11: floater feature is currently disabled in the UI
  // (see _maybeActivateDesktopFloater note). No heartbeat needed.
  // Re-enable when the floater ships by removing this guard.
  return;
}

async function _maybeActivateDesktopFloater() {
  // Desktop Floater feature is currently DISABLED in the UI per the
  // 2026-05-05 product call. The HTTP/heartbeat plumbing above stays
  // intact so re-enabling later is just a matter of removing this
  // early return + un-hiding the agent-edit modal section in
  // app/templates/portal.html (search "Desktop Floater feature is
  // hidden").
  return;
  /* eslint-disable */
  try {
    const res = await fetch('/api/portal/agents/desktop');
    if (!res.ok) return;
    const data = await res.json();
    if (!data.agents || data.agents.length === 0) return;

    const alive = await _floaterIsAlive();
    if (!sessionStorage.getItem('tudouFloaterActivated')) {
      sessionStorage.setItem('tudouFloaterActivated', '1');
      if (alive) {
        await _floaterFire('POST', '/show');
      } else {
        const a = document.createElement('a');
        a.href = 'tudouclaw://open';
        a.style.display = 'none';
        document.body.appendChild(a);
        a.click();
        a.remove();
      }
    }
    _startFloaterHeartbeat();
  } catch (_) {}
  /* eslint-enable */
}
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', _maybeActivateDesktopFloater);
} else {
  _maybeActivateDesktopFloater();
}

// ============ _ui — UI component helpers (Plan A polish, 2026-05-02) ============
// Centralized HTML builders so we stop hand-writing inline style blocks
// for chips, badges, buttons, icons, and section headers. Read tokens
// from portal.html's design system (--chip-*, --ui-shadow-*, etc).
//
// Usage:
//   _ui.chip('Completed', 'success')      → small status chip
//   _ui.icon('check_circle')            → Material Symbols span
//   _ui.iconChip('star', '已标记', 'success')  → icon + label chip
//   _ui.sectionHeader('Canvas Workflow', {icon:'view_kanban', count:3, action:'<button...>'})
//   _ui.emptyState({icon:'inbox', title:'暂无工作流', hint:'...', cta:'<button...>'})
//
// Existing inline-style code keeps working — these are additive.
window._ui = (function() {
  function _esc(s) {
    if (s === null || s === undefined) return '';
    return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  }

  // Material Symbols icon. size/baseline override CSS variation settings.
  function icon(name, opts) {
    opts = opts || {};
    var size = opts.size || 16;
    var color = opts.color ? 'color:' + opts.color + ';' : '';
    var va = opts.va || 'middle';   // vertical-align
    return '<span class="material-symbols-outlined" style="font-size:' + size + 'px;'
      + 'vertical-align:' + va + ';' + color + '">' + _esc(name) + '</span>';
  }

  // Status chip — short label with semantic color. Kind ∈
  // {success, warning, error, info, neutral}. Defaults to neutral.
  function chip(text, kind) {
    var k = kind || 'neutral';
    return '<span style="display:inline-flex;align-items:center;gap:3px;'
      + 'padding:1px 8px;font-size:10px;border-radius:10px;font-weight:600;'
      + 'background:var(--chip-' + k + '-bg);color:var(--chip-' + k + '-fg)">'
      + _esc(text) + '</span>';
  }

  // Icon + label chip — one block, semantic color.
  function iconChip(iconName, text, kind) {
    var k = kind || 'neutral';
    return '<span style="display:inline-flex;align-items:center;gap:4px;'
      + 'padding:2px 9px;font-size:11px;border-radius:11px;font-weight:600;'
      + 'background:var(--chip-' + k + '-bg);color:var(--chip-' + k + '-fg)">'
      + icon(iconName, {size: 13, va: '-2px'}) + _esc(text) + '</span>';
  }

  // Pill button — softer than primary, used for "tap to do something
  // contextual" actions (e.g. "▶ 运行" / "📦 交付件 N").
  function pillButton(opts) {
    opts = opts || {};
    var k = opts.kind || 'info';
    var click = opts.onclick ? ' onclick="' + opts.onclick + '"' : '';
    var title = opts.title ? ' title="' + _esc(opts.title) + '"' : '';
    var iconHtml = opts.icon ? icon(opts.icon, {size: 14, va: '-3px'}) + ' ' : '';
    return '<button' + click + title + ' style="display:inline-flex;align-items:center;gap:4px;'
      + 'padding:4px 12px;font-size:11px;border-radius:11px;font-weight:600;cursor:pointer;'
      + 'background:var(--chip-' + k + '-bg);color:var(--chip-' + k + '-fg);border:none">'
      + iconHtml + _esc(opts.text || '') + '</button>';
  }

  // Section header for a panel: icon + title + optional count + optional
  // right-side action HTML. Replaces hand-written 18-line headers.
  function sectionHeader(title, opts) {
    opts = opts || {};
    var iconHtml = opts.icon
      ? icon(opts.icon, {size: 18, va: '-3px', color: 'var(--primary)'}) + ' '
      : '';
    var countHtml = (opts.count !== undefined && opts.count !== null)
      ? '<span style="font-size:11px;color:var(--text3);margin-left:8px">' + _esc(opts.count) + '</span>'
      : '';
    var rightHtml = opts.action || '';
    return '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:14px;padding:0 4px">'
      + '<div style="display:flex;align-items:baseline;gap:6px">'
      +   '<div style="font-size:14px;font-weight:700">' + iconHtml + _esc(title) + '</div>'
      +   countHtml
      + '</div>'
      + rightHtml
      + '</div>';
  }

  // Friendly empty-state block with optional CTA. Replaces "无 X" gray text.
  function emptyState(opts) {
    opts = opts || {};
    var iconHtml = opts.icon
      ? icon(opts.icon, {size: 48, color: 'var(--text3)', va: 'middle'})
      : '<div style="font-size:42px;opacity:0.5">' + _esc(opts.emoji || '📭') + '</div>';
    return '<div style="padding:48px 30px;text-align:center;background:var(--surface);'
      + 'border:1px dashed var(--border);border-radius:12px">'
      + '<div style="margin-bottom:10px">' + iconHtml + '</div>'
      + '<div style="font-size:14px;color:var(--text2);font-weight:600;margin-bottom:6px">'
      +   _esc(opts.title || 'No data') + '</div>'
      + (opts.hint ? '<div style="font-size:12px;color:var(--text3);line-height:1.5;'
        + 'margin-bottom:14px;max-width:360px;margin-left:auto;margin-right:auto">'
        + _esc(opts.hint) + '</div>' : '')
      + (opts.cta || '')
      + '</div>';
  }

  return {
    icon: icon,
    chip: chip,
    iconChip: iconChip,
    pillButton: pillButton,
    sectionHeader: sectionHeader,
    emptyState: emptyState,
    _esc: _esc,
  };
})();

// ============ Toast / Confirm / Prompt — zero native popups ============
(function() {
  // ── Toast notifications (stacking, right-aligned) ──
  var _toastId = 0;
  var ICONS = {success:'check_circle', error:'error', warning:'warning', info:'info'};

  window._toast = function(msg, type) {
    if (!type) {
      // Auto-detect type from content
      if (/失败|错误|error|fail|invalid|出错/i.test(msg)) type = 'error';
      else if (/成功|已|完成|saved|success|✓|✅/i.test(msg)) type = 'success';
      else if (/警告|warn|注意/i.test(msg)) type = 'warning';
      else type = 'info';
    }
    // Defensive: unknown type names (legacy bug — callers passing 'ok' /
    // 'err' got white-on-white because CSS only had .toast-success /
    // .toast-error / .toast-warning / .toast-info). Map common aliases
    // and fall back to 'info' so a future typo never goes invisible.
    var _ALIAS = {ok: 'success', err: 'error', fail: 'error', warn: 'warning'};
    if (_ALIAS[type]) type = _ALIAS[type];
    if (['success','error','warning','info'].indexOf(type) === -1) type = 'info';
    var container = document.getElementById('toast-container');
    if (!container) {
      container = document.createElement('div');
      container.id = 'toast-container';
      document.body.appendChild(container);
    }
    var id = 'toast-' + (++_toastId);
    var el = document.createElement('div');
    el.id = id;
    el.className = 'toast toast-' + type;
    el.innerHTML =
      '<span class="material-symbols-outlined toast-icon">' + (ICONS[type]||'info') + '</span>' +
      '<span class="toast-msg">' + String(msg).replace(/</g,'&lt;').replace(/>/g,'&gt;') + '</span>' +
      '<span class="toast-close" onclick="this.parentNode.classList.add(\'removing\');setTimeout(function(){document.getElementById(\''+id+'\')&&document.getElementById(\''+id+'\').remove()},300)">&times;</span>';
    container.appendChild(el);
    // Auto-dismiss after 4s
    setTimeout(function(){
      if (document.getElementById(id)) {
        el.classList.add('removing');
        setTimeout(function(){ el.remove(); }, 300);
      }
    }, 4000);
    // Keep max 5 toasts visible
    while (container.children.length > 5) container.removeChild(container.firstChild);
  };

  // Override native alert
  window.alert = function(msg) { window._toast(String(msg)); };

  // ── Inline confirm (replaces native confirm()) ──
  window._confirm = function(message, onYes, onNo) {
    var overlay = document.createElement('div');
    overlay.className = 'confirm-overlay';
    var panel = document.createElement('div');
    panel.className = 'confirm-panel';
    panel.innerHTML =
      '<h4>确认操作</h4>' +
      '<p>' + String(message).replace(/</g,'&lt;').replace(/>/g,'&gt;') + '</p>' +
      '<div class="confirm-actions">' +
        '<button class="btn btn-ghost" id="_confirm-no">Cancel</button>' +
        '<button class="btn btn-primary" id="_confirm-yes">OK</button>' +
      '</div>';
    overlay.appendChild(panel);
    document.body.appendChild(overlay);

    // Focus the confirm button
    panel.querySelector('#_confirm-yes').focus();

    function close(result) {
      overlay.remove();
      if (result && onYes) onYes();
      if (!result && onNo) onNo();
    }
    panel.querySelector('#_confirm-yes').onclick = function() { close(true); };
    panel.querySelector('#_confirm-no').onclick = function() { close(false); };
    overlay.onclick = function(e) { if (e.target === overlay) close(false); };
    // ESC to cancel
    function onKey(e) { if (e.key === 'Escape') { document.removeEventListener('keydown', onKey); close(false); } }
    document.addEventListener('keydown', onKey);
  };

  // ── Inline prompt (replaces native prompt()) ──
  window._prompt = function(message, defaultVal, onOk, onCancel) {
    var overlay = document.createElement('div');
    overlay.className = 'confirm-overlay';
    var panel = document.createElement('div');
    panel.className = 'confirm-panel prompt-panel';
    panel.innerHTML =
      '<h4>' + String(message).replace(/</g,'&lt;').replace(/>/g,'&gt;') + '</h4>' +
      '<input type="text" id="_prompt-input" value="' + (defaultVal||'').replace(/"/g,'&quot;') + '" />' +
      '<div class="confirm-actions">' +
        '<button class="btn btn-ghost" id="_prompt-no">Cancel</button>' +
        '<button class="btn btn-primary" id="_prompt-yes">OK</button>' +
      '</div>';
    overlay.appendChild(panel);
    document.body.appendChild(overlay);

    var input = panel.querySelector('#_prompt-input');
    input.focus();
    input.select();

    function close(val) {
      overlay.remove();
      if (val !== null && onOk) onOk(val);
      if (val === null && onCancel) onCancel();
    }
    panel.querySelector('#_prompt-yes').onclick = function() { close(input.value); };
    panel.querySelector('#_prompt-no').onclick = function() { close(null); };
    input.onkeydown = function(e) { if (e.key === 'Enter') close(input.value); };
    overlay.onclick = function(e) { if (e.target === overlay) close(null); };
    function onKey(e) { if (e.key === 'Escape') { document.removeEventListener('keydown', onKey); close(null); } }
    document.addEventListener('keydown', onKey);
  };

  // ── Override native confirm/prompt with inline panels ──
  // Returns a Promise so callers can: if (!await confirm('...')) return;
  window.confirm = function(msg) {
    return new Promise(function(resolve) {
      window._confirm(msg, function() { resolve(true); }, function() { resolve(false); });
    });
  };

  // ── Track last-clicked anchor (non-inline buttons) for askInline fallback ──
  document.addEventListener('click', function(e) {
    var t = e.target;
    // Ignore clicks inside our inline-ask panels so the original trigger stays
    if (t && t.closest && t.closest('.inline-ask-panel')) return;
    while (t && t !== document.body) {
      if (t.tagName === 'BUTTON' || t.tagName === 'A' ||
          (t.hasAttribute && t.hasAttribute('onclick'))) {
        window._lastClickedAnchor = t;
        return;
      }
      t = t.parentElement;
    }
  }, true);

  // ── Inline ask helper: replaces prompt() with an in-page expansion ──
  // opts:
  //   defaultVal   default input value
  //   placeholder  input placeholder text
  //   multiline    true → textarea
  //   choices      [{value,label}] → select instead of input
  //   anchor       DOM element — panel inserted after it (else _lastClickedAnchor; else bottom-right)
  //   okLabel / cancelLabel
  // Returns Promise<string|null>
  window.askInline = function(message, opts) {
    opts = opts || {};
    return new Promise(function(resolve) {
      // Remove any prior inline-ask (single active)
      var existing = document.querySelectorAll('.inline-ask-panel');
      existing.forEach(function(p){ p.remove(); });

      var panel = document.createElement('div');
      panel.className = 'inline-ask-panel';
      panel.style.cssText =
        'margin:8px 0;padding:10px 12px;' +
        'background:rgba(167,139,250,0.08);' +
        'border:1px solid rgba(167,139,250,0.3);' +
        'border-radius:6px;font-size:13px;' +
        'display:flex;flex-direction:column;gap:8px;' +
        'box-sizing:border-box';

      if (message) {
        var label = document.createElement('div');
        label.style.cssText = 'font-size:12px;color:var(--text2);white-space:pre-wrap;line-height:1.5';
        label.textContent = String(message);
        panel.appendChild(label);
      }

      var inputEl;
      if (Array.isArray(opts.choices) && opts.choices.length > 0) {
        inputEl = document.createElement('select');
        inputEl.style.cssText = 'width:100%;font-size:13px;padding:6px 8px;' +
          'background:var(--surface);border:1px solid var(--border);' +
          'border-radius:4px;color:var(--text);box-sizing:border-box';
        opts.choices.forEach(function(c) {
          var o = document.createElement('option');
          o.value = c.value;
          o.textContent = c.label || c.value;
          if (c.value === opts.defaultVal) o.selected = true;
          inputEl.appendChild(o);
        });
      } else if (opts.multiline) {
        inputEl = document.createElement('textarea');
        inputEl.rows = 3;
        inputEl.style.cssText = 'width:100%;font-size:13px;padding:6px 8px;' +
          'background:var(--surface);border:1px solid var(--border);' +
          'border-radius:4px;color:var(--text);box-sizing:border-box;resize:vertical;' +
          'font-family:inherit';
        inputEl.value = opts.defaultVal || '';
        if (opts.placeholder) inputEl.placeholder = opts.placeholder;
      } else {
        inputEl = document.createElement('input');
        inputEl.type = 'text';
        inputEl.style.cssText = 'width:100%;font-size:13px;padding:6px 8px;' +
          'background:var(--surface);border:1px solid var(--border);' +
          'border-radius:4px;color:var(--text);box-sizing:border-box';
        inputEl.value = opts.defaultVal || '';
        if (opts.placeholder) inputEl.placeholder = opts.placeholder;
      }
      panel.appendChild(inputEl);

      var btnRow = document.createElement('div');
      btnRow.style.cssText = 'display:flex;gap:6px;justify-content:flex-end';
      var cancelBtn = document.createElement('button');
      cancelBtn.type = 'button';
      cancelBtn.className = 'btn btn-ghost btn-sm';
      cancelBtn.style.cssText = 'padding:4px 12px;font-size:12px';
      cancelBtn.textContent = opts.cancelLabel || 'Cancel';
      var okBtn = document.createElement('button');
      okBtn.type = 'button';
      okBtn.className = 'btn btn-primary btn-sm';
      okBtn.style.cssText = 'padding:4px 12px;font-size:12px';
      okBtn.textContent = opts.okLabel || 'OK';
      btnRow.appendChild(cancelBtn);
      btnRow.appendChild(okBtn);
      panel.appendChild(btnRow);

      function cleanup(val) {
        if (panel.parentNode) panel.parentNode.removeChild(panel);
        resolve(val);
      }
      okBtn.onclick = function(e) { e.stopPropagation(); cleanup(inputEl.value); };
      cancelBtn.onclick = function(e) { e.stopPropagation(); cleanup(null); };
      inputEl.onkeydown = function(e) {
        if (e.key === 'Enter' && !opts.multiline && inputEl.tagName !== 'SELECT') {
          e.preventDefault(); cleanup(inputEl.value);
        } else if (e.key === 'Escape') {
          e.preventDefault(); cleanup(null);
        }
      };

      // Mount: after anchor, else floating bottom-right
      var anchor = opts.anchor || window._lastClickedAnchor;
      if (anchor && anchor.parentNode && document.body.contains(anchor)) {
        anchor.parentNode.insertBefore(panel, anchor.nextSibling);
      } else {
        panel.style.cssText += ';position:fixed;bottom:20px;right:20px;left:auto;' +
          'width:360px;z-index:9999;box-shadow:0 4px 24px rgba(0,0,0,0.4);' +
          'background:var(--surface2,#1e1e24)';
        document.body.appendChild(panel);
      }

      setTimeout(function() {
        try { inputEl.focus(); if (inputEl.select) inputEl.select(); } catch(_) {}
      }, 10);
    });
  };

  // window.prompt stays available but now routes to askInline (so any missed
  // call sites inline as well). Keep the same (msg, defaultVal) signature.
  window.prompt = function(msg, defaultVal) {
    return window.askInline(msg, { defaultVal: defaultVal });
  };
})();

// ============ API helper ============
async function api(method, url, body) {
  const opts = {method, credentials: 'same-origin', headers: {}};
  if (body) {
    opts.headers['Content-Type'] = 'application/json';
    opts.body = JSON.stringify(body);
  }
  const resp = await fetch(url, opts);
  if (resp.status === 401) { window.location.href = '/'; return null; }
  if (resp.status === 204) return {};
  const ct = resp.headers.get('Content-Type') || '';
  const raw = await resp.text();
  let data = null;
  if (ct.indexOf('application/json') >= 0 || (raw && (raw[0] === '{' || raw[0] === '['))) {
    try { data = JSON.parse(raw); }
    catch(e) {
      const snippet = raw.slice(0, 200);
      throw new Error('HTTP '+resp.status+' — invalid JSON from '+url+': '+snippet);
    }
  } else {
    const snippet = (raw || '').slice(0, 200).replace(/\s+/g,' ');
    throw new Error('HTTP '+resp.status+' '+method+' '+url+' — non-JSON response: '+snippet);
  }
  if (!resp.ok) {
    console.error('API error', url, data);
    // FastAPI raises HTTPException → {"detail": "..."}. Legacy handlers
    // emit {"error": "..."}. Normalize so callers checking data.error
    // see the real message instead of falling through to a generic
    // "Check console" toast.
    if (data && typeof data === 'object') {
      if (data.detail && !data.error) {
        data.error = (typeof data.detail === 'string')
          ? data.detail
          : JSON.stringify(data.detail);
      }
      return data;
    }
    return {error: 'HTTP ' + resp.status};
  }
  return data;
}

// Short-window read coalesce. Multiple near-simultaneous GETs to the
// same URL (e.g. the 3 dashboard tiles each fetching
// /api/portal/projects) share one in-flight request + cached body.
// Prevents trivial rate-limit trips (RateLimitMiddleware caps each
// (ip, path) at 10 req / 5s) and saves roundtrips. TTL default 2s.
// On error the cache entry is dropped so the next caller retries.
// IMPORTANT: api() returns {error:...} for HTTP error responses (instead
// of rejecting), so .catch() alone isn't enough — we also have to inspect
// the resolved value and uncache failures. Otherwise a single 429 would
// poison the cache for 2s, and any caller that does
// `if (data.error) wipeUI()` would wipe on every retry within that window
// (the "sidebar 闪一下就没了" symptom).
const _apiShortCache = new Map();
function _apiShortGet(url, ttlMs) {
  ttlMs = ttlMs || 2000;
  const now = Date.now();
  const hit = _apiShortCache.get(url);
  if (hit && (now - hit.ts) < ttlMs) return hit.promise;
  const p = api('GET', url);
  _apiShortCache.set(url, {ts: now, promise: p});
  p.then(function(data){
    if (!data || (typeof data === 'object' && data.error)) {
      _apiShortCache.delete(url);
    }
  }, function(){ _apiShortCache.delete(url); });
  return p;
}
window._apiShortGet = _apiShortGet;

function esc(s) { const d=document.createElement('div'); d.textContent=s||''; return d.innerHTML; }

// Auto-grow textarea to fit content. Used by chat-input boxes — caller
// passes the textarea element (typically `this` from an inline `oninput`).
// Min: 1 row (computed from line-height). Max: clamped by CSS max-height.
// Also called after clearing the input (so a tall textarea collapses
// back to one row when value="").
function _autoGrowChatInput(el) {
  if (!el || el.tagName !== 'TEXTAREA') return;
  // Reset to "auto" first so shrinking works (scrollHeight only grows).
  el.style.height = 'auto';
  // Cap at max-height so very long pastes still scroll inside the box.
  // Read inline first (user may have manually drag-resized), fall back to
  // computed CSS (which now is 320px for chat-input-area textareas), and
  // a hard 320 floor so long prompts don't get visually cut to 200px.
  var maxH = parseInt(el.style.maxHeight)
          || parseInt(getComputedStyle(el).maxHeight)
          || 320;
  el.style.height = Math.min(el.scrollHeight, maxH) + 'px';
}
window._autoGrowChatInput = _autoGrowChatInput;


// ============ Unified chat input (agent / project / meeting) ============
// Three pages share the same chat input shape now:
//   ┌──────────────────────────────────────────────────────┐
//   │ [attachment preview row, hidden if empty]            │
//   │ [mention dropdown — abs positioned, optional]        │
//   ├──────────────────────────────────────────────────────┤
//   │ <textarea> auto-grow (Enter sends, Shift+Enter NL)   │
//   ├──────────────────────────────────────────────────────┤
//   │ [📎] [🎤?]   [provider▾ model▾]?      [⏹?] [↑]       │
//   └──────────────────────────────────────────────────────┘
//
// Single rounded container; controls below the text so the cursor sits
// where the eye lands. Agent gets the model selectors + STT + abort
// (via `showModelSelector` / `showSTT` / `showAbort` flags); project
// and meeting just get attach + send + the @-mention dropdown.
//
// opts:
//   id              unique scope id (agentId / projId / meetingId)
//   scope           'agent' | 'project' | 'meeting'  (drives ID prefixes)
//   placeholder     textarea placeholder string
//   disabled        true → grays out + disables input
//   sendFnName      'sendAgentMsg' / 'sendProjectMsg' / 'meetingPostMessage'
//   attachFnName    'handleAgentAttach' / 'handleProjAttach' / 'handleMtgAttach'
//   keydownHandler  optional inline handler string for textarea onkeydown
//                   (project/meeting use this for @ mention support).
//                   Default: Enter→send / Shift+Enter→newline.
//   inputChangeFn   optional oninput extra (e.g. _projInputChange)
//   acceptFiles     accept= attribute for the file input
//   showSTT         bool — render mic button (agent only)
//   showAbort       bool — render abort button (agent only)
//   showModelSel    bool — render provider+model dropdowns inside the
//                          control row (agent only; populated lazily by
//                          quickSwitchModel's existing init code)
// ── Slash command autocomplete ────────────────────────────────────
// When the user types `/` at the start of the chat input, pop up a
// floating dropdown listing matching commands. ↑/↓ to navigate,
// Tab/Enter to accept (inserts the command + space, leaving cursor
// ready for the argument), Esc to dismiss.
//
// Active across all 3 scopes (agent/project/meeting) — the unified
// input shell renders the dropdown container; helpers manage state
// per-input via the textarea's own id.

window._SLASH_CMD_SPECS = [
  { cmd: '/new',      arg: '<消息>',           desc: '不带聊天历史发本轮(可不带消息单独发起)' },
  { cmd: '/learn',    arg: '<主题>',           desc: '学习一个主题(轻量,~3K token,自动写入 wiki)' },
  { cmd: '/recall',   arg: '<问题>',           desc: '查 L3 + wiki(无 LLM 调用)' },
  { cmd: '/remember', arg: '<事实>',           desc: '显式存一条 L3 记忆(置信度 100%)' },
  { cmd: '/task',     arg: '<标题>',           desc: '升级为 V2 跟踪任务' },
  { cmd: '/handoff',  arg: '<agent> <消息>',   desc: '转交给另一个 agent(带上下文)' },
  { cmd: '/help',     arg: '',                 desc: '显示所有 / 命令' },
];

window._slashDropdownState = window._slashDropdownState || {};
// shape: { <textarea id>: { activeIdx, matches: [spec], visible: bool } }

function _slashGetTextareaId(scope, id) {
  return scope === 'meeting' ? 'mtg-msg-input'
       : scope === 'project' ? ('project-chat-input-' + id)
       : ('chat-input-' + id);
}

function _slashGetDropdownEl(scope, id) {
  return document.getElementById('slash-dd-' + _slashGetTextareaId(scope, id));
}

function _slashUpdate(scope, id) {
  var ta = document.getElementById(_slashGetTextareaId(scope, id));
  var dd = _slashGetDropdownEl(scope, id);
  if (!ta || !dd) return;
  var val = ta.value || '';
  // Trigger only when entire content starts with /; once user starts
  // typing the argument (whitespace), hide.
  if (!val.startsWith('/') || /\s/.test(val)) {
    dd.style.display = 'none';
    window._slashDropdownState[ta.id] = { matches: [], activeIdx: 0, visible: false };
    return;
  }
  var lc = val.toLowerCase();
  var matches = window._SLASH_CMD_SPECS.filter(function(s) {
    return s.cmd.startsWith(lc);
  });
  if (matches.length === 0) {
    dd.style.display = 'none';
    window._slashDropdownState[ta.id] = { matches: [], activeIdx: 0, visible: false };
    return;
  }
  var st = window._slashDropdownState[ta.id] = window._slashDropdownState[ta.id] || { activeIdx: 0 };
  st.matches = matches;
  st.visible = true;
  if (st.activeIdx >= matches.length) st.activeIdx = 0;
  dd.innerHTML = matches.map(function(spec, i) {
    var active = (i === st.activeIdx);
    return '<div data-slash-idx="' + i + '" ' +
      'onmousedown="event.preventDefault();_slashAccept(\'' + scope + '\',\'' + esc(id) + '\',' + i + ')" ' +
      'style="padding:6px 12px;cursor:pointer;display:flex;align-items:baseline;gap:10px;' +
        'background:' + (active ? 'var(--surface3)' : 'transparent') + ';' +
        'border-left:2px solid ' + (active ? 'var(--primary)' : 'transparent') + '">' +
      '<code style="color:var(--primary);font-weight:700;font-size:12px">' + esc(spec.cmd) + '</code>' +
      (spec.arg ? '<span style="font-size:10px;color:var(--text3);font-family:monospace">' + esc(spec.arg) + '</span>' : '') +
      '<span style="font-size:11px;color:var(--text2);margin-left:auto;text-align:right">' + esc(spec.desc) + '</span>' +
    '</div>';
  }).join('');
  dd.style.display = 'block';
}

window._slashUpdate = _slashUpdate;

window._slashAccept = function(scope, id, idx) {
  var ta = document.getElementById(_slashGetTextareaId(scope, id));
  var st = window._slashDropdownState[ta && ta.id];
  if (!ta || !st || !st.matches || !st.matches[idx]) return;
  var spec = st.matches[idx];
  var insertion = spec.cmd + (spec.arg ? ' ' : '');
  ta.value = insertion;
  ta.focus();
  // Cursor at end (ready for arg)
  try { ta.setSelectionRange(insertion.length, insertion.length); } catch(_){}
  // Hide dropdown — the next input event will check whether to re-show
  st.visible = false;
  var dd = _slashGetDropdownEl(scope, id);
  if (dd) dd.style.display = 'none';
  // Auto-grow check
  try { _autoGrowChatInput(ta); } catch(_) {}
};

// Returns true if the keypress was consumed by the slash dropdown.
window._slashHandleKey = function(scope, id, event) {
  var ta = document.getElementById(_slashGetTextareaId(scope, id));
  var st = window._slashDropdownState[ta && ta.id];
  if (!ta || !st || !st.visible || !st.matches || !st.matches.length) return false;
  if (event.key === 'ArrowDown') {
    event.preventDefault();
    st.activeIdx = (st.activeIdx + 1) % st.matches.length;
    _slashUpdate(scope, id);
    return true;
  }
  if (event.key === 'ArrowUp') {
    event.preventDefault();
    st.activeIdx = (st.activeIdx - 1 + st.matches.length) % st.matches.length;
    _slashUpdate(scope, id);
    return true;
  }
  if (event.key === 'Tab' || event.key === 'Enter') {
    event.preventDefault();
    _slashAccept(scope, id, st.activeIdx);
    return true;
  }
  if (event.key === 'Escape') {
    event.preventDefault();
    st.visible = false;
    var dd = _slashGetDropdownEl(scope, id);
    if (dd) dd.style.display = 'none';
    return true;
  }
  return false;
};


function _renderUnifiedChatInput(opts) {
  var o = opts || {};
  var id = o.id || '';
  var scope = o.scope || 'agent';
  var idPrefix = (
    scope === 'agent'   ? 'chat-input-' :
    scope === 'project' ? 'project-chat-input-' :
    /* meeting */         'mtg-msg-input'
  );
  // Meeting uses a fixed id (mtg-msg-input) for legacy reasons; only
  // prefix ones get the agent/project id appended.
  var inputId = scope === 'meeting' ? 'mtg-msg-input' : (idPrefix + id);
  var fileInputId  = scope === 'agent' ? ('agent-file-input-' + id)
                   : scope === 'project' ? ('proj-attach-file-' + id)
                   : ('mtg-file-input-' + id);
  var attachPrevId = scope === 'agent' ? ('agent-attach-preview-' + id)
                   : scope === 'project' ? ('proj-attach-preview-' + id)
                   : ('mtg-attach-preview-' + id);
  var mentionDropId = scope === 'project' ? ('mention-dropdown-' + id)
                   : scope === 'meeting' ? 'mtg-mention-dropdown'
                   : '';
  var placeholder = o.placeholder || 'Message ...';
  var sendFn = o.sendFnName || 'sendAgentMsg';
  var attachFn = o.attachFnName || 'handleAgentAttach';
  var acceptFiles = o.acceptFiles || 'image/*,.pdf,.doc,.docx,.txt,.md';
  var disabled = !!o.disabled;
  var disAttrs = disabled ? ' disabled aria-disabled="true"' : '';
  var disStyle = disabled ? 'opacity:0.45;cursor:not-allowed;' : '';
  var defaultKeydown = "if(event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();" + sendFn + "('" + id + "')}";
  // Wrap caller's keydown so the slash-command dropdown gets first
  // crack at ↑/↓/Tab/Enter/Esc when it's visible. If the dropdown
  // consumes the key, we short-circuit and don't run the original
  // handler. Otherwise the original send-on-Enter / @-mention logic
  // proceeds as before.
  var keydownInner = o.keydownHandler || defaultKeydown;
  var keydown = "if(window._slashHandleKey&&window._slashHandleKey('" + scope + "','" + id + "',event))return;" + keydownInner;
  var inputChange = o.inputChangeFn ? (o.inputChangeFn + "('" + id + "');") : '';
  // Always call _slashUpdate after each input — cheap (one regex
  // check) when the input doesn't start with /.
  var inputChangeFull = inputChange + "if(window._slashUpdate)_slashUpdate('" + scope + "','" + id + "');";
  // Visual: outer rounded container holds preview row + textarea + control row
  var slashDropId = 'slash-dd-' + inputId;
  var html =
    '<div class="uci-shell" data-scope="' + scope + '" data-id="' + esc(id) + '" style="' +
      'background:var(--surface3);border:1px solid var(--overlay-10);border-radius:14px;' +
      'padding:10px 12px;display:flex;flex-direction:column;gap:8px;position:relative;' + disStyle + '">' +
      // Slash command dropdown (positioned above the input). Floats
      // upward via bottom:100% so it never pushes the input around.
      '<div id="' + slashDropId + '" style="display:none;position:absolute;bottom:100%;left:0;right:0;' +
        'margin-bottom:6px;background:var(--surface);border:1px solid var(--overlay-10);' +
        'border-radius:8px;box-shadow:0 6px 24px rgba(0,0,0,0.3);z-index:1000;' +
        'max-height:300px;overflow-y:auto"></div>' +
      // Mention dropdown (project + meeting only) — sits above, absolute
      (mentionDropId ? '<div id="' + mentionDropId + '" class="mention-dropdown"></div>' : '') +
      // Attachment preview row — hidden until first attach
      '<div id="' + attachPrevId + '" style="display:none;flex-wrap:wrap;gap:6px"></div>' +
      // Hidden file input
      '<input type="file" id="' + fileInputId + '" multiple accept="' + acceptFiles +
        '" style="display:none" onchange="' + attachFn + "('" + id + "',this)" + '">' +
      // Textarea (auto-grow)
      '<textarea id="' + inputId + '" placeholder="' + esc(placeholder) + '"' + disAttrs +
        ' rows="1"' +
        ' style="background:transparent;border:none;color:var(--text);font-size:14px;' +
          'padding:6px 4px;outline:none;resize:none;line-height:1.4;max-height:200px;' +
          'overflow-y:auto;font-family:inherit;width:100%"' +
        ' oninput="' + inputChangeFull + '_autoGrowChatInput(this)"' +
        ' onkeydown="' + keydown + '"></textarea>' +
      // Control row: [attach][stt?]    [provider+model?]    [abort?][send]
      '<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap">' +
        // Left controls (attach, stt)
        '<button type="button" title="Upload image/file" onclick="document.getElementById(\'' + fileInputId + '\').click()" ' +
          'style="background:transparent;border:1px solid var(--overlay-10);border-radius:8px;padding:5px 8px;cursor:pointer;display:flex;align-items:center;gap:4px;color:var(--text3);transition:all .15s" ' +
          'onmouseenter="this.style.borderColor=\'var(--primary-tint-30)\';this.style.color=\'var(--text)\'" ' +
          'onmouseleave="this.style.borderColor=\'var(--overlay-10)\';this.style.color=\'var(--text3)\'">' +
          '<span class="material-symbols-outlined" style="font-size:16px">attach_file</span>' +
        '</button>' +
        (o.showSTT ? (
          '<button type="button" id="stt-btn-' + id + '" title="Voice input (STT)" onclick="_toggleSTT(\'' + id + '\')" ' +
            'style="background:transparent;border:1px solid var(--overlay-10);border-radius:8px;padding:5px 8px;cursor:pointer;display:flex;align-items:center;gap:4px;color:var(--text3);transition:all .15s" ' +
            'onmouseenter="this.style.borderColor=\'var(--primary-tint-30)\';this.style.color=\'var(--text)\'" ' +
            'onmouseleave="this.style.borderColor=\'var(--overlay-10)\';this.style.color=\'var(--text3)\'">' +
            '<span class="material-symbols-outlined" style="font-size:16px">mic</span>' +
          '</button>'
        ) : '') +
        // Thinking toggle (agent scope only) — when ON, the assistant
        // bubble shows a collapsible THINKING panel populated by SSE
        // `reasoning_delta` events emitted from the LLM stream.
        // Persisted per-agent via localStorage key `tudou_show_thinking_<id>`.
        (scope === 'agent' ? (
          '<button type="button" id="thinking-toggle-' + id + '" title="Show thinking process (streams reasoning_content via SSE)" onclick="_toggleShowThinking(\'' + id + '\')" ' +
            'style="background:transparent;border:1px solid var(--overlay-10);border-radius:8px;padding:5px 8px;cursor:pointer;display:flex;align-items:center;gap:4px;color:var(--text3);transition:all .15s">' +
            '<span class="material-symbols-outlined" style="font-size:16px" id="thinking-icon-' + id + '">psychology</span>' +
            '<span style="font-size:11px">Thinking</span>' +
          '</button>'
        ) : '') +
        (o.showAmplify ? (
          '<button type="button" id="amplify-toggle-' + id + '" title="✨ Optimize prompt (toggle)" onclick="_amplifyToggleClick(\'' + id + '\')" ' +
            'style="background:transparent;border:1px solid var(--overlay-10);border-radius:8px;padding:5px 8px;cursor:pointer;display:flex;align-items:center;gap:4px;color:var(--text3);transition:all .15s">' +
            '<span class="material-symbols-outlined" style="font-size:16px">auto_awesome</span>' +
            '<span style="font-size:11px">Optimize</span>' +
          '</button>'
        ) : '') +
        // Middle: provider + model selectors (agent only)
        (o.showModelSel ? (
          '<div style="display:flex;gap:4px;align-items:center;margin-left:6px">' +
            '<select id="agent-quick-provider-' + id + '" onchange="quickSwitchModel(\'' + id + '\')" ' +
              'title="LLM Provider" ' +
              'style="background:var(--surface);border:1px solid var(--overlay-10);border-radius:6px;color:var(--text2);font-size:11px;padding:4px 8px;max-width:140px;cursor:pointer"></select>' +
            '<select id="agent-quick-model-' + id + '" onchange="quickSwitchModel(\'' + id + '\')" ' +
              'title="Model" ' +
              'style="background:var(--surface);border:1px solid var(--overlay-10);border-radius:6px;color:var(--text);font-size:11px;padding:4px 8px;max-width:200px;cursor:pointer"></select>' +
          '</div>'
        ) : '') +
        // Right controls — push to right with spacer
        '<div style="flex:1"></div>' +
        (o.showAbort ? (
          '<button type="button" title="Force-abort current chat + kill subprocesses" onclick="agentAbort(\'' + id + '\')" ' +
            'style="background:transparent;border:1px solid rgba(239,68,68,0.4);border-radius:8px;padding:5px 8px;cursor:pointer;display:flex;align-items:center;color:var(--error);transition:all .15s" ' +
            'onmouseenter="this.style.background=\'rgba(239,68,68,0.08)\'" ' +
            'onmouseleave="this.style.background=\'transparent\'">' +
            '<span class="material-symbols-outlined" style="font-size:16px">stop_circle</span>' +
          '</button>'
        ) : '') +
        // Send button — primary CTA, large
        '<button type="button" title="Send" onclick="' + sendFn + "('" + id + "')" + '"' + disAttrs +
          ' style="background:var(--primary);border:none;border-radius:10px;padding:8px 14px;cursor:' + (disabled ? 'not-allowed' : 'pointer') +
            ';display:flex;align-items:center;gap:4px;color:#0f0e2e;font-weight:700;transition:transform .1s"' +
          ' onmousedown="this.style.transform=\'scale(0.95)\'" onmouseup="this.style.transform=\'\'">' +
          '<span class="material-symbols-outlined" style="font-size:18px">arrow_upward</span>' +
        '</button>' +
      '</div>' +
    '</div>';
  return html;
}
window._renderUnifiedChatInput = _renderUnifiedChatInput;

// ── Thinking toggle (per-agent, persisted) ──────────────────────────
// When ON, the SSE handler appends a collapsible "THINKING" panel
// above the assistant bubble and live-streams `reasoning_delta` chunks
// into it. When OFF (default), reasoning is dropped on the floor.
window._isShowThinking = function(agentId) {
  try { return localStorage.getItem('tudou_show_thinking_' + agentId) === '1'; }
  catch (e) { return false; }
};
window._toggleShowThinking = function(agentId) {
  var on = !_isShowThinking(agentId);
  try { localStorage.setItem('tudou_show_thinking_' + agentId, on ? '1' : '0'); } catch (e) {}
  _refreshThinkingToggleUi(agentId);
};
window._refreshThinkingToggleUi = function(agentId) {
  var btn = document.getElementById('thinking-toggle-' + agentId);
  var icon = document.getElementById('thinking-icon-' + agentId);
  if (!btn) return;
  var on = _isShowThinking(agentId);
  btn.style.borderColor = on ? 'var(--primary)' : 'var(--overlay-10)';
  btn.style.background = on ? 'rgba(192,193,255,0.10)' : 'transparent';
  btn.style.color = on ? 'var(--primary)' : 'var(--text3)';
  if (icon) icon.style.color = on ? 'var(--primary)' : 'var(--text3)';
};


// ============ Click-once button lock ============================
// Prevents double-submit on Create / Save buttons. Usage:
//   <button onclick="_lockBtn(this,'Creating…',createMeeting)">Create</button>
//   <button onclick="_lockBtn(this,'Saving…',_kmSaveDomainKb)">Save</button>
//   <button onclick="_lockBtn(this,'Creating…',createProjectTask,'projId123')">Create</button>
//
// While locked: button is disabled, dimmed, shows a spinner + busyText.
// Auto-unlocks when:
//   - the wrapped fn returns a Promise that settles (success or rejection)
//   - OR after 30s safety timer fires (covers fns that fire-and-forget
//     async work via api() without returning the promise)
//   - on synchronous throw, immediate unlock + rethrow
// If the modal closes (button removed from DOM), the lock state is moot.
(function _wireLockBtnHelper() {
  if (window._lockBtn) return;
  // Inject CSS keyframe once (shared with amplify spinner if present).
  if (!document.getElementById('_lockbtn_kf')) {
    var st = document.createElement('style');
    st.id = '_lockbtn_kf';
    st.textContent = '@keyframes _lockbtn_spin{from{transform:rotate(0)}to{transform:rotate(360deg)}}';
    (document.head || document.documentElement).appendChild(st);
  }
  window._lockBtn = function(btnEl, busyText, fn /*, ...args */) {
    if (!btnEl || btnEl.dataset.lockedOnce === '1') return;
    if (typeof fn !== 'function') {
      console.warn('[_lockBtn] fn must be a function, got', fn);
      return;
    }
    btnEl.dataset.lockedOnce = '1';
    var orig = btnEl.innerHTML;
    var origOpacity = btnEl.style.opacity;
    var origCursor = btnEl.style.cursor;
    btnEl.disabled = true;
    btnEl.style.opacity = '0.55';
    btnEl.style.cursor = 'not-allowed';
    btnEl.innerHTML =
      '<span class="material-symbols-outlined" style="font-size:14px;animation:_lockbtn_spin 1s linear infinite;vertical-align:middle">progress_activity</span> ' +
      (busyText || 'Working…');
    var unlock = function() {
      if (!btnEl.isConnected) return;  // button removed (modal closed) — nothing to do
      btnEl.dataset.lockedOnce = '';
      btnEl.disabled = false;
      btnEl.style.opacity = origOpacity;
      btnEl.style.cursor = origCursor;
      btnEl.innerHTML = orig;
    };
    var safetyTimer = setTimeout(unlock, 30000);
    var args = Array.prototype.slice.call(arguments, 3);
    try {
      var ret = fn.apply(null, args);
      if (ret && typeof ret.then === 'function') {
        ret.then(
          function() { clearTimeout(safetyTimer); unlock(); },
          function() { clearTimeout(safetyTimer); unlock(); }
        );
      }
      // Sync fns: rely on safetyTimer (or modal close) to unlock.
    } catch (e) {
      clearTimeout(safetyTimer);
      unlock();
      throw e;
    }
  };
})();


// ============ Prompt amplifier (✨ 优化提示词) =========================
// Toggle-gated rewriter. When the per-agent toggle is ON, sendAgentMsg
// pauses and runs the user's input through /api/portal/amplify-prompt
// before posting to the agent. The amplified prompt is rendered in an
// editable preview block above the input — user can tweak it, accept,
// or fall back to the original.
//
// All state is per-agent in localStorage. If the toggle is OFF,
// nothing in this section runs (sendAgentMsg short-circuits past it).
// ────────────────────────────────────────────────────────────────────

function _amplifyStorageKey(agentId) {
  return 'tudou_amplify_on_' + (agentId || 'global');
}
function _amplifyEnabled(agentId) {
  try {
    return localStorage.getItem(_amplifyStorageKey(agentId)) === '1';
  } catch (e) { return false; }
}
window._amplifyEnabled = _amplifyEnabled;

function _amplifySyncToggleVisual(agentId) {
  var btn = document.getElementById('amplify-toggle-' + agentId);
  if (!btn) return;
  var on = _amplifyEnabled(agentId);
  if (on) {
    btn.style.borderColor = 'var(--primary)';
    btn.style.color = 'var(--primary)';
    btn.style.background = 'color-mix(in srgb, var(--primary) 12%, transparent)';
    btn.title = '✨ Optimize prompt (ON, click to disable)';
  } else {
    btn.style.borderColor = 'var(--overlay-10)';
    btn.style.color = 'var(--text3)';
    btn.style.background = 'transparent';
    btn.title = '✨ Optimize prompt (OFF, click to enable)';
  }
}

function _amplifyToggleClick(agentId) {
  var on = _amplifyEnabled(agentId);
  try {
    localStorage.setItem(_amplifyStorageKey(agentId), on ? '0' : '1');
  } catch (e) {}
  _amplifySyncToggleVisual(agentId);
  if (typeof window._toast === 'function') {
    window._toast(on ? 'Prompt optimization disabled' : '✨ Prompt optimization enabled — your input will be rewritten before sending',
                  on ? 'info' : 'success');
  }
}
window._amplifyToggleClick = _amplifyToggleClick;

// MutationObserver-driven sync: whenever an `amplify-toggle-*` button
// gets inserted into the DOM (chat panel re-renders), run the visual
// sync so the on/off color matches localStorage. Cheap — only fires
// on subtree changes inside the chat area.
(function _wireAmplifyVisualSync() {
  if (window._amplifyVisualSyncWired) return;
  window._amplifyVisualSyncWired = true;
  var sync = function() {
    document.querySelectorAll('[id^="amplify-toggle-"]').forEach(function(btn) {
      var aid = btn.id.replace('amplify-toggle-', '');
      _amplifySyncToggleVisual(aid);
    });
  };
  // Initial sweep + on every animation frame after DOM mutations
  // settle. Debounced via rAF so we don't thrash on rapid re-renders.
  var pending = false;
  var schedule = function() {
    if (pending) return;
    pending = true;
    requestAnimationFrame(function() { pending = false; sync(); });
  };
  if (document.body) {
    new MutationObserver(schedule).observe(document.body, {
      childList: true, subtree: true,
    });
    sync();
  } else {
    document.addEventListener('DOMContentLoaded', function() {
      new MutationObserver(schedule).observe(document.body, {
        childList: true, subtree: true,
      });
      sync();
    });
  }
})();

async function _amplifyRunAndPreview(agentId, rawText) {
  var inputEl = document.getElementById('chat-input-' + agentId);
  var sendBtn = inputEl ? inputEl.closest('.uci-shell').querySelector('button[title="Send"]') : null;
  // Lock the input + send btn while we wait — prevents double-send.
  if (inputEl) inputEl.disabled = true;
  if (sendBtn) sendBtn.disabled = true;

  // Show a transient "优化中..." chip in the preview slot so the user
  // sees the round-trip is in flight (LLM call can take 1-3s).
  _renderAmplifyLoading(agentId);

  var res;
  try {
    res = await api('POST', '/api/portal/amplify-prompt', {
      raw_prompt: rawText,
      agent_id: agentId,
    });
  } catch (e) {
    _amplifyDismiss(agentId);
    if (inputEl) inputEl.disabled = false;
    if (sendBtn) sendBtn.disabled = false;
    if (window._toast) window._toast('Amplify failed:' + (e && e.message || e), 'error');
    try { console.error('[amplify] error', e); } catch(_){}
    return;
  }
  if (inputEl) inputEl.disabled = false;
  if (sendBtn) sendBtn.disabled = false;

  if (!res || !res.ok) {
    _amplifyDismiss(agentId);
    if (window._toast) window._toast('Amplify failed:' + ((res && res.error) || 'unknown'), 'error');
    return;
  }
  // Backend short-circuit: input was already specific. Dismiss the
  // loading chip and just send the original — no preview needed.
  if (res.skipped) {
    _amplifyDismiss(agentId);
    if (window._toast) {
      window._toast('💡 ' + (res.rationale || 'Input already specific, sending as-is'), 'info');
    }
    window._skipAmplifyOnce[agentId] = true;
    sendAgentMsg(agentId);
    return;
  }

  _renderAmplifyPreview(agentId, rawText, res.amplified || rawText, res.rationale || '');
}

function _amplifyPreviewSlotEl(agentId) {
  // The preview block lives just above the input shell, inside the
  // same wrapper. We append/replace it dynamically.
  var inputEl = document.getElementById('chat-input-' + agentId);
  if (!inputEl) return null;
  var shell = inputEl.closest('.uci-shell');
  if (!shell || !shell.parentNode) return null;
  var slotId = 'amplify-slot-' + agentId;
  var slot = document.getElementById(slotId);
  if (!slot) {
    slot = document.createElement('div');
    slot.id = slotId;
    shell.parentNode.insertBefore(slot, shell);
  }
  return slot;
}

function _renderAmplifyLoading(agentId) {
  var slot = _amplifyPreviewSlotEl(agentId);
  if (!slot) return;
  slot.innerHTML =
    '<div style="background:var(--surface3);border:1px solid var(--overlay-10);' +
      'border-radius:12px;padding:12px 14px;margin-bottom:8px;display:flex;' +
      'align-items:center;gap:10px;font-size:13px;color:var(--text2)">' +
      '<span class="material-symbols-outlined" style="font-size:18px;color:var(--primary);' +
        'animation:amplify-spin 1.4s linear infinite">auto_awesome</span>' +
      '<span>Optimizing prompt…</span>' +
    '</div>' +
    '<style>@keyframes amplify-spin{from{transform:rotate(0)}to{transform:rotate(360deg)}}</style>';
}

function _renderAmplifyPreview(agentId, original, amplified, rationale) {
  var slot = _amplifyPreviewSlotEl(agentId);
  if (!slot) return;
  // Encode the original safely — it gets stashed on a data attribute so
  // "用原文" can recover it without us re-reading inputEl (which the
  // user might have already edited).
  var origAttr = encodeURIComponent(original || '');
  slot.innerHTML =
    '<div style="background:var(--surface3);border:1px solid var(--primary);' +
      'border-radius:12px;padding:12px 14px;margin-bottom:8px;' +
      'display:flex;flex-direction:column;gap:10px"' +
      ' data-amplify-original="' + origAttr + '">' +
      // Header: ✨ + rationale
      '<div style="display:flex;align-items:flex-start;gap:8px;font-size:12px;' +
        'color:var(--text2);line-height:1.5">' +
        '<span class="material-symbols-outlined" style="font-size:16px;color:var(--primary);' +
          'flex-shrink:0;margin-top:1px">auto_awesome</span>' +
        '<div><b style="color:var(--text)">Optimized preview</b>' +
          (rationale ? ' · ' + esc(rationale) : '') +
        '</div>' +
      '</div>' +
      // Editable textarea
      '<textarea id="amplify-text-' + agentId + '" rows="5"' +
        ' style="background:var(--bg);border:1px solid var(--overlay-10);' +
          'border-radius:8px;padding:10px 12px;color:var(--text);font-size:13px;' +
          'line-height:1.5;font-family:inherit;resize:vertical;min-height:80px;' +
          'max-height:280px;outline:none;width:100%"' +
        '>' + esc(amplified) + '</textarea>' +
      // Action row
      '<div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap">' +
        '<button type="button" onclick="_amplifyConfirmSend(\'' + agentId + '\')" ' +
          'style="background:var(--primary);border:none;border-radius:8px;' +
          'padding:7px 14px;color:#0f0e2e;font-weight:600;font-size:12px;cursor:pointer;' +
          'display:flex;align-items:center;gap:4px">' +
          '<span class="material-symbols-outlined" style="font-size:14px">check</span>' +
          'Send this' +
        '</button>' +
        '<button type="button" onclick="_amplifyUseOriginal(\'' + agentId + '\')" ' +
          'style="background:transparent;border:1px solid var(--overlay-10);' +
          'border-radius:8px;padding:7px 12px;color:var(--text2);font-size:12px;' +
          'cursor:pointer;display:flex;align-items:center;gap:4px">' +
          '<span class="material-symbols-outlined" style="font-size:14px">undo</span>' +
          'Use original' +
        '</button>' +
        '<button type="button" onclick="_amplifyDismiss(\'' + agentId + '\')" ' +
          'style="background:transparent;border:1px solid var(--overlay-10);' +
          'border-radius:8px;padding:7px 12px;color:var(--text3);font-size:12px;' +
          'cursor:pointer;display:flex;align-items:center;gap:4px">' +
          '<span class="material-symbols-outlined" style="font-size:14px">close</span>' +
          'Cancel' +
        '</button>' +
      '</div>' +
    '</div>';
  // Focus the textarea so the user can immediately start editing.
  setTimeout(function() {
    var ta = document.getElementById('amplify-text-' + agentId);
    if (ta) { ta.focus(); ta.setSelectionRange(ta.value.length, ta.value.length); }
  }, 50);
}

function _amplifyDismiss(agentId) {
  var slot = document.getElementById('amplify-slot-' + agentId);
  if (slot && slot.parentNode) slot.parentNode.removeChild(slot);
}
window._amplifyDismiss = _amplifyDismiss;

function _amplifyConfirmSend(agentId) {
  var ta = document.getElementById('amplify-text-' + agentId);
  var inputEl = document.getElementById('chat-input-' + agentId);
  if (!ta || !inputEl) return;
  var text = (ta.value || '').trim();
  if (!text) {
    if (window._toast) window._toast('Amplified text cannot be empty', 'warning');
    return;
  }
  inputEl.value = text;
  try { _autoGrowChatInput(inputEl); } catch(_){}
  _amplifyDismiss(agentId);
  // Mark this turn as already amplified so sendAgentMsg's intercept
  // doesn't loop us back into the rewriter.
  window._skipAmplifyOnce = window._skipAmplifyOnce || {};
  window._skipAmplifyOnce[agentId] = true;
  sendAgentMsg(agentId);
}
window._amplifyConfirmSend = _amplifyConfirmSend;

function _amplifyUseOriginal(agentId) {
  var slot = document.getElementById('amplify-slot-' + agentId);
  var inputEl = document.getElementById('chat-input-' + agentId);
  if (!inputEl) return;
  var orig = '';
  if (slot) {
    var inner = slot.querySelector('[data-amplify-original]');
    if (inner) {
      try { orig = decodeURIComponent(inner.getAttribute('data-amplify-original') || ''); } catch(e) { orig = ''; }
    }
  }
  if (orig) {
    inputEl.value = orig;
    try { _autoGrowChatInput(inputEl); } catch(_){}
  }
  _amplifyDismiss(agentId);
  window._skipAmplifyOnce = window._skipAmplifyOnce || {};
  window._skipAmplifyOnce[agentId] = true;
  sendAgentMsg(agentId);
}
window._amplifyUseOriginal = _amplifyUseOriginal;


// ============ Unified artifact preview panel (right side) =============
// Mirrors the screenshot reference: when an agent writes a file
// (write_file / edit_file / apply_diff tool_call), it shows up as a
// tab in the right sidebar with live-rendered content. User can
// switch tabs, download, copy, or collapse the whole panel.
//
// Used by all three pages (agent / project / meeting); each page calls
// _renderArtifactPanelShell(scope, id) to inject the empty panel + the
// collapse toggle, then _ltArtifactRefresh(scope, id) to populate it
// from the appropriate event source (agent.events for agent;
// per-agent in project/meeting).
//
// State is per-scope-instance, kept in window._ltArtifactState so the
// panel survives re-renders during a chat session.
window._ltArtifactState = window._ltArtifactState || {};
// Shape: {<scope-id>: {paths: [str], activePath: str, lastEventCount: int}}

function _ltArtifactKey(scope, id) { return scope + ':' + id; }

// Persisted "panel collapsed" preference per scope-instance.
function _ltArtifactCollapsed(scope, id) {
  try {
    return localStorage.getItem('lt-artifact-collapsed:' + _ltArtifactKey(scope, id)) === '1';
  } catch (_) { return false; }
}
function _ltArtifactSetCollapsed(scope, id, val) {
  try {
    localStorage.setItem('lt-artifact-collapsed:' + _ltArtifactKey(scope, id), val ? '1' : '0');
  } catch (_) {}
}

// Path-list extraction: walk through events, pull file paths from
// write_file / edit_file / apply_diff / create_pptx tool_calls.
// Order: most-recently-written first; dedup by path.
function _ltExtractArtifactPaths(events, workspaceRoot) {
  if (!Array.isArray(events) || !events.length) return [];
  var WRITE_TOOLS = {write_file:1, edit_file:1, apply_diff:1,
    create_pptx:1, create_pptx_from_template:1, save_file:1, append_file:1};
  var PATH_KEYS = ['path','file_path','output_path','filename','target','dest','destination'];
  var seen = {};
  var ordered = [];
  // Resolve relative paths against the agent's sandbox root. The
  // tool_call args usually carry a relative path like
  // "generate_beautiful_pptx.py" because the LLM doesn't know the
  // absolute workspace path; write_file's safe_path() resolves it
  // server-side. The artifact panel needs the same resolution for
  // file-preview to find the file (otherwise: 404).
  function _resolve(p) {
    if (!p) return p;
    // Already absolute (POSIX or home-relative)?
    if (p.charAt(0) === '/' || p.charAt(0) === '~' || /^[a-zA-Z]:[\\\/]/.test(p)) {
      return p;
    }
    if (!workspaceRoot) return p;  // can't resolve; let backend 404 with raw path
    var root = workspaceRoot.replace(/\/+$/, '');
    var rel = p.replace(/^\.\/+/, '');
    return root + '/' + rel;
  }
  // Walk events in REVERSE so most-recent comes first
  for (var i = events.length - 1; i >= 0; i--) {
    var ev = events[i] || {};
    if (ev.kind !== 'tool_call') continue;
    var d = ev.data || {};
    var name = d.name || d.tool_name || '';
    if (!WRITE_TOOLS[name]) continue;
    var args = d.arguments || d.args || {};
    if (typeof args === 'string') {
      try { args = JSON.parse(args); } catch (_) { args = {}; }
    }
    var p = '';
    for (var k = 0; k < PATH_KEYS.length; k++) {
      var v = args[PATH_KEYS[k]];
      if (typeof v === 'string' && v.trim()) { p = v.trim(); break; }
    }
    if (!p) continue;
    var resolved = _resolve(p);
    if (seen[resolved]) continue;
    seen[resolved] = 1;
    ordered.push(resolved);
  }
  return ordered;
}

// File extension → renderer kind
function _ltKindForExt(path) {
  var p = (path || '').toLowerCase();
  var ext = p.split('.').pop();
  if (ext === 'md' || ext === 'markdown') return 'markdown';
  if (['png','jpg','jpeg','gif','webp','svg','bmp','ico'].indexOf(ext) >= 0) return 'image';
  if (['mp4','webm','mov','m4v'].indexOf(ext) >= 0) return 'video';
  if (['mp3','wav','m4a','ogg'].indexOf(ext) >= 0) return 'audio';
  if (['py','js','ts','tsx','jsx','go','rs','java','c','cpp','h','rb','php','sh','sql','yaml','yml','toml','json','html','css'].indexOf(ext) >= 0) return 'code';
  if (['pdf'].indexOf(ext) >= 0) return 'pdf';
  if (['pptx','docx','xlsx'].indexOf(ext) >= 0) return 'office';
  return 'text';
}

// Right-side panel shell. Returns HTML string. Width: 360px when
// expanded, 36px when collapsed (just the toggle).
function _renderArtifactPanelShell(scope, id) {
  var key = _ltArtifactKey(scope, id);
  var collapsed = _ltArtifactCollapsed(scope, id);
  var width = collapsed ? '36px' : '360px';
  return '<div id="lt-artifact-panel-' + key + '" data-collapsed="' + (collapsed ? '1' : '0') +
    '" style="width:' + width + ';flex-shrink:0;border-left:1px solid var(--overlay-6);' +
    'background:var(--bg);display:flex;flex-direction:column;transition:width .2s ease;overflow:hidden">' +
    // Header bar (always visible — collapse toggle + title)
    '<div style="display:flex;align-items:center;gap:6px;padding:8px 10px;border-bottom:1px solid var(--overlay-6);flex-shrink:0">' +
      '<button onclick="_ltArtifactToggleCollapse(\'' + scope + '\',\'' + esc(id) + '\')" ' +
        'title="' + (collapsed ? 'Expand preview panel' : 'Collapse preview panel') + '" ' +
        'style="background:transparent;border:none;color:var(--text3);cursor:pointer;padding:2px;' +
          'display:flex;align-items:center;border-radius:4px"' +
        ' onmouseenter="this.style.background=\'var(--surface2)\'" ' +
        ' onmouseleave="this.style.background=\'transparent\'">' +
        '<span class="material-symbols-outlined" style="font-size:18px">' +
          (collapsed ? 'chevron_left' : 'chevron_right') + '</span>' +
      '</button>' +
      (collapsed ? '' :
        '<span style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.8px;color:var(--text3);flex:1">' +
          'Artifacts</span>' +
        '<span id="lt-artifact-count-' + key + '" style="font-size:10px;color:var(--text3);background:var(--surface2);padding:1px 6px;border-radius:8px">0</span>') +
    '</div>' +
    (collapsed ? '' :
      // Tabs row (filled by _ltArtifactRefresh)
      '<div id="lt-artifact-tabs-' + key + '" style="display:flex;gap:2px;padding:6px 8px;border-bottom:1px solid var(--overlay-6);overflow-x:auto;flex-shrink:0;background:var(--bg2)"></div>' +
      // Toolbar (download / copy / open-in-new) for active tab
      '<div id="lt-artifact-toolbar-' + key + '" style="display:none;align-items:center;gap:4px;padding:6px 10px;border-bottom:1px solid var(--overlay-6);flex-shrink:0;background:var(--bg2)"></div>' +
      // Content area (fills remaining space)
      '<div id="lt-artifact-body-' + key + '" style="flex:1;overflow:auto;padding:14px 16px;font-size:13px;line-height:1.55;color:var(--text)">' +
        '<div style="color:var(--text3);font-size:12px;text-align:center;padding:30px 10px;line-height:1.6">' +
          '🪶 No artifacts yet<br><span style="font-size:11px;opacity:0.7">After the agent calls write_file / edit_file,<br>files will appear here for live preview</span>' +
        '</div>' +
      '</div>') +
    '</div>';
}
window._renderArtifactPanelShell = _renderArtifactPanelShell;

window._ltArtifactToggleCollapse = function(scope, id) {
  var collapsed = _ltArtifactCollapsed(scope, id);
  _ltArtifactSetCollapsed(scope, id, !collapsed);
  // Re-render the shell only — full chat re-render is overkill
  var key = _ltArtifactKey(scope, id);
  var panel = document.getElementById('lt-artifact-panel-' + key);
  if (!panel || !panel.parentNode) return;
  var newHtml = _renderArtifactPanelShell(scope, id);
  var tmp = document.createElement('div');
  tmp.innerHTML = newHtml;
  panel.parentNode.replaceChild(tmp.firstChild, panel);
  _ltArtifactRefresh(scope, id);
};

// Refresh: pull paths from the appropriate event source, rebuild tabs,
// load active path content. Called on initial render + after each chat
// turn (where event count grows).
window._ltArtifactRefresh = async function(scope, id) {
  var key = _ltArtifactKey(scope, id);
  var collapsed = _ltArtifactCollapsed(scope, id);
  if (collapsed) return;  // hidden — skip work
  var tabsEl = document.getElementById('lt-artifact-tabs-' + key);
  var toolbarEl = document.getElementById('lt-artifact-toolbar-' + key);
  var bodyEl = document.getElementById('lt-artifact-body-' + key);
  var countEl = document.getElementById('lt-artifact-count-' + key);
  if (!tabsEl || !bodyEl) return;

  // Fetch events for the scope
  var events = [];
  try {
    if (scope === 'agent') {
      var resp = await api('GET', '/api/portal/agent/' + encodeURIComponent(id) + '/events');
      events = (resp && resp.events) || [];
    } else if (scope === 'project') {
      // For projects: events live per-agent. For MVP, aggregate from
      // each project member's recent events. Cheaper option for now:
      // skip — project chat already has the workspace files panel.
      // (Future: aggregate or call /api/portal/projects/<id>/events)
      events = [];
    } else if (scope === 'meeting') {
      // Same as project — meetings track agent contributions, file
      // discovery comes via meeting/{mid}/files endpoint.
      events = [];
    }
  } catch (e) {
    console.debug('lt artifact refresh: events fetch failed', e);
  }

  // Resolve agent's workspace root so relative tool_call paths
  // (e.g. "out.md") become absolute (e.g.
  // "/Users/.../tudou_claw/workspaces/<id>/out.md") — otherwise
  // file-preview 404s on the bare relative path.
  var workspaceRoot = '';
  if (scope === 'agent') {
    var agentObj = (agents || []).find(function(a){ return a.id === id; });
    workspaceRoot = (agentObj && agentObj.working_dir) || '';
    // Fallback to TudouClaw's default convention if working_dir not set.
    if (!workspaceRoot) {
      workspaceRoot = '~/.tudou_claw/workspaces/' + id;
    }
  }
  var paths = _ltExtractArtifactPaths(events, workspaceRoot);
  // Filter out paths that don't actually exist on disk. The LLM
  // sometimes "writes" to fictional paths like /workspace/foo.md that
  // never land — we don't want broken tabs cluttering the panel.
  // Single batch request; falls back to all-paths-pass if the
  // endpoint errors so we don't blank the panel on transient failures.
  if (paths.length) {
    try {
      var existsResp = await api('POST', '/api/portal/files/exists', {paths: paths});
      var existsMap = (existsResp && existsResp.exists) || {};
      paths = paths.filter(function(p){ return existsMap[p] !== false; });
    } catch (_e) { /* keep all paths on error */ }
  }
  var state = window._ltArtifactState[key] = window._ltArtifactState[key] || {paths: [], activePath: '', lastEventCount: 0};
  var hadFirstArtifact = state.paths.length === 0 && paths.length > 0;
  state.paths = paths;
  if (!state.activePath || paths.indexOf(state.activePath) < 0) {
    state.activePath = paths[0] || '';
  }
  if (countEl) countEl.textContent = String(paths.length);

  // Render tabs
  if (paths.length === 0) {
    tabsEl.innerHTML = '';
    if (toolbarEl) toolbarEl.style.display = 'none';
    bodyEl.innerHTML = '<div style="color:var(--text3);font-size:12px;text-align:center;padding:30px 10px;line-height:1.6">' +
      '🪶 No artifacts yet<br><span style="font-size:11px;opacity:0.7">After the agent calls write_file / edit_file,<br>files will appear here for live preview</span>' +
      '</div>';
    return;
  }
  tabsEl.innerHTML = paths.map(function(p) {
    var name = p.split(/[\\/]/).pop();
    var active = (p === state.activePath);
    // Use data-path + onclick reads it via getAttribute. Inline
    // JSON.stringify(p) was getting embedded as `onclick="...,"foo""`
    // which broke the outer attribute when paths contained any quote
    // — silently disabling tab clicks. Data-attr approach is bullet-
    // proof for any path string (quotes, slashes, unicode).
    return '<button data-path="' + esc(p) + '" data-scope="' + esc(scope) + '" data-id="' + esc(id) + '"' +
      ' onclick="_ltArtifactSelectTab(this.getAttribute(\'data-scope\'),this.getAttribute(\'data-id\'),this.getAttribute(\'data-path\'))"' +
      ' title="' + esc(p) + '"' +
      ' style="background:' + (active ? 'var(--surface3)' : 'transparent') + ';' +
        'border:1px solid ' + (active ? 'var(--primary-tint-30)' : 'transparent') + ';' +
        'color:' + (active ? 'var(--text)' : 'var(--text3)') + ';' +
        'padding:4px 10px;border-radius:6px;cursor:pointer;font-size:11px;' +
        'white-space:nowrap;flex-shrink:0;font-weight:' + (active ? '600' : '500') + '">' +
      esc(name) + '</button>';
  }).join('');

  // Render active tab content
  await _ltArtifactRenderActive(scope, id);

  // Auto-open the panel the first time an artifact appears (Q2 design).
  if (hadFirstArtifact && _ltArtifactCollapsed(scope, id)) {
    _ltArtifactSetCollapsed(scope, id, false);
    var panel = document.getElementById('lt-artifact-panel-' + key);
    if (panel && panel.parentNode) {
      var tmp = document.createElement('div');
      tmp.innerHTML = _renderArtifactPanelShell(scope, id);
      panel.parentNode.replaceChild(tmp.firstChild, panel);
      _ltArtifactRefresh(scope, id);
    }
  }
};

window._ltArtifactSelectTab = function(scope, id, path) {
  var key = _ltArtifactKey(scope, id);
  var state = window._ltArtifactState[key];
  if (!state) return;
  state.activePath = path;
  // Re-render tab strip (so active style updates) + content
  _ltArtifactRefresh(scope, id);
};

async function _ltArtifactRenderActive(scope, id) {
  var key = _ltArtifactKey(scope, id);
  var state = window._ltArtifactState[key];
  var bodyEl = document.getElementById('lt-artifact-body-' + key);
  var toolbarEl = document.getElementById('lt-artifact-toolbar-' + key);
  if (!state || !state.activePath || !bodyEl) return;
  var path = state.activePath;
  var kind = _ltKindForExt(path);

  // Toolbar
  if (toolbarEl) {
    toolbarEl.style.display = 'flex';
    var attachUrl = '/api/portal/attachment?path=' + encodeURIComponent(path);
    toolbarEl.innerHTML =
      '<span style="font-size:10px;color:var(--text3);font-family:monospace;flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="' + esc(path) + '">' + esc(path) + '</span>' +
      '<a href="' + attachUrl + '" download title="Download" ' +
        'style="background:transparent;border:1px solid var(--overlay-10);color:var(--text3);' +
          'padding:3px 6px;border-radius:5px;cursor:pointer;display:flex;align-items:center;text-decoration:none">' +
        '<span class="material-symbols-outlined" style="font-size:14px">download</span></a>' +
      '<button onclick="_ltArtifactCopy(\'' + scope + '\',\'' + esc(id) + '\')" title="Copy content" ' +
        'style="background:transparent;border:1px solid var(--overlay-10);color:var(--text3);' +
          'padding:3px 6px;border-radius:5px;cursor:pointer;display:flex;align-items:center">' +
        '<span class="material-symbols-outlined" style="font-size:14px">content_copy</span></button>';
  }

  // Image / video / audio: just embed via attachment URL — no fetch
  if (kind === 'image') {
    bodyEl.innerHTML = '<img src="/api/portal/attachment?path=' + encodeURIComponent(path) +
      '" style="max-width:100%;border-radius:6px" alt="' + esc(path) + '">';
    return;
  }
  if (kind === 'video') {
    bodyEl.innerHTML = '<video controls src="/api/portal/attachment?path=' + encodeURIComponent(path) +
      '" style="max-width:100%;border-radius:6px"></video>';
    return;
  }
  if (kind === 'audio') {
    bodyEl.innerHTML = '<audio controls src="/api/portal/attachment?path=' + encodeURIComponent(path) +
      '" style="width:100%"></audio>';
    return;
  }

  // Markdown / code / text: fetch via existing /api/portal/file-preview endpoint
  bodyEl.innerHTML = '<div style="color:var(--text3);font-size:11px;text-align:center;padding:20px">Loading…</div>';
  try {
    var data = await api('POST', '/api/portal/file-preview', {path: path});
    if (!data || data.error) {
      bodyEl.innerHTML = '<div style="color:var(--error);font-size:11px;padding:10px">Load failed:' + esc((data && data.error) || '?') + '</div>';
      return;
    }
    if (kind === 'markdown' && (data.kind === 'markdown' || data.text)) {
      // Reuse the in-bundle markdown renderer used by chat bubbles
      bodyEl.innerHTML = '<div class="md-preview" style="color:var(--text)">' +
        _renderSimpleMarkdown(data.text || '', null) + '</div>';
      // Cache content for copy
      window._ltArtifactState[_ltArtifactKey(scope, id)]._content = data.text || '';
    } else {
      // Plain text / code / fallback
      var pre = document.createElement('pre');
      pre.style.cssText = 'white-space:pre-wrap;word-break:break-word;font-family:Menlo,Monaco,monospace;' +
        'font-size:11px;margin:0;color:var(--text);background:var(--surface);padding:10px;border-radius:6px';
      pre.textContent = data.text || data.html || '(empty)';
      bodyEl.innerHTML = '';
      bodyEl.appendChild(pre);
      window._ltArtifactState[_ltArtifactKey(scope, id)]._content = data.text || '';
    }
  } catch (e) {
    bodyEl.innerHTML = '<div style="color:var(--error);font-size:11px;padding:10px">Load failed:' + esc(String(e)) + '</div>';
  }
}

window._ltArtifactCopy = function(scope, id) {
  var state = window._ltArtifactState[_ltArtifactKey(scope, id)];
  var text = (state && state._content) || '';
  if (!text) { return; }
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(function() {
      // Visual feedback — flash the toolbar btn
      console.log('Copied ' + text.length + ' chars to clipboard');
    });
  }
};

/* Resolve agent ID → "role-name" display string; falls back to ID */
function agentName(id) {
  if (!id) return 'Unknown';
  var ag = (window._cachedAgents || agents || []).find(function(a){ return a.id === id; });
  return ag ? (ag.role + '-' + ag.name) : id;
}

function showModal(name) {
  document.getElementById('modal-'+name).classList.remove('hidden');
  if (name === 'create-agent') {
    try { loadPersonasForCreate(); } catch(e) { console.warn('loadPersonasForCreate failed', e); }
    // Inject V2 enhancement section if V2 mode is on. Empty otherwise.
    try {
      var slot = document.getElementById('ca-v2-enhancement');
      if (slot && typeof window.v2EnhanceAgentCreateForm === 'function') {
        window.v2EnhanceAgentCreateForm().then(function(html) {
          slot.innerHTML = html || '';
        });
      }
    } catch (e) { console.warn('v2 enhance inject failed', e); }
  }
}
function hideModal(name) {
  document.getElementById('modal-'+name).classList.add('hidden');
  if(name==='create-token'){
    document.getElementById('ct-form').classList.remove('hidden');
    document.getElementById('ct-result').classList.add('hidden');
    document.getElementById('ct-name').value = '';
    document.getElementById('ct-role').value = 'admin';
    document.getElementById('ct-admin-bind').disabled = false;
    // Populate admin binding dropdown
    var sel = document.getElementById('ct-admin-bind');
    sel.innerHTML = '<option value="">-- No binding (legacy) --</option>';
    if (_adminCtx.is_super) {
      api('POST', '/api/portal/admins/list', {}).then(function(data) {
        if (data && data.admins) {
          data.admins.forEach(function(a) {
            var opt = document.createElement('option');
            opt.value = a.user_id;
            opt.textContent = a.display_name + ' (' + a.role + ')';
            sel.appendChild(opt);
          });
        }
      });
    } else if (_adminCtx.user_id) {
      var opt = document.createElement('option');
      opt.value = _adminCtx.user_id;
      opt.textContent = _adminCtx.display_name + ' (' + _adminCtx.role + ')';
      opt.selected = true;
      sel.appendChild(opt);
      sel.disabled = true;
    }
  }
}

function showChangePasswordModal() {
  var html = '<h3 style="margin-bottom:16px">Change Password</h3>';
  html += '<div class="form-group"><label>Current password</label><input id="cpw-old" type="password" placeholder="Enter current password"></div>';
  html += '<div class="form-group"><label>New password</label><input id="cpw-new" type="password" placeholder="At least 6 characters"></div>';
  html += '<div class="form-group"><label>Confirm new password</label><input id="cpw-confirm" type="password" placeholder="Repeat new password"></div>';
  html += '<div class="form-actions"><button class="btn btn-ghost" onclick="closeModal()">Cancel</button>';
  html += '<button class="btn btn-primary" onclick="submitChangePassword()">Save</button></div>';
  showCustomModal(html);
}
async function submitChangePassword() {
  var oldPw = document.getElementById('cpw-old').value;
  var newPw = document.getElementById('cpw-new').value;
  var confirmPw = document.getElementById('cpw-confirm').value;
  if (!oldPw || !newPw) { alert('Please fill all fields'); return; }
  if (newPw.length < 6) { alert('New password must be at least 6 characters'); return; }
  if (newPw !== confirmPw) { alert('Passwords do not match'); return; }
  var data = await api('POST', '/api/portal/admins/change-password', {
    user_id: _adminCtx.user_id, old_password: oldPw, new_password: newPw
  });
  if (data && data.ok) { closeModal(); alert('Password changed successfully'); }
  else { alert((data && data.error) || 'Change failed'); }
}

function logout() {
  // Call backend to clear HttpOnly cookie, then redirect
  fetch('/api/auth/logout', {method: 'POST', credentials: 'same-origin'})
    .finally(function() {
      // Also clear any non-HttpOnly remnants
      document.cookie = 'td_sess=; Path=/; SameSite=Lax; Expires=Thu, 01 Jan 1970 00:00:00 GMT';
      window.location.href = '/';
    });
}

function applyPortalModeRestrictions() {
  // In 'node' mode, hide admin-only sidebar items
  var isNode = portalMode === 'node';
  // Hide/disable Tokens menu (admin only)
  document.querySelectorAll('.nav-item[data-view="tokens"]').forEach(function(el) {
    el.style.display = isNode ? 'none' : '';
  });
  // Mark Settings as read-only in node mode (hide global config edit)
  var configNav = document.querySelector('.nav-item[data-view="config"]');
  if (configNav) {
    if (isNode) {
      configNav.innerHTML = configNav.innerHTML.replace('Settings', 'Settings <span style="font-size:9px;color:var(--text3)">(local)</span>');
    }
  }
  // In node mode, disable "Connect Node" button (can't manage remote nodes)
  if (isNode) {
    document.querySelectorAll('[onclick*="connectNode"]').forEach(function(el) {
      el.style.display = 'none';
    });
  }
  // Show mode indicator in header
  var header = document.querySelector('.portal-header') || document.querySelector('header');
  var modeTag = document.getElementById('portal-mode-tag');
  if (!modeTag && header) {
    modeTag = document.createElement('span');
    modeTag.id = 'portal-mode-tag';
    modeTag.style.cssText = 'font-size:11px;padding:2px 8px;border-radius:4px;margin-left:8px;font-weight:600;';
    header.appendChild(modeTag);
  }
  if (modeTag) {
    if (isNode) {
      modeTag.textContent = 'NODE';
      modeTag.style.background = 'var(--warning)';
      modeTag.style.color = '#000';
    } else {
      modeTag.textContent = 'HUB';
      modeTag.style.background = 'var(--success)';
      modeTag.style.color = '#000';
    }
  }
}

// ============ Refresh ============
var portalMode = 'hub';  // 'hub' or 'node'
async function refresh() {
  try {
    var data = await api('GET', '/api/portal/state');
    if (!data) return;
    agents = data.agents || [];
    window._cachedAgents = agents;  // Cache for robot avatar lookups
    nodes = data.nodes || [];
    try { _refreshNodeSwitcher(); } catch(e) {}
    messages = data.messages || [];
    portalMode = data.portal_mode || 'hub';
    var rawApprovals = data.approvals || {};
    approvals = [].concat(rawApprovals.pending || []).concat(rawApprovals.history || []);

    // Load projects list
    try {
      var pData = await api('GET', '/api/portal/projects');
      if (pData) projects = pData.projects || [];
    } catch(e){}

    // Load admin context
    try {
      var meData = await api('GET', '/api/portal/admin/me');
      if (meData && meData.admin) {
        _adminCtx = {
          user_id: meData.admin.user_id || '',
          username: meData.admin.username || '',
          role: meData.admin.role || '',
          display_name: meData.admin.display_name || '',
          agent_ids: meData.admin.agent_ids || [],
          is_super: meData.admin.role === 'superAdmin',
        };
      } else {
        // Token-based login — treat as superAdmin
        _adminCtx = { user_id: '', username: 'admin', role: 'superAdmin', display_name: 'Admin', agent_ids: [], is_super: true };
      }
    } catch(e) {
      _adminCtx = { user_id: '', username: 'admin', role: 'superAdmin', display_name: 'Admin', agent_ids: [], is_super: true };
    }
    // Mirror onto window so _isSuperAdmin() / _isAdmin() / _isUser()
    // helpers work from anywhere without plumbing _adminCtx through.
    // NB: store under _currentRole / _currentUid (NOT _currentUserRole)
    // because a function _currentUserRole() reads this and a same-named
    // string would shadow it — crashed Settings page with "is not a
    // function". Same reason we keep function names and state names
    // clearly distinct here.
    window._currentRole = _adminCtx.role || '';
    window._currentUid  = _adminCtx.user_id || '';
    // Update sidebar footer with admin info
    var footerUser = document.getElementById('footer-username');
    var footerRole = document.getElementById('footer-role');
    if (footerUser) footerUser.textContent = _adminCtx.display_name || _adminCtx.username || 'admin';
    if (footerRole) { footerRole.textContent = _adminCtx.role || 'admin'; footerRole.style.background = _adminCtx.is_super ? 'var(--primary-tint-15)' : 'rgba(63,185,80,0.15)'; footerRole.style.color = _adminCtx.is_super ? 'var(--primary)' : 'var(--success)'; }
    // Admin management has been merged into Settings → 用户管理.
    // The old standalone nav item was removed; no legacy element to
    // show/hide here anymore.

    // Role-based sidebar filter. Regular users can only work with
    // their own agents — anything else is clutter. Hide tools/approvals,
    // integrations, system settings for role=user. Backend still rejects
    // any direct API calls to these via permission checks.
    if (_adminCtx.role === 'user') {
      ['projects', 'tools-approvals', 'integrations', 'settings-hub'].forEach(function(view) {
        var item = document.querySelector('.nav-item[data-view="' + view + '"]');
        if (item) item.style.display = 'none';
      });
    }
    // Show change password button for logged-in admin users
    var changePwBtn = document.getElementById('btn-change-pw');
    if (changePwBtn) changePwBtn.style.display = _adminCtx.user_id ? '' : 'none';

    // Apply portal mode UI restrictions
    applyPortalModeRestrictions();

    // Update agent count badge in sidebar
    var agentBadge = document.getElementById('agent-count-badge');
    if (agentBadge) agentBadge.textContent = agents.length;

    var nodeCountEl = document.getElementById('node-count');
    if (nodeCountEl) nodeCountEl.textContent = nodes.length;
    var pendingApprovals = approvals.filter(function(a){ return a.status === 'pending'; }).length;
    var approvalBadge = document.getElementById('approval-badge');
    var globalNotif = document.getElementById('global-notif-badge');
    if (globalNotif) {
      if (pendingApprovals > 0) { globalNotif.textContent = pendingApprovals; globalNotif.classList.remove('hidden'); }
      else { globalNotif.classList.add('hidden'); }
    }
    if (approvalBadge) {
      if (pendingApprovals > 0) {
        approvalBadge.textContent = pendingApprovals;
        approvalBadge.classList.remove('hidden');
      } else {
        approvalBadge.classList.add('hidden');
      }
    }

    // Pending manual reviews → dashboard sidebar badge
    try {
      var prData = await api('GET', '/api/portal/pending-reviews');
      var prCount = prData ? (prData.count || 0) : 0;
      var dashBadge = document.getElementById('dashboard-badge');
      if (dashBadge) {
        if (prCount > 0) {
          dashBadge.textContent = prCount;
          dashBadge.classList.remove('hidden');
          dashBadge.title = prCount + ' step(s) waiting for manual review';
        } else {
          dashBadge.classList.add('hidden');
        }
      }
      window._pendingReviews = prData || { count: 0, items: [] };
    } catch(e) {}

    buildAgentOptions();
    populateNodeSelect();
    renderCurrentView();
    // On login / refresh, probe for paused tasks waiting to resume.
    try { _checkResumableTasks(); } catch(_e) {}
  } catch(e) { console.error('refresh error', e); }
}

// ── Resume banner (M4) ────────────────────────────────────────────────
// Fires on refresh(). If any ConversationTask is PAUSED (previous
// server process died mid-execution, or user closed the tab), show a
// sticky top-of-page banner with a Continue button.

var _CT_PAUSED = (typeof window.CT_STATUS === 'object' && window.CT_STATUS)
  ? window.CT_STATUS.PAUSED : 'paused';
var _BANNER_ID = 'resume-banner';

async function _checkResumableTasks() {
  try {
    var r = await api('GET', '/api/portal/conversation-tasks/resumable');
    if (!r || !r.tasks) return;
    var paused = r.tasks.filter(function(t) { return t.status === _CT_PAUSED; });
    _renderResumeBanner(paused);
  } catch (e) { /* silent */ }
}

// ── _renderResumeBanner — decomposed into small pieces ───────────────

function _renderResumeBanner(tasks) {
  var existing = document.getElementById(_BANNER_ID);
  if (existing) existing.remove();
  if (!tasks || !tasks.length) return;

  var cap = window.CT_BANNER_TASK_DISPLAY_CAP || 5;
  var shown = tasks.slice(0, cap);
  var overflow = tasks.length - shown.length;

  var bar = document.createElement('div');
  bar.id = _BANNER_ID;
  bar.style.cssText =
    'position:fixed;top:8px;right:8px;z-index:5000;' +
    'max-width:460px;background:#1e293b;border:1px solid #f59e0b;' +
    'border-radius:10px;padding:14px 16px;' +
    'box-shadow:0 6px 24px rgba(0,0,0,0.4);font-size:12px';
  bar.innerHTML =
    _renderResumeBannerHeader(tasks.length) +
    shown.map(_renderResumeBannerRow).join('') +
    _renderResumeBannerOverflow(overflow);
  document.body.appendChild(bar);
}

function _renderResumeBannerHeader(taskCount) {
  return '<div style="display:flex;align-items:flex-start;gap:10px;' +
    'margin-bottom:10px">' +
      '<span style="font-size:20px">⏸</span>' +
      '<div style="flex:1">' +
        '<div style="color:#f59e0b;font-weight:700;margin-bottom:2px">' +
          taskCount + ' 个任务未完成 — 服务重启或断线时中断</div>' +
        '<div style="color:var(--text3);font-size:10px">' +
          '可以从上次断开的地方继续，或直接关闭。</div>' +
      '</div>' +
      '<button onclick="document.getElementById(\'' + _BANNER_ID +
        '\').remove()" ' +
        'style="background:none;border:none;color:var(--text3);' +
        'cursor:pointer;font-size:16px;padding:0 4px">×</button>' +
    '</div>';
}

function _bannerRowProgress(task) {
  var steps = task.steps || [];
  if (!steps.length) return '(no plan)';
  var doneCount = (typeof window._ctCountDoneSteps === 'function')
    ? window._ctCountDoneSteps(steps)
    : steps.filter(function(s){ return s.status === 'done'; }).length;
  return doneCount + '/' + steps.length + ' steps done';
}

function _renderResumeBannerRow(task) {
  var progress = _bannerRowProgress(task);
  return '<div style="display:flex;justify-content:space-between;' +
    'align-items:center;gap:8px;padding:6px 0;' +
    'border-top:1px solid var(--overlay-5)">' +
      '<div style="flex:1;min-width:0">' +
        '<div style="color:var(--text);font-weight:600;' +
          'overflow:hidden;text-overflow:ellipsis;white-space:nowrap">' +
          esc(task.title || task.intent) + '</div>' +
        '<div style="color:var(--text3);font-size:10px">' +
          progress + ' · agent ' + esc((task.agent_id || '').slice(0, 6)) +
        '</div>' +
      '</div>' +
      '<button class="btn btn-primary btn-sm" ' +
        'style="font-size:11px;white-space:nowrap" ' +
        'onclick="_resumeConversationTask(\'' + esc(task.id) + '\')">继续</button>' +
      '<button class="btn btn-ghost btn-sm" ' +
        'style="font-size:11px;color:var(--text3)" ' +
        'onclick="_dismissConversationTask(\'' + esc(task.id) + '\')">丢弃</button>' +
    '</div>';
}

function _renderResumeBannerOverflow(overflowCount) {
  if (overflowCount <= 0) return '';
  return '<div style="color:var(--text3);font-size:10px;' +
    'padding-top:6px;text-align:center">+ ' + overflowCount + ' more</div>';
}

// Show modal with task details and let user choose: 继续 / 放弃
function _showResumeConfirm(task) {
  var existing = document.getElementById('resume-confirm-modal');
  if (existing) existing.remove();

  var steps = task.steps || [];
  var done = steps.filter(function(s){ return s.status === 'done'; });
  var pending = steps.filter(function(s){ return s.status !== 'done'; });

  // Build inner HTML in pieces — no nested map() inside string concat.
  var intentText = (task.intent || task.title || '').slice(0, 600);
  if ((task.intent || '').length > 600) intentText += '…';

  var doneRows = done.map(function(s){
    return '<div style="font-size:12px;color:var(--text2);padding:2px 8px;'
      + 'border-left:2px solid #10b981;margin:2px 0">'
      + esc((s.goal || '').slice(0, 80))
      + '</div>';
  }).join('');

  var pendingRows = pending.slice(0, 5).map(function(s){
    var hint = s.tool_hint
      ? ' <span style="color:var(--text3);font-size:10px">(' + esc(s.tool_hint) + ')</span>'
      : '';
    return '<div style="font-size:12px;color:var(--text);padding:2px 8px;'
      + 'border-left:2px solid #f59e0b;margin:2px 0">'
      + esc((s.goal || '').slice(0, 80))
      + hint
      + '</div>';
  }).join('');
  if (pending.length > 5) {
    pendingRows += '<div style="font-size:11px;color:var(--text3);padding-left:8px">... +'
      + (pending.length - 5) + ' 更多</div>';
  }

  var stepsBlock = '';
  if (steps.length) {
    stepsBlock = '<div style="margin-bottom:8px;font-size:12px;color:var(--text2)">进度: <b>'
      + done.length + ' / ' + steps.length + '</b> 步已完成</div>';
    if (done.length) {
      stepsBlock += '<div style="margin-bottom:8px">'
        + '<div style="font-size:11px;color:#10b981;margin-bottom:4px">✓ 已完成</div>'
        + doneRows + '</div>';
    }
    if (pending.length) {
      stepsBlock += '<div style="margin-bottom:8px">'
        + '<div style="font-size:11px;color:#f59e0b;margin-bottom:4px">○ 待完成</div>'
        + pendingRows + '</div>';
    }
  } else {
    stepsBlock = '<div style="color:var(--text3);font-size:12px;margin-bottom:12px">(暂无计划步骤)</div>';
  }

  // Header text + icon + status badge vary by status
  var headerIcon = '⏸';
  var headerTitle = '上次任务未完成';
  var headerSub = '是否继续从断点处推进?';
  var statusBadge = '';
  if (task.status === 'awaiting_user') {
    headerIcon = '✅';
    headerTitle = 'Agent 已交付';
    headerSub = '请确认是否完成,如需修改请放弃后重新发起';
    statusBadge = '<span style="display:inline-block;padding:2px 8px;font-size:10px;'
      + 'background:rgba(16,185,129,0.15);color:#10b981;border-radius:8px;margin-left:6px">'
      + 'agent 已交付 · 待确认</span>';
  } else if (task.status === 'failed') {
    headerIcon = '⚠️';
    headerTitle = '任务执行出错';
    headerSub = '可以从断点重新尝试,或放弃此任务';
    statusBadge = '<span style="display:inline-block;padding:2px 8px;font-size:10px;'
      + 'background:rgba(239,68,68,0.15);color:#ef4444;border-radius:8px;margin-left:6px">'
      + '出错中断</span>';
  } else if (task.status === 'running') {
    headerIcon = '⏳';
    headerTitle = '任务正在执行';
    headerSub = '可以查看当前进度';
    statusBadge = '<span style="display:inline-block;padding:2px 8px;font-size:10px;'
      + 'background:rgba(59,130,246,0.15);color:#3b82f6;border-radius:8px;margin-left:6px">'
      + '运行中</span>';
  } else {
    statusBadge = '<span style="display:inline-block;padding:2px 8px;font-size:10px;'
      + 'background:rgba(245,158,11,0.15);color:#f59e0b;border-radius:8px;margin-left:6px">'
      + '已暂停</span>';
  }

  var headerBlock = '<div style="display:flex;align-items:center;gap:10px;margin-bottom:14px">'
    + '<span style="font-size:24px">' + headerIcon + '</span>'
    + '<div style="flex:1">'
    + '<h3 style="margin:0;font-size:16px;font-weight:700">'
    +   esc(headerTitle) + statusBadge + '</h3>'
    + '<div style="color:var(--text3);font-size:12px;margin-top:2px">'
    +   esc(headerSub) + '</div>'
    + '</div></div>';

  var intentBlock = '<div style="background:var(--surface);border:1px solid var(--border);'
    + 'border-radius:8px;padding:12px;margin-bottom:12px">'
    + '<div style="font-size:11px;color:var(--text3);margin-bottom:6px">原始请求</div>'
    + '<div style="font-size:13px;color:var(--text);line-height:1.5;'
    + 'max-height:150px;overflow-y:auto;white-space:pre-wrap">'
    + esc(intentText)
    + '</div></div>';

  // Button row depends on task.status:
  //   awaiting_user → "确认完成" / "放弃" / "关闭"
  //   running       → only "关闭" (task still in flight)
  //   paused/failed → "继续" / "放弃" / "取消"
  var btnRow;
  if (task.status === 'awaiting_user') {
    btnRow = '<div style="display:flex;gap:8px;justify-content:flex-end;margin-top:18px">'
      + '<button class="btn btn-ghost btn-sm" onclick="_resumeConfirmCancel()">关闭</button>'
      + '<button class="btn btn-ghost btn-sm" style="color:var(--error)" '
      +   'onclick="_resumeConfirmDiscard(\'' + esc(task.id) + '\')">放弃</button>'
      + '<button class="btn btn-primary btn-sm" '
      +   'onclick="_resumeConfirmComplete(\'' + esc(task.id) + '\')">✓ 确认完成</button>'
      + '</div>';
  } else if (task.status === 'running') {
    btnRow = '<div style="display:flex;gap:8px;justify-content:flex-end;margin-top:18px">'
      + '<button class="btn btn-primary btn-sm" onclick="_resumeConfirmCancel()">关闭</button>'
      + '</div>';
  } else {
    btnRow = '<div style="display:flex;gap:8px;justify-content:flex-end;margin-top:18px">'
      + '<button class="btn btn-ghost btn-sm" onclick="_resumeConfirmCancel()">Cancel</button>'
      + '<button class="btn btn-ghost btn-sm" style="color:var(--error)" '
      +   'onclick="_resumeConfirmDiscard(\'' + esc(task.id) + '\')">放弃此任务</button>'
      + '<button class="btn btn-primary btn-sm" '
      +   'onclick="_resumeConfirmContinue(\'' + esc(task.id) + '\')">▶ 继续</button>'
      + '</div>';
  }

  var modal = document.createElement('div');
  modal.id = 'resume-confirm-modal';
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.6);'
    + 'z-index:10001;display:flex;align-items:center;justify-content:center;padding:20px';
  modal.innerHTML = '<div style="background:var(--bg);border:1px solid var(--border);'
    + 'border-radius:12px;padding:24px;max-width:560px;width:96%;max-height:88vh;overflow:auto">'
    + headerBlock + intentBlock + stepsBlock + btnRow
    + '</div>';

  document.body.appendChild(modal);
  // Click outside to cancel
  modal.addEventListener('click', function(e){
    if (e.target === modal) _resumeConfirmCancel();
  });
}

function _resumeConfirmCancel() {
  var m = document.getElementById('resume-confirm-modal');
  if (m) m.remove();
}

async function _resumeConfirmContinue(taskId) {
  var btn = document.querySelector('#resume-confirm-modal .btn-primary');
  if (btn) {
    btn.disabled = true;
    btn.textContent = '正在恢复…';
  }
  try {
    var r = await api('POST',
      '/api/portal/conversation-task/' + taskId + '/resume');
    if (r && r.task_id) {
      _resumeConfirmCancel();
      _checkResumableTasks();
      // Switch to that agent's chat to watch the resumed task
      if (r.agent_id && typeof window.showAgentView === 'function') {
        try { window.showAgentView(r.agent_id, null); } catch(e){}
      }
      if (window._toast) window._toast('Task resumed, Agent is continuing', 'success');
    } else {
      alert('Continue failed:' + (r && r.error ? r.error : 'unknown'));
      if (btn) { btn.disabled = false; btn.textContent = '▶ Resume'; }
    }
  } catch (e) {
    alert('Continue failed:' + e.message);
    if (btn) { btn.disabled = false; btn.textContent = '▶ Resume'; }
  }
}

async function _resumeConfirmDiscard(taskId) {
  if (!confirm('确认放弃这个任务? 不会删除历史聊天,只是不再续跑。')) return;
  try {
    // Mark as cancelled (status), then delete the row
    await fetch('/api/portal/conversation-task/' + taskId + '/discard', {
      method: 'POST', credentials: 'same-origin',
    });
    await fetch('/api/portal/conversation-task/' + taskId, {
      method: 'DELETE', credentials: 'same-origin',
    });
    _resumeConfirmCancel();
    _checkResumableTasks();
  } catch (e) {
    alert('Abort failed:' + e.message);
  }
}

async function _resumeConfirmComplete(taskId) {
  // User confirms the task is fully done — flips AWAITING_USER → DONE
  // and removes it from the resume banner. History stays in chat for audit.
  try {
    var r = await api('POST',
      '/api/portal/conversation-task/' + taskId + '/confirm-done');
    if (r && r.ok) {
      _resumeConfirmCancel();
      _checkResumableTasks();
      if (window._toast) window._toast('Marked as done', 'success');
    } else {
      alert('Confirm failed:' + (r && r.error ? r.error : 'unknown'));
    }
  } catch (e) {
    alert('Confirm failed:' + e.message);
  }
}

// Banner buttons now open the confirm dialog instead of acting directly.
async function _resumeConversationTask(taskId) {
  // Look up the task in the cached banner data
  try {
    var r = await api('GET', '/api/portal/conversation-tasks/resumable');
    var task = (r && r.tasks || []).find(function(t){ return t.id === taskId; });
    if (!task) {
      alert('Task record not found');
      return;
    }
    _showResumeConfirm(task);
  } catch (e) {
    alert('Cannot load task details:' + e.message);
  }
}

async function _dismissConversationTask(taskId) {
  if (!confirm('确认丢弃此任务?')) return;
  try {
    await fetch('/api/portal/conversation-task/' + taskId + '/discard', {
      method: 'POST', credentials: 'same-origin',
    });
    await fetch('/api/portal/conversation-task/' + taskId, {
      method: 'DELETE', credentials: 'same-origin',
    });
    _checkResumableTasks();
  } catch (e) { /* silent */ }
}

window._resumeConversationTask = _resumeConversationTask;
window._dismissConversationTask = _dismissConversationTask;
window._resumeConfirmCancel = _resumeConfirmCancel;
window._resumeConfirmContinue = _resumeConfirmContinue;
window._resumeConfirmDiscard = _resumeConfirmDiscard;
window._resumeConfirmComplete = _resumeConfirmComplete;

async function refreshSidebar() {
  // Lightweight refresh: update agent status in sidebar without re-rendering current view
  try {
    var data = await api('GET', '/api/portal/state');
    if (!data) return;
    agents = data.agents || [];
    nodes = data.nodes || [];
    try { _refreshNodeSwitcher(); } catch(e) {}
    messages = data.messages || [];
    var rawApprovals = data.approvals || {};
    approvals = [].concat(rawApprovals.pending || []).concat(rawApprovals.history || []);
    var agentBadge2 = document.getElementById('agent-count-badge');
    if (agentBadge2) agentBadge2.textContent = agents.length;
    var nodeCountEl2 = document.getElementById('node-count');
    if (nodeCountEl2) nodeCountEl2.textContent = nodes.length;
    var pendingApprovals = approvals.filter(function(a){ return a.status === 'pending'; }).length;
    var approvalBadge = document.getElementById('approval-badge');
    if (approvalBadge) {
      if (pendingApprovals > 0) { approvalBadge.textContent = pendingApprovals; approvalBadge.classList.remove('hidden'); }
      else { approvalBadge.classList.add('hidden'); }
    }
    buildAgentOptions();
    // Update project count and global projects list
    try {
      var pData = await api('GET', '/api/portal/projects');
      if (pData) projects = pData.projects || [];
      var projCount = document.getElementById('project-count');
      if (projCount && pData) projCount.textContent = projects.length;
    } catch(e){}
    // Per-agent heartbeat refreshers. Previously fired every 15s
    // unconditionally → /api/portal/agent/<id>/events was hit 3× per
    // tick (loadAgentEventLog + _pollChatNewMessages + the artifact
    // refresh inside loadAgentEventLog), each pulling 80–400 KB +
    // doing markdown re-renders for agents with long histories. On
    // 小新 (coder, 500+ events) this stacked into a multi-second
    // freeze every 15s. Now: skip entirely when the agent is idle —
    // there's nothing new to surface. Re-enabled when the agent goes
    // busy (active task pushes new events worth showing).
    // Initial load (showAgentView → renderAgentChatTech) still fires
    // these once on entry; that's where freshness comes from.
    if (currentAgent) {
      var _ag = (agents || []).find(function(a){ return a.id === currentAgent; });
      var _isBusy = _ag && (_ag.status === 'busy' || _ag.status === 'running');
      if (_isBusy) {
        loadAgentEventLog(currentAgent);
        try { _pollChatNewMessages(currentAgent); } catch(e) {}
      }
      // Task queue refresh stays — it doesn't hit /events and is
      // needed so failed tasks drop off without navigating away.
      try {
        if (typeof window.isV2Mode === 'function' && window.isV2Mode() &&
            typeof window.loadConversationTasksIntoQueue === 'function') {
          window.loadConversationTasksIntoQueue(currentAgent);
        }
      } catch (_e) { /* silent */ }
    }
  } catch(e) {}
}

// ============ Navigation ============
function showView(view, navEl) {
  // Clean up agent-specific timers when navigating away
  if (currentView === 'agent') _clearAllStepsTimers();
  currentView = view;
  currentAgent = null;
  document.querySelectorAll('.nav-item').forEach(n => n.classList.remove('active'));
  if (navEl) navEl.classList.add('active');
  renderCurrentView();
}

function showAgentView(agentId, navEl) {
  // Clean up previous agent timers before switching
  _clearAllStepsTimers();
  currentView = 'agent';
  currentAgent = agentId;
  document.querySelectorAll('.nav-item').forEach(n => n.classList.remove('active'));
  if (navEl) navEl.classList.add('active');
  renderCurrentView();
}

function renderCurrentView() {
  _renderEpoch++;
  const titleEl = document.getElementById('view-title');
  const actionsEl = document.getElementById('topbar-actions');
  const c = document.getElementById('content');
  // Reset inline styles set by views that turn #content into a flex
  // column (renderAgentChat / renderAgentChatTech / project detail).
  // Without this, navigating BACK to a normal block-flow view (e.g.
  // Dashboard) leaves #content as display:flex height:100% — its
  // children become flex items sharing viewport height, squeezing
  // panels like the Active Agents grid down to a fraction of their
  // natural height ("agent 卡片显示不全 / 缩进去了" bug).
  c.style.padding = '24px';
  c.style.display = '';
  c.style.flexDirection = '';
  c.style.height = '';
  actionsEl.innerHTML = '';
  // Tech mode: ALL add/action buttons live in each page's hero, not
  // in the topbar — keeps actions context-bound to the current page
  // so they don't leak across hub sub-tabs (e.g. "Add Channel" was
  // showing on Inbox tab because it lived in the topbar).
  var _techRcv = false;
  try { _techRcv = localStorage.getItem('tudou_theme') === 'tech'; } catch (e) {}

  try {
  switch(currentView) {
    case 'dashboard': {
      titleEl.textContent = t('page.dashboard', 'Overview');
      actionsEl.innerHTML = '<span style="font-size:11px;color:var(--text3);margin-right:8px">Tudou Claws v0.1</span><span style="padding:3px 8px;background:var(--primary-tint-10);color:var(--primary);border-radius:4px;font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px">Active</span>';
      renderDashboard();
      break;
    }
    case 'agent': {
      var agentObj = agents.find(function(a){ return a.id === currentAgent; });
      titleEl.textContent = agentObj ? (agentObj.role||'general') + '-' + agentObj.name : 'Agent';
      // Tech mode: action buttons render inline in renderAgentChatTech's
      // header. Skip the topbar injection so the buttons aren't
      // duplicated (and the topbar itself is hidden in tech).
      if (!_techRcv) actionsEl.innerHTML =
          '<button class="btn btn-ghost btn-sm" onclick="editAgentProfile(\''+currentAgent+'\')"><span class="material-symbols-outlined" style="font-size:16px">edit</span> Settings</button>'
        + '<button class="btn btn-ghost btn-sm" id="agent-inbox-btn" onclick="_showAgentInboxModal(\''+currentAgent+'\')"><span class="material-symbols-outlined" style="font-size:16px">inbox</span> ' + window.t('chat.inbox', 'Inbox') + '<span class="badge notification hidden" id="agent-inbox-btn-badge" style="margin-left:6px">0</span></button>'
        + '<button class="btn btn-ghost btn-sm" id="agent-ckpt-btn" onclick="_showAgentCheckpointsModal(\''+currentAgent+'\')"><span class="material-symbols-outlined" style="font-size:16px">bookmark</span> ' + window.t('chat.checkpoints', 'Checkpoints') + '<span class="badge notification hidden" id="agent-ckpt-btn-badge" style="margin-left:6px">0</span></button>'
        + '<button class="btn btn-ghost btn-sm" onclick="clearAgent(\''+currentAgent+'\')"><span class="material-symbols-outlined" style="font-size:16px">delete_sweep</span> Clear Chat</button>'
        + '<button class="btn btn-danger btn-sm" onclick="deleteAgent(\''+currentAgent+'\')"><span class="material-symbols-outlined" style="font-size:16px">delete</span> Delete</button>';
      // Refresh per-agent inbox + checkpoint counts on the buttons.
      try { _refreshAgentHeaderCounts(currentAgent); } catch(_){}
      // PERF/UX: if the chat DOM for this agent is already mounted, skip the full
      // re-render so we don't wipe streaming bubbles / approval cards / input focus.
      // Partial refreshers (loadAgentEventLog, loadExecutionSteps, loadAgentRuntimeStats)
      // take care of keeping side panels fresh.
      var existingChat = document.getElementById('chat-msgs-' + currentAgent);
      if (existingChat) {
        try { loadAgentEventLog(currentAgent); } catch(e) {}
        try { _pollChatNewMessages(currentAgent); } catch(e) {}
        try { loadExecutionSteps(currentAgent); } catch(e) {}
        try { loadInterAgentMessages(currentAgent); } catch(e) {}
        try { loadAgentRuntimeStats(currentAgent); } catch(e) {}
        try { loadTasks(currentAgent); } catch(e) {}
        try { _ltArtifactRefresh('agent', currentAgent); } catch(_){}
        break;
      }
      renderAgentChat(currentAgent);
      // Initial artifact panel load (after DOM mount). Slight delay so
      // the panel divs exist by the time refresh runs.
      setTimeout(function(){
        try { _ltArtifactRefresh('agent', currentAgent); } catch(_){}
        try { _refreshPreprocessorBadge(currentAgent); } catch(_){}
      }, 100);
      break;
    }
    case 'nodes': {
      titleEl.textContent = t('page.nodes', 'Nodes');
      // "+ Connect Node" button now lives inside renderNodes() page
      // header. No topbar action — avoids double button.
      renderNodes();
      break;
    }
    case 'messages': {
      titleEl.textContent = t('page.messages', 'Messages');
      renderMessages();
      break;
    }
    case 'channels': {
      titleEl.textContent = t('page.channels', 'Channels');
      if (!_techRcv) actionsEl.innerHTML = '<button class="btn btn-primary btn-sm" onclick="showModal(\'add-channel\')"><span class="material-symbols-outlined" style="font-size:16px">add</span> Add Channel</button>';
      renderChannels();
      break;
    }
    case 'approvals': {
      titleEl.textContent = t('nav.toolsApprovals', 'Tool Approvals & Policies');
      renderApprovals();
      break;
    }
    case 'audit': {
      titleEl.textContent = t('page.auditLog', 'Audit Log');
      renderAudit();
      break;
    }
    case 'providers': {
      titleEl.textContent = t('page.llmProviders', 'LLM Providers');
      renderProviders();
      break;
    }
    case 'tokens': {
      titleEl.textContent = t('page.apiTokens', 'API Tokens');
      renderTokens();
      break;
    }
    case 'config': {
      titleEl.textContent = t('page.config', 'Configuration');
      renderConfig();
      break;
    }
    case 'nodeconfig': {
      titleEl.textContent = t('page.nodeConfig', 'Node Configuration');
      renderNodeConfig();
      break;
    }
    case 'templates': {
      titleEl.textContent = t('nav.rolesSkills', 'Domains');
      renderTemplateLibrary();
      break;
    }
    case 'scheduler': {
      titleEl.textContent = t('page.scheduled', 'Scheduled Tasks');
      if (!_techRcv) actionsEl.innerHTML = '<button class="btn btn-primary btn-sm" onclick="showCreateJob()"><span class="material-symbols-outlined" style="font-size:16px">add</span> New Job</button>';
      renderScheduler();
      break;
    }
    case 'mcpconfig': {
      titleEl.textContent = t('page.mcpConfig', 'MCP Configuration');
      if (!_techRcv) actionsEl.innerHTML = '<button class="btn btn-primary btn-sm" onclick="showAddMCP()"><span class="material-symbols-outlined" style="font-size:16px">add</span> Add MCP</button>';
      renderMCPConfig();
      break;
    }
    case 'projects': {
      titleEl.textContent = t('nav.projects', 'Projects & Tasks');
      renderProjectsHub();
      break;
    }
    case 'project_detail': {
      titleEl.textContent = 'Project';
      renderProjectDetail(currentProject);
      break;
    }
    case 'orchestration': {
      titleEl.textContent = t('nav.orchestration', 'Orchestration');
      actionsEl.innerHTML =
          '<button class="btn btn-sm" onclick="showView(\'canvas\', null)"><span class="material-symbols-outlined" style="font-size:14px">account_tree</span> Canvas</button>'
        + '<button class="btn btn-sm" onclick="renderOrchestrationPage()"><span class="material-symbols-outlined" style="font-size:14px">refresh</span> Refresh</button>';
      renderOrchestrationPage();
      break;
    }
    case 'canvas': {
      titleEl.textContent = t('nav.canvas', 'Canvas');
      actionsEl.innerHTML = '<button class="btn btn-sm" onclick="showView(\'orchestration\', null)"><span class="material-symbols-outlined" style="font-size:14px">arrow_back</span> Back to Orchestration</button>';
      renderCanvasPage();
      break;
    }
    case 'workflows': {
      titleEl.textContent = t('page.workflows', 'Workflows');
      if (!_techRcv) actionsEl.innerHTML = '<button class="btn btn-primary btn-sm" onclick="showCreateWorkflowModal()"><span class="material-symbols-outlined" style="font-size:16px">add</span> New Workflow</button>';
      renderWorkflows();
      break;
    }
    case 'self-improvement': {
      titleEl.textContent = t('page.selfImprove', 'Agent Self-Improvement');
      try { renderSelfImprovement(); } catch(re) { console.error('renderSelfImprovement error:', re); c.innerHTML = '<div style="color:var(--error);padding:20px">Self-Improvement render error: '+re.message+'</div>'; }
      break;
    }
    case 'agents-list': {
      titleEl.textContent = t('nav.agents', 'Agents');
      actionsEl.innerHTML = '';
      renderAgentsList();
      break;
    }
    // NOTE: 'inbox' / 'checkpoints' as top-level views were removed —
    // they now live as modal buttons on the agent detail page,
    // scoped to the currently-viewed agent.
    case 'settings': {
      titleEl.textContent = t('nav.settings', 'Settings');
      renderSettingsPage();
      break;
    }
    // 'admin-manage' view removed — users are now managed under
    // Settings → 用户管理. Route any legacy links there.
    case 'admin-manage': {
      showView('settings-hub', null);
      break;
    }
    case 'knowledge-memory': {
      titleEl.textContent = t('nav.knowledge', 'Knowledge & Memory');
      renderKnowledgeMemoryHub();
      break;
    }
    case 'roles-skills': {
      titleEl.textContent = t('nav.rolesSkills', 'Roles & Skills');
      renderRolesSkillsHub();
      break;
    }
    case 'tools-approvals': {
      titleEl.textContent = t('nav.toolsApprovals', 'Tools & Approvals');
      renderToolsApprovalsHub();
      break;
    }
    case 'integrations': {
      titleEl.textContent = t('nav.integrations', 'Integrations & Notifications');
      // Add Channel is rendered inline by renderChannels and only on
      // the Channels tab — this prevents the button from leaking into
      // the Inbox tab when the user switches sub-tabs.
      var _techIg = false;
      try { _techIg = localStorage.getItem('tudou_theme') === 'tech'; } catch (e) {}
      actionsEl.innerHTML = _techIg
        ? ''
        : '<button class="btn btn-primary btn-sm" onclick="showModal(\'add-channel\')"><span class="material-symbols-outlined" style="font-size:16px">add</span> Add Channel</button>';
      renderIntegrationsHub();
      break;
    }
    case 'settings-hub': {
      titleEl.textContent = t('nav.settings', 'System Settings');
      renderSettingsHub();
      break;
    }
    case 'cultivation': {
      titleEl.textContent = t('nav.cultivation', 'Agent 专家养成系统');
      var _techCv = false;
      try { _techCv = localStorage.getItem('tudou_theme') === 'tech'; } catch (e) {}
      actionsEl.innerHTML = _techCv
        ? ''
        : '<button class="btn btn-primary btn-sm" onclick="showCreateSpecialtyTemplate()"><span class="material-symbols-outlined" style="font-size:16px">add</span> 新建养成模板</button>';
      renderCultivationHub();
      break;
    }
    default: {
      c.innerHTML = '<div style="color:var(--text3);padding:40px;text-align:center">View "'+esc(currentView)+'" not found</div>';
      break;
    }
  }
  } catch(err) { console.error('renderCurrentView error:', err); c.innerHTML = '<div style="color:var(--error);padding:20px">Render error: '+err.message+'</div>'; }
}

