// ── renderSettingsHub — tech port ──
function renderSettingsHubTech() {
  var c = document.getElementById('content');
  if (!c) return;
  // Match legacy hub feature parity — branding / system / config /
  // providers / mcp / nodeconfig / nodes / audit / permissions / tokens
  var tabs = [
    { id: 'branding',    label: 'Branding',     icon: 'palette' },
    { id: 'rules',       label: 'Rule Engine',  icon: 'gavel' },
    { id: 'system',      label: 'System',       icon: 'tune' },
    { id: 'config',      label: 'Global Config',icon: 'settings' },
    { id: 'providers',   label: 'LLM Providers',icon: 'cloud_queue' },
    { id: 'mcp',         label: 'MCP Servers',  icon: 'extension' },
    // 'llm_tiers' tab hidden — replaced by per-agent LLM Router. Render
    // function (renderLLMTiers) and dispatch case kept below for any
    // deep-links / external nav.
    // { id: 'llm_tiers',   label: 'LLM Tiers',    icon: 'stacked_line_chart' },
    { id: 'nodeconfig',  label: 'Node Config',  icon: 'tune' },
    { id: 'nodes',       label: 'Worker Nodes', icon: 'device_hub' },
    { id: 'audit',       label: 'Audit Log',    icon: 'assignment' },
    { id: 'tokens',      label: 'API Tokens',   icon: 'key' },
    { id: 'admin',       label: 'Permissions',  icon: 'admin_panel_settings' },
  ];
  var r = _techHubPage({ label: 'Command Center', title: 'System Settings' }, tabs, 'settings');
  c.innerHTML = r.html;
  var sc = document.getElementById(r.bodyId);
  if (!sc) return;
  var _orig = document.getElementById('content');
  sc.id = 'content'; if (_orig !== sc) _orig.id = 'content-outer';
  try {
    if (r.current === 'branding') {
      if (typeof renderBrandingSettingsTech === 'function') renderBrandingSettingsTech(sc);
      else if (typeof renderBrandingSettings === 'function') renderBrandingSettings(sc);
    } else if (r.current === 'rules') {
      if (typeof renderRuleEngine === 'function') renderRuleEngine(sc);
    } else if (r.current === 'system') {
      if (typeof renderSystemSettings === 'function') renderSystemSettings(sc);
    } else if (r.current === 'config') {
      if (typeof renderConfig === 'function') renderConfig(sc);
    } else if (r.current === 'providers') {
      if (typeof renderProvidersTech === 'function') renderProvidersTech(sc);
      else if (typeof renderProviders === 'function') renderProviders(sc);
    } else if (r.current === 'mcp') {
      if (typeof renderMCPConfig === 'function') renderMCPConfig(sc);
    } else if (r.current === 'llm_tiers') {
      if (typeof renderLLMTiers === 'function') renderLLMTiers(sc);
    } else if (r.current === 'nodeconfig') {
      if (typeof renderNodeConfig === 'function') renderNodeConfig(sc);
    } else if (r.current === 'nodes') {
      if (typeof renderNodes === 'function') renderNodes(sc);
    } else if (r.current === 'audit') {
      if (typeof renderAudit === 'function') renderAudit();
    } else if (r.current === 'tokens') {
      if (typeof renderTokens === 'function') renderTokens(sc);
    } else if (r.current === 'admin') {
      if (typeof renderPermissionsPanel === 'function') renderPermissionsPanel();
      else if (typeof renderAdmin === 'function') renderAdmin();
    }
    else sc.innerHTML = '<div class="tc-card tc-text-dim" style="padding:var(--s-lg)">Tab not yet implemented.</div>';
  } catch (e) {
    sc.innerHTML = '<div class="tc-card" style="color:var(--error);padding:var(--s-lg)">' + esc(e.message) + '</div>';
  } finally {
    sc.id = r.bodyId;
    if (_orig !== sc) _orig.id = 'content';
  }
}
window.renderSettingsHubTech = renderSettingsHubTech;


// ──────────────────────────────────────────────────────────────
// Phase-2 batch 2 — sub-tab tech ports (form/list pages)
// ──────────────────────────────────────────────────────────────

// --- Branding Settings (stitch_31) ---
// Layout: 2-column. Left = Identity Preview (live preview card),
// right = controls (Site Name input / Subtitle input / Logo URL).
// Top: page header, mono "BRAND ENGINE" label, status pill.
async function renderBrandingSettingsTech(container) {
  var c = container || document.getElementById('content');
  if (!c) return;
  // Fetch current branding
  var b = {};
  try { b = (await api('GET', '/api/portal/branding')) || {}; } catch (e) { b = {}; }

  c.innerHTML =
    '<div class="tc-grid" style="grid-template-columns:minmax(280px,360px) 1fr;gap:var(--s-lg)">' +

      // Left: Identity Preview card
      '<div class="tc-card">' +
        '<div class="tc-mono-label">Identity Preview</div>' +
        '<div class="tc-stack-sm" style="margin-top:var(--s-md);align-items:center;text-align:center;padding:var(--s-md)">' +
          '<div id="tc-brand-preview-logo" style="width:72px;height:72px;border-radius:var(--r-md);' +
                       'background:linear-gradient(135deg,var(--primary),var(--primary-container));' +
                       'display:flex;align-items:center;justify-content:center;overflow:hidden;border:1px solid var(--outline-variant)">' +
            (b.logo_url
              ? '<img src="' + esc(b.logo_url) + '" style="width:100%;height:100%;object-fit:cover" alt="">'
              : '<span class="material-symbols-outlined" style="font-size:32px;color:var(--on-primary)">token</span>') +
          '</div>' +
          '<div id="tc-brand-preview-name" style="font-size:18px;font-weight:600;margin-top:var(--s-sm)">' + esc(b.site_name || 'Tudou Claws') + '</div>' +
          '<div id="tc-brand-preview-sub" class="tc-text-dim" style="font-size:12px">' + esc(b.site_subtitle || 'Multi-Agent Coordination Hub') + '</div>' +
        '</div>' +
        '<div style="margin-top:var(--s-md);padding-top:var(--s-md);border-top:1px solid var(--outline-variant)">' +
          '<div class="tc-row-sm">' +
            '<span class="tc-status-dot online"></span>' +
            '<span class="tc-mono-label">Active Brand Engine</span>' +
          '</div>' +
        '</div>' +
      '</div>' +

      // Right: controls
      '<div class="tc-card">' +
        '<div class="tc-form-group">' +
          '<label>Site Name</label>' +
          '<input class="tc-input" id="tc-brand-name" placeholder="Tudou Claws"' +
                 ' value="' + esc(b.site_name || '') + '"' +
                 ' oninput="document.getElementById(\'tc-brand-preview-name\').textContent=this.value||\'Tudou Claws\'">' +
        '</div>' +
        '<div class="tc-form-group">' +
          '<label>Subtitle</label>' +
          '<input class="tc-input" id="tc-brand-sub" placeholder="Multi-Agent Coordination Hub"' +
                 ' value="' + esc(b.site_subtitle || '') + '"' +
                 ' oninput="document.getElementById(\'tc-brand-preview-sub\').textContent=this.value||\'Multi-Agent Coordination Hub\'">' +
        '</div>' +
        '<div class="tc-form-group">' +
          '<label>Logo URL <span class="tc-text-dim" style="font-weight:400">(optional, https://...)</span></label>' +
          '<input class="tc-input" id="tc-brand-logo" placeholder="https://..."' +
                 ' value="' + esc(b.logo_url || '') + '">' +
        '</div>' +
        '<div class="tc-row" style="gap:var(--s-sm);margin-top:var(--s-lg)">' +
          '<button class="tc-btn tc-btn-primary" onclick="_techBrandSave()">' +
            '<span class="material-symbols-outlined" style="font-size:16px">save</span> Save Branding' +
          '</button>' +
          '<button class="tc-btn tc-btn-ghost" onclick="_techBrandReset()">' +
            '<span class="material-symbols-outlined" style="font-size:16px">restart_alt</span> Reset to Defaults' +
          '</button>' +
        '</div>' +
      '</div>' +

    '</div>';
}
window.renderBrandingSettingsTech = renderBrandingSettingsTech;

async function _techBrandSave() {
  var name = (document.getElementById('tc-brand-name') || {}).value || '';
  var sub  = (document.getElementById('tc-brand-sub') || {}).value || '';
  var logo = (document.getElementById('tc-brand-logo') || {}).value || '';
  try {
    await api('POST', '/api/portal/branding', { site_name: name, site_subtitle: sub, logo_url: logo });
    if (window._toast) window._toast('Branding saved', 'success');
    if (typeof _applyBranding === 'function') _applyBranding();
  } catch (e) { if (window._toast) window._toast('Save failed: ' + e, 'error'); }
}
async function _techBrandReset() {
  try {
    await api('POST', '/api/portal/branding/reset', {});
    if (window._toast) window._toast('Branding reset', 'success');
    renderBrandingSettingsTech();
    if (typeof _applyBranding === 'function') _applyBranding();
  } catch (e) { if (window._toast) window._toast('Reset failed: ' + e, 'error'); }
}
window._techBrandSave = _techBrandSave;
window._techBrandReset = _techBrandReset;


// --- LLM Providers (stitch_16) ---
// stitch shows table-like cards: per-provider row with status / latency
// / tokens metrics + edit/delete actions. We mirror with a table-style
// list, each row a tc-card with provider id, type, models count, status
// dot, and action buttons.
async function renderProvidersTech(container) {
  var c = container || document.getElementById('content');
  if (!c) return;
  // Reuse the GLOBAL providers array so click handlers (editProvider /
  // deleteProvider) can find entries by id. Previously this used a local
  // shadow var, which left the global empty whenever the user landed
  // straight on the tech page — clicking Edit silently no-op'd.
  try {
    var data = await api('GET', '/api/portal/providers');
    providers = (data && data.providers) || [];
  } catch (e) { providers = providers || []; }

  // Bento-grid layout (stitch_16): glass-panel cards in 2-col grid.
  // Each card mimics the stitch "config inspector" feel — small icon
  // + h3 name + subtitle, then form-style sections (Endpoint, Active
  // Models, 2-col scheduling sliders, masked API key) with mono-label
  // section headers. Edit / Delete on the bottom row.
  var cards = providers.map(function(p) {
    var enabled = !!p.enabled;
    var statusLabel = enabled ? 'ENABLED' : 'DISABLED';
    var statusColor = enabled ? 'var(--secondary)' : 'var(--outline)';
    var modelList = p.manual_models || p.models_cache || [];
    var iconKind = ((p.kind || p.type || '') + ' ' + (p.name || p.id || '')).toLowerCase();
    var icon = iconKind.indexOf('ollama') >= 0 ? 'terminal'
             : iconKind.indexOf('claude') >= 0 || iconKind.indexOf('anthropic') >= 0 ? 'psychology'
             : iconKind.indexOf('openai') >= 0 || iconKind.indexOf('gpt') >= 0 ? 'auto_awesome'
             : iconKind.indexOf('google') >= 0 || iconKind.indexOf('gemini') >= 0 ? 'travel_explore'
             : iconKind.indexOf('mistral') >= 0 ? 'air'
             : iconKind.indexOf('deepseek') >= 0 ? 'water_drop'
             : iconKind.indexOf('qwen') >= 0 || iconKind.indexOf('alibaba') >= 0 ? 'cloud'
             : iconKind.indexOf('zhipu') >= 0 || iconKind.indexOf('glm') >= 0 ? 'memory'
             : iconKind.indexOf('lm studio') >= 0 || iconKind.indexOf('lmstudio') >= 0 ? 'computer'
             : 'cloud_queue';
    var subtitle = iconKind.indexOf('ollama') >= 0 ? 'Local Host Environment'
                 : iconKind.indexOf('claude') >= 0 || iconKind.indexOf('anthropic') >= 0 ? 'Anthropic Cloud Provider'
                 : iconKind.indexOf('openai') >= 0 ? 'OpenAI Cloud Provider'
                 : iconKind.indexOf('gemini') >= 0 ? 'Google Cloud Provider'
                 : iconKind.indexOf('zhipu') >= 0 || iconKind.indexOf('glm') >= 0 ? 'Enterprise Cloud Provider'
                 : iconKind.indexOf('qwen') >= 0 ? 'Aliyun DashScope API'
                 : iconKind.indexOf('lm studio') >= 0 ? 'Local Server Instance'
                 : (p.scope === 'cloud' ? 'Cloud Provider' : 'OpenAI-Compatible Endpoint');

    // Stitch ENABLED/secondary tint for active models, outline for stale
    var modelChips = modelList.length
      ? modelList.map(function(m, i) {
          var on = enabled && i < 6;  // first 6 active visually
          var bg = on ? 'rgba(137,206,255,0.10)' : 'rgba(255,255,255,0.04)';
          var bd = on ? 'rgba(137,206,255,0.30)' : 'rgba(255,255,255,0.10)';
          var fg = on ? 'var(--secondary)' : 'var(--outline)';
          return '<span style="padding:3px 10px;background:' + bg + ';border:1px solid ' + bd + ';color:' + fg + ';border-radius:9999px;font-family:var(--font-mono);font-size:10px;letter-spacing:0.05em;text-transform:uppercase">' + esc(m) + '</span>';
        }).join('')
      : '<span class="tc-text-dim" style="font-size:11px">No models — click EDIT to add</span>';

    // Reusable read-only "input" field (stitch style — bg surface-container-low, outline border)
    var inputField = function(value) {
      return '<div style="background:var(--surface-container-lowest);border:1px solid var(--outline-variant);border-radius:var(--r-md);padding:8px 12px;font-family:var(--font-mono);font-size:12px;color:var(--on-surface);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;letter-spacing:0.02em">' + value + '</div>';
    };
    // Reusable "stat" with mini progress bar (stitch range slider analog)
    var statBlock = function(label, val, valColor, pct) {
      return '<div style="display:flex;flex-direction:column;gap:6px">' +
        '<div style="display:flex;justify-content:space-between;align-items:center">' +
          '<span class="tc-mono-label" style="color:var(--outline);font-size:10px">' + label + '</span>' +
          '<span style="font-family:var(--font-mono);font-size:12px;color:' + (valColor || 'var(--secondary)') + '">' + val + '</span>' +
        '</div>' +
        '<div style="height:3px;width:100%;background:var(--surface-container-high);border-radius:2px;overflow:hidden">' +
          '<div style="height:100%;background:' + (valColor || 'var(--secondary)') + ';width:' + Math.min(100, Math.max(2, pct || 30)) + '%;opacity:0.8"></div>' +
        '</div>' +
      '</div>';
    };

    var maxConc = p.max_concurrent || 1;
    var rateLimit = p.rate_limit_rpm || 0;
    var timeoutS = p.timeout_s || 60;

    return '<div class="tc-card-glass" style="padding:var(--s-lg);display:flex;flex-direction:column;gap:14px;position:relative;overflow:hidden;border-top:1px solid rgba(255,255,255,0.10)' +
             (enabled ? '' : ';opacity:0.7') +
             (enabled ? ';box-shadow:0 0 15px rgba(192,193,255,0.08)' : '') +
           '">' +
             // Top-right status indicator
             '<div style="position:absolute;top:14px;right:14px;display:flex;align-items:center;gap:6px;font-family:var(--font-mono);font-size:10px;letter-spacing:0.05em;color:' + statusColor + '">' +
               (enabled
                 ? '<span style="width:8px;height:8px;border-radius:50%;background:' + statusColor + ';animation:pulse-dot 2s infinite ease-in-out"></span>'
                 : '<span style="width:8px;height:8px;border-radius:50%;background:' + statusColor + '"></span>') +
               statusLabel +
             '</div>' +
             // Header: icon + name + subtitle
             '<div style="display:flex;align-items:center;gap:14px;margin-bottom:4px;padding-right:100px">' +
               '<div style="width:48px;height:48px;border-radius:var(--r-md);background:' + (enabled ? 'rgba(137,206,255,0.10)' : 'rgba(255,255,255,0.04)') + ';border:1px solid ' + (enabled ? 'rgba(137,206,255,0.25)' : 'rgba(255,255,255,0.10)') + ';display:flex;align-items:center;justify-content:center;flex-shrink:0">' +
                 '<span class="material-symbols-outlined" style="color:' + (enabled ? 'var(--secondary)' : 'var(--outline)') + ';font-size:24px">' + icon + '</span>' +
               '</div>' +
               '<div style="flex:1;min-width:0">' +
                 '<div style="font-family:var(--font-display);font-size:20px;font-weight:600;color:var(--on-surface);line-height:1.2;letter-spacing:-0.01em;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">' +
                   esc(p.name || p.id || 'Provider') +
                 '</div>' +
                 '<div class="tc-mono-label" style="color:var(--outline);margin-top:4px;font-size:10px">' + esc(subtitle) + '</div>' +
               '</div>' +
             '</div>' +
             // Endpoint URL field
             '<div style="display:flex;flex-direction:column;gap:6px">' +
               '<div class="tc-mono-label" style="color:var(--on-surface-variant);font-size:10px">ENDPOINT URL</div>' +
               inputField(esc(p.base_url || '—')) +
             '</div>' +
             // Active Models section
             '<div style="display:flex;flex-direction:column;gap:6px">' +
               '<div class="tc-mono-label" style="color:var(--on-surface-variant);font-size:10px">ACTIVE MODELS (' + modelList.length + ')</div>' +
               '<div style="display:flex;flex-wrap:wrap;gap:6px">' + modelChips + '</div>' +
             '</div>' +
             // 2-col scheduling: Concurrency + Rate Limit/Timeout
             '<div style="display:grid;grid-template-columns:1fr 1fr;gap:14px">' +
               statBlock('CONCURRENCY', String(maxConc), statusColor, Math.round((maxConc / 16) * 100)) +
               (rateLimit > 0
                 ? statBlock('RATE LIMIT', rateLimit + '/m', statusColor, Math.round((rateLimit / 500) * 100))
                 : statBlock('TIMEOUT', timeoutS + 's', statusColor, Math.round((timeoutS / 300) * 100))) +
             '</div>' +
             // API Key (masked input style)
             (p.api_key
               ? '<div style="display:flex;flex-direction:column;gap:6px">' +
                   '<div class="tc-mono-label" style="color:var(--on-surface-variant);font-size:10px">API KEY</div>' +
                   '<div style="position:relative">' +
                     inputField('<span style="font-family:var(--font-mono);letter-spacing:2px">••••••••••••••••••••</span>') +
                     '<span class="material-symbols-outlined" style="position:absolute;right:10px;top:50%;transform:translateY(-50%);color:var(--outline);font-size:16px">lock</span>' +
                   '</div>' +
                 '</div>'
               : '') +
             // Footer: Edit / Delete actions
             '<div style="display:flex;align-items:center;justify-content:space-between;padding-top:12px;border-top:1px solid var(--outline-variant);margin-top:auto">' +
               '<button class="tc-btn tc-btn-ghost tc-btn-sm" onclick="editProvider(\'' + esc(p.id || '') + '\')" style="font-family:var(--font-mono);font-size:11px;letter-spacing:0.05em">' +
                 '<span class="material-symbols-outlined" style="font-size:14px">edit</span> EDIT' +
               '</button>' +
               '<button class="tc-btn tc-btn-ghost tc-btn-sm" onclick="deleteProvider(\'' + esc(p.id || '') + '\')" style="font-family:var(--font-mono);font-size:11px;letter-spacing:0.05em;color:var(--error)">' +
                 '<span class="material-symbols-outlined" style="font-size:14px">delete</span> DELETE' +
               '</button>' +
             '</div>' +
           '</div>';
  }).join('');

  c.innerHTML =
    // Stitch_16: simple h2 + subtitle on left, ADD PROVIDER pill button on right
    '<div style="display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:var(--s-xl);gap:var(--s-md);flex-wrap:wrap">' +
      '<div style="flex:1;min-width:240px">' +
        '<h2 style="font-family:var(--font-display);font-size:30px;font-weight:600;letter-spacing:-0.01em;color:var(--on-surface);margin:0">LLM Providers</h2>' +
        '<p class="tc-text-dim" style="font-size:14px;line-height:1.55;margin-top:8px;max-width:640px">Manage backend orchestration for autonomous agents. Configure local instances, cloud endpoints, and specific model behaviors.</p>' +
      '</div>' +
      '<button onclick="showModal(\'add-provider\')" style="background:var(--primary-fixed);color:var(--on-primary-fixed);padding:10px 20px;border-radius:var(--r-md);font-family:var(--font-mono);font-size:11px;letter-spacing:0.05em;text-transform:uppercase;font-weight:600;border:none;cursor:pointer;display:inline-flex;align-items:center;gap:8px;transition:all 0.15s;box-shadow:0 4px 14px rgba(192,193,255,0.20)" onmouseover="this.style.filter=\'brightness(1.08)\';this.style.boxShadow=\'0 6px 22px rgba(192,193,255,0.32)\'" onmouseout="this.style.filter=\'\';this.style.boxShadow=\'0 4px 14px rgba(192,193,255,0.20)\'">' +
        '<span class="material-symbols-outlined" style="font-size:16px">add_circle</span> ADD PROVIDER' +
      '</button>' +
    '</div>' +
    (cards
      ? '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(440px,1fr));gap:var(--s-lg)">' + cards + '</div>'
      : '<div class="tc-card" style="text-align:center;padding:60px 20px;border-style:dashed">' +
          '<span class="material-symbols-outlined" style="font-size:48px;color:var(--outline)">cloud_off</span>' +
          '<div style="font-size:14px;color:var(--on-surface-variant);margin-top:14px;margin-bottom:8px">No LLM providers configured</div>' +
          '<div class="tc-text-dim" style="font-size:12px;margin-bottom:20px">Add your first provider to enable agent chat.</div>' +
          '<button onclick="showModal(\'add-provider\')" style="background:var(--primary-fixed);color:var(--on-primary-fixed);padding:10px 20px;border-radius:var(--r-md);font-family:var(--font-mono);font-size:11px;letter-spacing:0.05em;text-transform:uppercase;font-weight:600;border:none;cursor:pointer;display:inline-flex;align-items:center;gap:8px;box-shadow:0 4px 14px rgba(192,193,255,0.20)">' +
            '<span class="material-symbols-outlined" style="font-size:16px">add_circle</span> ADD FIRST PROVIDER' +
          '</button>' +
        '</div>');
}
window.renderProvidersTech = renderProvidersTech;


// --- Approvals (stitch_2) ---
// "Tool Approvals & Policies" — list of pending requests, each row
// with risk-tier color + agent + tool + arguments preview + Approve /
// Deny / Always-Allow actions.
async function renderApprovalsTech() {
  var c = document.getElementById('content');
  if (!c) return;
  // Reuse existing approvals data (loaded into `approvals` global) +
  // poll/fetcher pattern.
  if (typeof loadApprovals === 'function') {
    try { await loadApprovals(); } catch (e) {}
  }
  var pending = Array.isArray(approvals)
    ? approvals.filter(function(a) { return a.status === 'pending'; })
    : ((approvals || {}).pending || []);
  var history = Array.isArray(approvals)
    ? approvals.filter(function(a) { return a.status !== 'pending'; }).slice(0, 30)
    : ((approvals || {}).history || []).slice(0, 30);

  var riskChip = function(risk) {
    var r = String(risk || 'unknown').toLowerCase();
    var tone = r === 'high' ? 'error'
             : r === 'moderate' ? 'warn'
             : r === 'low' ? 'success'
             : r === 'red' ? 'error'
             : 'neutral';
    return '<span class="tc-chip tc-chip-' + tone + '" style="font-size:9px">' + esc(r.toUpperCase()) + '</span>';
  };

  var renderRow = function(a, isPending) {
    var argsPreview = '';
    try {
      var args = typeof a.arguments === 'string' ? JSON.parse(a.arguments) : (a.arguments || {});
      argsPreview = JSON.stringify(args).slice(0, 120);
    } catch (e) { argsPreview = String(a.arguments || '').slice(0, 120); }
    return '<div class="tc-card tc-row" style="gap:var(--s-md);align-items:center">' +
             '<div style="flex:1;min-width:0">' +
               '<div class="tc-row-sm" style="margin-bottom:4px">' +
                 '<span style="font-family:var(--font-mono);font-size:13px;font-weight:600;color:var(--on-surface)">' +
                   esc(a.tool_name || a.tool || 'unknown') +
                 '</span>' +
                 riskChip(a.risk_level || a.risk) +
                 (a.agent_name ? '<span class="tc-text-dim" style="font-size:11px">by ' + esc(a.agent_name) + '</span>' : '') +
               '</div>' +
               '<div class="tc-text-dim" style="font-size:11px;font-family:var(--font-mono);overflow:hidden;text-overflow:ellipsis;white-space:nowrap">' +
                 esc(argsPreview) +
               '</div>' +
             '</div>' +
             (isPending
               ? '<div class="tc-row-sm" style="gap:4px;flex-shrink:0">' +
                   '<button class="tc-btn tc-btn-primary tc-btn-sm" onclick="approveRequest(\'' + esc(a.approval_id || a.id || '') + '\')" title="Approve this request once">' +
                     '<span class="material-symbols-outlined" style="font-size:14px">check</span> Approve</button>' +
                   '<button class="tc-btn tc-btn-ghost tc-btn-sm" onclick="approveRequest(\'' + esc(a.approval_id || a.id || '') + '\',\'session\')" title="Approve and skip future prompts in this session">' +
                     '<span class="material-symbols-outlined" style="font-size:14px">all_inclusive</span> Always</button>' +
                   '<button class="tc-btn tc-btn-ghost tc-btn-sm" onclick="denyRequest(\'' + esc(a.approval_id || a.id || '') + '\')" style="color:var(--error)">' +
                     '<span class="material-symbols-outlined" style="font-size:14px">close</span> Deny</button>' +
                 '</div>'
               : '<span class="tc-chip" style="font-size:9px">' + esc(String(a.status || '').toUpperCase()) + '</span>') +
           '</div>';
  };

  c.innerHTML =
    // Pending section
    '<div class="tc-row-spread" style="margin-bottom:var(--s-md)">' +
      '<div class="tc-row-sm">' +
        '<span class="tc-mono-label">Pending Requests</span>' +
        '<span class="tc-chip tc-chip-' + (pending.length > 0 ? 'warn' : 'neutral') + '">' + pending.length + '</span>' +
      '</div>' +
    '</div>' +
    (pending.length === 0
      ? '<div class="tc-card tc-text-dim" style="text-align:center;padding:var(--s-xl)">No pending approvals.</div>'
      : '<div class="tc-stack-sm" style="margin-bottom:var(--s-lg)">' + pending.map(function(a) { return renderRow(a, true); }).join('') + '</div>') +

    // History section
    '<div class="tc-row-spread" style="margin:var(--s-lg) 0 var(--s-md)">' +
      '<div class="tc-row-sm">' +
        '<span class="tc-mono-label">Recent History</span>' +
        '<span class="tc-chip">' + history.length + '</span>' +
      '</div>' +
    '</div>' +
    (history.length === 0
      ? '<div class="tc-card tc-text-dim" style="text-align:center;padding:var(--s-md)">No history yet.</div>'
      : '<div class="tc-stack-sm">' + history.map(function(a) { return renderRow(a, false); }).join('') + '</div>');
}
window.renderApprovalsTech = renderApprovalsTech;


// --- Skill Marketplace (stitch_27) ---
