// ============ Meeting Attachments ============
var _mtgAttachments = {};

function _mtgAttachList(mid) {
  if (!_mtgAttachments[mid]) _mtgAttachments[mid] = [];
  return _mtgAttachments[mid];
}

function _renderMtgAttachPreview(mid) {
  var box = document.getElementById('mtg-attach-preview-'+mid);
  if (!box) return;
  var list = _mtgAttachList(mid);
  if (list.length === 0) { box.style.display = 'none'; box.innerHTML = ''; return; }
  box.style.display = 'flex';
  box.innerHTML = list.map(function(a, idx) {
    var thumb = a.preview_url
      ? '<img src="'+a.preview_url+'" style="width:28px;height:28px;object-fit:cover;border-radius:3px">'
      : '<span class="material-symbols-outlined" style="font-size:16px;color:var(--text3)">draft</span>';
    return '<div style="display:inline-flex;align-items:center;gap:4px;background:var(--surface);border:1px solid var(--overlay-8);border-radius:4px;padding:2px 6px;font-size:10px;color:var(--text)">' +
      thumb + '<span style="max-width:80px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+esc(a.name)+'</span>' +
      '<button onclick="_mtgAttachList(\''+mid+'\').splice('+idx+',1);_renderMtgAttachPreview(\''+mid+'\')" style="background:none;border:none;color:var(--text3);cursor:pointer;padding:0"><span class="material-symbols-outlined" style="font-size:12px">close</span></button>' +
    '</div>';
  }).join('');
}

function handleMtgAttach(mid, fileInput) {
  if (!fileInput || !fileInput.files || !fileInput.files.length) return;
  var list = _mtgAttachList(mid);
  var files = Array.prototype.slice.call(fileInput.files, 0, Math.max(0, 10 - list.length));
  files.forEach(function(f) {
    if (f.size > 10*1024*1024) { alert('File "'+f.name+'" exceeds 10 MB.'); return; }
    var reader = new FileReader();
    reader.onload = function(e) {
      var dataUrl = e.target.result || '';
      var b64 = dataUrl.indexOf(',') >= 0 ? dataUrl.split(',')[1] : dataUrl;
      var isImage = (f.type||'').indexOf('image/') === 0;
      list.push({ name: f.name, mime: f.type||'application/octet-stream', size: f.size, data_base64: b64, preview_url: isImage ? dataUrl : '' });
      _renderMtgAttachPreview(mid);
    };
    reader.readAsDataURL(f);
  });
  fileInput.value = '';
}

// ---------- Send Message ----------
async function meetingPostMessage(mid) {
  var el = document.getElementById('mtg-msg-input');
  var v = (el && el.value || '').trim();
  var attachments = _mtgAttachList(mid).slice();
  if (!v && !attachments.length) return;

  // ── Queue + merge: round in progress ──
  // If any agent is mid-reply (typing bubble visible OR active_speakers
  // non-empty), instead of firing a new round we push the user's input
  // into a pending queue. Auto-flush as ONE merged interjection after
  // all current respondents have posted.
  if (_isScopeBusy('meeting', mid)) {
    var ok = _pendingQueueEnqueue('meeting', mid, v, attachments);
    if (ok) {
      if (el) { el.value = ''; }
      _mtgAttachments[mid] = [];
      try { _renderMtgAttachPreview(mid); } catch(_){}
    }
    return;
  }

  // -- Parse @ mentions --
  // @all / @ALL / @全员 / @所有人  -> null (backend default: all reply)
  // @<name> [@<name>...]           -> list of agent ids
  // no @                           -> [] (explicit: nobody replies)
  var mentionedIds = [];
  var hasAll = false;
  var unknownMentions = [];
  var rx = /@([^\s@]+)/g;
  var mm;
  var participants = _getMeetingParticipants(mid);
  while ((mm = rx.exec(v)) !== null) {
    var name = mm[1];
    if (/^(all|ALL|全员|所有人)$/.test(name)) { hasAll = true; continue; }
    // Longest-prefix match against participant display names
    var match = null;
    for (var i=0;i<participants.length;i++) {
      var p = participants[i];
      if (p.id === '__ALL__') continue;
      if (name.indexOf(p.name) === 0 || name === p.display || name === p.id) {
        if (!match || p.name.length > match.name.length) match = p;
      }
    }
    if (match) {
      if (mentionedIds.indexOf(match.id) < 0) mentionedIds.push(match.id);
    } else {
      unknownMentions.push(name);
    }
  }
  if (unknownMentions.length && window._toast) {
    window._toast('@ not found' + unknownMentions.join(', @'), 'warning');
  }

  var targetAgents;  // undefined → omit
  var willReply;
  if (hasAll) {
    willReply = true;
  } else if (mentionedIds.length > 0) {
    targetAgents = mentionedIds;
    willReply = true;
  } else {
    targetAgents = [];
    willReply = false;
  }

  // Disable input while sending
  if (el) { el.disabled = true; el.value = ''; }

  var msgBody = {content: v || '(attached files)', role: 'user'};
  if (typeof targetAgents !== 'undefined') msgBody.target_agents = targetAgents;
  if (attachments.length) {
    msgBody.attachments = attachments.map(function(a) {
      return { name: a.name, mime: a.mime, data_base64: a.data_base64 };
    });
    _mtgAttachments[mid] = [];
    _renderMtgAttachPreview(mid);
  }
  try {
    var resp = await api('POST', '/api/portal/meetings/'+mid+'/messages', msgBody);
    // Capture respondents returned by backend → per-agent typing bubbles
    var respondents = (resp && Array.isArray(resp.respondents)) ? resp.respondents : [];
    window._mtgTyping = window._mtgTyping || {};
    if (willReply && respondents.length) {
      // Merge into existing pending so rapid successive sends don't clobber
      // earlier typing bubbles. Shape: {pending: {aid: sinceTimestamp}}.
      var slot = window._mtgTyping[mid] || {pending: {}};
      if (!slot.pending || typeof slot.pending !== 'object' || Array.isArray(slot.pending)) {
        slot.pending = {};
      }
      var nowTs = Date.now() / 1000 - 1;
      respondents.forEach(function(aid) {
        if (!(aid in slot.pending)) slot.pending[aid] = nowTs;
      });
      window._mtgTyping[mid] = slot;
    }
    // Render bubbles NOW so the user sees immediate feedback — don't
    // wait for the 3s poll tick. The surgical poll will keep them
    // updated thereafter.
    _mtgRenderTypingBubbles(mid, { messages: (window._currentMeeting && window._currentMeeting.messages) || [] });
    // Scroll to bottom so the new bubbles are visible.
    var _sc = document.getElementById('mtg-chat-scroll');
    if (_sc) _sc.scrollTop = _sc.scrollHeight;
  } catch(e) {
    alert('Error: '+e.message);
    if (el) { el.disabled = false; el.value = v; }
  }
}

// ---------- Assignment Modal ----------
function showMeetingAssignmentModal(mid) {
  var agentOpts = '<option value="">选择负责 Agent</option>' + agents.map(function(a){
    return '<option value="'+a.id+'">'+esc((a.role?a.role+' · ':'')+a.name)+'</option>';
  }).join('');
  var html = '<div style="padding:24px;max-width:480px"><h3 style="margin:0 0 16px">新建任务</h3>' +
    '<p style="font-size:12px;color:var(--text3);margin:-8px 0 14px">从讨论中明确的行动项</p>' +
    '<input id="asg-title" placeholder="任务标题" style="width:100%;padding:10px;margin-bottom:10px;background:var(--surface);border:1px solid var(--overlay-10);border-radius:8px;color:var(--text);font-size:13px">' +
    '<textarea id="asg-desc" placeholder="描述 / 背景 (可选)" style="width:100%;padding:10px;margin-bottom:10px;background:var(--surface);border:1px solid var(--overlay-10);border-radius:8px;color:var(--text);font-size:13px;min-height:60px;resize:vertical"></textarea>' +
    '<select id="asg-assignee" style="width:100%;padding:10px;margin-bottom:10px;background:var(--surface);border:1px solid var(--overlay-10);border-radius:8px;color:var(--text);font-size:13px">'+agentOpts+'</select>' +
    '<input id="asg-due" placeholder="截止提示 (e.g. 明天 17:00)" style="width:100%;padding:10px;margin-bottom:14px;background:var(--surface);border:1px solid var(--overlay-10);border-radius:8px;color:var(--text);font-size:13px">' +
    '<div style="display:flex;gap:8px;justify-content:flex-end">' +
      '<button class="btn btn-ghost" onclick="closeModal()">Cancel</button>' +
      '<button class="btn btn-primary" onclick="_lockBtn(this,\'Creating…\',createMeetingAssignment,\''+mid+'\')">Create</button>' +
    '</div></div>';
  showModalHTML(html);
}

async function createMeetingAssignment(mid) {
  var title = document.getElementById('asg-title').value.trim();
  if (!title) { alert('Title cannot be empty'); return; }
  try {
    await api('POST', '/api/portal/meetings/'+mid+'/assignments', {
      title: title,
      description: document.getElementById('asg-desc').value.trim(),
      assignee_agent_id: document.getElementById('asg-assignee').value,
      due_hint: document.getElementById('asg-due').value.trim(),
    });
    closeModal();
    openMeetingDetail(mid);
  } catch(e) { alert('Error: '+e.message); }
}

async function updateMeetingAssignment(mid, aid, status) {
  if (!status) return;
  try {
    await api('POST', '/api/portal/meetings/'+mid+'/assignments/'+aid+'/update', {status: status});
    openMeetingDetail(mid);
  } catch(e) { alert('Error: '+e.message); }
}

async function _reexecuteAssignment(mid, aid) {
  // Re-execute uses the persisted plan + workspace — won't redo finished
  // steps. Confirm so accidental clicks don't kick off a long run.
  if (!confirm('重新执行此任务？\n系统会读取已完成的步骤和产物，只跑未完成部分。')) return;
  try {
    var r = await api('POST', '/api/portal/meetings/'+mid+'/assignments/'+aid+'/reexecute', {});
    if (r && r.ok) {
      // Refresh so the user sees status → 进行中 + 重试 ×N badge
      openMeetingDetail(mid);
    } else {
      alert('Re-execute failed:' + ((r && r.error) || 'unknown'));
    }
  } catch(e) { alert('Re-execute failed:' + (e.message || e)); }
}

// ============ @mention autocomplete for meetings ============
var _mtgMentionActiveIdx = -1;
var _mtgMentionMid = '';

function _getMeetingParticipants(mid) {
  var m = window._currentMeeting;
  var agList = window._cachedAgents || (typeof agents !== 'undefined' ? agents : []);
  var out = [
    { id: '__ALL__', name: 'Everyone', role: '全员集体思考', display: 'Everyone' }
  ];
  if (m && m.participants) {
    m.participants.forEach(function(pid) {
      var a = agList.find(function(x){ return x.id === pid; });
      if (a) out.push({ id: a.id, name: a.name, role: a.role || 'general', display: a.name });
    });
  }
  return out;
}

function _mtgInputChange(mid) {
  var input = document.getElementById('mtg-msg-input');
  if (!input) return;
  var val = input.value;
  var cursorPos = input.selectionStart;
  var textBefore = val.slice(0, cursorPos);
  var atIdx = textBefore.lastIndexOf('@');
  if (atIdx === -1 || (atIdx > 0 && textBefore[atIdx-1] !== ' ' && textBefore[atIdx-1] !== '\n')) {
    _hideMtgMentionDropdown();
    return;
  }
  var query = textBefore.slice(atIdx + 1).toLowerCase();
  if (/\s/.test(query)) { _hideMtgMentionDropdown(); return; }
  var members = _getMeetingParticipants(mid);
  var filtered = members.filter(function(m) {
    if (!query) return true;
    return m.name.toLowerCase().indexOf(query) !== -1 ||
           (m.role||'').toLowerCase().indexOf(query) !== -1 ||
           m.display.toLowerCase().indexOf(query) !== -1;
  });
  if (filtered.length === 0) { _hideMtgMentionDropdown(); return; }
  _mtgMentionMid = mid;
  _mtgMentionActiveIdx = 0;
  _showMtgMentionDropdown(filtered, atIdx);
}

function _showMtgMentionDropdown(members, atIdx) {
  var dd = document.getElementById('mtg-mention-dropdown');
  if (!dd) return;
  dd.innerHTML = members.map(function(m, i) {
    var icon = m.id === '__ALL__' ? 'groups' : 'smart_toy';
    var color = m.id === '__ALL__' ? '#22c55e' : 'var(--primary)';
    return '<div class="mention-item'+(i===0?' active':'')+'" data-name="'+esc(m.display)+'" data-at-idx="'+atIdx+'" onclick="_selectMtgMention(\''+esc(m.display)+'\','+atIdx+')">' +
      '<span class="material-symbols-outlined" style="font-size:18px;color:'+color+'">'+icon+'</span>' +
      '<div><span class="mention-name">'+esc(m.display)+'</span><br><span class="mention-role">'+esc(m.role||'')+'</span></div>' +
    '</div>';
  }).join('');
  dd.classList.add('show');
}

function _hideMtgMentionDropdown() {
  var dd = document.getElementById('mtg-mention-dropdown');
  if (dd) { dd.classList.remove('show'); dd.innerHTML = ''; }
  _mtgMentionActiveIdx = -1;
}

function _selectMtgMention(name, atIdx) {
  var input = document.getElementById('mtg-msg-input');
  if (!input) return;
  var val = input.value;
  var cursorPos = input.selectionStart;
  var before = val.slice(0, atIdx);
  var after = val.slice(cursorPos);
  input.value = before + '@' + name + ' ' + after;
  input.focus();
  var newPos = before.length + 1 + name.length + 1;
  input.setSelectionRange(newPos, newPos);
  _hideMtgMentionDropdown();
}

function _mtgInputKeydown(e, mid) {
  var dd = document.getElementById('mtg-mention-dropdown');
  if (dd && dd.classList.contains('show')) {
    var items = dd.querySelectorAll('.mention-item');
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      _mtgMentionActiveIdx = Math.min(_mtgMentionActiveIdx + 1, items.length - 1);
      items.forEach(function(el,i){ el.classList.toggle('active', i===_mtgMentionActiveIdx); });
      return;
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      _mtgMentionActiveIdx = Math.max(_mtgMentionActiveIdx - 1, 0);
      items.forEach(function(el,i){ el.classList.toggle('active', i===_mtgMentionActiveIdx); });
      return;
    } else if (e.key === 'Enter' || e.key === 'Tab') {
      e.preventDefault();
      if (_mtgMentionActiveIdx >= 0 && _mtgMentionActiveIdx < items.length) {
        var item = items[_mtgMentionActiveIdx];
        _selectMtgMention(item.getAttribute('data-name'), parseInt(item.getAttribute('data-at-idx')));
      }
      return;
    } else if (e.key === 'Escape') {
      _hideMtgMentionDropdown();
      return;
    }
  }
  // Default: Enter sends message (but skip during IME composition)
  if (e.key === 'Enter' && !e.shiftKey && !e.isComposing) {
    e.preventDefault();
    meetingPostMessage(mid);
  }
}


// ============ Task Center (定时任务 + 独立任务统一视图) ============
async function renderTaskCenterTab() {
  var c = document.getElementById('content');
  // Single unified view. V2 tasks merge into the same list as V1's
  // 定时/独立任务 — separated into sections but rendered on one page,
  // each row carrying a status chip so users can see everything at once.
  var v2On = (typeof window.isV2Mode === 'function') && window.isV2Mode();

  c.innerHTML =
    '<div style="padding:18px">' +
      '<div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:16px">' +
        '<div><h2 style="margin:0;font-size:22px;font-weight:800">任务中心</h2>' +
        '<p style="font-size:12px;color:var(--text3);margin-top:4px">' +
          '定时任务 (Agent / Workflow) · 独立任务' +
          (v2On ? ' · 状态机任务（6-phase）' : '') +
        '</p></div>' +
        '<div style="display:flex;gap:8px">' +
          '<button class="btn btn-primary btn-sm" onclick="showCreateJob()">' +
            '<span class="material-symbols-outlined" style="font-size:16px">schedule</span> 新建定时任务</button>' +
          '<button class="btn btn-sm" onclick="showCreateStandaloneTaskModal()">' +
            '<span class="material-symbols-outlined" style="font-size:16px">add</span> 新建独立任务</button>' +
          (v2On
            ? '<button class="btn btn-sm" onclick="v2ShowSubmitTaskModal(\'\')" ' +
              'style="background:rgba(249,115,22,0.15);color:#f97316;border:1px solid rgba(249,115,22,0.4)">' +
              '<span class="material-symbols-outlined" style="font-size:16px">rocket_launch</span> 新建状态机任务</button>'
            : '') +
        '</div>' +
      '</div>' +
      '<div id="tc-content"><div style="color:var(--text3);font-size:12px">Loading…</div></div>' +
    '</div>';
  loadTaskCenter();
}

async function loadTaskCenter() {
  var area = document.getElementById('tc-content');
  if (!area) return;
  try {
    var v2On = (typeof window.isV2Mode === 'function') && window.isV2Mode();
    var results = await Promise.all([
      api('GET', '/api/portal/scheduler/jobs'),
      api('GET', '/api/portal/standalone-tasks'),
      api('GET', '/api/portal/agents').catch(function(){ return {agents: []}; }),
      api('GET', '/api/portal/workflows').catch(function(){ return {workflows: []}; }),
      api('GET', '/api/portal/meetings').catch(function(){ return {meetings: []}; }),
      v2On ? api('GET', '/api/v2/tasks?limit=100').catch(function(){ return {tasks: []}; })
           : Promise.resolve({tasks: []}),
    ]);
    var v2TasksResp = results[5] || {};
    var v2Tasks = v2TasksResp.tasks || [];
    var jobsResp = results[0] || {};
    var stResp = results[1] || {};
    var agentsResp = results[2] || {};
    var wfResp = results[3] || {};
    var mtgResp = results[4] || {};
    var jobs = jobsResp.jobs || [];
    var standaloneTasks = (stResp.tasks || []).map(function(t){ t._src='standalone'; return t; });
    var agentsList = agentsResp.agents || [];
    var wfList = wfResp.workflows || [];
    var mtgList = mtgResp.meetings || [];
    var agentNameById = {};
    agentsList.forEach(function(a){ agentNameById[a.id] = (a.role?a.role+'-':'')+a.name; });
    var wfNameById = {};
    wfList.forEach(function(w){ wfNameById[w.id||w.template_id] = w.name||'(unnamed)'; });
    var meetingNameById = {};
    mtgList.forEach(function(m){ meetingNameById[m.id] = m.title || '(untitled)'; });

    // Split scheduled jobs into agent-chat targets vs workflow targets
    var chatJobs = [];
    var workflowJobs = [];
    jobs.forEach(function(j){
      if ((j.target_type||'chat') === 'workflow' || j.workflow_id) workflowJobs.push(j);
      else chatJobs.push(j);
    });

    var renderJobCard = function(job, kind){
      var enabled = !!job.enabled;
      var statusIcon = enabled
        ? (job.last_status==='success'?'✅':job.last_status==='failed'?'❌':'⏱')
        : '⏸';
      var nextRun = job.next_run_at ? _formatTs(job.next_run_at) : '-';
      var lastRun = job.last_run_at ? _formatTs(job.last_run_at) : '从未';
      var targetLine = '';
      if (kind === 'workflow') {
        var wfName = wfNameById[job.workflow_id] || job.workflow_id || '(未指定)';
        var defaultAgent = job.agent_id ? (agentNameById[job.agent_id] || job.agent_id) : '(全部默认)';
        targetLine =
          '<div style="font-size:11px;color:var(--text2);margin-top:4px">' +
            '🔀 Workflow: <strong>'+esc(wfName)+'</strong>' +
          '</div>' +
          '<div style="font-size:10px;color:var(--text3);margin-top:2px">默认 Agent: '+esc(defaultAgent)+'</div>';
      } else {
        var agName = job.agent_id ? (agentNameById[job.agent_id] || job.agent_id) : '(未指定)';
        targetLine =
          '<div style="font-size:11px;color:var(--text2);margin-top:4px">👤 Agent: <strong>'+esc(agName)+'</strong></div>';
      }
      return '<div style="background:var(--surface);border-radius:10px;padding:12px 14px;border:1px solid var(--overlay-6);margin-bottom:8px">' +
        '<div style="display:flex;align-items:center;gap:8px">' +
          '<span style="font-size:14px;line-height:1">'+statusIcon+'</span>' +
          '<span style="font-weight:700;font-size:13px;flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+esc(job.name||'(unnamed)')+'</span>' +
          '<span style="font-size:10px;background:var(--overlay-6);padding:2px 8px;border-radius:10px;color:var(--text3)">'+esc(job.job_type||'recurring')+'</span>' +
        '</div>' +
        targetLine +
        '<div style="font-size:10px;color:var(--text3);margin-top:6px;font-family:monospace">⏰ '+esc(job.cron_expr||'one-time')+'</div>' +
        '<div style="font-size:10px;color:var(--text3);margin-top:2px">下次: '+esc(nextRun)+' · 上次: '+esc(lastRun)+' · 执行 '+(job.run_count||0)+' 次</div>' +
        '<div style="display:flex;gap:6px;margin-top:8px;border-top:1px solid var(--overlay-5);padding-top:8px">' +
          '<button class="btn btn-primary btn-xs" onclick="triggerJob(\''+job.id+'\')">▶ 立即运行</button>' +
          '<button class="btn btn-ghost btn-xs" onclick="toggleJob(\''+job.id+'\','+(!enabled)+')">'+(enabled?'暂停':'Resume')+'</button>' +
          '<button class="btn btn-ghost btn-xs" onclick="viewJobHistory(\''+job.id+'\')">历史</button>' +
          '<button class="btn btn-ghost btn-xs" style="margin-left:auto;color:var(--error)" onclick="deleteJob(\''+job.id+'\')">Delete</button>' +
        '</div>' +
      '</div>';
    };

    var chatJobsHtml = chatJobs.map(function(j){ return renderJobCard(j, 'chat'); }).join('')
      || '<div style="color:var(--text3);font-size:12px;padding:12px;text-align:center">无 Agent 定时任务</div>';
    var wfJobsHtml = workflowJobs.map(function(j){ return renderJobCard(j, 'workflow'); }).join('')
      || '<div style="color:var(--text3);font-size:12px;padding:12px;text-align:center">无 Workflow 定时任务</div>';

    var stRows = standaloneTasks.map(function(t){
      var icon = t.status==='done'?'✅':t.status==='in_progress'?'⏳':t.status==='blocked'?'🚫':t.status==='cancelled'?'❌':'📋';
      var statusSelect = '<select onchange="updateStandaloneTask(\''+t.id+'\',{status:this.value})" style="background:var(--surface2);border:1px solid var(--overlay-10);border-radius:4px;color:var(--text);font-size:10px;padding:2px 6px">' +
        ['todo','in_progress','done','blocked','cancelled'].map(function(s){return '<option value="'+s+'"'+(t.status===s?' selected':'')+'>'+s+'</option>';}).join('') +
      '</select>';
      var mtgBadge = '';
      if (t.source_meeting_id) {
        var mtgName = meetingNameById[t.source_meeting_id] || ('Meeting '+t.source_meeting_id.substring(0,6));
        mtgBadge = '<span onclick="event.stopPropagation();openMeetingDetail(\''+t.source_meeting_id+'\')" ' +
          'style="display:inline-block;margin-top:4px;padding:2px 8px;border-radius:10px;background:rgba(34,197,94,0.12);color:#22c55e;font-size:10px;font-weight:600;cursor:pointer" ' +
          'title="Click to open meeting">💬 '+esc(mtgName)+'</span>';
      }
      var assigneeName = t.assigned_to ? (agentNameById[t.assigned_to] || t.assigned_to) : '—';
      return '<div style="background:var(--surface);border-radius:8px;padding:10px 12px;border:1px solid var(--overlay-5);margin-bottom:6px">' +
        '<div style="display:flex;justify-content:space-between;align-items:center;gap:8px">' +
          '<div style="flex:1;min-width:0"><span style="font-weight:600;font-size:13px">'+icon+' '+esc(t.title||'')+'</span>' +
          (t.description?'<div style="font-size:10px;color:var(--text3);margin-top:2px">'+esc(t.description.slice(0,120))+'</div>':'') +
          '<div style="font-size:10px;color:var(--text3);margin-top:3px">'+esc(t.priority||'normal')+(t.due_hint?' · ⏰ '+esc(t.due_hint):'')+' · → '+esc(assigneeName)+'</div>' +
          mtgBadge +
          '</div>' +
          '<div style="display:flex;flex-direction:column;gap:4px;align-items:flex-end">'+statusSelect+
            '<button class="btn btn-ghost btn-xs" style="color:var(--error)" onclick="deleteStandaloneTask(\''+t.id+'\')">Delete</button>' +
          '</div>' +
        '</div>' +
      '</div>';
    }).join('') || '<div style="color:var(--text3);font-size:12px;padding:12px;text-align:center">无独立任务</div>';

    // V2 section: merged into the same view, one row per task with
    // a status chip so both V1 and V2 tasks are visible at a glance.
    var v2Html = '';
    if (v2On && v2Tasks.length) {
      var statusChip = function(status) {
        var cfg = {
          running:   ['#22c55e', 'Running'],
          queued:    ['var(--primary)', '排队中'],
          succeeded: ['#22c55e', 'Completed'],
          failed:    ['#ef4444', 'Failed'],
          paused:    ['#f59e0b', '暂停'],
          abandoned: ['var(--text3)', 'Cancelled'],
        };
        var v = cfg[status] || ['var(--text3)', status];
        return '<span style="display:inline-block;padding:2px 8px;border-radius:10px;' +
          'background:var(--overlay-8);color:'+v[0]+';font-size:10px;font-weight:600">' +
          esc(v[1])+'</span>';
      };
      var v2Rows = v2Tasks.map(function(t) {
        var aName = agentNameById[t.agent_id] || t.agent_id.slice(0,8);
        // Build the right action buttons for the row based on status.
        // - running  : 暂停 + 终止
        // - paused   : 继续 + 终止
        // - queued   : 终止
        // - failed / succeeded / abandoned : 删除
        var btns = [];
        var S = t.status;
        if (S === 'running') {
          btns.push('<button class="btn btn-ghost btn-xs" style="color:#f59e0b" ' +
            'onclick="event.stopPropagation();v2PauseTask(\''+esc(t.id)+'\')">⏸ 暂停</button>');
          btns.push('<button class="btn btn-ghost btn-xs" style="color:var(--error)" ' +
            'onclick="event.stopPropagation();v2CancelTask(\''+esc(t.id)+'\')">⏹ 终止</button>');
        } else if (S === 'paused') {
          btns.push('<button class="btn btn-ghost btn-xs" style="color:#22c55e" ' +
            'onclick="event.stopPropagation();v2ResumeTask(\''+esc(t.id)+'\')">▶ 继续</button>');
          btns.push('<button class="btn btn-ghost btn-xs" style="color:var(--error)" ' +
            'onclick="event.stopPropagation();v2CancelTask(\''+esc(t.id)+'\')">⏹ 终止</button>');
        } else if (S === 'queued') {
          btns.push('<button class="btn btn-ghost btn-xs" style="color:var(--error)" ' +
            'onclick="event.stopPropagation();v2CancelTask(\''+esc(t.id)+'\')">⏹ 终止</button>');
        } else {
          // terminal: failed / succeeded / abandoned (= cancelled)
          btns.push('<button class="btn btn-ghost btn-xs" style="color:var(--text3)" ' +
            'onclick="event.stopPropagation();v2DeleteTask(\''+esc(t.id)+'\')">🗑 删除</button>');
        }
        var actionBtn = btns.join('');
        return '<div onclick="v2OpenTaskDetail(\''+esc(t.id)+'\')" ' +
          'style="background:var(--surface);border-radius:8px;padding:10px 12px;' +
          'border:1px solid var(--overlay-5);margin-bottom:6px;cursor:pointer" ' +
          'onmouseover="this.style.borderColor=\'var(--primary)\'" ' +
          'onmouseout="this.style.borderColor=\'var(--overlay-5)\'">' +
          '<div style="display:flex;justify-content:space-between;align-items:center;gap:8px">' +
            '<div style="flex:1;min-width:0">' +
              '<span style="font-weight:600;font-size:13px">🚀 '+esc(t.intent||'(no intent)')+'</span>' +
              '<div style="font-size:10px;color:var(--text3);margin-top:3px">' +
                'phase=' + esc(t.phase) + ' · agent='+esc(aName)+' · template='+esc(t.template_id||'auto') +
              '</div>' +
            '</div>' +
            '<div style="display:flex;gap:6px;align-items:center">' +
              statusChip(t.status) +
              actionBtn +
            '</div>' +
          '</div>' +
        '</div>';
      }).join('');
      v2Html =
        '<div style="margin-top:18px">' +
          '<div style="font-size:12px;font-weight:700;text-transform:uppercase;color:#f97316;margin-bottom:10px">' +
            '🚀 状态机任务 · 6-phase ('+v2Tasks.length+')</div>' +
          v2Rows +
        '</div>';
    } else if (v2On) {
      v2Html =
        '<div style="margin-top:18px">' +
          '<div style="font-size:12px;font-weight:700;text-transform:uppercase;color:#f97316;margin-bottom:10px">' +
            '🚀 状态机任务 · 6-phase (0)</div>' +
          '<div style="color:var(--text3);font-size:12px;padding:12px;text-align:center">' +
            '暂无 状态机任务。点击右上角「新建状态机任务」创建第一个。</div>' +
        '</div>';
    }

    area.innerHTML =
      '<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:18px">' +
        '<div><div style="font-size:12px;font-weight:700;text-transform:uppercase;color:var(--text3);margin-bottom:10px">⏱ 定时任务 · Agent ('+chatJobs.length+')</div>'+chatJobsHtml+'</div>' +
        '<div><div style="font-size:12px;font-weight:700;text-transform:uppercase;color:var(--text3);margin-bottom:10px">🔀 定时任务 · Workflow ('+workflowJobs.length+')</div>'+wfJobsHtml+'</div>' +
        '<div><div style="font-size:12px;font-weight:700;text-transform:uppercase;color:var(--text3);margin-bottom:10px">⚡ 独立任务 ('+standaloneTasks.length+')</div>'+stRows+'</div>' +
      '</div>' +
      v2Html;
  } catch(e) {
    area.innerHTML = '<div style="color:var(--error)">Error: '+esc(e.message)+'</div>';
  }
}

function showCreateStandaloneTaskModal() {
  var agentOpts = '<option value="">Unassigned</option>' + agents.map(function(a){
    return '<option value="'+a.id+'">'+esc((a.role||'')+'-'+a.name)+'</option>';
  }).join('');
  var html = '<div style="padding:24px;max-width:480px"><h3 style="margin:0 0 16px">新建独立任务</h3>' +
    '<input id="st-title" placeholder="任务标题" style="width:100%;padding:10px;margin-bottom:10px;background:var(--surface);border:1px solid var(--overlay-10);border-radius:8px;color:var(--text);font-size:13px">' +
    '<textarea id="st-desc" placeholder="描述 (可选)" style="width:100%;padding:10px;margin-bottom:10px;background:var(--surface);border:1px solid var(--overlay-10);border-radius:8px;color:var(--text);font-size:13px;min-height:60px;resize:vertical"></textarea>' +
    '<select id="st-assignee" style="width:100%;padding:10px;margin-bottom:10px;background:var(--surface);border:1px solid var(--overlay-10);border-radius:8px;color:var(--text);font-size:13px">'+agentOpts+'</select>' +
    '<select id="st-priority" style="width:100%;padding:10px;margin-bottom:10px;background:var(--surface);border:1px solid var(--overlay-10);border-radius:8px;color:var(--text);font-size:13px">' +
      '<option value="normal">Normal</option><option value="low">Low</option><option value="high">High</option><option value="urgent">Urgent</option>' +
    '</select>' +
    '<input id="st-due" placeholder="截止提示 (e.g. \"明天下班前\")" style="width:100%;padding:10px;margin-bottom:14px;background:var(--surface);border:1px solid var(--overlay-10);border-radius:8px;color:var(--text);font-size:13px">' +
    '<div style="display:flex;gap:8px;justify-content:flex-end">' +
      '<button class="btn btn-ghost" onclick="closeModal()">Cancel</button>' +
      '<button class="btn btn-primary" onclick="_lockBtn(this,\'Creating…\',createStandaloneTask)">Create</button>' +
    '</div></div>';
  showModalHTML(html);
}
async function createStandaloneTask() {
  var title = document.getElementById('st-title').value.trim();
  if (!title) { alert('Title cannot be empty'); return; }
  try {
    await api('POST', '/api/portal/standalone-tasks', {
      title: title,
      description: document.getElementById('st-desc').value.trim(),
      assigned_to: document.getElementById('st-assignee').value,
      priority: document.getElementById('st-priority').value,
      due_hint: document.getElementById('st-due').value.trim(),
    });
    closeModal();
    loadTaskCenter();
  } catch(e) { alert('Error: '+e.message); }
}
async function updateStandaloneTask(tid, fields) {
  try { await api('POST', '/api/portal/standalone-tasks/'+tid, fields); loadTaskCenter(); }
  catch(e) { alert('Error: '+e.message); }
}
async function deleteStandaloneTask(tid) {
  if (!await confirm('删除此任务？')) return;
  try { await api('POST', '/api/portal/standalone-tasks/'+tid+'/delete', {}); loadTaskCenter(); }
  catch(e) { alert('Error: '+e.message); }
}

// ============ Orchestration Visualization (force-directed SVG) ============
function renderOrchestration() {
  var c = document.getElementById('content');
  c.innerHTML =
    '<div style="padding:18px">'
    + '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px">'
    + '<div><h2 style="margin:0;font-family:\'Plus Jakarta Sans\',sans-serif;font-size:22px;font-weight:800">Orchestration Map</h2>'
    + '<p style="font-size:12px;color:var(--text3);margin-top:4px">Project · Agent · Task relationship graph</p></div>'
    + '<div style="display:flex;align-items:center;gap:12px"><div id="orch-stats" style="font-size:12px;color:var(--text3)"></div>'
    + '<button class="btn btn-sm" onclick="renderOrchestration()"><span class="material-symbols-outlined" style="font-size:14px">refresh</span> Refresh</button></div></div>'
    + '<div id="orch-legend" style="font-size:11px;color:var(--text3);margin-bottom:8px">'
    + '<span style="display:inline-block;width:10px;height:10px;background:#5b8def;border-radius:2px;margin:0 4px 0 0;vertical-align:middle"></span>Project'
    + '<span style="display:inline-block;width:10px;height:10px;background:#22c55e;border-radius:50%;margin:0 4px 0 12px;vertical-align:middle"></span>Agent'
    + '<span style="display:inline-block;width:10px;height:10px;background:#a855f7;border-radius:50%;margin:0 4px 0 12px;vertical-align:middle"></span>Sub-agent'
    + '<span style="display:inline-block;width:10px;height:10px;background:#f59e0b;border-radius:2px;margin:0 4px 0 12px;vertical-align:middle"></span>Task</div>'
    + '<div id="orch-svg-wrap" style="border:1px solid var(--border);border-radius:8px;background:var(--surface);overflow:auto">'
    + '<svg id="orch-svg" width="100%" height="640" style="display:block"></svg></div>'
    + '<div id="orch-detail" style="margin-top:12px;font-size:12px;color:var(--text2)"></div></div>';

  fetch('/api/portal/orchestration').then(function(r){return r.json();}).then(function(g){
    var stats = g.stats || {};
    document.getElementById('orch-stats').textContent =
      'Projects ' + (stats.projects||0) + ' · Agents ' + (stats.agents||0)
      + ' · 子 Agent ' + (stats.subagents||0) + ' · 任务 ' + (stats.tasks||0);
    _drawOrchestrationGraph(g);
  }).catch(function(e){
    document.getElementById('orch-svg-wrap').innerHTML =
      '<div style="padding:20px;color:var(--error)">Load failed:'+esc(String(e))+'</div>';
  });
}

function _drawOrchestrationGraph(g) {
  var svg = document.getElementById('orch-svg');
  if (!svg) return;
  var nodes = (g.nodes || []).slice();
  var edges = (g.edges || []).slice();
  if (!nodes.length) {
    svg.innerHTML = '<text x="50%" y="50%" text-anchor="middle" fill="#888">暂无数据</text>';
    return;
  }
  var W = svg.clientWidth || 1000;
  var H = 640;

  // Simple layered layout: projects → agents → tasks
  var byType = { project: [], agent: [], subagent: [], task: [] };
  nodes.forEach(function(n){ (byType[n.type] || (byType[n.type]=[])).push(n); });
  var lanes = [
    { type: 'project',  y: 80,  color: '#5b8def', shape: 'rect' },
    { type: 'agent',    y: 240, color: '#22c55e', shape: 'circle' },
    { type: 'subagent', y: 380, color: '#a855f7', shape: 'circle' },
    { type: 'task',     y: 540, color: '#f59e0b', shape: 'rect' },
  ];
  var posMap = {};
  lanes.forEach(function(lane) {
    var arr = byType[lane.type] || [];
    var n = arr.length;
    if (!n) return;
    var step = W / (n + 1);
    arr.forEach(function(node, i) {
      posMap[node.id] = { x: step * (i+1), y: lane.y, color: lane.color, shape: lane.shape, node: node };
    });
  });

  // Build SVG
  var defs = '<defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#888"/></marker></defs>';
  var edgeSvg = edges.map(function(e) {
    var a = posMap[e.from], b = posMap[e.to];
    if (!a || !b) return '';
    var color = e.type === 'parent' ? '#a855f7' :
                e.type === 'assigned' ? '#f59e0b' :
                e.type === 'belongs_to' ? '#94a3b8' : '#5b8def';
    var dash = e.type === 'belongs_to' ? '3,3' : '0';
    return '<line x1="'+a.x+'" y1="'+a.y+'" x2="'+b.x+'" y2="'+b.y+'" stroke="'+color+'" stroke-width="1.2" stroke-dasharray="'+dash+'" marker-end="url(#arrow)" opacity="0.65"/>';
  }).join('');
  var nodeSvg = nodes.map(function(n) {
    var p = posMap[n.id]; if (!p) return '';
    var label = (n.label || n.id).replace(/[<>&]/g, '');
    var status = n.status || '';
    var sub = '';
    if (n.type === 'task' && n.step_total > 0) {
      sub = n.step_done + '/' + n.step_total + ' steps';
    } else if (n.type === 'project') {
      sub = (n.task_count||0) + ' tasks · ' + (n.member_count||0) + ' members';
    } else if (n.type === 'agent' || n.type === 'subagent') {
      sub = (n.role||'') + ' · ' + (n.task_count||0) + ' open';
    }
    var shape;
    if (p.shape === 'circle') {
      shape = '<circle cx="'+p.x+'" cy="'+p.y+'" r="22" fill="'+p.color+'" stroke="#fff" stroke-width="2"/>';
    } else {
      shape = '<rect x="'+(p.x-44)+'" y="'+(p.y-18)+'" width="88" height="36" rx="6" fill="'+p.color+'" stroke="#fff" stroke-width="2"/>';
    }
    var clickHandler = "onclick=\"_orchSelect('"+n.id+"')\"";
    return '<g style="cursor:pointer" '+clickHandler+'>'
      + shape
      + '<text x="'+p.x+'" y="'+(p.y+44)+'" text-anchor="middle" font-size="11" fill="var(--text)" font-weight="600">'+label.substring(0,18)+'</text>'
      + '<text x="'+p.x+'" y="'+(p.y+58)+'" text-anchor="middle" font-size="9" fill="var(--text3)">'+esc(sub)+'</text>'
      + (status ? '<text x="'+p.x+'" y="'+(p.y+4)+'" text-anchor="middle" font-size="9" fill="#fff" font-weight="700">'+esc(status.substring(0,5))+'</text>' : '')
      + '</g>';
  }).join('');
  svg.innerHTML = defs + edgeSvg + nodeSvg;
  window._orchData = g;
}

function _orchSelect(nid) {
  var g = window._orchData; if (!g) return;
  var n = (g.nodes||[]).find(function(x){return x.id===nid;});
  if (!n) return;
  var lines = [];
  Object.keys(n).forEach(function(k){
    if (k === 'id' || k === 'type') return;
    lines.push('<div><span style="color:var(--text3)">'+esc(k)+':</span> '+esc(String(n[k])) + '</div>');
  });
  var related = (g.edges||[]).filter(function(e){return e.from===nid || e.to===nid;});

  // Build navigation buttons based on node type
  var navBtns = '';
  var realId = '';
  if (n.type === 'project') {
    realId = nid.replace(/^proj:/, '');
    navBtns =
      '<button class="btn btn-primary btn-sm" onclick="_orchOpenProject(\''+esc(realId)+'\')">'
      + '<span class="material-symbols-outlined" style="font-size:14px">open_in_new</span> Open Project</button>'
      + '<button class="btn btn-ghost btn-sm" onclick="_orchOpenProjectTab(\''+esc(realId)+'\',\'goals\')">Goals</button>'
      + '<button class="btn btn-ghost btn-sm" onclick="_orchOpenProjectTab(\''+esc(realId)+'\',\'milestones\')">Milestones</button>'
      + '<button class="btn btn-ghost btn-sm" onclick="_orchOpenProjectTab(\''+esc(realId)+'\',\'chat\')">Chat</button>';
  } else if (n.type === 'agent' || n.type === 'subagent') {
    realId = nid.replace(/^agent:/, '');
    navBtns =
      '<button class="btn btn-primary btn-sm" onclick="_orchOpenAgent(\''+esc(realId)+'\')">'
      + '<span class="material-symbols-outlined" style="font-size:14px">smart_toy</span> '+t('orch.openAgent','Open Agent')+'</button>'
      + '<button class="btn btn-ghost btn-sm" onclick="showAgentMemoryView(\''+esc(realId)+'\')">'
      + '<span class="material-symbols-outlined" style="font-size:14px">psychology</span> '+t('mem.openBtn','Memory View')+'</button>';
  } else if (n.type === 'task') {
    // task:projId:taskId
    var rest = nid.replace(/^task:/, '');
    var colon = rest.indexOf(':');
    var projId = colon > 0 ? rest.substring(0, colon) : rest;
    var taskId = colon > 0 ? rest.substring(colon + 1) : '';
    navBtns =
      '<button class="btn btn-primary btn-sm" onclick="_orchOpenTask(\''+esc(projId)+'\',\''+esc(taskId)+'\')">'
      + '<span class="material-symbols-outlined" style="font-size:14px">task</span> 打开任务</button>'
      + '<button class="btn btn-ghost btn-sm" onclick="_orchOpenProject(\''+esc(projId)+'\')">Parent Project</button>';
    if (n.assigned_to) {
      navBtns += '<button class="btn btn-ghost btn-sm" onclick="_orchOpenAgent(\''+esc(n.assigned_to)+'\')">执行 Agent</button>';
    }
  }

  document.getElementById('orch-detail').innerHTML =
    '<div style="background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:12px">'
    + '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:8px">'
    + '  <div style="font-weight:600">'+esc(n.label||n.id)+'</div>'
    + '  <div style="font-size:10px;padding:2px 6px;background:var(--surface2);border-radius:4px;color:var(--text3)">'+esc(n.type||'')+'</div>'
    + '</div>'
    + (navBtns ? '<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:10px">'+navBtns+'</div>' : '')
    + '<div style="font-size:11px;color:var(--text2);line-height:1.6">'+lines.join('')+'</div>'
    + '<div style="margin-top:8px;font-size:11px;color:var(--text3)">关联边: '+related.length+' 条</div></div>';
}

// Navigation helpers for orchestration click-through
function _orchOpenProject(projId) {
  if (typeof openProject === 'function') { openProject(projId); }
  else { currentView = 'project_detail'; currentProject = projId; renderCurrentView(); }
}
function _orchOpenProjectTab(projId, tab) {
  window._projectDetailTab = window._projectDetailTab || {};
  window._projectDetailTab[projId] = tab;
  _orchOpenProject(projId);
}
function _orchOpenAgent(agentId) {
  if (typeof showAgentView === 'function') { showAgentView(agentId, null); }
  else { currentView = 'agent'; currentAgent = agentId; renderCurrentView(); }
}
function _orchOpenTask(projId, taskId) {
  window._projectDetailTab = window._projectDetailTab || {};
  window._projectDetailTab[projId] = 'milestones';
  window._highlightTaskId = taskId;
  _orchOpenProject(projId);
}

// ============ Orchestration Page (top-level, tabs) ============
// 2026-05-02 v2: tab layout per user direction. Each tab fetches its
// own data on activation (no waste on tabs the user never opens).
//   • 画布工作流 (default)  — saved canvas DAGs
//   • 长任务流水线           — in-flight + completed pipelines
//   • Agent 排行             — success-rate leaderboard
//   • 预处理 metrics         — phase calls, cache, breakers
//   • 系统概览               — 4-card stat strip
// Tab state lives on _orchActiveTab (module-level) so it survives
// re-renders triggered by filter changes inside a tab.

var _orchActiveTab = 'canvas';
var _orchPageRoleFilter = '';

function renderOrchestrationPage() {
  try {
    if (localStorage.getItem('tudou_theme') === 'tech') {
      return _techWrapTopLevel(
        { label: 'Workflow Engine', title: 'Orchestration' },
        _renderOrchestrationPageLegacy
      );
    }
  } catch (e) {}
  return _renderOrchestrationPageLegacy();
}
function _renderOrchestrationPageLegacy() {
  var c = document.getElementById('content');
  var _techOp = false;
  try { _techOp = localStorage.getItem('tudou_theme') === 'tech'; } catch (e) {}
  if (_techOp) {
    c.innerHTML = '' +
      '<div style="padding:var(--s-lg);display:flex;flex-direction:column;height:calc(100vh - 80px)">' +
        '<div style="margin-bottom:var(--s-lg)">' +
          '<div class="tc-mono-label" style="color:var(--primary);display:flex;align-items:center;gap:8px"><span>WORKFLOW ENGINE</span><span style="width:6px;height:6px;border-radius:50%;background:var(--secondary);animation:pulse-dot 2s infinite ease-in-out"></span></div>' +
          '<h2 style="font-family:var(--font-display);font-size:30px;font-weight:600;letter-spacing:-0.01em;color:var(--on-surface);margin:8px 0 6px">Orchestration</h2>' +
          '<p class="tc-text-dim" style="font-size:14px;line-height:1.55;max-width:680px">Visual canvas workflows · long-task pipelines · agent performance · system health.</p>' +
        '</div>' +
        '<div id="orch-tabbar" style="display:flex;gap:4px;padding:4px;background:var(--surface-container-low);border:1px solid var(--outline-variant);border-radius:var(--r-md);margin-bottom:var(--s-lg);flex-wrap:wrap;align-self:flex-start"></div>' +
        '<div id="orch-tab-content" style="flex:1;min-height:0;overflow:auto"></div>' +
      '</div>';
  } else {
    c.innerHTML =
      '<div style="padding:18px;display:flex;flex-direction:column;height:calc(100vh - 80px)">'
      + '<div style="margin-bottom:14px">'
      + '<h2 style="margin:0;font-family:\'Plus Jakarta Sans\',sans-serif;font-size:22px;font-weight:800">Orchestration</h2>'
      + '<p style="font-size:12px;color:var(--text3);margin-top:4px">Visual canvas workflows · long-task pipelines · agent performance · system health.</p>'
      + '</div>'
      + '<div id="orch-tabbar" style="display:flex;gap:2px;border-bottom:1px solid var(--border);margin-bottom:16px;flex-wrap:wrap"></div>'
      + '<div id="orch-tab-content" style="flex:1;min-height:0;overflow:auto"></div>'
      + '</div>';
  }
  _renderOrchTabBar();
  _renderOrchTabContent();
}

function _renderOrchTabBar() {
  var bar = document.getElementById('orch-tabbar');
  if (!bar) return;
  var _techOtb = false;
  try { _techOtb = localStorage.getItem('tudou_theme') === 'tech'; } catch (e) {}
  var tabs = _techOtb
    ? [
        {key: 'canvas',    label: 'Canvas Workflows',  icon: 'account_tree'},
        {key: 'pipelines', label: 'Long-Task Pipelines', icon: 'timeline'},
        {key: 'agents',    label: 'Agent Rankings',    icon: 'leaderboard'},
        {key: 'preproc',   label: 'Preprocessor Metrics', icon: 'bolt'},
        {key: 'overview',  label: 'System Overview',   icon: 'insights'},
      ]
    : [
        {key: 'canvas',    label: 'Canvas Workflow',     icon: 'account_tree'},
        {key: 'pipelines', label: '长任务流水线',   icon: 'timeline'},
        {key: 'agents',    label: 'Agent 排行',     icon: 'leaderboard'},
        {key: 'preproc',   label: '预处理 metrics', icon: 'bolt'},
        {key: 'overview',  label: '系统概览',       icon: 'insights'},
      ];
  bar.innerHTML = tabs.map(function(t) {
    var active = (_orchActiveTab === t.key);
    if (_techOtb) {
      var bg = active ? 'rgba(192,193,255,0.10)' : 'transparent';
      var bd = active ? '1px solid rgba(192,193,255,0.30)' : '1px solid transparent';
      var color = active ? 'var(--primary)' : 'var(--outline)';
      return '<button onclick="_switchOrchTab(\'' + t.key + '\')" ' +
        'style="background:' + bg + ';border:' + bd + ';color:' + color + ';' +
        'font-family:var(--font-mono);font-size:11px;letter-spacing:0.04em;' +
        'padding:7px 14px;border-radius:var(--r-md);cursor:pointer;display:inline-flex;align-items:center;gap:6px;transition:all 0.15s">' +
        '<span class="material-symbols-outlined" style="font-size:14px">' + t.icon + '</span>' +
        t.label + '</button>';
    }
    return '<button onclick="_switchOrchTab(\'' + t.key + '\')" class="btn btn-ghost btn-sm" '
      + 'style="border-radius:0;border-bottom:2px solid '+(active?'var(--primary)':'transparent')
      + ';color:'+(active?'var(--primary)':'var(--text2)')
      + ';font-weight:'+(active?'700':'500')+';padding:10px 16px">'
      + '<span class="material-symbols-outlined" style="font-size:16px;margin-right:4px;vertical-align:middle">'+t.icon+'</span>'
      + t.label + '</button>';
  }).join('');
}

window._switchOrchTab = function(key) {
  _orchActiveTab = key;
  _renderOrchTabBar();
  _renderOrchTabContent();
};

function _renderOrchTabContent() {
  var c = document.getElementById('orch-tab-content');
  if (!c) return;
  var tab = _orchActiveTab;

  if (tab === 'canvas') {
    c.innerHTML = '<div id="orch-canvas-section">' + _orchSkelBlock('Canvas Workflow') + '</div>';
    fetch('/api/portal/canvas-workflows').then(function(r){return r.json();}).catch(function(e){return {_err: String(e)};})
      .then(_renderOrchCanvasWorkflows);
  } else if (tab === 'pipelines') {
    c.innerHTML = '<div id="orch-pipelines-section">' + _orchSkelBlock('长任务流水线') + '</div>';
    fetch('/api/portal/orchestration/pipelines?limit=20').then(function(r){return r.json();}).catch(function(e){return {_err: String(e)};})
      .then(_renderOrchPipelines);
  } else if (tab === 'agents') {
    c.innerHTML = '<div id="orch-agents-section">' + _orchSkelBlock('Agent 排行') + '</div>';
    fetch('/api/portal/orchestration/agents?limit=50').then(function(r){return r.json();}).catch(function(e){return {_err: String(e)};})
      .then(_renderOrchAgents);
  } else if (tab === 'preproc') {
    c.innerHTML = '<div id="orch-preprocessor-section">' + _orchSkelBlock('⚡ 预处理 metrics') + '</div>';
    fetch('/api/portal/orchestration/preprocessor-metrics').then(function(r){return r.json();}).catch(function(e){return {_err: String(e)};})
      .then(_renderOrchPreprocessor);
  } else if (tab === 'overview') {
    c.innerHTML = '<div id="orch-overview-cards" style="display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px">'
      + _orchSkelCards(4) + '</div>';
    fetch('/api/portal/orchestration/overview').then(function(r){return r.json();}).catch(function(e){return {_err: String(e)};})
      .then(_renderOrchOverview);
  }
}

function _renderOrchCanvasWorkflows(d) {
  var el = document.getElementById('orch-canvas-section');
  if (!el) return;
  if (d && d._err) {
    el.innerHTML = '<div style="background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:18px;color:var(--error);font-size:12px">画布工作流Load failed: '+esc(d._err)+'</div>';
    return;
  }
  var workflows = (d && d.workflows) || [];
  var _techCv = false;
  try { _techCv = localStorage.getItem('tudou_theme') === 'tech'; } catch (e) {}

  // Section header — in legacy mode the "新建 / 管理" CTA pill sits on
  // the right. In tech mode the CTA is rendered as a dashed-border
  // card that lives inside the workflow grid (visually consistent
  // with the workflow cards), so the section header drops the action.
  var headerHtml = _ui.sectionHeader(
    _techCv ? 'Canvas Workflows' : 'Canvas Workflow',
    {
      icon: 'view_kanban',
      count: _techCv ? workflows.length : (workflows.length + ' 个'),
      action: _techCv ? '' :
        '<button class="btn btn-sm btn-primary" onclick="renderCanvasPage()" title="进入画布编辑器" style="padding:5px 12px;font-size:11px">'
        + _ui.icon('add', {size:14}) + ' 新建 / 管理</button>',
    }
  );

  // Left-edge status stripe — token-based for theme awareness.
  var stripeColor = function(st) {
    if (st === 'ready')    return 'var(--chip-success-fg)';
    if (st === 'disabled') return 'var(--chip-warning-fg)';
    return 'var(--text3)';   // draft
  };

  var bodyHtml;
  if (!workflows.length) {
    bodyHtml = _ui.emptyState({
      icon: 'view_kanban',
      title: '还没有画布工作流',
      hint: '从"新建 / 管理"进入编辑器,拖拽节点构建第一个 DAG',
      cta: '<button class="btn btn-sm btn-primary" onclick="renderCanvasPage()" style="padding:6px 16px;font-size:12px">'
        + _ui.icon('add', {size:14}) + ' 创建第一个</button>',
    });
  } else {
    bodyHtml = '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:14px">'
      + workflows.map(function(w) {
          var st = String(w.executable_status || 'draft');
          var ageHint = '';
          if (w.updated_at) {
            var ageS = (Date.now()/1000) - w.updated_at;
            if (ageS < 60) ageHint = (_techCv ? 'JUST NOW' : '刚刚');
            else if (ageS < 3600) ageHint = Math.floor(ageS/60) + (_techCv ? 'M AGO' : '分钟前');
            else if (ageS < 86400) ageHint = Math.floor(ageS/3600) + (_techCv ? 'H AGO' : '小时前');
            else ageHint = Math.floor(ageS/86400) + (_techCv ? 'D AGO' : '天前');
          }
          var runState = window._orchRunStates ? window._orchRunStates[w.id] : null;
          var isRunning = runState && runState.status === 'running';

          if (_techCv) {
            // Stitch_26-style bento. Status pill in upper-right (READY
            // glows green, DRAFT muted, DISABLED warning), title in body
            // with id mono subtitle, stats grid (NODES/EDGES/UPDATED),
            // EDIT + RUN footer.
            var stColor = st === 'ready' ? 'var(--secondary)'
                        : st === 'disabled' ? 'var(--warning, #ff9800)'
                        : 'var(--outline)';
            var stRGB = st === 'ready' ? '137,206,255'
                      : st === 'disabled' ? '255,152,0'
                      : '144,143,160';
            var stLabel = st === 'ready' ? 'READY'
                        : st === 'disabled' ? 'DISABLED'
                        : 'DRAFT';
            var runBtn = '';
            if (st === 'ready') {
              runBtn = isRunning
                ? '<button disabled class="tc-mono-label" style="padding:8px 14px;background:rgba(255,255,255,0.04);border:1px solid rgba(255,255,255,0.08);border-radius:var(--r-md);color:var(--outline);font-size:10px;cursor:not-allowed;opacity:0.6;letter-spacing:0.05em;display:inline-flex;align-items:center;gap:6px"><span class="material-symbols-outlined" style="font-size:13px;animation:spin 1.2s linear infinite">progress_activity</span>RUNNING…</button>'
                : '<button onclick="event.stopPropagation();_orchRunCanvasFromOverview(\'' + esc(w.id).replace(/\\'/g, "\\\\'") + '\')" class="tc-mono-label" style="padding:8px 14px;background:rgba(34,197,94,0.10);border:1px solid rgba(34,197,94,0.30);border-radius:var(--r-md);color:#22c55e;font-size:10px;cursor:pointer;letter-spacing:0.05em;display:inline-flex;align-items:center;gap:6px;transition:all 0.15s" onmouseover="this.style.background=\'rgba(34,197,94,0.18)\'" onmouseout="this.style.background=\'rgba(34,197,94,0.10)\'"><span class="material-symbols-outlined" style="font-size:13px">play_arrow</span>RUN</button>';
            }
            var openInline = '_canvasOpenEditor(\'' + esc(w.id).replace(/\\'/g, "\\\\'") + '\')';
            return '<div onclick="' + openInline + '" class="tc-card-glass" style="' +
                     'padding:var(--s-lg);display:flex;flex-direction:column;gap:14px;cursor:pointer;' +
                     'position:relative;overflow:hidden;border-top:1px solid rgba(255,255,255,0.15);' +
                     (st === 'ready' ? 'box-shadow:0 0 15px -3px rgba(' + stRGB + ',0.25);' : '') +
                     'transition:transform 0.15s,box-shadow 0.15s" ' +
                     'onmouseover="this.style.transform=\'translateY(-2px)\';this.style.boxShadow=\'0 8px 24px -4px rgba(' + stRGB + ',0.40)\'" ' +
                     'onmouseout="this.style.transform=\'\';this.style.boxShadow=\'\'">' +
                     // Ghost icon
                     '<div style="position:absolute;top:0;right:0;padding:14px;pointer-events:none">' +
                       '<span class="material-symbols-outlined" style="font-size:64px;color:rgba(' + stRGB + ',0.18);margin:-12px -12px 0 0">account_tree</span>' +
                     '</div>' +
                     // Icon-square + status pill
                     '<div style="display:flex;justify-content:space-between;align-items:flex-start;position:relative">' +
                       '<div style="padding:8px;background:rgba(' + stRGB + ',0.10);border:1px solid rgba(' + stRGB + ',0.20);border-radius:var(--r-md);display:inline-flex">' +
                         '<span class="material-symbols-outlined" style="font-size:22px;color:' + stColor + ';font-variation-settings:\'FILL\' 1">account_tree</span>' +
                       '</div>' +
                       '<div style="display:flex;align-items:center;gap:6px;background:var(--surface-container-high);padding:4px 10px;border-radius:9999px;border:1px solid rgba(255,255,255,0.05)">' +
                         '<span style="width:6px;height:6px;border-radius:50%;background:' + stColor + ';' + (st === 'ready' ? 'animation:pulse-dot 2s infinite ease-in-out;box-shadow:0 0 6px ' + stColor + ';' : '') + '"></span>' +
                         '<span class="tc-mono-label" style="font-size:10px;color:var(--on-surface);letter-spacing:0.05em">' + stLabel + '</span>' +
                       '</div>' +
                     '</div>' +
                     // Title + id subtitle
                     '<div style="position:relative">' +
                       '<h3 style="font-family:var(--font-display);font-size:18px;font-weight:600;color:var(--on-surface);margin:0;letter-spacing:-0.01em;line-height:1.3;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">' + esc(w.name || '(unnamed)') + '</h3>' +
                       '<p class="tc-mono-label" style="font-size:10px;color:var(--on-surface-variant);margin:4px 0 0;font-family:var(--font-mono);overflow:hidden;text-overflow:ellipsis;white-space:nowrap">' + esc(w.id) + '</p>' +
                     '</div>' +
                     // Stats grid: NODES / EDGES / UPDATED
                     '<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px;padding:12px 0;border-top:1px solid rgba(255,255,255,0.05);border-bottom:1px solid rgba(255,255,255,0.05)">' +
                       '<div>' +
                         '<p class="tc-mono-label" style="font-size:9px;color:var(--outline);margin:0 0 4px">NODES</p>' +
                         '<p style="font-family:var(--font-mono);font-size:16px;font-weight:600;color:' + stColor + ';margin:0">' + (w.node_count || 0) + '</p>' +
                       '</div>' +
                       '<div>' +
                         '<p class="tc-mono-label" style="font-size:9px;color:var(--outline);margin:0 0 4px">EDGES</p>' +
                         '<p style="font-family:var(--font-mono);font-size:16px;color:var(--on-surface);margin:0">' + (w.edge_count || 0) + '</p>' +
                       '</div>' +
                       '<div>' +
                         '<p class="tc-mono-label" style="font-size:9px;color:var(--outline);margin:0 0 4px">UPDATED</p>' +
                         '<p style="font-family:var(--font-mono);font-size:11px;color:var(--on-surface);margin:0">' + esc(ageHint || '—') + '</p>' +
                       '</div>' +
                     '</div>' +
                     // Footer actions
                     '<div style="display:flex;gap:8px;margin-top:auto;justify-content:flex-end">' +
                       '<button onclick="event.stopPropagation();' + openInline + '" class="tc-mono-label" style="padding:8px 14px;background:rgba(255,255,255,0.04);border:1px solid rgba(255,255,255,0.08);border-radius:var(--r-md);color:var(--on-surface);font-size:10px;cursor:pointer;letter-spacing:0.05em;display:inline-flex;align-items:center;gap:6px;transition:all 0.15s" onmouseover="this.style.background=\'rgba(255,255,255,0.08)\'" onmouseout="this.style.background=\'rgba(255,255,255,0.04)\'">' +
                         '<span class="material-symbols-outlined" style="font-size:13px">edit</span>EDIT' +
                       '</button>' +
                       runBtn +
                     '</div>' +
                   '</div>';
          }

          // Legacy fallback
          var stripe = stripeColor(st);
          var statusBadge = _canvasStatusBadge(st);
          var runStatusPill = _orchRunStatusPill(runState);
          var runBtnLegacy;
          if (st !== 'ready') {
            runBtnLegacy = '';
          } else if (isRunning) {
            runBtnLegacy = '<button class="btn btn-sm" disabled title="已有 run 在执行中,等它完成再点" style="padding:5px 10px;font-size:11px;color:#9ca3af;cursor:not-allowed;opacity:0.6;font-weight:600;border-radius:6px"><span class="material-symbols-outlined" style="font-size:13px;vertical-align:-2px;animation:spin 1.2s linear infinite">progress_activity</span> 运行中…</button>';
          } else {
            runBtnLegacy = '<button class="btn btn-sm" onclick="event.stopPropagation();_orchRunCanvasFromOverview(\'' + esc(w.id).replace(/'/g, "\\'") + '\')" title="启动一次执行" style="padding:5px 10px;font-size:11px;background:#16a34a22;color:#16a34a;border:1px solid #16a34a44;font-weight:600;border-radius:6px"><span class="material-symbols-outlined" style="font-size:13px;vertical-align:-2px">play_arrow</span> 运行</button>';
          }
          var openInlineLegacy = '_canvasOpenEditor(\'' + esc(w.id).replace(/'/g, "\\'") + '\')';
          return '<div onclick="' + openInlineLegacy + '" '
            + 'onmouseenter="this.style.transform=\'translateY(-2px)\';this.style.boxShadow=\'0 6px 16px rgba(0,0,0,0.08)\'" '
            + 'onmouseleave="this.style.transform=\'\';this.style.boxShadow=\'\'" '
            + 'style="position:relative;background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:14px 16px 12px 18px;cursor:pointer;transition:transform 0.15s ease, box-shadow 0.15s ease;overflow:hidden">'
            + '<div style="position:absolute;top:0;bottom:0;left:0;width:4px;background:' + stripe + '"></div>'
            + '<div style="display:flex;align-items:flex-start;justify-content:space-between;gap:8px;margin-bottom:10px">'
            +   '<div style="flex:1;min-width:0">'
            +     '<div style="font-size:14px;font-weight:700;color:var(--text);line-height:1.3;margin-bottom:3px;overflow:hidden;text-overflow:ellipsis;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical">' + esc(w.name || '(unnamed)') + '</div>'
            +     '<div style="font-size:10px;color:var(--text3);font-family:ui-monospace,SFMono-Regular,Menlo,monospace">' + esc(w.id) + '</div>'
            +   '</div>'
            +   '<div style="display:flex;flex-direction:column;align-items:flex-end;gap:4px">' + statusBadge + runStatusPill + '</div>'
            + '</div>'
            + '<div style="display:flex;flex-wrap:wrap;gap:6px;margin-bottom:12px;font-size:10px">'
            +   '<span style="display:inline-flex;align-items:center;gap:3px;padding:2px 7px;background:var(--surface2,rgba(0,0,0,0.04));border-radius:10px;color:var(--text2);font-weight:500"><span class="material-symbols-outlined" style="font-size:11px">circle</span>' + (w.node_count || 0) + ' 节点</span>'
            +   '<span style="display:inline-flex;align-items:center;gap:3px;padding:2px 7px;background:var(--surface2,rgba(0,0,0,0.04));border-radius:10px;color:var(--text2);font-weight:500"><span class="material-symbols-outlined" style="font-size:11px">trending_flat</span>' + (w.edge_count || 0) + ' 边</span>'
            +   (ageHint ? '<span style="display:inline-flex;align-items:center;gap:3px;padding:2px 7px;background:var(--surface2,rgba(0,0,0,0.04));border-radius:10px;color:var(--text3)"><span class="material-symbols-outlined" style="font-size:11px">schedule</span>' + ageHint + '</span>' : '')
            + '</div>'
            + '<div style="display:flex;gap:6px;justify-content:flex-end;border-top:1px solid var(--border-light);padding-top:10px;margin-top:auto">'
            +   '<button class="btn btn-sm btn-ghost" onclick="event.stopPropagation();_canvasOpenEditor(\'' + esc(w.id).replace(/'/g, "\\'") + '\')" style="padding:5px 10px;font-size:11px"><span class="material-symbols-outlined" style="font-size:13px;vertical-align:-2px">edit</span> 编辑</button>'
            +   runBtnLegacy
            + '</div>'
            + '</div>';
        }).join('')
      // Tech-mode "+ New Workflow" card sits as a dashed-bordered tile
      // inside the grid so the add affordance lives in the same visual
      // tier as the workflow cards (matches user request: "添加按钮，
      // 显示为卡片形式").
      + (_techCv
        ? '<div onclick="renderCanvasPage()" ' +
            'onmouseover="this.style.borderColor=\'rgba(192,193,255,0.50)\';this.style.background=\'rgba(192,193,255,0.05)\'" ' +
            'onmouseout="this.style.borderColor=\'\';this.style.background=\'\'" ' +
            'style="display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;min-height:172px;border:2px dashed rgba(192,193,255,0.25);border-radius:12px;background:transparent;cursor:pointer;transition:all 0.18s;padding:20px;text-align:center">' +
            '<div style="width:48px;height:48px;border-radius:9999px;background:rgba(192,193,255,0.10);border:1px solid rgba(192,193,255,0.30);display:flex;align-items:center;justify-content:center">' +
              '<span class="material-symbols-outlined" style="color:var(--primary);font-size:24px">add</span>' +
            '</div>' +
            '<div class="tc-mono-label" style="color:var(--primary);font-size:11px;letter-spacing:0.05em">NEW WORKFLOW</div>' +
            '<div class="tc-text-dim" style="font-size:11px;line-height:1.5">Drag nodes in the canvas editor to build a DAG</div>' +
          '</div>'
        : '')
      + '</div>';
  }

  el.innerHTML = headerHtml + bodyHtml;
}

// Per-workflow run-status cache for the orchestration overview cards.
// Lives on window so it survives tab switches within the same page
// (page refresh wipes it — see _orchAttachOverviewRunStream comment).
//   Shape: { [wfId]: { status, runId, startedAt, es? } }
//   status ∈ 'running' | 'succeeded' | 'failed' | 'aborted'
window._orchRunStates = window._orchRunStates || {};

function _orchRunStatusPill(rs) {
  if (!rs) return '';
  var palette = {
    running:   { bg: 'rgba(202,138,4,0.18)',  fg: '#ca8a04', icon: 'progress_activity', label: 'Running', spin: true },
    succeeded: { bg: 'rgba(34,197,94,0.18)',  fg: '#16a34a', icon: 'check_circle',      label: 'Success' },
    failed:    { bg: 'rgba(239,68,68,0.18)',  fg: '#ef4444', icon: 'error',              label: 'Failed' },
    aborted:   { bg: 'rgba(100,116,139,0.18)',fg: '#64748b', icon: 'stop_circle',        label: '已中止' },
  };
  var p = palette[rs.status]; if (!p) return '';
  var spin = p.spin ? ' style="font-size:11px;animation:spin 1.2s linear infinite"' : ' style="font-size:11px"';
  return '<span style="display:inline-flex;align-items:center;gap:3px;padding:2px 7px;background:' + p.bg + ';color:' + p.fg + ';border-radius:10px;font-size:10px;font-weight:600">'
    + '<span class="material-symbols-outlined"' + spin + '>' + p.icon + '</span>'
    + p.label + '</span>';
}

window._orchRunCanvasFromOverview = async function(wfId) {
  // Block double-click while the previous overview-spawned run is
  // still going. Editor-side has its own guard; this one defends the
  // overview surface in isolation.
  var existing = window._orchRunStates[wfId];
  if (existing && existing.status === 'running') {
    _toast('A run is already in progress, please wait', 'info');
    return;
  }
  try {
    var run = await api('POST', '/api/portal/canvas-workflows/' + encodeURIComponent(wfId) + '/runs', {});
    window._orchRunStates[wfId] = { status: 'running', runId: run.id, startedAt: Date.now() };
    _renderOrchTabContent();   // re-render the cards so this one shows "运行中"
    _toast('▶ 已启动 (run ' + (run.id || '').slice(-8) + ')', 'success');
    _orchAttachOverviewRunStream(wfId, run.id);
  } catch (e) {
    _toast('Start failed:' + e, 'error');
  }
};

function _orchAttachOverviewRunStream(wfId, runId) {
  // Lightweight SSE listener — only watches for terminal events, no
  // per-node updates (those are visible in the editor). When the run
  // ends, flip the card pill to succeeded/failed/aborted and clear
  // after 30 s so the overview doesn't get stale.
  var url = '/api/portal/canvas-workflows/' + encodeURIComponent(wfId) + '/runs/' + encodeURIComponent(runId) + '/events';
  var es = new EventSource(url);
  if (window._orchRunStates[wfId]) window._orchRunStates[wfId].es = es;
  es.onmessage = function(msg) {
    var evt;
    try { evt = JSON.parse(msg.data); } catch (_) { return; }
    var t = evt.type;
    var newStatus = null;
    if (t === 'run_succeeded') newStatus = 'succeeded';
    else if (t === 'run_failed') newStatus = 'failed';
    else if (t === 'run_aborted') newStatus = 'aborted';
    if (newStatus) {
      var prev = window._orchRunStates[wfId] || {};
      window._orchRunStates[wfId] = { status: newStatus, runId: runId, startedAt: prev.startedAt || Date.now() };
      es.close();
      _renderOrchTabContent();
      setTimeout(function() {
        var rs = window._orchRunStates[wfId];
        if (rs && rs.runId === runId && rs.status !== 'running') {
          delete window._orchRunStates[wfId];
          _renderOrchTabContent();
        }
      }, 30000);
    }
  };
  es.onerror = function() {
    // EventSource auto-retries; only treat fully-closed as fatal.
    if (es.readyState === EventSource.CLOSED) {
      // Leave state alone — terminal event may have arrived just before
    }
  };
}

function _orchSkelBlock(title) {
  return '<div style="background:var(--surface);border:1px solid var(--border);border-radius:10px;padding:14px">'
    + '<div style="font-size:13px;font-weight:700;margin-bottom:8px">'+title+'</div>'
    + '<div style="height:200px;opacity:0.4;background:var(--surface2);border-radius:6px"></div></div>';
}

function _orchSkelCards(n) {
  var s = '';
  for (var i = 0; i < n; i++) {
    s += '<div style="background:var(--surface);border:1px solid var(--border);border-radius:10px;padding:16px;height:80px;opacity:0.5"></div>';
  }
  return s;
}

function _renderOrchOverview(d) {
  var el = document.getElementById('orch-overview-cards');
  if (!el) return;
  if (d && d._err) {
    el.innerHTML = '<div style="grid-column:1/-1;color:var(--error);font-size:12px">Load failed: '+esc(d._err)+'</div>';
    return;
  }
  d = d || {};
  var st = d.agent_status || {};
  var tk = d.tokens || {};
  var pj = d.projects || {};
  var cards = [
    {label: 'Agents',       big: String(d.agent_count || 0),     sub: 'Idle '+(st.idle||0)+' · Busy '+(st.busy||0)+' · Error '+(st.error||0), color:'#5b8def', icon:'smart_toy'},
    {label: 'Total Events', big: _formatNum(d.total_events || 0), sub: 'Cumulative across all agents', color:'#22c55e', icon:'bolt'},
    {label: 'Token Usage',  big: _formatNum(tk.total || 0),       sub: 'In '+_formatNum(tk.in||0)+' · Out '+_formatNum(tk.out||0), color:'#f59e0b', icon:'data_usage'},
    {label: 'Long-Task Pipelines', big: String(pj.parent_tasks || 0), sub: 'In flight '+(pj.in_flight_subtasks||0)+' · Aggregated '+(pj.aggregated||0), color:'#a855f7', icon:'account_tree'},
  ];
  el.innerHTML = cards.map(function(c) {
    return '<div style="background:var(--surface);border:1px solid var(--border);border-left:3px solid '+c.color+';border-radius:10px;padding:14px 16px">'
      + '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:8px">'
      + '<div style="font-size:11px;color:var(--text3);font-weight:600;text-transform:uppercase;letter-spacing:0.4px">'+c.label+'</div>'
      + '<span class="material-symbols-outlined" style="font-size:18px;color:'+c.color+';opacity:0.85">'+c.icon+'</span>'
      + '</div>'
      + '<div style="font-size:24px;font-weight:800;color:var(--text);line-height:1">'+c.big+'</div>'
      + '<div style="font-size:11px;color:var(--text3);margin-top:6px">'+c.sub+'</div>'
      + '</div>';
  }).join('');
}

function _renderOrchAgents(d) {
  var el = document.getElementById('orch-agents-section');
  if (!el) return;
  if (d && d._err) {
    el.innerHTML = '<div style="background:var(--surface);border:1px solid var(--border);border-radius:10px;padding:14px;color:var(--error);font-size:12px">Agent 排行Load failed: '+esc(d._err)+'</div>';
    return;
  }
  var rows = (d && d.agents) || [];
  window._orchAgentRows = rows;   // cache for the Context Preview modal
  var roles = {};
  rows.forEach(function(r){ if (r.role) roles[r.role] = true; });
  var roleOptions = '<option value="">All roles</option>'
    + Object.keys(roles).map(function(r){
        return '<option value="'+esc(r)+'"'+(_orchPageRoleFilter===r?' selected':'')+'>'+esc(r)+'</option>';
      }).join('');
  var filtered = _orchPageRoleFilter
    ? rows.filter(function(r){ return r.role === _orchPageRoleFilter; })
    : rows;
  var tableRows = filtered.length ? filtered.map(function(r, i) {
    var hasData = (r.total_count || 0) > 0;
    var rate = hasData ? ((r.success_rate * 100).toFixed(1) + '%') : '—';
    var rateColor = !hasData ? 'var(--text3)' :
      (r.success_rate >= 0.7 ? '#22c55e' : (r.success_rate >= 0.4 ? '#f59e0b' : '#ef4444'));
    var rateTitle = hasData ? '' : ' title="No completed tasks yet — cannot compute success rate"';
    var stColor = r.status === 'idle' ? '#22c55e' : (r.status === 'busy' ? '#f59e0b' : (r.status === 'error' ? '#ef4444' : '#94a3b8'));
    var medal = (hasData && i === 0) ? 'workspace_premium' :
                (hasData && i === 1) ? 'military_tech' :
                (hasData && i === 2) ? 'emoji_events' : '';
    var medalSpan = medal ? '<span class="material-symbols-outlined" style="font-size:14px;color:#f59e0b;vertical-align:middle">'+medal+'</span> ' : '';
    var counts = hasData ? (r.success_count + ' / ' + r.fail_count) : '0 / 0';
    return '<tr style="border-bottom:1px solid var(--border-light);cursor:pointer" onclick="_orchOpenAgent(\''+esc(r.id)+'\')">'
      + '<td style="padding:8px 6px;font-size:12px">'+medalSpan+'<b>'+esc(r.name||r.id)+'</b><div style="font-size:10px;color:var(--text3)">'+esc(r.role||'-')+'</div></td>'
      + '<td style="padding:8px 6px;text-align:right;font-size:12px;font-weight:700;color:'+rateColor+'"'+rateTitle+'>'+rate+'</td>'
      + '<td style="padding:8px 6px;text-align:right;font-size:11px;color:var(--text3)">'+counts+'</td>'
      + '<td style="padding:8px 6px;text-align:right"><span style="font-size:10px;padding:2px 6px;background:'+stColor+'22;color:'+stColor+';border-radius:4px;font-weight:600">'+esc(r.status||'?')+'</span></td>'
      + '</tr>';
  }).join('') : '<tr><td colspan="4" style="padding:40px;text-align:center;color:var(--text3);font-size:12px">No agent data yet</td></tr>';
  // onChange re-renders just THIS tab's content (not the whole page —
  // that would reset _orchActiveTab back to default).
  el.innerHTML = '<div style="background:var(--surface);border:1px solid var(--border);border-radius:10px;padding:14px">'
    + '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px">'
    + '<div style="font-size:13px;font-weight:700"><span class="material-symbols-outlined" style="font-size:16px;vertical-align:middle;margin-right:4px">leaderboard</span>Agent Leaderboard</div>'
    + '<select onchange="_orchPageRoleFilter=this.value;_renderOrchTabContent()" style="font-size:11px;padding:4px 8px;border:1px solid var(--border);border-radius:6px;background:var(--surface)">'+roleOptions+'</select>'
    + '</div>'
    + '<div style="font-size:10px;color:var(--text3);margin-bottom:6px">Sorted by smoothed success rate · (s+1)/(s+f+2)</div>'
    + '<div style="overflow:auto;max-height:520px"><table style="width:100%;border-collapse:collapse">'
    + '<thead><tr style="border-bottom:1px solid var(--border)"><th style="padding:6px;text-align:left;font-size:10px;color:var(--text3);font-weight:600">Name / Role</th>'
    + '<th style="padding:6px;text-align:right;font-size:10px;color:var(--text3);font-weight:600">Success Rate</th>'
    + '<th style="padding:6px;text-align:right;font-size:10px;color:var(--text3);font-weight:600">Wins / Losses</th>'
    + '<th style="padding:6px;text-align:right;font-size:10px;color:var(--text3);font-weight:600">Status</th></tr></thead>'
    + '<tbody>'+tableRows+'</tbody></table></div></div>';
}

function _renderOrchPreprocessor(d) {
  var el = document.getElementById('orch-preprocessor-section');
  if (!el) return;
  if (d && d._err) {
    el.innerHTML = '<div style="background:var(--surface);border:1px solid var(--border);border-radius:10px;padding:14px;color:var(--error);font-size:12px">⚡ 预处理 metrics Load failed: '+esc(d._err)+'</div>';
    return;
  }
  d = d || {};
  var phases = d.phases || [];
  var enabledAgents = d.enabled_agents || [];
  var breaker = d.breaker || [];
  var pausedCount = d.breaker_paused_count || 0;
  var cache = d.cache || {};
  var headerHtml = '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:12px">'
    + '<div style="font-size:13px;font-weight:700">⚡ Preprocessor Metrics</div>'
    + '<div style="font-size:11px;color:var(--text3)">'
    +   enabledAgents.length + ' agents enabled · cache ' + (cache.size||0) + '/' + (cache.capacity||256)
    +   ' · hits ' + (cache.hits||0) + ' / misses ' + (cache.misses||0)
    +   (pausedCount > 0 ? ' · <span style="color:#f59e0b;font-weight:600">⏸ ' + pausedCount + ' phase(s) tripped</span>' : '')
    + '</div></div>';
  var phasesHtml = '';
  if (!phases.length) {
    phasesHtml = '<div style="padding:30px;text-align:center;color:var(--text3);font-size:12px">No preprocessor calls yet — phase data will appear once agents enable preprocessing.</div>';
  } else {
    phasesHtml = '<div style="overflow:auto"><table style="width:100%;border-collapse:collapse;font-size:11px">'
      + '<thead><tr style="border-bottom:1px solid var(--border)">'
      + '<th style="padding:6px;text-align:left;font-size:10px;color:var(--text3);font-weight:600">PHASE</th>'
      + '<th style="padding:6px;text-align:right;font-size:10px;color:var(--text3);font-weight:600">CALLS</th>'
      + '<th style="padding:6px;text-align:right;font-size:10px;color:var(--text3);font-weight:600">CACHE HIT RATE</th>'
      + '<th style="padding:6px;text-align:right;font-size:10px;color:var(--text3);font-weight:600">FALLBACK</th>'
      + '<th style="padding:6px;text-align:right;font-size:10px;color:var(--text3);font-weight:600">TOKENS in/out</th>'
      + '<th style="padding:6px;text-align:right;font-size:10px;color:var(--text3);font-weight:600">AVG LATENCY</th>'
      + '</tr></thead><tbody>';
    phases.forEach(function(p) {
      var hitPct = (p.cache_hit_rate * 100).toFixed(0) + '%';
      var hitColor = p.cache_hit_rate >= 0.5 ? '#22c55e' : (p.cache_hit_rate >= 0.2 ? '#f59e0b' : 'var(--text3)');
      var fbColor = p.fallbacks > 0 ? '#ef4444' : 'var(--text3)';
      phasesHtml += '<tr style="border-bottom:1px solid var(--border-light)">'
        + '<td style="padding:6px"><b>'+esc(p.kind)+'</b></td>'
        + '<td style="padding:6px;text-align:right">'+p.calls+'</td>'
        + '<td style="padding:6px;text-align:right;color:'+hitColor+';font-weight:600">'+hitPct+' ('+p.cache_hits+')</td>'
        + '<td style="padding:6px;text-align:right;color:'+fbColor+'">'+p.fallbacks+'</td>'
        + '<td style="padding:6px;text-align:right;color:var(--text2)">'+_formatNum(p.tokens_in)+' / '+_formatNum(p.tokens_out)+'</td>'
        + '<td style="padding:6px;text-align:right">'+p.latency_ms_avg+'ms</td>'
        + '</tr>';
    });
    phasesHtml += '</tbody></table></div>';
  }
  var breakerHtml = '';
  var pausedBreakers = breaker.filter(function(b){ return b.paused; });
  if (pausedBreakers.length) {
    breakerHtml = '<div style="margin-top:12px;padding:10px;background:#f59e0b11;border-left:3px solid #f59e0b;border-radius:4px">'
      + '<div style="font-size:11px;font-weight:600;color:#f59e0b;margin-bottom:6px">⏸ Tripped (failure rate above threshold, auto-paused 60s)</div>';
    pausedBreakers.forEach(function(b) {
      breakerHtml += '<div style="font-size:11px;margin-bottom:3px">'
        + '<code>'+esc(b.kind)+'</code> on agent <code>'+esc(b.agent_id.slice(0,12))+'</code>'
        + ' · failures '+b.fail_count+'/'+b.history_size+'  · resumes in '+b.paused_remaining_s+'s'
        + '</div>';
    });
    breakerHtml += '</div>';
  }
  var agentsHtml = '';
  if (enabledAgents.length) {
    agentsHtml = '<div style="margin-top:12px;font-size:11px;color:var(--text3)">'
      + '<div style="font-weight:600;margin-bottom:6px">Enabled agents</div>';
    enabledAgents.forEach(function(a) {
      var modeLabel = (a.modes||[]).map(function(m){
        return m === 'optimize_prompt' ? 'prompt' : (m === 'task_understanding' ? 'understand' : m);
      }).join('+') || 'default';
      agentsHtml += '<div style="margin-bottom:3px"><b>'+esc(a.name)+'</b>: '
        + '<code style="font-size:10px">'+esc(a.model.split(':')[0])+'</code>'
        + ' @ <code style="font-size:10px">'+esc(a.endpoint || 'default')+'</code>'
        + ' (' + esc(modeLabel) + ')</div>';
    });
    agentsHtml += '</div>';
  }
  el.innerHTML = '<div style="background:var(--surface);border:1px solid var(--border);border-radius:10px;padding:14px">'
    + headerHtml + phasesHtml + breakerHtml + agentsHtml + '</div>';
}

function _renderOrchPipelines(d) {
  var el = document.getElementById('orch-pipelines-section');
  if (!el) return;
  if (d && d._err) {
    el.innerHTML = '<div style="background:var(--surface);border:1px solid var(--border);border-radius:10px;padding:14px;color:var(--error);font-size:12px">Pipeline load failed: '+esc(d._err)+'</div>';
    return;
  }
  var pipes = (d && d.pipelines) || [];
  // Cache for the DAG modal — avoids re-fetching on click.
  window._orchPipesCache = pipes;
  var body = pipes.length ? pipes.map(function(p) {
    var sc = p.child_status_counts || {};
    var statusBar = ['done','in_progress','todo','blocked','cancelled'].map(function(k){
      var n = sc[k] || 0;
      if (!n) return '';
      var color = k==='done'?'#22c55e':(k==='in_progress'?'#5b8def':(k==='blocked'?'#ef4444':(k==='cancelled'?'#94a3b8':'#f59e0b')));
      return '<span style="display:inline-block;font-size:10px;padding:2px 6px;background:'+color+'22;color:'+color+';border-radius:4px;margin-right:4px">'+k+' '+n+'</span>';
    }).join('');
    var aggBadge = p.aggregated
      ? '<span style="font-size:10px;padding:2px 6px;background:#22c55e22;color:#22c55e;border-radius:4px;font-weight:600">Aggregated · '+esc(p.aggregator_mode||'')+'</span>'
      : '<span style="font-size:10px;padding:2px 6px;background:#f59e0b22;color:#f59e0b;border-radius:4px;font-weight:600">In progress</span>';
    var preview = p.result_preview ? '<div style="font-size:11px;color:var(--text3);margin-top:6px;padding:6px 8px;background:var(--surface2);border-radius:4px;max-height:50px;overflow:hidden">'+esc(p.result_preview)+'</div>' : '';
    return '<div onclick="_orchOpenDAGModal(\''+esc(p.parent_task_id)+'\')" title="Click to view DAG" '
      + 'onmouseenter="this.style.transform=\'translateY(-2px)\';this.style.boxShadow=\'0 6px 16px rgba(0,0,0,0.08)\'" '
      + 'onmouseleave="this.style.transform=\'\';this.style.boxShadow=\'\'" '
      + 'style="background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:14px 16px;cursor:pointer;transition:transform 0.15s ease, box-shadow 0.15s ease">'
      + '<div style="display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:8px">'
      + '<div style="font-size:14px;font-weight:700;flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--text)" title="'+esc(p.parent_title||'')+'">'+esc(p.parent_title||'(untitled)')+'</div>'
      + aggBadge + '</div>'
      + '<div style="font-size:11px;color:var(--text3);margin-bottom:8px">'+esc(p.project_name||'')+' · '+p.child_count+' subtasks · <span style="color:var(--primary)">click for DAG</span></div>'
      + '<div style="display:flex;flex-wrap:wrap;gap:4px">'+statusBar+'</div>'
      + preview + '</div>';
  }).join('')
   : _ui.emptyState({
       icon: 'travel_explore',
       title: 'No long-task pipelines yet',
       hint: 'Agents auto-decompose complex prompts into parallel subtasks — try giving one a multi-step request.',
     });

  // Section header — uses _ui.sectionHeader helper for consistency
  // with the canvas-workflow section above.
  var headerHtml = _ui.sectionHeader('Long-Task Pipelines', {
    icon: 'account_tree',
    count: pipes.length + ' · in-flight first',
  });

  el.innerHTML = headerHtml
    + '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:14px">' + body + '</div>';
}

// ============ DAG modal — task decomposition visualization ============
// Opens a modal showing the parent task's children as a topologically
// layered DAG. Click a node → right-side detail panel shows status,
// assigned agent, output path, and assignment_reason ("why this agent").
// ============ Context Preview Modal (P1b — budget allocator) ============
// Lets the operator see what an agent's per-call context looks like:
// 5-section budget breakdown + rendered preview. Useful for debugging
// "why did agent X see this in its prompt".
// ============ Shared Context Visualization (P7) ============
// Modal showing project shared-context tables: artifacts (timeline) /
// decisions (log) / milestones (Gantt-ish) / handoffs (network) /
// open Q&A. Project-scoped — dropdown to switch.
function _orchOpenSharedContextViz() {
  var existing = document.getElementById('orch-sc-modal');
  if (existing) existing.remove();
  var modal = document.createElement('div');
  modal.id = 'orch-sc-modal';
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.6);z-index:9999;display:flex;align-items:center;justify-content:center;padding:24px';
  modal.innerHTML =
    '<div style="background:var(--surface);border:1px solid var(--border);border-radius:12px;width:min(1100px,100%);max-height:90vh;display:flex;flex-direction:column;overflow:hidden">'
    + '<div style="display:flex;align-items:center;justify-content:space-between;padding:14px 18px;border-bottom:1px solid var(--border-light)">'
    + '<div><div style="font-size:14px;font-weight:700"><span class="material-symbols-outlined" style="font-size:16px;vertical-align:middle">database</span> Project Shared Context</div>'
    + '<div style="font-size:11px;color:var(--text3)">artifacts / decisions / milestones / handoffs / pending_qs — 跨 agent 协作的状态全貌</div></div>'
    + '<button class="btn btn-ghost btn-sm" onclick="document.getElementById(\'orch-sc-modal\').remove()"><span class="material-symbols-outlined" style="font-size:16px">close</span></button></div>'
    + '<div style="padding:14px 18px;border-bottom:1px solid var(--border-light);display:flex;align-items:center;gap:12px">'
    + '<label style="font-size:11px;color:var(--text3);font-weight:600;text-transform:uppercase">PROJECT</label>'
    + '<select id="sc-proj-select" style="flex:1;font-size:12px;padding:6px 8px;border:1px solid var(--border);border-radius:6px;background:var(--surface)" onchange="_orchSCLoad(this.value)"><option value="">Loading…</option></select>'
    + '<button class="btn btn-ghost btn-sm" onclick="_orchSCLoad(document.getElementById(\'sc-proj-select\').value)"><span class="material-symbols-outlined" style="font-size:14px">refresh</span></button></div>'
    + '<div id="sc-content" style="flex:1;overflow:auto;padding:14px 18px"><div style="color:var(--text3);font-size:12px;text-align:center;padding:30px">选择 project 查看共享状态</div></div></div>';
  modal.addEventListener('click', function(e){ if (e.target === modal) modal.remove(); });
  document.body.appendChild(modal);
  // Populate project list
  fetch('/api/portal/orchestration/shared-context/projects')
    .then(function(r){ return r.json(); })
    .then(function(d) {
      var sel = document.getElementById('sc-proj-select');
      var projects = (d && d.projects) || [];
      if (!projects.length) {
        sel.innerHTML = '<option value="">（无项目共享数据）</option>';
        document.getElementById('sc-content').innerHTML = '<div style="color:var(--text3);font-size:12px;text-align:center;padding:40px">还没有项目使用 sc_* 表。等 agent 通过 sc_register_artifact / sc_record_decision / sc_handoff 等工具写入数据后会出现在这里。</div>';
        return;
      }
      sel.innerHTML = '<option value="">--- 选择 project ---</option>'
        + projects.map(function(p) {
          var c = p.counts || {};
          var summary = ' (a=' + (c.artifacts||0) + ' d=' + (c.decisions||0) + ' m=' + (c.milestones||0) + ' h=' + (c.handoffs||0) + ' q=' + (c.pending_qs||0) + ')';
          return '<option value="'+esc(p.project_id)+'">'+esc(p.name)+summary+'</option>';
        }).join('');
      // Auto-select first one
      if (projects.length === 1) {
        sel.value = projects[0].project_id;
        _orchSCLoad(projects[0].project_id);
      }
    });
}

async function _orchSCLoad(project_id) {
  var el = document.getElementById('sc-content');
  if (!el) return;
  if (!project_id) {
    el.innerHTML = '<div style="color:var(--text3);font-size:12px;text-align:center;padding:30px">选择 project</div>';
    return;
  }
  el.innerHTML = '<div style="color:var(--text3);font-size:12px;padding:20px;text-align:center">⏳ 加载中…</div>';
  try {
    var d = await fetch('/api/portal/orchestration/shared-context/state/'+encodeURIComponent(project_id))
      .then(function(r){ return r.json(); });
    if (!d || d.detail) {
      el.innerHTML = '<div style="color:var(--error);font-size:12px;padding:20px">'+esc((d&&d.detail)||'加载失败')+'</div>';
      return;
    }
    _orchSCRender(d, el);
  } catch (e) {
    el.innerHTML = '<div style="color:var(--error);font-size:12px;padding:20px">Load failed:'+esc(String(e))+'</div>';
  }
}

function _orchSCRender(d, el) {
  var names = d.agent_names || {};
  var nameOf = function(aid) { return names[aid] || (aid ? aid.slice(0,8) : '-'); };
  var fmtTs = function(ts) {
    if (!ts) return '-';
    var date = new Date(ts * 1000);
    return date.toLocaleString('zh-CN', {month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});
  };

  // ── Milestones (Gantt-ish list) ──────────────────────────────────
  var ms = d.milestones || [];
  var msHtml = '<div style="margin-bottom:18px"><div style="font-size:13px;font-weight:700;margin-bottom:8px">📅 Milestones ('+ms.length+')</div>';
  if (!ms.length) {
    msHtml += '<div style="font-size:11px;color:var(--text3);padding:10px;background:var(--surface2);border-radius:6px">（无）</div>';
  } else {
    msHtml += '<div style="display:grid;gap:6px">';
    ms.forEach(function(m) {
      var statusColor = m.status==='done'?'#22c55e':m.status==='in_progress'?'#5b8def':m.status==='blocked'?'#ef4444':'#94a3b8';
      msHtml += '<div style="display:flex;align-items:center;gap:8px;padding:8px 10px;background:var(--surface2);border-left:3px solid '+statusColor+';border-radius:4px">'
        + '<span style="font-size:10px;font-weight:600;color:'+statusColor+';text-transform:uppercase">'+esc(m.status)+'</span>'
        + '<span style="font-size:12px;flex:1">'+esc(m.name)+'</span>'
        + '<span style="font-size:10px;color:var(--text3)">owner: '+esc(nameOf(m.owner_agent))+'</span>'
        + (m.blocked_by ? '<span style="font-size:10px;color:#ef4444">blocked by: '+esc(m.blocked_by.slice(0,30))+'</span>' : '')
        + '</div>';
    });
    msHtml += '</div>';
  }
  msHtml += '</div>';

  // ── Decisions (log) ──────────────────────────────────────────────
  var decs = d.decisions || [];
  var decHtml = '<div style="margin-bottom:18px"><div style="font-size:13px;font-weight:700;margin-bottom:8px">⚖️ Decisions ('+decs.length+')</div>';
  if (!decs.length) {
    decHtml += '<div style="font-size:11px;color:var(--text3);padding:10px;background:var(--surface2);border-radius:6px">（无）</div>';
  } else {
    decHtml += '<div style="display:grid;gap:6px">';
    decs.forEach(function(de) {
      var stColor = de.status==='final'?'#22c55e':de.status==='overridden'?'#94a3b8':'#f59e0b';
      decHtml += '<div style="padding:8px 10px;background:var(--surface2);border-left:3px solid '+stColor+';border-radius:4px">'
        + '<div style="display:flex;align-items:center;justify-content:space-between;font-size:12px;margin-bottom:3px">'
        + '<span><b>'+esc(de.topic)+'</b> → <span style="color:'+stColor+';font-weight:600">'+esc(de.decision)+'</span></span>'
        + '<span style="font-size:10px;color:var(--text3)">'+esc(nameOf(de.decided_by))+' · '+fmtTs(de.decided_at)+'</span></div>'
        + (de.rationale ? '<div style="font-size:10px;color:var(--text3);margin-top:3px">'+esc(de.rationale.slice(0,200))+'</div>' : '')
        + '</div>';
    });
    decHtml += '</div>';
  }
  decHtml += '</div>';

  // ── Artifacts (timeline) ─────────────────────────────────────────
  var arts = d.artifacts || [];
  var artHtml = '<div style="margin-bottom:18px"><div style="font-size:13px;font-weight:700;margin-bottom:8px">📦 Artifacts ('+arts.length+')</div>';
  if (!arts.length) {
    artHtml += '<div style="font-size:11px;color:var(--text3);padding:10px;background:var(--surface2);border-radius:6px">（无）</div>';
  } else {
    artHtml += '<div style="overflow:auto;max-height:300px"><table style="width:100%;border-collapse:collapse;font-size:11px"><thead><tr style="border-bottom:1px solid var(--border)">'
      + '<th style="padding:6px;text-align:left;font-size:10px;color:var(--text3);font-weight:600">ID</th>'
      + '<th style="padding:6px;text-align:left;font-size:10px;color:var(--text3);font-weight:600">KIND</th>'
      + '<th style="padding:6px;text-align:left;font-size:10px;color:var(--text3);font-weight:600">TITLE</th>'
      + '<th style="padding:6px;text-align:left;font-size:10px;color:var(--text3);font-weight:600">CREATOR</th>'
      + '<th style="padding:6px;text-align:left;font-size:10px;color:var(--text3);font-weight:600">SUMMARY</th>'
      + '<th style="padding:6px;text-align:right;font-size:10px;color:var(--text3);font-weight:600">CREATED</th></tr></thead><tbody>';
    arts.forEach(function(a) {
      var statusBadge = a.status === 'superseded' ? '<span style="font-size:9px;padding:1px 4px;background:var(--surface3);color:var(--text3);border-radius:3px;margin-left:4px">superseded</span>' : '';
      artHtml += '<tr style="border-bottom:1px solid var(--border-light)">'
        + '<td style="padding:5px 6px;font-family:monospace;font-size:10px"><code>'+esc(a.id.slice(0,12))+'</code></td>'
        + '<td style="padding:5px 6px"><span style="font-size:10px;padding:1px 4px;background:var(--primary-tint-10);color:var(--primary);border-radius:3px">'+esc(a.kind)+'</span></td>'
        + '<td style="padding:5px 6px"><b>'+esc(a.title)+'</b>'+statusBadge+'</td>'
        + '<td style="padding:5px 6px;color:var(--text3)">'+esc(nameOf(a.agent_id))+'</td>'
        + '<td style="padding:5px 6px;color:var(--text3);font-size:10px">'+esc((a.summary||'').slice(0,80))+'</td>'
        + '<td style="padding:5px 6px;text-align:right;font-size:10px;color:var(--text3)">'+fmtTs(a.produced_at)+'</td></tr>';
    });
    artHtml += '</tbody></table></div>';
  }
  artHtml += '</div>';

  // ── Handoffs (network — simple list grouped by status) ───────────
  var ho = d.handoffs || [];
  var hoHtml = '<div style="margin-bottom:18px"><div style="font-size:13px;font-weight:700;margin-bottom:8px">↪️ Handoffs ('+ho.length+')</div>';
  if (!ho.length) {
    hoHtml += '<div style="font-size:11px;color:var(--text3);padding:10px;background:var(--surface2);border-radius:6px">（无）</div>';
  } else {
    hoHtml += '<div style="display:grid;gap:6px">';
    ho.forEach(function(h) {
      var stColor = h.status==='pending'?'#f59e0b':h.status==='acknowledged'?'#5b8def':h.status==='resolved'?'#22c55e':'#94a3b8';
      var refsText = (h.artifact_refs||[]).length ? ' · refs: ' + h.artifact_refs.map(function(r){return r.slice(0,12);}).join(', ') : '';
      hoHtml += '<div style="padding:8px 10px;background:var(--surface2);border-left:3px solid '+stColor+';border-radius:4px;font-size:11px">'
        + '<div style="display:flex;align-items:center;gap:6px;margin-bottom:3px">'
        + '<b>'+esc(nameOf(h.src_agent))+'</b><span style="color:var(--text3)">→</span><b>'+esc(nameOf(h.dst_agent))+'</b>'
        + '<span style="font-size:10px;padding:1px 4px;background:'+stColor+'22;color:'+stColor+';border-radius:3px;font-weight:600">'+esc(h.status)+'</span>'
        + '<span style="font-size:10px;color:var(--text3);margin-left:auto">'+fmtTs(h.ts)+'</span></div>'
        + '<div style="font-size:11px">'+esc(h.intent.slice(0,200))+'</div>'
        + (h.summary ? '<div style="font-size:10px;color:var(--text3);margin-top:3px">'+esc(h.summary.slice(0,150))+'</div>' : '')
        + (refsText ? '<div style="font-size:10px;color:var(--text3);font-family:monospace;margin-top:3px">'+esc(refsText)+'</div>' : '')
        + '</div>';
    });
    hoHtml += '</div>';
  }
  hoHtml += '</div>';

  // ── Pending Q&A ──────────────────────────────────────────────────
  var qs = d.pending_qs || [];
  var qsHtml = '<div style="margin-bottom:8px"><div style="font-size:13px;font-weight:700;margin-bottom:8px">❓ Open Questions ('+qs.length+')</div>';
  if (!qs.length) {
    qsHtml += '<div style="font-size:11px;color:var(--text3);padding:10px;background:var(--surface2);border-radius:6px">（无）</div>';
  } else {
    qsHtml += '<div style="display:grid;gap:6px">';
    qs.forEach(function(q) {
      var stColor = q.status==='answered'?'#22c55e':q.status==='abandoned'?'#94a3b8':'#f59e0b';
      qsHtml += '<div style="padding:8px 10px;background:var(--surface2);border-left:3px solid '+stColor+';border-radius:4px;font-size:11px">'
        + '<div style="display:flex;gap:6px;margin-bottom:3px">'
        + esc(nameOf(q.asked_by))+' <span style="color:var(--text3)">问</span> '+esc(nameOf(q.asked_to))
        + '<span style="font-size:10px;padding:1px 4px;background:'+stColor+'22;color:'+stColor+';border-radius:3px;font-weight:600;margin-left:auto">'+esc(q.status)+'</span></div>'
        + '<div>'+esc(q.question.slice(0,300))+'</div>'
        + (q.answer ? '<div style="font-size:10px;color:var(--text3);margin-top:6px;padding:4px 6px;background:var(--surface);border-radius:3px"><b>答:</b> '+esc(q.answer.slice(0,200))+'</div>' : '')
        + '</div>';
    });
    qsHtml += '</div>';
  }
  qsHtml += '</div>';

  el.innerHTML = msHtml + decHtml + artHtml + hoHtml + qsHtml;
}

function _orchOpenContextPreview() {
  var rows = (window._orchAgentRows || []);
  var defaultAgent = rows[0] ? rows[0].id : '';
  var agentOptions = rows.map(function(a) {
    return '<option value="'+esc(a.id)+'">'+esc(a.name||a.id)+' ('+esc(a.role||'-')+')</option>';
  }).join('');
  var existing = document.getElementById('orch-ctx-modal');
  if (existing) existing.remove();
  var modal = document.createElement('div');
  modal.id = 'orch-ctx-modal';
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.6);z-index:9999;display:flex;align-items:center;justify-content:center;padding:24px';
  modal.innerHTML =
    '<div style="background:var(--surface);border:1px solid var(--border);border-radius:12px;width:min(900px,100%);max-height:90vh;display:flex;flex-direction:column;overflow:hidden">'
    + '<div style="display:flex;align-items:center;justify-content:space-between;padding:14px 18px;border-bottom:1px solid var(--border-light)">'
    + '<div><div style="font-size:14px;font-weight:700"><span class="material-symbols-outlined" style="font-size:16px;vertical-align:middle">data_usage</span> Context 预算预览</div>'
    + '<div style="font-size:11px;color:var(--text3)">查看 budget allocator 给某个 agent 的 5 段 context 分配</div></div>'
    + '<button class="btn btn-ghost btn-sm" onclick="document.getElementById(\'orch-ctx-modal\').remove()"><span class="material-symbols-outlined" style="font-size:16px">close</span></button></div>'
    + '<div style="padding:14px 18px;border-bottom:1px solid var(--border-light);display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px">'
    + '<div><label style="font-size:10px;color:var(--text3);font-weight:600;text-transform:uppercase">Agent</label>'
    + '<select id="ctx-agent" style="width:100%;font-size:12px;padding:6px 8px;border:1px solid var(--border);border-radius:6px;background:var(--surface);margin-top:4px">'+agentOptions+'</select></div>'
    + '<div><label style="font-size:10px;color:var(--text3);font-weight:600;text-transform:uppercase">Project ID（可空）</label>'
    + '<input id="ctx-project" type="text" placeholder="留空 = 不查 project" style="width:100%;font-size:12px;padding:6px 8px;border:1px solid var(--border);border-radius:6px;background:var(--surface);margin-top:4px"/></div>'
    + '<div><label style="font-size:10px;color:var(--text3);font-weight:600;text-transform:uppercase">Budget</label>'
    + '<input id="ctx-budget" type="number" value="2000" min="200" max="8000" step="200" style="width:100%;font-size:12px;padding:6px 8px;border:1px solid var(--border);border-radius:6px;background:var(--surface);margin-top:4px"/></div>'
    + '<div><label style="font-size:10px;color:var(--text3);font-weight:600;text-transform:uppercase">Mode</label>'
    + '<select id="ctx-complex" style="width:100%;font-size:12px;padding:6px 8px;border:1px solid var(--border);border-radius:6px;background:var(--surface);margin-top:4px"><option value="false">默认（35% RAG）</option><option value="true">复杂任务（50% RAG）</option></select></div>'
    + '</div>'
    + '<div style="padding:14px 18px;border-bottom:1px solid var(--border-light)">'
    + '<label style="font-size:10px;color:var(--text3);font-weight:600;text-transform:uppercase">Intent (任务意图)</label>'
    + '<input id="ctx-intent" type="text" value="测试: 起草竞品分析报告" style="width:100%;font-size:12px;padding:6px 8px;border:1px solid var(--border);border-radius:6px;background:var(--surface);margin-top:4px"/>'
    + '<button class="btn btn-primary btn-sm" onclick="_orchRunContextPreview()" style="margin-top:10px"><span class="material-symbols-outlined" style="font-size:14px">play_arrow</span> 计算 context</button></div>'
    + '<div id="ctx-result" style="flex:1;overflow:auto;padding:14px 18px"><div style="color:var(--text3);font-size:12px;text-align:center;padding:30px">点击"计算 context"查看分配结果</div></div></div>';
  modal.addEventListener('click', function(e){ if (e.target === modal) modal.remove(); });
  document.body.appendChild(modal);
  if (defaultAgent) document.getElementById('ctx-agent').value = defaultAgent;
}

async function _orchRunContextPreview() {
  var agent = document.getElementById('ctx-agent').value;
  var proj = document.getElementById('ctx-project').value.trim();
  var budget = document.getElementById('ctx-budget').value;
  var complex = document.getElementById('ctx-complex').value === 'true';
  var intent = document.getElementById('ctx-intent').value || '示例任务';
  var resultEl = document.getElementById('ctx-result');
  resultEl.innerHTML = '<div style="color:var(--text3);font-size:12px;padding:20px;text-align:center">⏳ 计算中…</div>';
  var url = '/api/portal/orchestration/context-preview/' + encodeURIComponent(agent)
    + '?intent=' + encodeURIComponent(intent)
    + '&budget=' + encodeURIComponent(budget)
    + '&complex_task=' + (complex ? 'true' : 'false');
  if (proj) url += '&project_id=' + encodeURIComponent(proj);
  try {
    var d = await fetch(url, {headers: {Authorization: 'Bearer ' + (localStorage.getItem('lt-jwt')||'')}}).then(function(r){return r.json();});
    if (!d || d.detail) {
      resultEl.innerHTML = '<div style="color:var(--error);font-size:12px;padding:20px">'+esc(d&&d.detail||'查询失败')+'</div>';
      return;
    }
    // Section bars
    var sectionRows = (d.sections||[]).map(function(s){
      var pct = s.budget > 0 ? Math.round(100 * s.used / s.budget) : 0;
      var color = s.truncated ? '#ef4444' : (pct > 80 ? '#f59e0b' : '#22c55e');
      var truncBadge = s.truncated ? ' <span style="font-size:9px;padding:1px 4px;background:#ef444422;color:#ef4444;border-radius:3px;font-weight:600">truncated</span>' : '';
      return '<div style="margin-bottom:10px">'
        + '<div style="display:flex;justify-content:space-between;font-size:11px;margin-bottom:3px">'
        + '<div style="font-weight:600">'+esc(s.name)+'<span style="color:var(--text3);font-weight:400;margin-left:6px">· '+esc(s.source||'-')+'</span>'+truncBadge+'</div>'
        + '<div style="color:var(--text3)">'+s.used+' / '+s.budget+' tokens</div></div>'
        + '<div style="height:6px;background:var(--surface2);border-radius:3px;overflow:hidden"><div style="height:100%;width:'+Math.min(100,pct)+'%;background:'+color+'"></div></div>'
        + (s.text_preview ? '<div style="font-size:10px;color:var(--text3);margin-top:4px;padding:6px 8px;background:var(--surface2);border-radius:4px;font-family:monospace;white-space:pre-wrap;max-height:80px;overflow:hidden">'+esc(s.text_preview)+'</div>' : '')
        + '</div>';
    }).join('');
    var headerColor = d.utilization_pct > 90 ? '#ef4444' : (d.utilization_pct > 70 ? '#f59e0b' : '#22c55e');
    resultEl.innerHTML =
      '<div style="display:flex;align-items:center;justify-content:space-between;padding:10px 12px;background:var(--surface2);border-radius:8px;margin-bottom:14px">'
      + '<div style="font-size:12px"><b>'+esc(d.agent_name)+'</b> ('+esc(d.agent_role||'-')+')</div>'
      + '<div style="font-size:12px;color:'+headerColor+';font-weight:700">利用率 '+d.utilization_pct+'% · '+d.total_used+' / '+d.total_budget+' tokens</div></div>'
      + '<div style="font-size:11px;color:var(--text3);margin-bottom:8px;font-weight:600;text-transform:uppercase">5 段分配</div>'
      + sectionRows
      + '<details style="margin-top:14px"><summary style="cursor:pointer;font-size:11px;color:var(--text3);font-weight:600">渲染后完整 context</summary>'
      + '<pre style="margin-top:8px;padding:10px;background:var(--surface2);border-radius:6px;font-size:10px;max-height:300px;overflow:auto;white-space:pre-wrap">'+esc(d.rendered_preview)+'</pre></details>';
  } catch (e) {
    resultEl.innerHTML = '<div style="color:var(--error);font-size:12px;padding:20px">查询失败: '+esc(String(e))+'</div>';
  }
}

function _orchOpenDAGModal(parentId) {
  var pipes = window._orchPipesCache || [];
  var p = pipes.find(function(x){ return x.parent_task_id === parentId; });
  if (!p) {
    alert('Pipeline data not loaded');
    return;
  }
  // Build modal scaffolding (with one-time style block for responsive layout)
  if (!document.getElementById('orch-dag-modal-styles')) {
    var styleEl = document.createElement('style');
    styleEl.id = 'orch-dag-modal-styles';
    styleEl.textContent =
      '#orch-dag-modal .orch-dag-body { display: grid; grid-template-columns: 1fr 280px; overflow: hidden; flex: 1; }' +
      '#orch-dag-modal .orch-dag-detail { border-left: 1px solid var(--border-light); }' +
      '@media (max-width: 700px) {' +
        '#orch-dag-modal .orch-dag-body { grid-template-columns: 1fr; grid-template-rows: 1fr auto; }' +
        '#orch-dag-modal .orch-dag-detail { border-left: none; border-top: 1px solid var(--border-light); max-height: 40vh; }' +
      '}';
    document.head.appendChild(styleEl);
  }
  var existing = document.getElementById('orch-dag-modal');
  if (existing) existing.remove();
  var modal = document.createElement('div');
  modal.id = 'orch-dag-modal';
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.6);z-index:9999;display:flex;align-items:center;justify-content:center;padding:24px';
  modal.innerHTML =
    '<div style="background:var(--surface);border:1px solid var(--border);border-radius:12px;width:min(1100px,100%);max-height:90vh;display:flex;flex-direction:column;overflow:hidden">'
    + '<div style="display:flex;align-items:center;justify-content:space-between;padding:14px 18px;border-bottom:1px solid var(--border-light)">'
    + '<div style="display:flex;align-items:center;gap:8px;flex:1;min-width:0">'
    + '<span class="material-symbols-outlined" style="color:var(--primary)">account_tree</span>'
    + '<div style="flex:1;min-width:0">'
    + '<div style="font-size:14px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+esc(p.parent_title||'')+'</div>'
    + '<div style="font-size:10px;color:var(--text3)">'+esc(p.project_name||'')+' · '+p.child_count+' 子任务 · '
    + (p.aggregated ? 'Aggregated · '+esc(p.aggregator_mode||'') : 'In Progress')+'</div></div></div>'
    + '<button class="btn btn-ghost btn-sm" onclick="document.getElementById(\'orch-dag-modal\').remove()" style="flex-shrink:0">'
    + '<span class="material-symbols-outlined" style="font-size:16px">close</span></button></div>'
    + '<div class="orch-dag-body">'
    + '<div id="orch-dag-svgwrap" style="overflow:auto;background:var(--surface2);padding:16px"></div>'
    + '<div id="orch-dag-detail" class="orch-dag-detail" style="padding:14px;overflow:auto"></div>'
    + '</div></div>';
  // Click on backdrop closes modal
  modal.addEventListener('click', function(e) { if (e.target === modal) modal.remove(); });
  document.body.appendChild(modal);
  _drawOrchDAG(p);
  _orchSelectDAGNode(p, null);
}

function _drawOrchDAG(p) {
  var children = (p.children || []).slice();
  var wrap = document.getElementById('orch-dag-svgwrap');
  if (!wrap) return;
  if (!children.length) {
    wrap.innerHTML = '<div style="padding:40px;color:var(--text3);text-align:center;font-size:12px">该流水线无子任务</div>';
    return;
  }
  // Topological layering: level = longest dep chain depth from any root
  var byId = {};
  children.forEach(function(c){ byId[c.id] = c; });
  var level = {};
  function depthOf(id, seen) {
    if (level[id] != null) return level[id];
    if (seen[id]) return 0;  // cycle guard — shouldn't happen but safe
    seen[id] = true;
    var c = byId[id];
    var deps = (c && c.depends_on) || [];
    var maxDep = -1;
    deps.forEach(function(d) {
      if (byId[d]) maxDep = Math.max(maxDep, depthOf(d, seen));
    });
    var lv = maxDep + 1;
    level[id] = lv;
    return lv;
  }
  children.forEach(function(c){ depthOf(c.id, {}); });
  // Group by level, sort within level by `order`
  var byLevel = {};
  var maxLv = 0;
  children.forEach(function(c) {
    var lv = level[c.id] || 0;
    if (!byLevel[lv]) byLevel[lv] = [];
    byLevel[lv].push(c);
    if (lv > maxLv) maxLv = lv;
  });
  Object.keys(byLevel).forEach(function(k){
    byLevel[k].sort(function(a,b){ return (a.order||0) - (b.order||0); });
  });
  // Compute SVG dimensions
  var COL_W = 220, ROW_H = 80, NODE_W = 180, NODE_H = 56, PAD = 30;
  var maxRows = 0;
  Object.keys(byLevel).forEach(function(k){
    if (byLevel[k].length > maxRows) maxRows = byLevel[k].length;
  });
  var W = (maxLv + 1) * COL_W + PAD * 2;
  var H = maxRows * ROW_H + PAD * 2;
  // Compute node positions
  var pos = {};
  Object.keys(byLevel).forEach(function(lvKey) {
    var lv = parseInt(lvKey, 10);
    var col = byLevel[lvKey];
    col.forEach(function(c, i) {
      pos[c.id] = {
        x: PAD + lv * COL_W + (COL_W - NODE_W) / 2,
        y: PAD + i * ROW_H + (ROW_H - NODE_H) / 2,
      };
    });
  });
  // Build SVG
  var STATUS_COLOR = {
    done: '#22c55e',
    in_progress: '#5b8def',
    todo: '#f59e0b',
    blocked: '#ef4444',
    cancelled: '#94a3b8',
  };
  var defs = '<defs><marker id="dag-arrow" viewBox="0 0 10 10" refX="10" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#94a3b8"/></marker></defs>';
  // Edges first so nodes overlay
  var edges = '';
  children.forEach(function(c) {
    (c.depends_on || []).forEach(function(depId) {
      var a = pos[depId], b = pos[c.id];
      if (!a || !b) return;
      var x1 = a.x + NODE_W, y1 = a.y + NODE_H/2;
      var x2 = b.x, y2 = b.y + NODE_H/2;
      // Smooth Bezier curve
      var midX = (x1 + x2) / 2;
      edges += '<path d="M '+x1+' '+y1+' C '+midX+' '+y1+', '+midX+' '+y2+', '+x2+' '+y2+'" fill="none" stroke="#94a3b8" stroke-width="1.4" marker-end="url(#dag-arrow)" opacity="0.7"/>';
    });
  });
  // Nodes
  var nodes = children.map(function(c) {
    var p2 = pos[c.id];
    var color = STATUS_COLOR[c.status] || '#94a3b8';
    var titleShort = esc((c.title || '').substring(0, 22));
    var agentLabel = c.assigned_to_name ? esc(c.assigned_to_name) : (c.role_hint ? esc(c.role_hint) : 'Unassigned');
    return '<g style="cursor:pointer" onclick="_orchSelectDAGNode(window._orchActivePipe, &quot;'+esc(c.id)+'&quot;)">'
      + '<rect x="'+p2.x+'" y="'+p2.y+'" width="'+NODE_W+'" height="'+NODE_H+'" rx="8" fill="var(--surface)" stroke="'+color+'" stroke-width="2"/>'
      + '<rect x="'+p2.x+'" y="'+p2.y+'" width="4" height="'+NODE_H+'" rx="2" fill="'+color+'"/>'
      + '<text x="'+(p2.x+12)+'" y="'+(p2.y+20)+'" font-size="11" font-weight="700" fill="var(--text)">'+titleShort+'</text>'
      + '<text x="'+(p2.x+12)+'" y="'+(p2.y+36)+'" font-size="10" fill="var(--text3)">'+agentLabel+'</text>'
      + '<text x="'+(p2.x+NODE_W-8)+'" y="'+(p2.y+NODE_H-8)+'" text-anchor="end" font-size="9" font-weight="700" fill="'+color+'">'+esc(c.status||'')+'</text>'
      + '</g>';
  }).join('');
  wrap.innerHTML = '<svg width="'+W+'" height="'+H+'" style="display:block">'+defs+edges+nodes+'</svg>';
  window._orchActivePipe = p;  // remembered for node-click handler
}

function _orchSelectDAGNode(p, childId) {
  var detail = document.getElementById('orch-dag-detail');
  if (!detail) return;
  if (!childId) {
    // Default panel — parent summary
    var modeNote = '';
    if (p.aggregator_mode === 'concat_markdown') modeNote = '所有子结果按顺序拼接为单个 Markdown';
    else if (p.aggregator_mode === 'merge_code') modeNote = '合并所有代码块（按文件路径分组）';
    else if (p.aggregator_mode === 'llm_summarize') modeNote = '用 LLM 综合所有子结果';
    else if (p.aggregator_mode === 'skill') modeNote = 'Calls custom aggregator skill';
    detail.innerHTML = '<div style="font-size:11px;color:var(--text3);margin-bottom:8px;font-weight:600;letter-spacing:0.4px;text-transform:uppercase">流水线概览</div>'
      + '<div style="font-size:12px;line-height:1.7">'
      + '<div><b>父任务</b>：'+esc(p.parent_title||'')+'</div>'
      + '<div><b>状态</b>：'+esc(p.parent_status||'')+'</div>'
      + '<div><b>子任务</b>：'+p.child_count+'</div>'
      + '<div><b>聚合模式</b>：'+esc(p.aggregator_mode||'concat_markdown')+'</div>'
      + (modeNote ? '<div style="color:var(--text3);font-size:11px;margin-top:4px">' + esc(modeNote) + '</div>' : '')
      + (p.aggregated ? '<div style="margin-top:6px"><span style="font-size:10px;padding:2px 6px;background:#22c55e22;color:#22c55e;border-radius:4px;font-weight:600">Aggregated</span></div>' : '')
      + '</div>'
      + '<div style="margin-top:14px;font-size:10px;color:var(--text3)">点击任意节点查看详情</div>';
    return;
  }
  var c = (p.children || []).find(function(x){ return x.id === childId; });
  if (!c) return;
  var color = ({
    done: '#22c55e', in_progress: '#5b8def', todo: '#f59e0b',
    blocked: '#ef4444', cancelled: '#94a3b8',
  })[c.status] || '#94a3b8';
  var reason = c.assignment_reason || {};
  var hasReason = reason.agent_id;
  // Build assignment reason explanation
  var reasonHtml = '';
  if (hasReason) {
    var bullets = [];
    bullets.push((reason.role_match ? '✓' : '○') + ' role 匹配（要求 ' + esc(reason.role_hint||'?') + '，agent 是 ' + esc(reason.agent_role||'?') + '）');
    bullets.push('✓ 平滑成功率 ' + ((reason.success_rate||0) * 100).toFixed(1) + '%');
    bullets.push('✓ 候选总数 ' + (reason.candidates_total||0) + ' 人');
    if ((reason.runner_ups||[]).length) {
      var ru = reason.runner_ups.map(function(r){ return esc(r.name) + '（' + ((r.success_rate||0)*100).toFixed(0) + '%）'; }).join('、');
      bullets.push('备选：' + ru);
    }
    reasonHtml = '<div style="margin-top:14px;padding:10px 12px;background:var(--surface2);border-radius:6px;border-left:3px solid var(--primary)">'
      + '<div style="font-size:10px;color:var(--text3);margin-bottom:6px;font-weight:600;text-transform:uppercase;letter-spacing:0.4px">为什么选这个 agent</div>'
      + bullets.map(function(b){ return '<div style="font-size:11px;line-height:1.6;color:var(--text2)">' + b + '</div>'; }).join('')
      + '</div>';
  } else if (c.assigned_to) {
    reasonHtml = '<div style="margin-top:12px;font-size:10px;color:var(--text3)">（手动分配，无自动决策记录）</div>';
  }
  detail.innerHTML = '<div style="font-size:11px;color:var(--text3);margin-bottom:8px;font-weight:600;letter-spacing:0.4px;text-transform:uppercase">子任务详情</div>'
    + '<div style="font-size:13px;font-weight:700;margin-bottom:6px">'+esc(c.title||'(untitled)')+'</div>'
    + '<div style="margin-bottom:10px"><span style="font-size:10px;padding:2px 6px;background:'+color+'22;color:'+color+';border-radius:4px;font-weight:600">'+esc(c.status||'')+'</span></div>'
    + '<div style="font-size:12px;line-height:1.7">'
    + '<div><b>分配 Agent</b>：' + (c.assigned_to_name ? esc(c.assigned_to_name) : '<span style="color:var(--text3)">未分配</span>') + '</div>'
    + '<div><b>角色提示</b>：' + (c.role_hint ? esc(c.role_hint) : '-') + '</div>'
    + '<div><b>执行顺序</b>：' + (c.order||0) + '</div>'
    + (c.depends_on && c.depends_on.length ? '<div><b>依赖</b>：'+c.depends_on.length+' 个</div>' : '')
    + (c.output_path ? '<div><b>输出</b>：<code style="font-size:10px">'+esc(c.output_path)+'</code></div>' : '')
    + '</div>'
    + reasonHtml;
}

function _formatNum(n) {
  n = Number(n) || 0;
  if (n >= 1000000) return (n/1000000).toFixed(1)+'M';
  if (n >= 1000) return (n/1000).toFixed(1)+'k';
  return String(n);
}

// ---- Knowledge & Memory Hub (redesigned with RAG integration) ----
var _kmTab = 'shared';

function renderKnowledgeMemoryHub() {
  try { if (localStorage.getItem('tudou_theme') === 'tech') return renderKnowledgeMemoryHubTech(); } catch (e) {}
  var c = document.getElementById('content');
  var tabs = [
    { id: 'shared',  label: window.t('tab.km.shared',  '共享知识库'),     icon: 'public' },
    { id: 'private', label: window.t('tab.km.private', '专业领域知识库'), icon: 'school' },
    { id: 'rag',     label: window.t('tab.km.rag',     'RAG 提供方'),     icon: 'cloud' },
    { id: 'memory',  label: window.t('tab.km.memory',  'Agent 私有记忆'), icon: 'psychology' },
  ];
  var tabsHtml = tabs.map(function(t) {
    var active = _kmTab === t.id;
    return '<button onclick="_kmTab=\''+t.id+'\';renderKnowledgeMemoryHub()" style="padding:8px 16px;border:none;background:'+(active?'var(--surface2)':'none')+';color:'+(active?'var(--primary)':'var(--text3)')+';font-size:12px;font-weight:'+(active?'700':'500')+';cursor:pointer;border-radius:8px;display:flex;align-items:center;gap:6px;font-family:inherit;transition:all 0.15s"><span class="material-symbols-outlined" style="font-size:16px">'+t.icon+'</span>'+t.label+'</button>';
  }).join('');

  c.innerHTML = '<div style="display:flex;gap:8px;margin-bottom:20px;padding:8px;background:var(--surface);border-radius:12px;border:1px solid var(--border-light);align-items:center;flex-wrap:wrap">'+tabsHtml+'</div>'
    + '<div id="km-content"></div>';

  if (_kmTab === 'shared') _renderKmShared();
  else if (_kmTab === 'private') _renderKmPrivate();
  else if (_kmTab === 'rag') _renderKmRagProviders();
  else if (_kmTab === 'memory') _renderKmMemory();
}

// ── Tab 1: Shared Knowledge ──
async function _renderKmShared() {
  var sc = document.getElementById('km-content');
  // Tech hub doesn't create #km-content — its body is #tech-hub-km-body
  // (or temporarily renamed to #content during the initial render). The
  // bridge in theme-tech.css handles the visual skin; we just need the
  // right container.
  if (!sc) {
    sc = document.getElementById('tech-hub-km-body') || document.getElementById('content');
  }
  if (!sc) return;
  // Step E (2026-05-08): legacy banner. The migration from Shared
  // Knowledge → Wiki happened in 361f04b; new content should land on
  // the Wiki tab. We keep this view live so admins can verify the
  // migration / spot anything they want to clean up before fully
  // dropping the legacy_kb store.
  // (2026-05-10: deduplicated — recovery transcript replay had inserted
  // this block twice. The second `var _legacyBanner` silently shadowed
  // the first; behavior unchanged but the duplicate is now removed.)
  var _legacyBanner = ''
    + '<div style="padding:12px 14px;margin-bottom:14px;background:rgba(255,180,0,0.08);'
    +              'border:1px solid rgba(255,180,0,0.25);border-radius:8px;'
    +              'display:flex;align-items:flex-start;gap:10px;font-size:12px;color:var(--text2)">'
    +   '<span class="material-symbols-outlined" style="font-size:18px;color:#e6a700;flex-shrink:0">history</span>'
    +   '<div style="flex:1">'
    +     '<div style="font-weight:700;color:var(--text);margin-bottom:2px">这个 tab 已迁出 (legacy)</div>'
    +     '内容已经迁到 <b>Wiki / 经验库</b> tab,新条目请去那边添加。本视图保留供你核对迁移结果,后续会移除。'
    +   '</div>'
    +   '<button class="btn btn-sm" onclick="_kmTab=\'wiki\';renderKnowledgeMemoryHub()" '
    +     'style="flex-shrink:0">去 Wiki tab →</button>'
    + '</div>';
  sc.innerHTML = '<div style="color:var(--text3);padding:20px;text-align:center">加载中...</div>';
  try {
    var data = await api('GET', '/api/portal/knowledge');
    var entries = data || [];
    if (Array.isArray(data)) entries = data;
    else if (data && data.entries) entries = data.entries;
    else entries = [];

    var _techShared = false;
    try { _techShared = localStorage.getItem('tudou_theme') === 'tech'; } catch (e) {}

    // Tech mode: stitch_26-style bento card (matches RAG Providers).
    // Glass panel + ghost icon top-right + small icon square header +
    // status pill + h3 title + 2-col stats + action row.
    var cardsHtml = entries.map(function(e) {
      var tagsList = e.tags || [];
      var preview = (e.content || '').substring(0, 140).replace(/\n/g, ' ');
      var wordCount = (e.content || '').length;
      if (_techShared) {
        var tagPills = tagsList.slice(0, 4).map(function(t) {
          return '<span class="tc-mono-label" style="padding:2px 8px;background:rgba(192,193,255,0.10);color:var(--primary);border:1px solid rgba(192,193,255,0.20);border-radius:9999px;font-size:9px;letter-spacing:0.05em">' + esc(t) + '</span>';
        }).join('');
        var moreTags = tagsList.length > 4
          ? '<span class="tc-mono-label" style="font-size:9px;color:var(--outline);padding:2px 6px">+' + (tagsList.length - 4) + '</span>'
          : '';
        return '' +
          '<div class="tc-card-glass" style="padding:var(--s-lg);display:flex;flex-direction:column;gap:14px;position:relative;overflow:hidden;border-top:1px solid rgba(255,255,255,0.15);box-shadow:0 0 12px -3px rgba(192,193,255,0.10)">' +
            // Ghost icon top-right
            '<div style="position:absolute;top:0;right:0;padding:14px;pointer-events:none">' +
              '<span class="material-symbols-outlined" style="font-size:64px;color:rgba(192,193,255,0.18);margin:-12px -12px 0 0">menu_book</span>' +
            '</div>' +
            // Header: icon-square + status pill
            '<div style="display:flex;justify-content:space-between;align-items:flex-start;position:relative">' +
              '<div style="padding:8px;background:rgba(192,193,255,0.10);border:1px solid rgba(192,193,255,0.20);border-radius:var(--r-md);display:inline-flex">' +
                '<span class="material-symbols-outlined" style="font-size:22px;color:var(--primary);font-variation-settings:\'FILL\' 1">article</span>' +
              '</div>' +
              '<div style="display:flex;align-items:center;gap:6px;background:var(--surface-container-high);padding:4px 10px;border-radius:9999px;border:1px solid rgba(255,255,255,0.05)">' +
                '<span style="width:6px;height:6px;border-radius:50%;background:var(--secondary);animation:pulse-dot 2s infinite ease-in-out;box-shadow:0 0 6px var(--secondary)"></span>' +
                '<span class="tc-mono-label" style="font-size:10px;color:var(--on-surface);letter-spacing:0.05em">INDEXED</span>' +
              '</div>' +
            '</div>' +
            // Title + preview line
            '<div style="position:relative">' +
              '<h3 style="font-family:var(--font-display);font-size:18px;font-weight:600;color:var(--on-surface);margin:0;letter-spacing:-0.01em;line-height:1.3;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">' + esc(e.title || '') + '</h3>' +
              '<p class="tc-text-dim" style="font-size:12px;line-height:1.5;margin:6px 0 0;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden">' + esc(preview) + (preview.length >= 140 ? '…' : '') + '</p>' +
            '</div>' +
            // Stats grid: TAGS + WORDS
            '<div style="display:grid;grid-template-columns:1fr auto;gap:14px;padding:12px 0;border-top:1px solid rgba(255,255,255,0.05);border-bottom:1px solid rgba(255,255,255,0.05);align-items:center">' +
              '<div>' +
                '<p class="tc-mono-label" style="font-size:10px;color:var(--outline);margin:0 0 4px">TAGS (' + tagsList.length + ')</p>' +
                (tagsList.length
                  ? '<div style="display:flex;flex-wrap:wrap;gap:4px;align-items:center">' + tagPills + moreTags + '</div>'
                  : '<span class="tc-text-dim" style="font-size:11px;font-style:italic">— untagged —</span>') +
              '</div>' +
              '<div style="text-align:right">' +
                '<p class="tc-mono-label" style="font-size:10px;color:var(--outline);margin:0 0 4px">WORDS</p>' +
                '<p style="font-family:var(--font-mono);font-size:14px;color:var(--secondary);margin:0">' + wordCount + '</p>' +
              '</div>' +
            '</div>' +
            // Footer actions
            '<div style="display:flex;gap:8px;margin-top:auto">' +
              '<button onclick="_kmEditEntry(\'' + esc(e.id) + '\')" class="tc-mono-label" style="flex:1;padding:8px 0;background:rgba(255,255,255,0.04);border:1px solid rgba(255,255,255,0.08);border-radius:var(--r-md);color:var(--on-surface);font-size:10px;cursor:pointer;letter-spacing:0.05em;display:inline-flex;align-items:center;justify-content:center;gap:6px;transition:all 0.15s" onmouseover="this.style.background=\'rgba(255,255,255,0.08)\'" onmouseout="this.style.background=\'rgba(255,255,255,0.04)\'">' +
                '<span class="material-symbols-outlined" style="font-size:14px">edit</span> EDIT' +
              '</button>' +
              '<button onclick="_kmDeleteEntry(\'' + esc(e.id) + '\')" title="Delete" style="padding:8px 12px;background:rgba(255,180,171,0.06);border:1px solid rgba(255,180,171,0.20);border-radius:var(--r-md);color:var(--error);cursor:pointer;display:inline-flex;align-items:center;transition:all 0.15s" onmouseover="this.style.background=\'rgba(255,180,171,0.14)\'" onmouseout="this.style.background=\'rgba(255,180,171,0.06)\'">' +
                '<span class="material-symbols-outlined" style="font-size:16px">delete</span>' +
              '</button>' +
            '</div>' +
          '</div>';
      }
      // Legacy fallback (unchanged)
      var tags = tagsList.map(function(t){return '<span style="padding:1px 6px;border-radius:4px;font-size:10px;background:var(--primary-tint-10);color:var(--primary)">'+esc(t)+'</span>';}).join(' ');
      return '<div style="background:var(--surface);border-radius:10px;padding:14px;border:1px solid var(--border-light)">'
        + '<div style="display:flex;justify-content:space-between;align-items:start;margin-bottom:6px">'
          + '<div style="font-weight:600;font-size:13px;color:var(--text)">'+esc(e.title||'')+'</div>'
          + '<div style="display:flex;gap:4px;flex-shrink:0">'
            + '<button onclick="_kmEditEntry(\''+esc(e.id)+'\')" class="btn btn-sm" style="padding:4px 8px;font-size:11px">编辑</button>'
            + '<button onclick="_kmDeleteEntry(\''+esc(e.id)+'\')" class="btn btn-sm" style="padding:4px 8px;font-size:11px;color:var(--error)">Delete</button>'
          + '</div>'
        + '</div>'
        + '<div style="font-size:11px;color:var(--text3);margin-bottom:6px;line-height:1.5">'+esc(preview)+(preview.length>=120?'...':'')+'</div>'
        + (tags ? '<div style="display:flex;gap:4px;flex-wrap:wrap">'+tags+'</div>' : '')
        + '</div>';
    }).join('');
    var sharedHeader = _techShared
      ? '<div style="flex:1;min-width:240px">' +
          '<div class="tc-mono-label" style="color:var(--primary);display:flex;align-items:center;gap:8px">' +
            '<span>WIKI / SHARED VAULT</span>' +
            '<span style="width:6px;height:6px;border-radius:50%;background:var(--secondary);animation:pulse-dot 2s infinite ease-in-out"></span>' +
          '</div>' +
          '<h1 class="tc-h2" style="margin-top:6px">Shared Knowledge</h1>' +
          '<div class="tc-text-dim" style="font-size:12px;margin-top:6px">RAG-indexed knowledge available to all enterprise agents.</div>' +
        '</div>'
      : '<div><div style="font-size:15px;font-weight:700;color:var(--text)">共享知识库</div>' +
        '<div style="font-size:12px;color:var(--text3);margin-top:2px">所有企业办公智能体共享的 RAG 知识，支持向量语义检索</div></div>';
    var sharedActions = _techShared
      ? '<div style="display:flex;gap:8px;flex-shrink:0">' +
          '<button class="tc-btn tc-btn-ghost tc-btn-sm" onclick="_kmShowImport(\'knowledge\',\'\')"><span class="material-symbols-outlined" style="font-size:14px">upload_file</span> IMPORT</button>' +
          '<button class="tc-btn tc-btn-primary tc-btn-sm" onclick="_kmShowAddEntry()"><span class="material-symbols-outlined" style="font-size:14px">add</span> NEW ENTRY</button>' +
        '</div>'
      : '<div style="display:flex;gap:8px">' +
          '<button class="btn btn-sm" onclick="_kmShowImport(\'knowledge\',\'\')"><span class="material-symbols-outlined" style="font-size:14px">upload_file</span> 批量导入</button>' +
          '<button class="btn btn-primary btn-sm" onclick="_kmShowAddEntry()"><span class="material-symbols-outlined" style="font-size:14px">add</span> 新增条目</button>' +
        '</div>';
    sc.innerHTML = ''
      + '<div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:16px;gap:12px;flex-wrap:wrap">'
        + sharedHeader
        + sharedActions
      + '</div>'
      + '<div style="display:flex;gap:10px;margin-bottom:16px">'
        + '<input id="km-search-input" placeholder="搜索知识库..." style="flex:1;font-size:13px;background:var(--bg);border:1px solid var(--border);border-radius:8px;color:var(--text);padding:8px 12px" onkeydown="if(event.key===\'Enter\')_kmSearch()">'
        + '<button class="btn btn-sm" onclick="_kmSearch()">搜索</button>'
      + '</div>'
      + (entries.length === 0 ? '<div style="color:var(--text3);padding:40px;text-align:center"><span class="material-symbols-outlined" style="font-size:40px;display:block;margin-bottom:8px">library_books</span>暂无知识条目，点击上方按钮添加</div>' : '')
      + '<div id="km-entries-grid" style="display:grid;grid-template-columns:repeat(auto-fill,minmax(340px,1fr));gap:10px">'+cardsHtml+'</div>';
  } catch(e) {
    sc.innerHTML = '<div style="color:var(--error);padding:20px">Load failed:'+e+'</div>';
  }
}

async function _kmSearch() {
  var q = (document.getElementById('km-search-input')||{}).value||'';
  if (!q.trim()) { _renderKmShared(); return; }
  try {
    var data = await api('GET', '/api/portal/knowledge/search?q='+encodeURIComponent(q));
    var grid = document.getElementById('km-entries-grid');
    if (!grid) return;
    var entries = data || [];
    if (!entries.length) { grid.innerHTML = '<div style="color:var(--text3);padding:20px;text-align:center">未找到匹配 "'+esc(q)+'" 的条目</div>'; return; }
    grid.innerHTML = entries.map(function(e) {
      return '<div style="background:var(--surface);border-radius:10px;padding:14px;border:1px solid var(--border-light)">'
        + '<div style="font-weight:600;font-size:13px;margin-bottom:4px">'+esc(e.title||'')+'</div>'
        + '<div style="font-size:11px;color:var(--text3)">'+esc((e.content||'').substring(0,120))+'</div>'
        + '</div>';
    }).join('');
  } catch(e) { console.error(e); }
}

function _kmShowAddEntry() {
  var html = '<div class="modal-overlay" id="km-add-modal" onclick="if(event.target===this)this.remove()">'
    + '<div class="modal" style="max-width:560px">'
    + '<h3>新增知识条目</h3>'
    + '<div class="form-group"><label>标题 *</label><input id="km-add-title" placeholder="e.g. 公司代码规范"></div>'
    + '<div class="form-group"><label>内容 *</label><textarea id="km-add-content" rows="8" placeholder="知识内容..."></textarea></div>'
    + '<div class="form-group"><label>标签 (逗号分隔)</label><input id="km-add-tags" placeholder="e.g. 规范,编码,Python"></div>'
    + '<div class="form-actions"><button class="btn btn-ghost" onclick="document.getElementById(\'km-add-modal\').remove()">Cancel</button>'
    + '<button class="btn btn-primary" onclick="_kmSaveNewEntry()">保存</button></div>'
    + '</div></div>';
  document.body.insertAdjacentHTML('beforeend', html);
}

async function _kmSaveNewEntry() {
  var title = (document.getElementById('km-add-title')||{}).value||'';
  var content = (document.getElementById('km-add-content')||{}).value||'';
  var tagsRaw = (document.getElementById('km-add-tags')||{}).value||'';
  if (!title.trim() || !content.trim()) { alert('Title and content cannot be empty'); return; }
  var tags = tagsRaw.split(',').map(function(t){return t.trim()}).filter(Boolean);
  try {
    await api('POST', '/api/portal/knowledge', {title:title,content:content,tags:tags});
    var m = document.getElementById('km-add-modal'); if(m)m.remove();
    _renderKmShared();
  } catch(e) { alert('Save failed:'+e); }
}

async function _kmDeleteEntry(id) {
  if (!await confirm('确定删除此知识条目？')) return;
  try {
    await api('POST', '/api/portal/knowledge/'+id+'/delete');
    _renderKmShared();
  } catch(e) { alert('Delete failed:'+e); }
}

async function _kmEditEntry(id) {
  try {
    var entries = await api('GET', '/api/portal/knowledge');
    var arr = Array.isArray(entries) ? entries : (entries.entries||[]);
    var entry = arr.find(function(e){return e.id===id;});
    if (!entry) { alert('Entry not found'); return; }
    var html = '<div class="modal-overlay" id="km-edit-modal" onclick="if(event.target===this)this.remove()">'
      + '<div class="modal" style="max-width:560px">'
      + '<h3>编辑知识条目</h3>'
      + '<div class="form-group"><label>标题</label><input id="km-edit-title" value="'+esc(entry.title||'')+'"></div>'
      + '<div class="form-group"><label>内容</label><textarea id="km-edit-content" rows="8">'+esc(entry.content||'')+'</textarea></div>'
      + '<div class="form-group"><label>标签</label><input id="km-edit-tags" value="'+esc((entry.tags||[]).join(', '))+'"></div>'
      + '<div class="form-actions"><button class="btn btn-ghost" onclick="document.getElementById(\'km-edit-modal\').remove()">Cancel</button>'
      + '<button class="btn btn-primary" onclick="_kmSaveEditEntry(\''+esc(id)+'\')">保存</button></div>'
      + '</div></div>';
    document.body.insertAdjacentHTML('beforeend', html);
  } catch(e) { alert('Load failed:'+e); }
}

async function _kmSaveEditEntry(id) {
  var title = (document.getElementById('km-edit-title')||{}).value;
  var content = (document.getElementById('km-edit-content')||{}).value;
  var tags = ((document.getElementById('km-edit-tags')||{}).value||'').split(',').map(function(t){return t.trim()}).filter(Boolean);
  try {
    await api('POST', '/api/portal/knowledge/'+id, {title:title,content:content,tags:tags});
    var m = document.getElementById('km-edit-modal'); if(m)m.remove();
    _renderKmShared();
  } catch(e) { alert('Save failed:'+e); }
}

