function _kmWikiStatTile(label, value, icon, color, isTech) {
  if (isTech) {
    return ''
      + '<div class="tc-card-glass" style="padding:14px;display:flex;align-items:center;gap:12px;position:relative;overflow:hidden">'
      +   '<div style="position:absolute;top:0;right:0;padding:8px;pointer-events:none">'
      +     '<span class="material-symbols-outlined" style="font-size:36px;color:'+color+';opacity:0.18">'+icon+'</span>'
      +   '</div>'
      +   '<div style="padding:8px;background:'+color+'20;border:1px solid '+color+'40;border-radius:var(--r-md);display:inline-flex">'
      +     '<span class="material-symbols-outlined" style="font-size:18px;color:'+color+';font-variation-settings:\'FILL\' 1">'+icon+'</span>'
      +   '</div>'
      +   '<div>'
      +     '<div style="font-family:var(--font-mono);font-size:22px;font-weight:600;color:'+color+';line-height:1">'+(value||0)+'</div>'
      +     '<div class="tc-mono-label" style="font-size:10px;color:var(--outline);margin-top:4px">'+label+'</div>'
      +   '</div>'
      + '</div>';
  }
  // legacy
  return ''
    + '<div style="background:var(--surface);border:1px solid var(--border-light);border-radius:8px;padding:12px;display:flex;align-items:center;gap:10px">'
    +   '<div style="width:36px;height:36px;border-radius:8px;background:'+color+'20;display:flex;align-items:center;justify-content:center;color:'+color+'"><span class="material-symbols-outlined" style="font-size:20px">'+icon+'</span></div>'
    +   '<div>'
    +     '<div style="font-size:18px;font-weight:700;color:var(--text);line-height:1.1">'+(value||0)+'</div>'
    +     '<div style="font-size:11px;color:var(--text3);margin-top:2px">'+label+'</div>'
    +   '</div>'
    + '</div>';
}

function _kmWikiCardHtml(p, isTech) {
  var refArgs = "'"+esc(p.scope)+"','"+esc(p.kind)+"','"+esc(p.slug)+"'";
  var validToggleLabel = p.is_valid ? (isTech ? 'INVALIDATE' : '失效') : (isTech ? 'RESTORE' : '恢复');
  var validToggleColor = p.is_valid ? 'var(--error)' : '#3fb950';

  if (isTech) {
    var statusColor = p.is_valid
      ? (p.applied_count > 0 ? 'var(--secondary)' : 'var(--primary)')
      : '#ff9800';
    var statusLabel = p.is_valid
      ? (p.applied_count > 0 ? ('APPLIED · ' + p.applied_count) : 'READY')
      : 'INVALID';
    var scopeBadge = '<span class="tc-mono-label" style="padding:2px 8px;background:'+(p.scope==='global'?'rgba(192,193,255,0.10)':'rgba(163,113,247,0.10)')+';color:'+(p.scope==='global'?'var(--primary)':'#a371f7')+';border:1px solid '+(p.scope==='global'?'rgba(192,193,255,0.20)':'rgba(163,113,247,0.20)')+';border-radius:9999px;font-size:9px;letter-spacing:0.05em">'+esc(p.scope).toUpperCase()+'</span>';
    var kindBadge = '<span class="tc-mono-label" style="padding:2px 8px;background:rgba(63,185,80,0.10);color:#3fb950;border:1px solid rgba(63,185,80,0.20);border-radius:9999px;font-size:9px;letter-spacing:0.05em">'+esc(p.kind).toUpperCase()+'</span>';
    var domainBadges = (p.tags||[]).filter(function(t){ return !t.startsWith('source:'); }).slice(0, 4).map(function(t){
      return '<span class="tc-mono-label" style="padding:2px 8px;background:rgba(192,193,255,0.10);color:var(--primary);border:1px solid rgba(192,193,255,0.20);border-radius:9999px;font-size:9px;letter-spacing:0.05em">'+esc(t)+'</span>';
    }).join('');
    return ''
      + '<div class="tc-card-glass" style="padding:var(--s-lg);display:flex;flex-direction:column;gap:14px;position:relative;overflow:hidden;border-top:1px solid rgba(255,255,255,0.15);'+(p.is_valid?'':'opacity:0.55;')+'box-shadow:0 0 12px -3px rgba(192,193,255,0.10)">'
      // ghost icon
      +   '<div style="position:absolute;top:0;right:0;padding:14px;pointer-events:none">'
      +     '<span class="material-symbols-outlined" style="font-size:64px;color:rgba(192,193,255,0.18);margin:-12px -12px 0 0">article</span>'
      +   '</div>'
      // header: icon + status pill
      +   '<div style="display:flex;justify-content:space-between;align-items:flex-start;position:relative">'
      +     '<div style="padding:8px;background:rgba(192,193,255,0.10);border:1px solid rgba(192,193,255,0.20);border-radius:var(--r-md);display:inline-flex">'
      +       '<span class="material-symbols-outlined" style="font-size:22px;color:var(--primary);font-variation-settings:\'FILL\' 1">menu_book</span>'
      +     '</div>'
      +     '<div style="display:flex;align-items:center;gap:6px;background:var(--surface-container-high);padding:4px 10px;border-radius:9999px;border:1px solid rgba(255,255,255,0.05)">'
      +       '<span style="width:6px;height:6px;border-radius:50%;background:'+statusColor+';animation:pulse-dot 2s infinite ease-in-out;box-shadow:0 0 6px '+statusColor+'"></span>'
      +       '<span class="tc-mono-label" style="font-size:10px;color:var(--on-surface);letter-spacing:0.05em">'+statusLabel+'</span>'
      +     '</div>'
      +   '</div>'
      // title + preview
      +   '<div style="position:relative">'
      +     '<h3 style="font-family:var(--font-display);font-size:16px;font-weight:600;color:var(--on-surface);margin:0;letter-spacing:-0.01em;line-height:1.3;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="'+esc(p.title||p.slug)+'">'+esc(p.title||p.slug)+'</h3>'
      +     '<p class="tc-text-dim" style="font-size:12px;line-height:1.5;margin:6px 0 0;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden">'+esc(p.preview||'')+'</p>'
      +   '</div>'
      // badges row
      +   '<div style="display:flex;gap:6px;flex-wrap:wrap;align-items:center">'
      +     scopeBadge + kindBadge + domainBadges
      +   '</div>'
      // success/fail stats grid
      +   '<div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;padding:10px 0;border-top:1px solid rgba(255,255,255,0.05);border-bottom:1px solid rgba(255,255,255,0.05)">'
      +     '<div>'
      +       '<p class="tc-mono-label" style="font-size:9px;color:var(--outline);margin:0 0 2px">SUCCESS / FAIL</p>'
      +       '<p style="font-family:var(--font-mono);font-size:14px;color:var(--secondary);margin:0">'+(p.success_count||0)+' / '+(p.fail_count||0)+'</p>'
      +     '</div>'
      +     '<div style="text-align:right">'
      +       '<p class="tc-mono-label" style="font-size:9px;color:var(--outline);margin:0 0 2px">SLUG</p>'
      +       '<p style="font-family:var(--font-mono);font-size:11px;color:var(--outline);margin:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="'+esc(p.slug)+'">'+esc(p.slug)+'</p>'
      +     '</div>'
      +   '</div>'
      // action row — all 3 buttons get text labels so users don't
      // confuse INVALIDATE with DELETE (icon-only previously caused
      // mis-clicks). Equal-width via flex:1 so the row reads as
      // 3 sibling actions, not "1 primary + 2 dangerous icons".
      +   '<div style="display:flex;gap:8px;margin-top:auto">'
      +     '<button onclick="_kmWikiEdit('+refArgs+')" class="tc-mono-label" style="flex:1;padding:8px 0;background:rgba(255,255,255,0.04);border:1px solid rgba(255,255,255,0.08);border-radius:var(--r-md);color:var(--on-surface);font-size:10px;cursor:pointer;letter-spacing:0.05em;display:inline-flex;align-items:center;justify-content:center;gap:6px;transition:all 0.15s" onmouseover="this.style.background=\'rgba(255,255,255,0.08)\'" onmouseout="this.style.background=\'rgba(255,255,255,0.04)\'"><span class="material-symbols-outlined" style="font-size:14px">edit</span> EDIT</button>'
      +     '<button onclick="_kmWikiToggleValid('+refArgs+')" class="tc-mono-label" title="'+validToggleLabel+(p.is_valid ? ' — agent 检索时跳过此 entry' : ' — 恢复对 agent 可见')+'" style="flex:1;padding:8px 0;background:'+validToggleColor+'10;border:1px solid '+validToggleColor+'30;border-radius:var(--r-md);color:'+validToggleColor+';cursor:pointer;font-size:10px;letter-spacing:0.05em;display:inline-flex;align-items:center;justify-content:center;gap:6px;transition:all 0.15s" onmouseover="this.style.background=\''+validToggleColor+'20\'" onmouseout="this.style.background=\''+validToggleColor+'10\'">'
      +       '<span class="material-symbols-outlined" style="font-size:14px">'+(p.is_valid ? 'block' : 'check_circle')+'</span> '+validToggleLabel
      +     '</button>'
      +     '<button onclick="_kmWikiDelete('+refArgs+')" class="tc-mono-label" title="DELETE — 永久从磁盘移除文件,不可恢复" style="flex:1;padding:8px 0;background:rgba(255,180,171,0.06);border:1px solid rgba(255,180,171,0.20);border-radius:var(--r-md);color:var(--error);cursor:pointer;font-size:10px;letter-spacing:0.05em;display:inline-flex;align-items:center;justify-content:center;gap:6px;transition:all 0.15s" onmouseover="this.style.background=\'rgba(255,180,171,0.14)\'" onmouseout="this.style.background=\'rgba(255,180,171,0.06)\'">'
      +       '<span class="material-symbols-outlined" style="font-size:14px">delete</span> DELETE'
      +     '</button>'
      +   '</div>'
      + '</div>';
  }

  // ── Legacy card ──
  var scopeBadgeL = '<span style="padding:1px 6px;border-radius:4px;font-size:10px;background:'+(p.scope==='global'?'rgba(99,102,241,0.12);color:var(--primary)':'rgba(139,92,246,0.12);color:#a371f7')+'">'+esc(p.scope)+'</span>';
  var kindBadgeL = '<span style="padding:1px 6px;border-radius:4px;font-size:10px;background:rgba(34,197,94,0.12);color:#3fb950">'+esc(p.kind)+'</span>';
  var validBadgeL = p.is_valid
    ? ''
    : '<span title="已失效 — 3 连败被标记，不再返回给 agent" style="padding:1px 6px;border-radius:4px;font-size:10px;background:rgba(248,81,73,0.12);color:var(--error)">已失效</span>';
  var statsL = '<span style="font-size:10px;color:var(--text3);font-family:Menlo,monospace">✓'+p.success_count+'/✗'+p.fail_count+(p.applied_count?' · applied '+p.applied_count:'')+'</span>';
  var tagsL = (p.tags||[]).slice(0,5).map(function(t){
    return '<span style="padding:1px 5px;border-radius:3px;font-size:10px;background:var(--primary-tint-10);color:var(--primary)">'+esc(t)+'</span>';
  }).join(' ');
  var moreTagsL = (p.tags||[]).length > 5
    ? '<span style="font-size:10px;color:var(--text3)">+'+((p.tags||[]).length-5)+'</span>'
    : '';
  return ''
    + '<div style="background:var(--surface);border:1px solid var(--border-light);border-radius:10px;padding:14px;display:flex;flex-direction:column;gap:8px'+(p.is_valid?'':';opacity:0.6')+'">'
    +   '<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:8px">'
    +     '<div style="font-weight:600;font-size:13px;color:var(--text);flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis">'+esc(p.title||p.slug)+'</div>'
    +     '<div style="display:flex;gap:4px;flex-shrink:0">'
    +       '<button onclick="_kmWikiEdit('+refArgs+')" class="btn btn-sm" style="padding:3px 8px;font-size:11px">编辑</button>'
    +       '<button onclick="_kmWikiToggleValid('+refArgs+')" class="btn btn-sm" style="padding:3px 8px;font-size:11px;color:'+validToggleColor+'">'+validToggleLabel+'</button>'
    +       '<button onclick="_kmWikiDelete('+refArgs+')" class="btn btn-sm" style="padding:3px 8px;font-size:11px;color:var(--error)">删除</button>'
    +     '</div>'
    +   '</div>'
    +   '<div style="display:flex;gap:6px;align-items:center;flex-wrap:wrap">'
    +     scopeBadgeL + kindBadgeL + validBadgeL + statsL
    +   '</div>'
    +   '<div style="font-size:11px;color:var(--text3);line-height:1.4;max-height:50px;overflow:hidden">'+esc(p.preview||'')+'</div>'
    +   (tagsL ? '<div style="display:flex;gap:4px;flex-wrap:wrap;align-items:center">'+tagsL+' '+moreTagsL+'</div>' : '')
    +   '<div style="font-size:10px;color:var(--text3);font-family:Menlo,monospace;margin-top:auto">'+p.slug+'</div>'
    + '</div>';
}

async function _kmWikiFetchList() {
  var qs = [];
  if (_kmWikiFilters.scope) qs.push('scope='+encodeURIComponent(_kmWikiFilters.scope));
  if (_kmWikiFilters.kind) qs.push('kind='+encodeURIComponent(_kmWikiFilters.kind));
  if (_kmWikiFilters.domain) qs.push('domain='+encodeURIComponent(_kmWikiFilters.domain));
  if (_kmWikiFilters.q) qs.push('q='+encodeURIComponent(_kmWikiFilters.q));
  if (_kmWikiFilters.include_invalid) qs.push('include_invalid=true');
  return await api('GET', '/api/portal/wiki' + (qs.length ? '?'+qs.join('&') : ''));
}

function _kmWikiApplyFilters() {
  _kmWikiFilters.scope = (document.getElementById('kmw-scope')||{}).value || '';
  _kmWikiFilters.kind = (document.getElementById('kmw-kind')||{}).value || '';
  _kmWikiFilters.domain = (document.getElementById('kmw-domain')||{}).value || '';
  _kmWikiFilters.q = (document.getElementById('kmw-q')||{}).value || '';
  _kmWikiFilters.include_invalid = (document.getElementById('kmw-include-invalid')||{}).checked || false;
  _renderKmWiki();
}

async function _kmWikiToggleValid(scope, kind, slug) {
  // 2026-05-08: confirm-only flow (no success toast). The list re-
  // render is the feedback — the chip badge flips from READY/APPLIED
  // to INVALID (or vice versa), or the row disappears if the default
  // filter hides invalid pages. Two-popup design (confirm + toast)
  // was redundant per user feedback "弹一个框，也弹一个 toast".
  var ok = confirm(
    '确认切换 ' + scope + '/' + kind + '/' + slug + ' 的有效状态？\n\n' +
    '• 标记失效：agent 检索时不再返回该 entry,页面在默认列表里也会隐藏\n' +
    '• 标记恢复：恢复对 agent 可见'
  );
  if (!ok) return;
  try {
    await api('POST', '/api/portal/wiki/toggle-valid', { scope: scope, kind: kind, slug: slug });
    _renderKmWiki();   // re-render IS the feedback
  } catch (e) {
    alert('Toggle failed: ' + (e.message || e));
  }
}

async function _kmWikiDelete(scope, kind, slug) {
  // 2026-05-08: confirm-only, no success toast. The card disappearing
  // from the list IS the feedback. User flagged the confirm+toast
  // double popup as redundant.
  if (!confirm('永久删除 ' + scope + '/' + kind + '/' + slug + ' ？\n此操作不可恢复 — 文件会从磁盘移除。')) return;
  try {
    await api('POST', '/api/portal/wiki/delete', { scope: scope, kind: kind, slug: slug });
    _renderKmWiki();   // re-render IS the feedback
  } catch (e) {
    alert('Delete failed: ' + (e.message || e));
  }
}

async function _kmWikiEdit(scope, kind, slug) {
  try {
    var p = await api('GET', '/api/portal/wiki/page?scope=' + encodeURIComponent(scope) + '&kind=' + encodeURIComponent(kind) + '&slug=' + encodeURIComponent(slug));
    _kmWikiShowEditModal(p, /*isCreate=*/false);
  } catch (e) {
    alert('Load failed: ' + (e.message || e));
  }
}

function _kmWikiShowCreate() {
  _kmWikiShowEditModal({
    scope: 'global', kind: 'experience', slug: '', title: '', body: '',
    tags: [], sources: [], related: [],
    signals_match: [], preconditions: [], strategy: [], validation: [],
    constraints: {},
  }, /*isCreate=*/true);
}

function _kmWikiShowEditModal(p, isCreate) {
  var kindOpts = ['experience','methodology','template','pattern','reference']
    .map(function(k){ return '<option value="'+k+'"'+(p.kind===k?' selected':'')+'>'+k+'</option>'; }).join('');
  // 2026-05-08: scope is now editable on edit (with a select drop-
  // down + "(原 scope)" hint). Backend /edit handles scope move via
  // new_scope field. User-reported request: "scope 要矫正一下".
  var commonScopes = ['global', 'role:pm', 'role:coder', 'role:reviewer',
                      'role:researcher', 'role:tester', 'role:general'];
  // Add the page's current scope if not in the standard list
  if (p.scope && commonScopes.indexOf(p.scope) === -1) {
    commonScopes.push(p.scope);
  }
  var scopeOpts = commonScopes.map(function(s){
    return '<option value="'+esc(s)+'"'+(p.scope===s?' selected':'')+'>'+esc(s)+'</option>';
  }).join('');
  var html = ''
    + '<div class="modal-overlay" id="kmw-edit-modal" onclick="if(event.target===this)this.remove()">'
    +   '<div class="modal" style="max-width:860px;max-height:92vh;overflow-y:auto">'
    +     '<h3>'+(isCreate?'新建 Wiki 条目':'编辑 Wiki 条目')+'</h3>'
    +     '<div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:8px">'
    +       '<div class="form-group"><label>Scope</label><select id="kmw-edit-scope">'+scopeOpts+'</select>'
    +         (isCreate ? '' : '<div style="font-size:10px;color:var(--text3);margin-top:4px">改 scope 会移动文件到新路径(scope 矫正)</div>')
    +       '</div>'
    +       '<div class="form-group"><label>Kind</label><select id="kmw-edit-kind"'+(isCreate?'':' disabled')+'>'+kindOpts+'</select></div>'
    +     '</div>'
    +     '<div class="form-group"><label>Title</label><input id="kmw-edit-title" value="'+esc(p.title||'')+'"></div>'
    +     (isCreate
        ? '<div class="form-group"><label>Slug (留空自动生成)</label><input id="kmw-edit-slug" value="" placeholder="auto"></div>'
        : '<div style="font-size:11px;color:var(--text3);margin-bottom:8px">slug: <code data-orig-scope="'+esc(p.scope)+'">'+esc(p.slug)+'</code> · 当前路径 <code>'+esc(p.scope)+'/'+esc(p.kind)+'</code></div>'
      )
    +     '<div class="form-group"><label>Tags (逗号分隔)</label><input id="kmw-edit-tags" value="'+esc((p.tags||[]).join(', '))+'" placeholder="payments, security, audit"></div>'
    +     '<div class="form-group"><label>Domains (逗号分隔, 受控词表)</label><input id="kmw-edit-domains" value="'+esc((p.domains||[]).join(', '))+'" placeholder="security, payments-compliance, project-management..."></div>'
    +     '<div class="form-group"><label>Body (Markdown)</label><textarea id="kmw-edit-body" rows="14" style="font-family:Menlo,Monaco,monospace;font-size:12px;line-height:1.5">'+esc(p.body||'')+'</textarea></div>'
    +     '<details style="margin-bottom:10px"><summary style="cursor:pointer;font-size:12px;color:var(--text2)">高级字段（结构化经验，可选）</summary>'
    +       '<div class="form-group" style="margin-top:10px"><label>Signals Match (逗号分隔关键词)</label><input id="kmw-edit-signals" value="'+esc((p.signals_match||[]).join(', '))+'"></div>'
    +       '<div class="form-group"><label>Preconditions (每行一条)</label><textarea id="kmw-edit-precond" rows="3">'+esc((p.preconditions||[]).join('\n'))+'</textarea></div>'
    +       '<div class="form-group"><label>Strategy (每行一条)</label><textarea id="kmw-edit-strat" rows="4">'+esc((p.strategy||[]).join('\n'))+'</textarea></div>'
    +       '<div class="form-group"><label>Validation (每行一条)</label><textarea id="kmw-edit-valid" rows="3">'+esc((p.validation||[]).join('\n'))+'</textarea></div>'
    +     '</details>'
    +     (isCreate ? '' : '<div style="font-size:11px;color:var(--text3);margin-bottom:10px">✓'+(p.success_count||0)+'/✗'+(p.fail_count||0)+' · applied '+(p.applied_count||0)+' · valid='+p.is_valid+'</div>')
    +     '<div class="form-actions">'
    +       '<button class="btn btn-ghost" onclick="document.getElementById(\'kmw-edit-modal\').remove()">取消</button>'
    +       '<button class="btn btn-primary" onclick="_kmWikiSaveModal('+(isCreate?'true':'false')+')">'+(isCreate?'创建':'保存')+'</button>'
    +     '</div>'
    +   '</div>'
    + '</div>';
  document.body.insertAdjacentHTML('beforeend', html);
}

async function _kmWikiSaveModal(isCreate) {
  function _val(id) { var e = document.getElementById(id); return e ? e.value.trim() : ''; }
  function _list(id) { return _val(id).split(',').map(function(t){ return t.trim(); }).filter(Boolean); }
  function _lines(id) { return _val(id).split('\n').map(function(t){ return t.trim(); }).filter(Boolean); }

  var formScope = _val('kmw-edit-scope') || 'global';
  var payload = {
    scope: formScope,
    kind:  _val('kmw-edit-kind') || 'experience',
    title: _val('kmw-edit-title'),
    body:  document.getElementById('kmw-edit-body').value,  // preserve newlines
    tags:  _list('kmw-edit-tags'),
    domains: _list('kmw-edit-domains'),
    signals_match: _list('kmw-edit-signals'),
    preconditions: _lines('kmw-edit-precond'),
    strategy:      _lines('kmw-edit-strat'),
    validation:    _lines('kmw-edit-valid'),
  };
  if (isCreate) {
    var slug = _val('kmw-edit-slug');
    if (slug) payload.slug = slug;
  } else {
    // 2026-05-08: detect scope move. The original (pre-edit) scope
    // is stamped on the slug <code> via data-orig-scope; if the
    // current select differs, send `new_scope` so backend rewrites
    // the file under the new path.
    var modal = document.getElementById('kmw-edit-modal');
    var slugEl = modal && modal.querySelector('code[data-orig-scope]');
    if (slugEl) {
      payload.slug = slugEl.textContent.trim();
      var origScope = slugEl.getAttribute('data-orig-scope') || '';
      if (origScope && origScope !== formScope) {
        // Tell backend: identify by origScope, rewrite under formScope
        payload.scope = origScope;       // identifier
        payload.new_scope = formScope;   // target
      }
    } else {
      // Fallback for older modals (shouldn't happen post-this-commit)
      var anySlugEl = modal && modal.querySelector('code');
      if (anySlugEl) payload.slug = anySlugEl.textContent.trim();
    }
  }
  if (!payload.title) { alert('Title required'); return; }
  if (!isCreate && !payload.slug) { alert('Internal error: slug missing'); return; }
  if (isCreate && !payload.body.trim()) { alert('Body required'); return; }

  try {
    var url = isCreate ? '/api/portal/wiki/create' : '/api/portal/wiki/edit';
    var resp = await api('POST', url, payload);
    var m = document.getElementById('kmw-edit-modal'); if (m) m.remove();
    var msg = isCreate ? '已创建' : '已保存';
    if (resp && resp.moved) msg = '已移动到 ' + payload.new_scope;
    if (window._toast) window._toast(msg, 'success');
    _renderKmWiki();
  } catch (e) {
    alert((isCreate ? 'Create' : 'Save') + ' failed: ' + (e.message || e));
  }
}


// ── Wiki: rebuild RAG index (Step D of merge plan) ──
async function _kmWikiRebuildIndex() {
  if (!confirm('重建 RAG 向量索引？所有 valid 的 wiki 页面会被重新写入 collection=wiki。\n仅需在内容大幅变化或迁移后执行一次。')) return;
  try {
    var r = await api('POST', '/api/portal/wiki/index', {
      provider_id: '',  // empty = use default/local
      collection: 'wiki',
    });
    var msg = '已重建索引: ' + r.indexed_count + ' 篇 wiki 页 (跳过 invalid: ' + r.skipped_invalid + ')';
    if (window._toast) window._toast(msg, 'success');
    else alert(msg);
  } catch (e) {
    alert('Rebuild failed: ' + (e.message || e));
  }
}


