// ── Tab 3: Domain Knowledge Bases (standalone, decoupled from agents) ──
async function _renderKmPrivate() {
  // Tech (Aether) variant — different visual chrome, reuses the same
  // /api/portal/domain-kb/list endpoint and the existing edit/delete/
  // import/search handlers + create modal.
  try {
    if (localStorage.getItem('tudou_theme') === 'tech') return _renderKmPrivateTech();
  } catch (e) {}
  var sc = document.getElementById('km-content');
  sc.innerHTML = '<div style="color:var(--text3);padding:20px;text-align:center">加载中...</div>';
  try {
    var data = await api('POST', '/api/portal/domain-kb/list');
    var kbs = (data && data.knowledge_bases) || [];

    // Find which agents use each KB
    var agentsByKb = {};
    (agents||[]).forEach(function(a) {
      var colIds = (a.profile && a.profile.rag_collection_ids) || [];
      colIds.forEach(function(cid) { if (!agentsByKb[cid]) agentsByKb[cid] = []; agentsByKb[cid].push(a); });
    });

    var cardsHtml = kbs.map(function(kb) {
      var boundAgents = agentsByKb[kb.id] || [];
      var agentNames = boundAgents.map(function(a){ return esc(a.name); }).join(', ');
      var tagHtml = (kb.tags||[]).map(function(t){return '<span style="padding:1px 6px;border-radius:4px;font-size:10px;background:rgba(240,136,62,0.1);color:#f0883e">'+esc(t)+'</span>';}).join(' ');
      return '<div style="background:var(--surface);border-radius:12px;padding:18px;border:1px solid var(--border-light)">'
        + '<div style="display:flex;align-items:start;gap:12px;margin-bottom:10px">'
          + '<div style="width:42px;height:42px;border-radius:12px;background:rgba(240,136,62,0.12);display:flex;align-items:center;justify-content:center;flex-shrink:0"><span class="material-symbols-outlined" style="font-size:22px;color:#f0883e">menu_book</span></div>'
          + '<div style="flex:1;min-width:0">'
            + '<div style="font-weight:700;font-size:14px;color:var(--text)">'+esc(kb.name)+'</div>'
            + '<div style="font-size:11px;color:var(--text3);margin-top:2px">'+esc(kb.description||'')+'</div>'
          + '</div>'
          + '<div style="display:flex;gap:4px;flex-shrink:0">'
            + '<button onclick="_kmEditDomainKb(\''+esc(kb.id)+'\')" class="btn btn-sm" style="padding:4px 8px;font-size:11px" title="编辑"><span class="material-symbols-outlined" style="font-size:14px">edit</span></button>'
            + '<button onclick="_kmDeleteDomainKb(\''+esc(kb.id)+'\',\''+esc(kb.name)+'\')" class="btn btn-sm" style="padding:4px 8px;font-size:11px;color:var(--error)" title="删除"><span class="material-symbols-outlined" style="font-size:14px">delete</span></button>'
          + '</div>'
        + '</div>'
        + '<div style="display:flex;gap:12px;font-size:11px;color:var(--text3);margin-bottom:10px">'
          + '<span style="display:flex;align-items:center;gap:4px"><span class="material-symbols-outlined" style="font-size:14px">description</span>'+kb.doc_count+' 文档块</span>'
          + '<span style="display:flex;align-items:center;gap:4px"><span class="material-symbols-outlined" style="font-size:14px">smart_toy</span>'+(boundAgents.length > 0 ? boundAgents.length+' 个 Agent 使用' : '未绑定 Agent')+'</span>'
          + (kb.provider_id ? '<span style="display:flex;align-items:center;gap:4px"><span class="material-symbols-outlined" style="font-size:14px">cloud</span>远程</span>' : '<span style="display:flex;align-items:center;gap:4px"><span class="material-symbols-outlined" style="font-size:14px">storage</span>本地</span>')
        + '</div>'
        + (agentNames ? '<div style="font-size:11px;color:var(--text3);margin-bottom:8px">绑定: '+agentNames+'</div>' : '')
        + (tagHtml ? '<div style="display:flex;gap:4px;flex-wrap:wrap;margin-bottom:10px">'+tagHtml+'</div>' : '')
        + '<div style="display:flex;gap:8px">'
          + '<button class="btn btn-sm" onclick="_kmShowDomainImport(\''+esc(kb.id)+'\',\''+esc(kb.name)+'\')"><span class="material-symbols-outlined" style="font-size:14px">upload_file</span> 导入知识</button>'
          + '<button class="btn btn-sm" onclick="_kmSearchDomainKb(\''+esc(kb.id)+'\',\''+esc(kb.name)+'\')"><span class="material-symbols-outlined" style="font-size:14px">search</span> 检索测试</button>'
        + '</div>'
        + '</div>';
    }).join('');

    sc.innerHTML = '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px">'
      + '<div><div style="font-size:15px;font-weight:700;color:var(--text)">专业领域知识库</div>'
      + '<div style="font-size:12px;color:var(--text3);margin-top:2px">独立于智能体，可创建后绑定给多个顾问。删除智能体不影响知识库。</div></div>'
      + '<button class="btn btn-primary btn-sm" onclick="_kmShowCreateDomainKb()"><span class="material-symbols-outlined" style="font-size:14px">add</span> 新建知识库</button>'
      + '</div>'
      + (kbs.length === 0
        ? '<div style="text-align:center;padding:60px 20px;border:1px dashed var(--border);border-radius:12px">'
          + '<span class="material-symbols-outlined" style="font-size:48px;color:var(--text3);display:block;margin-bottom:12px">menu_book</span>'
          + '<div style="font-size:14px;color:var(--text2);margin-bottom:8px">暂无专业领域知识库</div>'
          + '<div style="font-size:12px;color:var(--text3);margin-bottom:16px">创建知识库后，可导入 PDF/Word/文本，然后在创建顾问智能体时选择绑定</div>'
          + '<button class="btn btn-primary btn-sm" onclick="_kmShowCreateDomainKb()"><span class="material-symbols-outlined" style="font-size:14px">add</span> 新建专业领域知识库</button>'
          + '</div>'
        : '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(380px,1fr));gap:12px">'+cardsHtml+'</div>');
  } catch(e) {
    sc.innerHTML = '<div style="color:var(--error);padding:20px">Load failed:'+e+'</div>';
  }
}

// ============ Tech (Aether) — Private/Domain KB list (stitch_30) ============
// Same /api/portal/domain-kb/list payload as legacy. Visual chrome only.
// Container resolution: tech hub renames its body div to 'content' during
// the initial sub-render call, then restores it to 'tech-hub-km-body'.
// We try both so post-action refreshes (e.g., after create modal saves)
// also find the right target.
async function _renderKmPrivateTech() {
  var sc = document.getElementById('tech-hub-km-body')
        || document.getElementById('content');
  if (!sc) return;
  sc.innerHTML = '<div class="tc-text-dim" style="padding:40px 20px;text-align:center;font-family:var(--font-mono);font-size:11px;letter-spacing:0.05em">LOADING…</div>';
  try {
    var data = await api('POST', '/api/portal/domain-kb/list');
    var kbs = (data && data.knowledge_bases) || [];

    // Health probe — async; KB list still renders immediately, the
    // health badge is patched in once the response arrives.
    var healthByKb = {};
    var healthPromise = api('POST', '/api/portal/domain-kb/health', {})
      .then(function(h) {
        ((h && h.items) || []).forEach(function(it) { healthByKb[it.kb_id] = it; });
      })
      .catch(function() { /* no-op — badge stays absent */ });

    // Map of which agents bind each KB
    var agentsByKb = {};
    (agents || []).forEach(function(a) {
      var colIds = (a.profile && a.profile.rag_collection_ids) || [];
      colIds.forEach(function(cid) {
        if (!agentsByKb[cid]) agentsByKb[cid] = [];
        agentsByKb[cid].push(a);
      });
    });

    var cardsHtml = kbs.map(function(kb) {
      var boundAgents = agentsByKb[kb.id] || [];
      var isRemote = !!kb.provider_id;
      var idShort = (kb.id || '').slice(0, 12);
      var statusChip = isRemote
        ? '<span class="tc-mono-label" style="padding:3px 8px;border-radius:var(--r-md);background:var(--surface-container-highest);color:var(--outline);border:1px solid var(--outline-variant);font-size:10px">REMOTE</span>'
        : '<span class="tc-mono-label" style="padding:3px 8px;border-radius:var(--r-md);background:rgba(192,193,255,0.10);color:var(--primary);border:1px solid rgba(192,193,255,0.20);font-size:10px">LOCAL</span>';

      var firstAgent = boundAgents[0];
      var avatarRow;
      if (firstAgent) {
        var aurl = _aetherAvatarFor(firstAgent);
        var moreCount = boundAgents.length - 1;
        avatarRow =
          '<div style="display:flex;align-items:center;gap:10px">' +
            '<div style="width:32px;height:32px;border-radius:9999px;border:1px solid var(--outline-variant);overflow:hidden;background:var(--surface-container-high);flex-shrink:0">' +
              '<img src="' + aurl + '" style="width:100%;height:100%;object-fit:cover" alt="" onerror="this.style.display=\'none\'">' +
            '</div>' +
            '<div style="display:flex;flex-direction:column">' +
              '<span class="tc-mono-label" style="color:var(--outline);font-size:9px">EXPERT LEAD</span>' +
              '<span style="font-size:13px;font-weight:500;color:var(--on-surface)">' + esc(firstAgent.name) + (moreCount > 0 ? ' <span class="tc-text-dim" style="font-size:11px">+' + moreCount + '</span>' : '') + '</span>' +
            '</div>' +
          '</div>';
      } else {
        avatarRow =
          '<div style="display:flex;align-items:center;gap:10px">' +
            '<div style="width:32px;height:32px;border-radius:var(--r-md);border:1px solid var(--outline-variant);background:var(--surface-container-highest);display:flex;align-items:center;justify-content:center;flex-shrink:0">' +
              '<span class="material-symbols-outlined" style="color:var(--outline);font-size:18px">person_off</span>' +
            '</div>' +
            '<div style="display:flex;flex-direction:column">' +
              '<span class="tc-mono-label" style="color:var(--outline);font-size:9px">EXPERT LEAD</span>' +
              '<span class="tc-text-dim" style="font-size:13px">Unassigned</span>' +
            '</div>' +
          '</div>';
      }

      var tagPills = (kb.tags || []).slice(0, 3).map(function(t) {
        return '<span class="tc-mono-label" style="padding:2px 8px;border-radius:var(--r-md);background:rgba(255,183,131,0.10);color:var(--tertiary);border:1px solid rgba(255,183,131,0.25);font-size:10px">' + esc(t) + '</span>';
      }).join(' ');
      if ((kb.tags || []).length > 3) tagPills += ' <span class="tc-text-dim" style="font-size:10px">+' + ((kb.tags || []).length - 3) + '</span>';

      return '' +
        '<div class="tc-card-glass" data-kb-id="' + esc(kb.id) + '" style="padding:18px;display:flex;flex-direction:column;gap:14px;position:relative;border-top:1px solid rgba(255,255,255,0.10);' + (boundAgents.length > 0 ? 'box-shadow:0 0 15px rgba(99,102,241,0.10);' : '') + '">' +
          // Top: ID + name | status chip
          '<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:12px">' +
            '<div style="flex:1;min-width:0">' +
              '<div class="tc-mono-label" style="color:var(--primary);font-size:10px;margin-bottom:4px">ID: ' + esc(idShort).toUpperCase() + '</div>' +
              '<div style="font-size:18px;font-weight:700;color:var(--on-surface);line-height:1.3">' + esc(kb.name) + '</div>' +
              (kb.description
                ? '<div class="tc-text-dim" style="font-size:12px;margin-top:6px;line-height:1.5">' + esc(kb.description) + '</div>'
                : '') +
            '</div>' +
            '<div style="display:flex;flex-direction:column;align-items:flex-end;gap:4px">' +
              statusChip +
              '<span class="kb-health-slot" data-kb-health-id="' + esc(kb.id) + '"></span>' +
            '</div>' +
          '</div>' +
          // 2-col grid: docs / utilization
          '<div style="display:grid;grid-template-columns:1fr 1fr;gap:14px">' +
            '<div style="display:flex;flex-direction:column;gap:4px">' +
              '<span class="tc-mono-label" style="color:var(--outline);font-size:9px">VOLUME</span>' +
              '<div style="display:flex;align-items:baseline;gap:4px">' +
                '<span style="font-size:18px;font-weight:700;color:var(--on-surface);font-family:var(--font-mono)">' + (kb.doc_count || 0) + '</span>' +
                '<span class="tc-text-dim" style="font-size:10px">docs</span>' +
              '</div>' +
            '</div>' +
            '<div style="display:flex;flex-direction:column;gap:4px">' +
              '<span class="tc-mono-label" style="color:var(--outline);font-size:9px">UTILIZATION</span>' +
              '<div style="display:flex;align-items:center;gap:6px">' +
                '<div style="width:6px;height:6px;border-radius:50%;background:' + (boundAgents.length > 0 ? 'var(--cyber-blue, var(--secondary))' : 'var(--outline)') + '"></div>' +
                '<span style="font-size:14px;font-weight:600;color:var(--on-surface)">' + boundAgents.length + ' Agent' + (boundAgents.length === 1 ? '' : 's') + '</span>' +
              '</div>' +
            '</div>' +
          '</div>' +
          // Tags row (if any)
          (tagPills ? '<div style="display:flex;gap:6px;flex-wrap:wrap">' + tagPills + '</div>' : '') +
          // Footer: avatar | actions
          '<div style="display:flex;align-items:center;justify-content:space-between;padding-top:12px;border-top:1px solid var(--outline-variant)">' +
            avatarRow +
            '<div style="display:flex;gap:4px">' +
              '<button class="tc-btn tc-btn-ghost tc-btn-sm" onclick="_kmShowDomainImport(\'' + esc(kb.id) + '\',\'' + esc(kb.name) + '\')" title="Import" style="padding:6px;min-width:0">' +
                '<span class="material-symbols-outlined" style="font-size:16px">upload_file</span></button>' +
              '<button class="tc-btn tc-btn-ghost tc-btn-sm" onclick="_kmSearchDomainKb(\'' + esc(kb.id) + '\',\'' + esc(kb.name) + '\')" title="Search test" style="padding:6px;min-width:0">' +
                '<span class="material-symbols-outlined" style="font-size:16px">search</span></button>' +
              '<button class="tc-btn tc-btn-ghost tc-btn-sm" onclick="_kmResetIndexState(\'' + esc(kb.id) + '\',\'' + esc(kb.name) + '\')" title="Reset stale index counters (use after re-importing to fix doc_count)" style="padding:6px;min-width:0">' +
                '<span class="material-symbols-outlined" style="font-size:16px">restart_alt</span></button>' +
              '<button class="tc-btn tc-btn-ghost tc-btn-sm" onclick="_kmEditDomainKb(\'' + esc(kb.id) + '\')" title="Edit" style="padding:6px;min-width:0">' +
                '<span class="material-symbols-outlined" style="font-size:16px">edit</span></button>' +
              '<button class="tc-btn tc-btn-ghost tc-btn-sm" onclick="_kmDeleteDomainKb(\'' + esc(kb.id) + '\',\'' + esc(kb.name) + '\')" title="Delete" style="padding:6px;min-width:0;color:var(--error)">' +
                '<span class="material-symbols-outlined" style="font-size:16px">delete</span></button>' +
            '</div>' +
          '</div>' +
        '</div>';
    }).join('');

    // Header — strips out the "+ NEW KB" topbar button. Add affordance
    // is now a card at the end of the grid (matches Worker Nodes pattern,
    // user direction "所有的添加按钮,做成卡片示添加").
    var headerHtml =
      '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:var(--s-lg);gap:var(--s-md);flex-wrap:wrap">' +
        '<div style="flex:1;min-width:240px">' +
          '<div class="tc-mono-label" style="color:var(--primary);display:flex;align-items:center;gap:8px">' +
            '<span>REPOSITORY STATUS</span>' +
            '<span style="width:6px;height:6px;border-radius:50%;background:var(--secondary);animation:pulse-dot 2s infinite ease-in-out"></span>' +
          '</div>' +
          '<div class="tc-text-dim" style="font-size:12px;margin-top:6px">' +
            'Domain knowledge bases — independent of agents. Bind to multiple advisors; deleting an agent does not affect the KB.' +
          '</div>' +
        '</div>' +
      '</div>';

    // Card-style "+" add affordance — appended to grid; styled like Worker
    // Nodes' "+ CONNECT NODE" but with cyber-magenta tint to match the
    // cultivation hub's overall accent color.
    var addKbCard =
      '<div onclick="_kmShowCreateDomainKb()" ' +
           'onmouseover="this.style.borderColor=\'rgba(137,206,255,0.50)\';this.style.background=\'rgba(137,206,255,0.05)\'" ' +
           'onmouseout="this.style.borderColor=\'\';this.style.background=\'transparent\'" ' +
           'style="display:flex;flex-direction:column;align-items:center;justify-content:center;' +
                  'gap:10px;min-height:200px;border:2px dashed rgba(137,206,255,0.30);' +
                  'border-radius:var(--r-lg,12px);background:transparent;cursor:pointer;' +
                  'transition:all 0.18s;padding:18px;text-align:center">' +
        '<div style="width:42px;height:42px;border-radius:9999px;background:rgba(137,206,255,0.10);' +
              'border:1px solid rgba(137,206,255,0.40);' +
              'display:flex;align-items:center;justify-content:center">' +
          '<span class="material-symbols-outlined" style="color:var(--secondary);font-size:22px">add</span>' +
        '</div>' +
        '<div class="tc-mono-label" style="color:var(--secondary);font-size:12px;font-weight:600;letter-spacing:0.05em">NEW KB</div>' +
        '<div class="tc-text-dim" style="font-size:11px;line-height:1.5;max-width:220px">' +
            'Create a knowledge base, import documents, then bind to advisor agents' +
        '</div>' +
      '</div>';

    var bodyHtml = (kbs.length === 0)
      ? '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(380px,1fr));gap:var(--s-md)">' +
          addKbCard +
          '<div class="tc-card tc-text-dim" style="padding:30px 20px;text-align:center;font-size:12px;line-height:1.6">' +
            '<span class="material-symbols-outlined" style="font-size:32px;color:var(--outline);display:block;margin-bottom:10px">menu_book</span>' +
            'No domain knowledge bases yet — click the card on the left to create your first one.' +
          '</div>' +
        '</div>'
      : '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(380px,1fr));gap:var(--s-md)">' + cardsHtml + addKbCard + '</div>';

    sc.innerHTML = headerHtml + bodyHtml;

    // Patch in health badges once the async health probe resolves.
    healthPromise.then(function() {
      Object.keys(healthByKb).forEach(function(kbId) {
        var slot = sc.querySelector('span.kb-health-slot[data-kb-health-id="' + kbId + '"]');
        if (!slot) return;
        var h = healthByKb[kbId];
        // Healthy → tiny green pulse + "INDEXED N"
        if (h.healthy && h.chroma_count > 0) {
          slot.innerHTML = '<span class="tc-mono-label" title="Vector store has ' + h.chroma_count + ' chunks" style="display:inline-flex;align-items:center;gap:5px;padding:2px 7px;border-radius:var(--r-md);background:rgba(137,206,255,0.10);color:var(--secondary);border:1px solid rgba(137,206,255,0.25);font-size:9px">' +
            '<span style="width:5px;height:5px;border-radius:50%;background:var(--secondary);box-shadow:0 0 5px var(--secondary)"></span>' +
            'INDEXED ' + h.chroma_count + '</span>';
          return;
        }
        // Empty (registry==chroma==0) → no badge, KB is just empty.
        if (h.healthy && h.chroma_count === 0 && h.registry_count === 0) {
          return;
        }
        // Unhealthy: registry says X chunks but chroma has Y < X.
        if (h.mismatch > 0) {
          var label = '⚠ ' + h.mismatch + ' UNINDEXED';
          var tip = (h.last_ingest_error || ('Registry remembers ' + h.registry_count +
            ' chunks but vector store only holds ' + (h.chroma_count >= 0 ? h.chroma_count : 'unknown') +
            '. Re-import to fix.'));
          slot.innerHTML = '<span class="tc-mono-label" title="' + esc(tip) + '" style="display:inline-flex;align-items:center;gap:5px;padding:2px 7px;border-radius:var(--r-md);background:rgba(255,180,171,0.10);color:var(--error);border:1px solid rgba(255,180,171,0.30);font-size:9px;cursor:help">' +
            label + '</span>';
        }
      });
    });
  } catch (e) {
    sc.innerHTML = '<div class="tc-card" style="color:var(--error);padding:var(--s-lg)">' + esc(String(e)) + '</div>';
  }
}
window._renderKmPrivateTech = _renderKmPrivateTech;

window._kmResetIndexState = async function(kbId, kbName) {
  if (!await confirm('Reset stale index counters for "' + kbName + '"?\n\n' +
                     'This zeros out doc_count and indexed_count so the next ' +
                     'import reports correct totals. The actual ChromaDB ' +
                     'collection is NOT touched. Use this when the badge ' +
                     'shows "UNINDEXED" — typically because Ollama was ' +
                     'down during the original import.')) return;
  try {
    await api('POST', '/api/portal/domain-kb/reset-index-state', { kb_id: kbId });
    if (typeof _toast === 'function') _toast('Index counters reset', 'success');
    if (typeof _renderKmPrivateTech === 'function') _renderKmPrivateTech();
  } catch (e) { alert('Reset failed: ' + e); }
};

function _kmShowCreateDomainKb() {
  // Storage: ALWAYS local ChromaDB. Remote-store providers are not
  // exposed here — the only meaningful customisation is the embedding
  // source (local model OR an existing LLM Provider). Defaults pick
  // an Ollama LLM provider when one exists, so the typical user
  // shipping with Ollama gets a working setup with zero config.
  var html = '<div class="modal-overlay" id="km-dkb-modal" onclick="if(event.target===this)this.remove()">'
    + '<div class="modal" style="max-width:540px">'
    + '<h3>New Domain Knowledge Base</h3>'
    + '<p style="font-size:11px;color:var(--text3);margin:-6px 0 14px;line-height:1.55">Storage is the local ChromaDB shipped with TudouClaw. Pick where embeddings come from below — Ollama (or any LLM provider with <code>/v1/embeddings</code>) gives the best multilingual recall; the local model is the zero-dep fallback.</p>'
    + '<div class="form-group"><label>Name *</label><input id="km-dkb-name" placeholder="e.g. Legal KB / Finance KB"></div>'
    + '<div class="form-group"><label>Description</label><input id="km-dkb-desc" placeholder="e.g. Labour law and contract law documents"></div>'
    + '<div class="form-group"><label>Tags <span style="font-size:11px;color:var(--text3)">(comma separated)</span></label><input id="km-dkb-tags" placeholder="legal, labour-law, contract"></div>'
    // Storage is fixed — no dropdown, no remote-provider option.
    + '<input type="hidden" id="km-dkb-provider" value="">'
    // ── Embedding source: 2-way choice (local OR LLM provider) ──
    + '<div class="form-group">'
    +   '<label>Embedding source <span style="font-size:11px;color:var(--text3);font-weight:400">(immutable after creation)</span></label>'
    +   '<div style="display:flex;gap:18px;margin:6px 0 8px 0;font-size:13px">'
    +     '<label style="display:flex;align-items:center;gap:6px;cursor:pointer">'
    +       '<input type="radio" name="km-dkb-embed-source" value="llm" checked'
    +         ' onchange="_kmSwitchEmbedSource(\'llm\')"> LLM Provider <span class="tc-text-dim" style="font-size:11px">(Ollama / OpenAI-compat)</span>'
    +     '</label>'
    +     '<label style="display:flex;align-items:center;gap:6px;cursor:pointer">'
    +       '<input type="radio" name="km-dkb-embed-source" value="local"'
    +         ' onchange="_kmSwitchEmbedSource(\'local\')"> Local model'
    +     '</label>'
    +   '</div>'
    // — LLM provider sub-section (default)
    +   '<div id="km-dkb-llm-embed-section">'
    +     '<div class="form-group" style="margin-bottom:8px">'
    +       '<label style="font-size:12px">LLM Provider</label>'
    +       '<select id="km-dkb-llm-embed-provider" onchange="_kmAutofillEmbedModel()"><option value="">Loading…</option></select>'
    +     '</div>'
    +     '<div class="form-group" style="margin-bottom:0">'
    +       '<label style="font-size:12px">Embedding model</label>'
    +       '<input id="km-dkb-llm-embed-model" placeholder="e.g. bge-m3 / nomic-embed-text / text-embedding-3-small">'
    +       '<div style="font-size:11px;color:var(--text3);margin-top:4px;line-height:1.4" id="km-dkb-embed-model-hint">'
    +         'Must be a model ID supported by this provider\\\'s <code>/v1/embeddings</code> endpoint.'
    +       '</div>'
    +     '</div>'
    +   '</div>'
    // — Local sub-section (hidden by default)
    +   '<div id="km-dkb-embed-local-section" style="display:none">'
    +     '<select id="km-dkb-embed-model"><option value="">Loading…</option></select>'
    +     '<div id="km-dkb-embed-note" style="font-size:11px;color:var(--text3);margin-top:6px;line-height:1.55;white-space:pre-line;background:var(--surface3);border:1px solid var(--overlay-5);border-radius:8px;padding:8px 10px"></div>'
    +   '</div>'
    + '</div>'
    // Cross-encoder reranker — optional. Adds latency, big precision win.
    + '<div class="form-group">'
    +   '<label>Reranker <span style="font-size:11px;color:var(--text3);font-weight:400">(optional, editable later)</span></label>'
    +   '<select id="km-dkb-rerank-model"><option value="">Loading…</option></select>'
    +   '<div id="km-dkb-rerank-note" style="font-size:11px;color:var(--text3);margin-top:4px;line-height:1.4"></div>'
    + '</div>'
    + '<div class="form-actions"><button class="btn btn-ghost" onclick="document.getElementById(\'km-dkb-modal\').remove()">Cancel</button>'
    + '<button class="btn btn-primary" onclick="_lockBtn(this,\'Creating…\',_kmSaveDomainKb)">Create</button></div>'
    + '</div></div>';
  document.body.insertAdjacentHTML('beforeend', html);

  // Storage stays hardcoded local — no /api/portal/rag/providers fetch.

  // Eagerly populate the LLM provider dropdown since LLM-embedding is
  // now the default. Auto-select an Ollama provider if one exists,
  // and auto-fill the model field with a sensible default per kind.
  api('GET', '/api/portal/providers').then(function(data) {
    var sel = document.getElementById('km-dkb-llm-embed-provider');
    if (!sel) return;
    var providers = (data && data.providers) || [];
    if (!providers.length) {
      sel.innerHTML = '<option value="">(no LLM providers configured — add one in Settings → LLM Providers)</option>';
      return;
    }
    sel.innerHTML = '<option value="">— Select provider —</option>'
      + providers.map(function(p) {
          var label = (p.name || p.id) + ' (' + (p.kind || '?')
                    + (p.base_url ? ' · ' + p.base_url.slice(0, 30) : '') + ')';
          return '<option value="' + esc(p.id || '') + '" data-kind="' + esc((p.kind || '').toLowerCase()) + '" data-name="' + esc((p.name || '').toLowerCase()) + '">' + esc(label) + '</option>';
        }).join('');
    // Auto-pick Ollama if present, else the first provider.
    var pickIdx = 0;
    for (var i = 0; i < providers.length; i++) {
      var p = providers[i];
      var nm = (p.name || '').toLowerCase();
      var kd = (p.kind || '').toLowerCase();
      if (nm.indexOf('ollama') >= 0 || kd === 'ollama') { pickIdx = i + 1; break; }
    }
    if (pickIdx > 0) {
      sel.selectedIndex = pickIdx;
      _kmAutofillEmbedModel();
    }
  }).catch(function() {
    var sel = document.getElementById('km-dkb-llm-embed-provider');
    if (sel) sel.innerHTML = '<option value="">load failed — check master is running</option>';
  });

  // Load embedding model catalog. Two groups:
  //   1. curated (recommended/safe options)
  //   2. local_extra (other models the admin pre-downloaded — accepted
  //      because presence in cache implies user-vetted)
  api('GET', '/api/portal/domain-kb/embedding-models').then(function(data) {
    var sel = document.getElementById('km-dkb-embed-model');
    var note = document.getElementById('km-dkb-embed-note');
    if (!sel || !data) return;
    sel.innerHTML = '';

    var fmtSize = function(mb) {
      if (!mb) return '';
      return ' · ~' + (mb >= 1024 ? (mb/1024).toFixed(1) + 'GB' : mb + 'MB');
    };
    var addGroup = function(label, models) {
      if (!models || !models.length) return;
      var grp = document.createElement('optgroup');
      grp.label = label;
      models.forEach(function(m) {
        var lab = m.label || m.id || '默认';
        if (m.recommended) lab = '⭐ ' + lab + ' (推荐)';
        if (m.local && !m.recommended) lab = '✓ ' + lab + ' (已下载)';
        if (m.dim) lab += ' · ' + m.dim + ' dim';
        lab += fmtSize(m.size_mb);
        var opt = document.createElement('option');
        opt.value = m.id;
        opt.textContent = lab;
        opt.dataset.note = m.note || '';
        if (m.recommended) opt.dataset.recommended = '1';
        grp.appendChild(opt);
      });
      sel.appendChild(grp);
    };
    addGroup('内置选项', data.models || []);
    addGroup('本地已缓存（自定义）', data.local_extra || []);

    // Pre-select the recommended option if any
    for (var i = 0; i < sel.options.length; i++) {
      if (sel.options[i].dataset.recommended === '1') {
        sel.selectedIndex = i;
        break;
      }
    }
    var update = function() {
      var sel2 = document.getElementById('km-dkb-embed-model');
      var note2 = document.getElementById('km-dkb-embed-note');
      if (!sel2 || !note2) return;
      var opt = sel2.options[sel2.selectedIndex];
      note2.textContent = (opt && opt.dataset && opt.dataset.note) || '';
    };
    sel.addEventListener('change', update);
    update();
  }).catch(function(){
    var sel = document.getElementById('km-dkb-embed-model');
    if (sel) sel.innerHTML = '<option value="">默认 (服务器配置)</option>';
  });

  // Reranker model dropdown — same shape as embedding catalog.
  api('GET', '/api/portal/domain-kb/reranker-models').then(function(data) {
    var sel = document.getElementById('km-dkb-rerank-model');
    var note = document.getElementById('km-dkb-rerank-note');
    if (!sel || !data) return;
    sel.innerHTML = '';
    var fmtSize = function(mb) {
      if (!mb) return '';
      return ' · ~' + (mb >= 1024 ? (mb/1024).toFixed(1) + 'GB' : mb + 'MB');
    };
    var addGroup = function(label, models) {
      if (!models || !models.length) return;
      var grp = document.createElement('optgroup');
      grp.label = label;
      models.forEach(function(m) {
        var lab = m.label || m.id || '不使用';
        if (m.recommended) lab = '⭐ ' + lab + ' (推荐)';
        if (m.local && !m.recommended) lab = '✓ ' + lab + ' (已下载)';
        lab += fmtSize(m.size_mb);
        var opt = document.createElement('option');
        opt.value = m.id;
        opt.textContent = lab;
        opt.dataset.note = m.note || '';
        if (m.id === '') opt.dataset.preselect = '1';   // default = no rerank
        grp.appendChild(opt);
      });
      sel.appendChild(grp);
    };
    addGroup('内置选项', data.models || []);
    addGroup('本地已缓存（自定义）', data.local_extra || []);
    // Default to "no rerank" — opt-in, not opt-out, so first-run KBs
    // don't suddenly need 568MB extra download for one experiment.
    for (var i = 0; i < sel.options.length; i++) {
      if (sel.options[i].value === '') { sel.selectedIndex = i; break; }
    }
    var update = function() {
      var sel2 = document.getElementById('km-dkb-rerank-model');
      var note2 = document.getElementById('km-dkb-rerank-note');
      if (!sel2 || !note2) return;
      var opt = sel2.options[sel2.selectedIndex];
      note2.textContent = (opt && opt.dataset && opt.dataset.note) || '';
    };
    sel.addEventListener('change', update);
    update();
  }).catch(function(){
    var sel = document.getElementById('km-dkb-rerank-model');
    if (sel) sel.innerHTML = '<option value="">不使用 (默认)</option>';
  });
}

// Switch the embedding-source radio in the KB create modal.
// Source is "local" (default) or "llm". Only one sub-section is
// visible at a time so the operator can't accidentally fill both.
function _kmSwitchEmbedSource(source) {
  var localSec = document.getElementById('km-dkb-embed-local-section');
  var llmSec = document.getElementById('km-dkb-llm-embed-section');
  if (!localSec || !llmSec) return;
  if (source === 'llm') {
    localSec.style.display = 'none';
    llmSec.style.display = '';
    // Provider list is now eager-loaded on modal open, so nothing
    // else to do here.
  } else {
    localSec.style.display = '';
    llmSec.style.display = 'none';
  }
}

// Pick the most-likely embedding model name for a provider kind.
// Saves the operator a trip to the provider docs for the common
// case (Ollama → bge-m3, OpenAI-style → text-embedding-3-small).
window._kmAutofillEmbedModel = function() {
  var sel = document.getElementById('km-dkb-llm-embed-provider');
  var modelInp = document.getElementById('km-dkb-llm-embed-model');
  var hint = document.getElementById('km-dkb-embed-model-hint');
  if (!sel || !modelInp) return;
  var opt = sel.options[sel.selectedIndex];
  if (!opt || !opt.value) return;
  var kind = (opt.dataset.kind || '').toLowerCase();
  var name = (opt.dataset.name || '').toLowerCase();
  // Don't overwrite a value the user has typed.
  if (modelInp.value && modelInp.value.trim()) return;
  var defaultModel = '';
  var hintText = '';
  if (kind === 'ollama' || name.indexOf('ollama') >= 0) {
    defaultModel = 'bge-m3';
    hintText = 'Ollama default — pull it first: <code>ollama pull bge-m3</code>';
  } else if (kind === 'openai' || name.indexOf('openai') >= 0 || name.indexOf('gpt') >= 0) {
    defaultModel = 'text-embedding-3-small';
    hintText = 'OpenAI default. Use <code>text-embedding-3-large</code> for higher dim.';
  } else if (name.indexOf('zhipu') >= 0 || name.indexOf('glm') >= 0) {
    defaultModel = 'embedding-2';
    hintText = 'Zhipu default — see GLM /v1/embeddings docs for alternatives.';
  } else if (name.indexOf('qwen') >= 0 || name.indexOf('alibaba') >= 0 || name.indexOf('dashscope') >= 0) {
    defaultModel = 'text-embedding-v3';
    hintText = 'DashScope/Qwen default. v2/v3 supported.';
  } else if (name.indexOf('claude') >= 0 || name.indexOf('anthropic') >= 0) {
    defaultModel = '';
    hintText = '⚠ Anthropic does NOT serve embeddings — pick a different provider for this KB.';
  } else {
    hintText = 'Must be a model ID supported by this provider\'s <code>/v1/embeddings</code> endpoint.';
  }
  if (defaultModel) modelInp.value = defaultModel;
  if (hint) hint.innerHTML = hintText;
};

async function _kmSaveDomainKb() {
  var name = (document.getElementById('km-dkb-name')||{}).value||'';
  var desc = (document.getElementById('km-dkb-desc')||{}).value||'';
  var tags = ((document.getElementById('km-dkb-tags')||{}).value||'').split(',').map(function(t){return t.trim()}).filter(Boolean);
  var provider = (document.getElementById('km-dkb-provider')||{}).value||'';
  var embedModel = (document.getElementById('km-dkb-embed-model')||{}).value||'';
  var rerankerModel = (document.getElementById('km-dkb-rerank-model')||{}).value||'';
  // LLM-provider-as-embedding-source bridge (optional).
  // Read from the radio-group; the "llm" branch fills in
  // embedding_provider_id + overrides embed_model with the
  // remote model id.
  var checkedRadio = document.querySelector('input[name="km-dkb-embed-source"]:checked');
  var useLlmEmbed = checkedRadio && checkedRadio.value === 'llm';
  var llmEmbedProvider = '';
  if (useLlmEmbed) {
    llmEmbedProvider = (document.getElementById('km-dkb-llm-embed-provider')||{}).value || '';
    var llmEmbedModel = ((document.getElementById('km-dkb-llm-embed-model')||{}).value || '').trim();
    if (!llmEmbedProvider) { alert('Please select LLM Provider'); return; }
    if (!llmEmbedModel)    { alert('Please fill Embedding Model name (the model ID at this provider)'); return; }
    embedModel = llmEmbedModel;
  }
  if (!name.trim()) { alert('Name cannot be empty'); return; }
  try {
    await api('POST', '/api/portal/domain-kb/create', {
      name: name,
      description: desc,
      tags: tags,
      provider_id: provider,
      embedding_model: embedModel,
      embedding_provider_id: llmEmbedProvider,
      reranker_model: rerankerModel,
    });
    var m = document.getElementById('km-dkb-modal'); if(m) m.remove();
    _renderKmPrivate();
  } catch(e) { alert('创建失败: '+e); }
}

function _kmEditDomainKb(kbId) {
  api('POST', '/api/portal/domain-kb/list').then(function(data) {
    var kbs = (data && data.knowledge_bases) || [];
    var kb = kbs.find(function(k){ return k.id === kbId; });
    if (!kb) { alert('未找到'); return; }
    var html = '<div class="modal-overlay" id="km-dkb-edit-modal" onclick="if(event.target===this)this.remove()">'
      + '<div class="modal" style="max-width:500px">'
      + '<h3>编辑知识库</h3>'
      + '<div class="form-group"><label>名称</label><input id="km-dkb-edit-name" value="'+esc(kb.name)+'"></div>'
      + '<div class="form-group"><label>描述</label><input id="km-dkb-edit-desc" value="'+esc(kb.description||'')+'"></div>'
      + '<div class="form-group"><label>标签</label><input id="km-dkb-edit-tags" value="'+esc((kb.tags||[]).join(', '))+'"></div>'
      + '<div class="form-actions"><button class="btn btn-ghost" onclick="document.getElementById(\'km-dkb-edit-modal\').remove()">Cancel</button>'
      + '<button class="btn btn-primary" onclick="_kmSaveEditDomainKb(\''+esc(kbId)+'\')">保存</button></div>'
      + '</div></div>';
    document.body.insertAdjacentHTML('beforeend', html);
  }).catch(function(e){ alert('Load failed:'+e); });
}

async function _kmSaveEditDomainKb(kbId) {
  var name = (document.getElementById('km-dkb-edit-name')||{}).value;
  var desc = (document.getElementById('km-dkb-edit-desc')||{}).value;
  var tags = ((document.getElementById('km-dkb-edit-tags')||{}).value||'').split(',').map(function(t){return t.trim()}).filter(Boolean);
  try {
    await api('POST', '/api/portal/domain-kb/update', {id:kbId, name:name, description:desc, tags:tags});
    var m = document.getElementById('km-dkb-edit-modal'); if(m) m.remove();
    _renderKmPrivate();
  } catch(e) { alert('Save failed:'+e); }
}

async function _kmDeleteDomainKb(kbId, name) {
  if (!await confirm('确定删除知识库 "'+name+'" 吗？\\n\\n注意：删除后知识库中的所有文档将被永久移除！')) return;
  try {
    await api('POST', '/api/portal/domain-kb/delete', {id:kbId});
    _renderKmPrivate();
  } catch(e) { alert('Delete failed:'+e); }
}

