window._canvasToggleLog = function() {
  _canvasState._logExpanded = !_canvasState._logExpanded;
  _canvasRenderEditor();
};

window._canvasClearLog = function() {
  _canvasState._runEvents = [];
  _canvasRenderLogBody();
  _canvasUpdateLogCounter();
};

function _canvasUpdateLogCounter() {
  var el = document.getElementById('canvas-log-counter');
  if (!el) return;
  var n = (_canvasState._runEvents || []).length;
  el.textContent = n ? '· ' + n + ' 条' : '';
}

function _canvasFormatLogEvent(evt) {
  var t = evt.type || '';
  var d = evt.data || {};
  var ts = evt.ts ? new Date(evt.ts * 1000) : new Date();
  var hh = String(ts.getHours()).padStart(2, '0');
  var mm = String(ts.getMinutes()).padStart(2, '0');
  var ss = String(ts.getSeconds()).padStart(2, '0');
  var ms = String(ts.getMilliseconds()).padStart(3, '0');
  var time = hh + ':' + mm + ':' + ss + '.' + ms;
  // Per-type icon + color
  var ICONS = {
    run_created:   {sym: '◆', color: '#94a3b8',  text: 'run created'},
    run_started:   {sym: '▶', color: '#3b82f6',  text: 'run started'},
    run_succeeded: {sym: '✓', color: '#16a34a',  text: 'run succeeded'},
    run_failed:    {sym: '✗', color: '#dc2626',  text: 'run failed'},
    run_aborted:   {sym: '◼', color: '#ea580c',  text: 'run aborted'},
    node_started:  {sym: '●', color: '#f59e0b',  text: '→'},
    node_succeeded:{sym: '✓', color: '#16a34a',  text: '✓'},
    node_failed:   {sym: '✗', color: '#dc2626',  text: '✗'},
    node_skipped:  {sym: '⊘', color: '#94a3b8',  text: '⊘'},
  };
  var spec = ICONS[t] || {sym: '·', color: 'var(--text3)', text: t};
  var detail = '';
  if (t.startsWith('node_')) {
    var nid = d.node_id || '?';
    var ntype = d.node_type ? ' (' + d.node_type + ')' : '';
    detail = '<b style="color:var(--text)">' + esc(nid) + '</b>' + esc(ntype);
    if (t === 'node_failed' && d.error) {
      detail += '  <span style="color:#dc2626">— ' + esc(String(d.error).slice(0, 120)) + '</span>';
    }
    if (t === 'node_skipped' && d.reason) {
      detail += '  <span style="color:var(--text3)">— ' + esc(String(d.reason).slice(0, 120)) + '</span>';
    }
    if (t === 'node_succeeded' && d.outputs) {
      var keys = Object.keys(d.outputs);
      if (keys.length) {
        detail += '  <span style="color:var(--text3)">→ ' + esc(keys.slice(0, 4).join(', ')) + (keys.length > 4 ? ', …' : '') + '</span>';
      }
    }
  } else if (t === 'run_started') {
    detail = '<span style="color:var(--text2)">' + esc(d.workflow_name || '') + '</span>';
  } else if (t === 'run_succeeded' || t === 'run_failed' || t === 'run_aborted') {
    if (d.duration_s !== undefined) detail = '<span style="color:var(--text3)">' + d.duration_s.toFixed(2) + 's</span>';
    if (d.error) detail += '  <span style="color:#dc2626">' + esc(String(d.error).slice(0, 200)) + '</span>';
  }
  return '<div style="display:flex;gap:8px;padding:2px 0;border-bottom:1px solid var(--border-light)">'
    + '<span style="color:var(--text3);flex-shrink:0;font-size:10px;padding-top:1px">' + time + '</span>'
    + '<span style="color:' + spec.color + ';flex-shrink:0;font-weight:700;font-size:13px;line-height:1">' + spec.sym + '</span>'
    + '<span style="flex:1;min-width:0;word-break:break-word">' + detail + '</span>'
    + '</div>';
}

function _canvasAppendLogEvent(evt) {
  if (!_canvasState._runEvents) _canvasState._runEvents = [];
  _canvasState._runEvents.push(evt);
  // Cap at 500 events to keep DOM size manageable on long runs
  if (_canvasState._runEvents.length > 500) _canvasState._runEvents.shift();
  var body = document.getElementById('canvas-log-body');
  if (!body) return;
  var atBottom = body.scrollTop + body.clientHeight >= body.scrollHeight - 20;
  body.insertAdjacentHTML('beforeend', _canvasFormatLogEvent(evt));
  if (atBottom) body.scrollTop = body.scrollHeight;
  _canvasUpdateLogCounter();
}

function _canvasRenderLogBody() {
  var body = document.getElementById('canvas-log-body');
  if (!body) return;
  var events = _canvasState._runEvents || [];
  body.innerHTML = events.length
    ? events.map(_canvasFormatLogEvent).join('')
    : '<div style="color:var(--text3);font-size:11px;padding:8px 0">点击右上角"运行"启动 — 事件会流式出现在这里</div>';
  body.scrollTop = body.scrollHeight;
  _canvasUpdateLogCounter();
}

// ─────────── Run-status pill in toolbar ───────────
// Replaces the implicit "node colors changing" feedback with an
// explicit overall-run indicator so the user can't miss it. Lives
// next to the static executable_status badge in the editor toolbar.
//
// States:
//   running   → blue pulse + elapsed-seconds counter
//   succeeded → green check + total elapsed
//   failed    → red x + brief reason
//   (cleared after 30s on terminal states so the badge doesn't linger)

function _canvasSetRunStatus(status, payload) {
  _canvasState._runStatus = {
    status: status,        // 'running' | 'succeeded' | 'failed' | 'aborted'
    startedAt: (status === 'running') ? Date.now() : (_canvasState._runStatus && _canvasState._runStatus.startedAt) || Date.now(),
    payload: payload || {},
  };
  _canvasRenderRunStatusPill();
  // Start / stop the live elapsed-time tick
  if (_canvasState._runTickHandle) {
    clearInterval(_canvasState._runTickHandle);
    _canvasState._runTickHandle = null;
  }
  if (status === 'running') {
    _canvasState._runTickHandle = setInterval(_canvasRenderRunStatusPill, 250);
  } else {
    // Auto-clear terminal status after 30s so the badge doesn't stick around forever
    setTimeout(function() {
      if (_canvasState._runStatus && _canvasState._runStatus.status === status) {
        _canvasState._runStatus = null;
        _canvasRenderRunStatusPill();
      }
    }, 30000);
  }
}

// ─────────── Artifacts panel (HANDOFF closed-loop UI) ───────────
//
// Per-run shared workspace lives at <data_dir>/canvas_runs/<run_id>/shared/.
// Engine post-scans after each agent node + auto-registers new files
// as artifacts. UI:
//   • toolbar pill with count, opens a modal
//   • modal lists artifacts (marked deliverables first), per-row:
//     name + size + producer node + download / mark / delete actions
//   • polled every 2s while a run is active, refreshed on terminal events

function _canvasUpdateArtifactsButton() {
  var btn = document.getElementById('canvas-artifacts-btn');
  var cnt = document.getElementById('canvas-artifacts-count');
  if (!btn || !cnt) return;
  var artifacts = _canvasState._runArtifacts || [];
  var n = artifacts.length;
  if (n > 0) {
    btn.style.display = 'inline-flex';
    btn.style.alignItems = 'center';
    btn.style.gap = '4px';
    cnt.textContent = String(n);
  } else {
    btn.style.display = 'none';
  }
}

async function _canvasRefreshArtifactsList() {
  var wf = _canvasState.current;
  var rs = _canvasState._runStatus;
  if (!wf || !wf.id || !rs || !rs.payload || !rs.payload.run_id) {
    _canvasState._runArtifacts = [];
    _canvasUpdateArtifactsButton();
    return;
  }
  var runId = rs.payload.run_id;
  try {
    var d = await api('GET', '/api/portal/canvas-workflows/' + encodeURIComponent(wf.id)
      + '/runs/' + encodeURIComponent(runId) + '/artifacts');
    _canvasState._runArtifacts = d.artifacts || [];
  } catch (e) {
    // Ignore — likely no artifacts endpoint or no run yet
  }
  _canvasUpdateArtifactsButton();
  // If the modal is open, re-render its body too
  if (document.getElementById('canvas-artifacts-modal')) {
    _canvasRenderArtifactsModalBody();
  }
}

function _canvasFmtBytes(n) {
  if (n < 1024) return n + ' B';
  if (n < 1024 * 1024) return (n / 1024).toFixed(1) + ' KB';
  return (n / (1024 * 1024)).toFixed(2) + ' MB';
}

window._canvasOpenArtifactsModal = function() {
  var existing = document.getElementById('canvas-artifacts-modal');
  if (existing) { existing.remove(); return; }
  var modal = document.createElement('div');
  modal.id = 'canvas-artifacts-modal';
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.55);z-index:9998;display:flex;align-items:center;justify-content:center;padding:24px';
  modal.innerHTML =
      '<div style="background:var(--surface);border:1px solid var(--border);border-radius:12px;width:min(820px,100%);max-height:84vh;display:flex;flex-direction:column;overflow:hidden">'
    + '  <div style="display:flex;align-items:center;justify-content:space-between;padding:14px 18px;border-bottom:1px solid var(--border-light)">'
    + '    <div><div style="font-size:14px;font-weight:700"><span class="material-symbols-outlined" style="font-size:18px;vertical-align:-4px;color:#4f46e5">folder_zip</span> 运行交付件</div>'
    + '         <div style="font-size:11px;color:var(--text3);margin-top:2px">★ 标记的交付件靠前;其余为自动检测的中间文件</div></div>'
    + '    <div style="display:flex;gap:6px">'
    + '      <button class="btn btn-ghost btn-sm" onclick="_canvasOpenArtifactsAuditModal()" title="View audit log"><span class="material-symbols-outlined" style="font-size:14px">history</span> Audit</button>'
    + '      <button class="btn btn-ghost btn-sm" onclick="_canvasRefreshArtifactsList()" title="刷新"><span class="material-symbols-outlined" style="font-size:14px">refresh</span></button>'
    + '      <button class="btn btn-ghost btn-sm" onclick="document.getElementById(\'canvas-artifacts-modal\').remove()"><span class="material-symbols-outlined" style="font-size:16px">close</span></button>'
    + '    </div>'
    + '  </div>'
    + '  <div id="canvas-artifacts-modal-body" style="flex:1;overflow:auto;padding:14px 18px"></div>'
    + '</div>';
  modal.addEventListener('click', function(e){ if (e.target === modal) modal.remove(); });
  document.body.appendChild(modal);
  _canvasRenderArtifactsModalBody();
};

function _canvasRenderArtifactsModalBody() {
  var body = document.getElementById('canvas-artifacts-modal-body');
  if (!body) return;
  var artifacts = _canvasState._runArtifacts || [];
  if (!artifacts.length) {
    body.innerHTML = '<div style="padding:40px;text-align:center;color:var(--text3);font-size:12px">暂无交付件 — agent 节点写入 <code>working_dir</code> 的文件会自动出现在这里</div>';
    return;
  }
  var wf = _canvasState.current;
  var rs = _canvasState._runStatus;
  var runId = rs && rs.payload && rs.payload.run_id;
  if (!wf || !runId) {
    body.innerHTML = '<div style="color:var(--text3);font-size:12px">no active run</div>';
    return;
  }
  var dlBase = '/api/portal/canvas-workflows/' + encodeURIComponent(wf.id) + '/runs/' + encodeURIComponent(runId) + '/artifacts/';
  body.innerHTML = artifacts.map(function(a) {
    var markChip = a.marked
      ? '<span style="font-size:10px;padding:1px 7px;background:rgba(34,197,94,0.18);color:#16a34a;border-radius:9px;font-weight:600;margin-right:6px">★ 已标记</span>'
      : '<span style="font-size:10px;padding:1px 7px;background:var(--surface2,rgba(0,0,0,0.05));color:var(--text3);border-radius:9px;margin-right:6px">自动检测</span>';
    var tagChips = (a.tags || []).map(function(t) {
      return '<span style="font-size:10px;padding:1px 6px;background:rgba(99,102,241,0.15);color:#4f46e5;border-radius:9px;margin-right:3px">' + esc(t) + '</span>';
    }).join('');
    var descLine = a.description
      ? '<div style="font-size:11px;color:var(--text3);margin-top:4px;font-style:italic">' + esc(a.description) + '</div>'
      : '';
    return '<div style="border:1px solid var(--border);border-radius:10px;padding:12px 14px;margin-bottom:10px;background:var(--bg)">'
      + '<div style="display:flex;align-items:flex-start;justify-content:space-between;gap:8px">'
      +   '<div style="flex:1;min-width:0">'
      +     '<div style="display:flex;align-items:center;gap:4px;margin-bottom:4px">' + markChip + tagChips + '</div>'
      +     '<div style="font-size:14px;font-weight:600;color:var(--text);overflow:hidden;text-overflow:ellipsis;white-space:nowrap">' + esc(a.name) + '</div>'
      +     '<div style="font-size:11px;color:var(--text3);margin-top:3px">'
      +       _canvasFmtBytes(a.size_bytes||0) + ' · ' + esc(a.mime || '')
      +       ' · 来自 <b style="color:var(--text2)">' + esc(a.producer_node_id) + '</b>'
      +       (a.producer_agent_id ? ' (' + esc(a.producer_agent_id.slice(0,8)) + ')' : '')
      +     '</div>'
      +     descLine
      +     '<div style="font-size:10px;color:var(--text3);margin-top:4px;font-family:monospace">vars: ' + esc(a.vars_key) + '</div>'
      +   '</div>'
      +   '<div style="display:flex;flex-direction:column;gap:4px;flex-shrink:0">'
      +     '<a href="' + dlBase + encodeURIComponent(a.id) + '" download="' + esc(a.name) + '" class="btn btn-sm" style="padding:4px 10px;font-size:11px;text-decoration:none"><span class="material-symbols-outlined" style="font-size:13px;vertical-align:-2px">download</span> 下载</a>'
      +     (a.marked ? '' : '<button onclick="_canvasMarkArtifact(\'' + esc(a.id) + '\')" class="btn btn-sm" style="padding:4px 10px;font-size:11px;color:#16a34a"><span class="material-symbols-outlined" style="font-size:13px;vertical-align:-2px">star</span> 标记</button>')
      +     '<button onclick="_canvasDeleteArtifact(\'' + esc(a.id) + '\',\'' + esc(a.name).replace(/'/g, "\\'") + '\')" class="btn btn-sm" style="padding:4px 10px;font-size:11px;color:var(--error)"><span class="material-symbols-outlined" style="font-size:13px;vertical-align:-2px">delete</span></button>'
      +   '</div>'
      + '</div>'
      + '</div>';
  }).join('');
}

window._canvasMarkArtifact = async function(artifactId) {
  var wf = _canvasState.current;
  var runId = _canvasState._runStatus && _canvasState._runStatus.payload && _canvasState._runStatus.payload.run_id;
  if (!wf || !runId) return;
  var desc = prompt('描述(可选):', '') || '';
  var tagsRaw = prompt('标签(逗号分隔,可选):', '') || '';
  var tags = tagsRaw.split(',').map(function(s){return s.trim();}).filter(Boolean);
  try {
    await api('POST', '/api/portal/canvas-workflows/' + encodeURIComponent(wf.id)
      + '/runs/' + encodeURIComponent(runId) + '/artifacts/' + encodeURIComponent(artifactId) + '/mark',
      {description: desc, tags: tags});
    _toast('✓ Marked as deliverable', 'success');
    await _canvasRefreshArtifactsList();
  } catch (e) {
    _toast('Mark failed:' + e, 'error');
  }
};

window._canvasDeleteArtifact = async function(artifactId, name) {
  if (!confirm('Delete "' + name + '"?\nFile and index will be removed; audit record kept.')) return;
  var wf = _canvasState.current;
  var runId = _canvasState._runStatus && _canvasState._runStatus.payload && _canvasState._runStatus.payload.run_id;
  if (!wf || !runId) return;
  try {
    await api('DELETE', '/api/portal/canvas-workflows/' + encodeURIComponent(wf.id)
      + '/runs/' + encodeURIComponent(runId) + '/artifacts/' + encodeURIComponent(artifactId));
    _toast('Deleted', 'info');
    await _canvasRefreshArtifactsList();
  } catch (e) {
    _toast('Delete failed:' + e, 'error');
  }
};

window._canvasOpenArtifactsAuditModal = async function() {
  var wf = _canvasState.current;
  var runId = _canvasState._runStatus && _canvasState._runStatus.payload && _canvasState._runStatus.payload.run_id;
  if (!wf || !runId) return;
  var existing = document.getElementById('canvas-audit-modal');
  if (existing) existing.remove();
  var modal = document.createElement('div');
  modal.id = 'canvas-audit-modal';
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.6);z-index:9999;display:flex;align-items:center;justify-content:center;padding:24px';
  modal.innerHTML = '<div style="background:var(--surface);border:1px solid var(--border);border-radius:12px;width:min(820px,100%);max-height:84vh;display:flex;flex-direction:column;overflow:hidden">'
    + '<div style="display:flex;align-items:center;justify-content:space-between;padding:14px 18px;border-bottom:1px solid var(--border-light)">'
    + '<div style="font-size:14px;font-weight:700"><span class="material-symbols-outlined" style="font-size:18px;vertical-align:-4px">history</span> Artifact Audit Log</div>'
    + '<button class="btn btn-ghost btn-sm" onclick="document.getElementById(\'canvas-audit-modal\').remove()"><span class="material-symbols-outlined" style="font-size:16px">close</span></button>'
    + '</div>'
    + '<div id="canvas-audit-body" style="flex:1;overflow:auto;padding:14px 18px;font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:11px">Loading…</div>'
    + '</div>';
  modal.addEventListener('click', function(e){ if (e.target === modal) modal.remove(); });
  document.body.appendChild(modal);
  try {
    var d = await api('GET', '/api/portal/canvas-workflows/' + encodeURIComponent(wf.id) + '/runs/' + encodeURIComponent(runId) + '/audit');
    var rows = d.audit || [];
    var ACTION_COLORS = {
      register: '#16a34a', mark: '#4f46e5', read: '#3b82f6',
      delete: '#dc2626', scan_start: '#94a3b8', scan_end: '#94a3b8',
    };
    document.getElementById('canvas-audit-body').innerHTML = rows.length
      ? rows.map(function(r) {
          var ts = r.ts ? new Date(r.ts * 1000).toLocaleTimeString('zh-CN', {hour12: false}) + '.' + String(Math.floor((r.ts*1000)%1000)).padStart(3,'0') : '';
          var color = ACTION_COLORS[r.action] || 'var(--text3)';
          var detail = '';
          if (r.action === 'register') detail = ' size=' + (r.size_bytes||0) + ' sha=' + (r.sha256||'').slice(0,8);
          else if (r.action === 'mark') detail = ' tags=' + JSON.stringify(r.tags||[]);
          else if (r.action === 'scan_start') detail = ' pre=' + (r.pre_files||0) + ' files';
          else if (r.action === 'scan_end') detail = ' new=' + (r.new_artifacts||0);
          return '<div style="display:flex;gap:8px;padding:3px 0;border-bottom:1px solid var(--border-light)">'
            + '<span style="color:var(--text3);flex-shrink:0">' + ts + '</span>'
            + '<span style="color:' + color + ';font-weight:700;min-width:80px">' + esc(r.action || '?') + '</span>'
            + '<span style="color:var(--text2);flex:1;min-width:0;word-break:break-word">'
            +   (r.actor_agent_id ? '<b>' + esc(r.actor_agent_id.slice(0,8)) + '</b>@' : '')
            +   esc(r.actor_node_id || '') + ' · ' + esc(r.name || r.artifact_id || '')
            +   '<span style="color:var(--text3)">' + detail + '</span>'
            + '</span>'
            + '</div>';
        }).join('')
      : '<div style="color:var(--text3);text-align:center;padding:30px">No audit entries yet</div>';
  } catch (e) {
    document.getElementById('canvas-audit-body').innerHTML = '<div style="color:var(--error)">Load failed:' + esc(String(e)) + '</div>';
  }
};

function _canvasRenderRunStatusPill() {
  var el = document.getElementById('canvas-run-status-pill');
  if (!el) return;
  var rs = _canvasState._runStatus;
  if (!rs) {
    el.style.display = 'none';
    el.innerHTML = '';
    return;
  }
  // Token-based palette — picks up theme switch automatically (dark
  // ↔ light) instead of being hardcoded to a hex.
  var STYLES = {
    running:   {kind:'warning', icon:'sync',         label:'Running',   pulse:true},
    succeeded: {kind:'success', icon:'check_circle', label:'运行成功'},
    failed:    {kind:'error',   icon:'error',        label:'运行失败'},
    aborted:   {kind:'warning', icon:'stop_circle',  label:'已中止'},
  };
  var s = STYLES[rs.status] || STYLES.running;
  var elapsedS = ((Date.now() - rs.startedAt) / 1000);
  var elapsedTxt;
  if (rs.status === 'running') {
    elapsedTxt = elapsedS.toFixed(1) + 's';
  } else {
    var d = (rs.payload && typeof rs.payload.duration_s === 'number') ? rs.payload.duration_s : elapsedS;
    elapsedTxt = d.toFixed(1) + 's';
  }
  var pulseStyle = s.pulse ? 'animation:_cvRunPulse 1.4s ease-in-out infinite;' : '';
  var detail = '';
  if (rs.status === 'failed' && rs.payload && rs.payload.error) {
    detail = ' · ' + esc(String(rs.payload.error).slice(0, 40));
  }
  // Use --chip-{kind}-{bg,fg} tokens; theme-aware (dark/light auto-swap).
  el.style.display = 'inline-flex';
  el.style.cssText = 'display:inline-flex;align-items:center;gap:4px;padding:3px 10px;'
    + 'font-size:11px;border-radius:11px;font-weight:600;margin-left:6px;'
    + 'background:var(--chip-'+s.kind+'-bg);color:var(--chip-'+s.kind+'-fg);' + pulseStyle;
  el.innerHTML = _ui.icon(s.icon, {size: 14})
    + '<span>'+s.label+'</span>'
    + '<span style="opacity:0.75">· '+elapsedTxt+esc(detail)+'</span>';
}

function _canvasRedrawSvg() {
  var svg = document.getElementById('canvas-svg');
  if (!svg) return;
  var wf = _canvasState.current;
  // Defs (arrowheads)
  var defs = '<defs>'
    + '<marker id="cv-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="8" markerHeight="8" orient="auto-start-reverse">'
    + '  <path d="M 0 0 L 10 5 L 0 10 z" fill="var(--text2)"/>'
    + '</marker>'
    + '</defs>';
  // Edges first (so nodes render on top)
  var edgesSvg = (wf.edges || []).map(_canvasRenderEdge).join('');
  // Pending edge (during creation drag)
  var pendingSvg = '';
  if (_canvasState.pendingEdge) {
    var pe = _canvasState.pendingEdge;
    var src = _findNode(pe.fromNodeId);
    if (src) {
      var p = _nodeAnchorPoint(src, pe.fromAnchor);
      pendingSvg = '<path d="M ' + p.x + ' ' + p.y + ' L ' + pe.svgX + ' ' + pe.svgY
        + '" stroke="var(--primary)" stroke-width="2" stroke-dasharray="4 3" fill="none" pointer-events="none"/>';
    }
  }
  var nodesSvg = (wf.nodes || []).map(_canvasRenderNode).join('');
  svg.innerHTML = defs + edgesSvg + pendingSvg + nodesSvg;
  // Bind events on each node group (event delegation would need svg listener)
  svg.querySelectorAll('g[data-node-id]').forEach(function(g) {
    var nid = g.getAttribute('data-node-id');
    g.addEventListener('mousedown', function(e) { _canvasNodeMouseDown(e, nid); });
    g.addEventListener('click', function(e) { e.stopPropagation(); _canvasSelectNode(nid); });
  });
  svg.querySelectorAll('circle[data-anchor]').forEach(function(circle) {
    circle.addEventListener('mousedown', function(e) {
      e.stopPropagation();
      _canvasStartEdge(circle.getAttribute('data-node-id'),
                       circle.getAttribute('data-anchor'));
    });
  });
  svg.addEventListener('mousemove', _canvasMouseMove);
  svg.addEventListener('mouseup', _canvasMouseUp);
  svg.addEventListener('click', function() { _canvasSelectNode(null); });
}

function _findNode(id) {
  return (_canvasState.current.nodes || []).find(function(n) { return n.id === id; });
}

function _nodeAnchorPoint(node, anchor) {
  var d = (typeof _canvasNodeDims === 'function')
    ? _canvasNodeDims(node)
    : { w: (node.type === 'start' || node.type === 'end') ? 50 : _NODE_W,
        h: (node.type === 'start' || node.type === 'end') ? 50 : _NODE_H };
  var w = d.w, h = d.h;
  switch (anchor) {
    case 'top':    return { x: node.x + w/2, y: node.y };
    case 'right':  return { x: node.x + w,   y: node.y + h/2 };
    case 'bottom': return { x: node.x + w/2, y: node.y + h };
    case 'left':   return { x: node.x,       y: node.y + h/2 };
  }
  return { x: node.x + w/2, y: node.y + h/2 };
}

// ─────────── Per-node run-state badge (2026-05-02) ───────────
// State source of truth lives on _canvasState._nodeRunStates so the
// SVG redraw (drag, layout change, edge add) doesn't lose visual state.
//
// Badge palette: small filled circle in the top-right corner of the
// node, with a Material Symbol indicating the state. Pending = no
// badge (default look — implies "waiting").
//
//   running   → orange spinner, with a CSS rotate animation
//   succeeded → green check
//   failed    → red x
//   skipped   → grey dash (upstream broken)

var _NODE_BADGE_STYLES = {
  running:   {fill: 'var(--chip-warning-fg)', icon: 'M -3,0 a 3,3 0 1,0 6,0 a 3,3 0 1,0 -6,0', label: '⟳'},
  succeeded: {fill: 'var(--chip-success-fg)', label: '✓'},
  failed:    {fill: 'var(--chip-error-fg)',   label: '✕'},
  skipped:   {fill: 'var(--text3)',           label: '⊘'},
};

function _canvasNodeStatusBadge(state, nodeW) {
  if (!state || state === 'pending') return '';
  var s = _NODE_BADGE_STYLES[state] || _NODE_BADGE_STYLES.skipped;
  var cx = nodeW - 4;   // top-right corner overlap
  var cy = 4;
  var pulseAttr = (state === 'running')
    ? ' style="animation:_cvRunPulse 1.4s ease-in-out infinite"'
    : '';
  return '<g class="cv-node-badge" pointer-events="none"' + pulseAttr + '>'
    + '<circle cx="' + cx + '" cy="' + cy + '" r="9" fill="' + s.fill + '" stroke="var(--surface)" stroke-width="2"/>'
    + '<text x="' + cx + '" y="' + (cy + 4) + '" text-anchor="middle" font-size="11" font-weight="700" fill="#fff">'
    +    s.label
    + '</text>'
    + '</g>';
}

function _canvasRenderNode(n) {
  var nt = _NODE_TYPES[n.type] || _NODE_TYPES.agent;
  var isSel = (_canvasState.selectedNodeId === n.id);
  var _techNd = false;
  try { _techNd = localStorage.getItem('tudou_theme') === 'tech'; } catch (e) {}
  var stroke = isSel ? 'var(--primary)' : nt.color;
  var sw = isSel ? 3 : 2;
  var w = _NODE_W, h = _NODE_H;
  // Tech mode: bigger rect nodes (200x90) with header band — closer to
  // stitch_19's "AGENT: SEARCH" cards. Circle/diamond nodes keep their
  // legacy compact form so start/end/decision shapes still read as
  // distinct from agent cards.
  if (_techNd && nt.shape === 'rect') {
    w = 200;
    h = 90;
  }
  // Tech mode: scale start/end circles up to stitch_19 spec (80px)
  // so they read as PEER nodes next to the 200x90 agent cards.
  if (_techNd && nt.shape === 'circle') {
    w = h = 80;
  }
  var shapeSvg = '';
  if (nt.shape === 'circle') {
    if (_techNd) {
      w = h = 80;
      // Stitch_19 start/end node: 80px circle, glass-card bg, 2px
      // tier-color border, soft tier-color glow halo, play_circle (or
      // flag) Material Symbol centered + small mono label below.
      var cBgFill = isSel ? 'rgba(31,31,39,0.95)' : 'rgba(31,31,39,0.80)';
      var cR = 38;
      shapeSvg =
        '<circle cx="40" cy="40" r="' + cR + '" fill="' + cBgFill + '" stroke="' + stroke + '" stroke-width="' + sw + '" filter="drop-shadow(0 0 12px ' + nt.color + '70)"/>' +
        // Tier-color inner ring (matches the agent-card top accent)
        '<circle cx="40" cy="40" r="' + (cR - 4) + '" fill="none" stroke="' + nt.color + '" stroke-width="1" stroke-opacity="0.40"/>';
    } else {
      w = h = 50;
      shapeSvg = '<circle cx="25" cy="25" r="23" fill="' + nt.color + '" fill-opacity="0.15" stroke="' + stroke + '" stroke-width="' + sw + '"/>';
    }
  } else if (nt.shape === 'diamond') {
    shapeSvg = '<path d="M ' + (w/2) + ' 2 L ' + (w-2) + ' ' + (h/2) + ' L ' + (w/2) + ' ' + (h-2) + ' L 2 ' + (h/2) + ' z" fill="' + nt.color + '" fill-opacity="0.15" stroke="' + stroke + '" stroke-width="' + sw + '"/>';
  } else {
    if (_techNd) {
      // Glass-panel rect: dark indigo bg + 1px outline + colored top
      // accent bar with the tier color, plus inset highlight.
      var bgFill = isSel ? 'rgba(31,31,39,0.95)' : 'rgba(31,31,39,0.85)';
      var topAccent = '<rect x="2" y="2" width="' + (w-4) + '" height="3" rx="2" ry="2" fill="' + nt.color + '" fill-opacity="0.85"/>';
      shapeSvg =
        '<rect x="2" y="2" width="' + (w-4) + '" height="' + (h-4) + '" rx="8" ry="8" fill="' + bgFill + '" stroke="' + stroke + '" stroke-width="' + sw + '"/>' +
        topAccent +
        // Subtle inner glow when selected
        (isSel ? '<rect x="3" y="3" width="' + (w-6) + '" height="' + (h-6) + '" rx="7" ry="7" fill="none" stroke="' + nt.color + '" stroke-width="1" stroke-opacity="0.3"/>' : '');
    } else {
      shapeSvg = '<rect x="2" y="2" width="' + (w-4) + '" height="' + (h-4) + '" rx="6" ry="6" fill="' + nt.color + '" fill-opacity="0.15" stroke="' + stroke + '" stroke-width="' + sw + '"/>';
    }
  }
  // Label — for agent nodes, surface the BOUND AGENT'S NAME so the
  // canvas isn't a sea of identical "Agent Node" boxes. Falls back to
  // user's custom label / generic type label if no agent bound or
  // agent list hasn't loaded yet. "未绑定" is shown in error color so
  // the author catches missing agent_id BEFORE running.
  var primaryLabel, secondaryLabel = '';
  var secondaryColor = 'var(--text3)';
  if (n.type === 'agent') {
    var agentId = (n.config || {}).agent_id || '';
    var customLabel = (n.label && n.label !== nt.label) ? n.label : '';
    var resolvedAgentName = '';
    if (agentId) {
      var agentList = _canvasState._agentsList || [];
      var hit = agentList.find(function(a) { return a.id === agentId; });
      if (hit) {
        resolvedAgentName = hit.name + (hit.role ? '·' + hit.role : '');
      } else {
        resolvedAgentName = agentId.slice(0, 8);  // cache miss, show prefix
      }
    }
    if (customLabel && resolvedAgentName) {
      primaryLabel = customLabel;
      secondaryLabel = resolvedAgentName;
    } else if (resolvedAgentName) {
      primaryLabel = resolvedAgentName;
      secondaryLabel = '';
    } else if (customLabel) {
      primaryLabel = customLabel;
      secondaryLabel = '⚠ No agent bound';
      secondaryColor = 'var(--chip-error-fg)';
    } else {
      primaryLabel = 'Agent Node';
      secondaryLabel = '⚠ Unbound';
      secondaryColor = 'var(--chip-error-fg)';
    }
  } else {
    primaryLabel = n.label || nt.label;
    // Older workflow files persisted Chinese labels for start/end
    // ("开始" / "结束"). Show the canonical English label instead so
    // the canvas reads consistently in tech mode without forcing a
    // data migration.
    if (n.type === 'start' && (primaryLabel === '开始' || primaryLabel === 'End')) primaryLabel = 'Start';
    if (n.type === 'end' && (primaryLabel === 'End' || primaryLabel === 'End')) primaryLabel = 'End';
    if (n.type === 'parallel' && primaryLabel === '并行执行') primaryLabel = 'Parallel';
    if (n.type === 'decision' && primaryLabel === '条件分支') primaryLabel = 'Branch';
  }
  primaryLabel = _techNd ? primaryLabel.slice(0, 22) : primaryLabel.slice(0, 18);
  var labelSvg;
  if (_techNd && nt.shape === 'rect') {
    // Stitch_19 layout — title centered vertically in the body, role
    // kicker omitted (no hard-coded role taxonomy). Bottom band shows
    // the bound agent's name.mono. Title font-size bumped to 16 for
    // readability per user feedback.
    var titleY = 36;
    labelSvg =
      // Primary label (Inter, white, bold) — larger so the agent name
      // reads from across the canvas.
      '<text x="14" y="' + titleY + '" font-family="Inter, sans-serif" font-size="16" font-weight="600" fill="#e4e1ed" letter-spacing="-0.2" pointer-events="none">' +
        esc(primaryLabel) +
      '</text>' +
      // Bottom divider
      '<line x1="14" y1="' + (h - 26) + '" x2="' + (w - 14) + '" y2="' + (h - 26) + '" stroke="rgba(255,255,255,0.08)" stroke-width="1" pointer-events="none"/>' +
      // Secondary meta line in mono
      (secondaryLabel
        ? '<text x="14" y="' + (h - 11) + '" font-family="\'Space Grotesk\', monospace" font-size="10" letter-spacing="0.5" fill="' + (secondaryColor === 'var(--chip-error-fg)' ? '#ffb4ab' : '#908fa0') + '" pointer-events="none">' + esc(secondaryLabel.slice(0, 28)) + '</text>'
        : '');
  } else if (_techNd && nt.shape === 'circle') {
    // Stitch_19 start/end node — big play_circle / flag glyph centered
    // in the upper half of the circle, mono "START" / "END" label
    // tucked beneath. Glyphs are unicode triangle / square fallbacks
    // (font-family-agnostic, render reliably via SVG innerHTML).
    var glyph = (n.type === 'start') ? '▶' : '■';
    labelSvg =
      '<text x="' + (w/2) + '" y="' + (h/2 + 2) + '" text-anchor="middle" font-size="22" font-weight="600" fill="' + nt.color + '" pointer-events="none">' + glyph + '</text>' +
      '<text x="' + (w/2) + '" y="' + (h/2 + 22) + '" text-anchor="middle" font-family="\'Space Grotesk\', monospace" font-size="9" letter-spacing="1.5" fill="rgba(255,255,255,0.65)" pointer-events="none">' + esc(primaryLabel.toUpperCase()) + '</text>';
  } else if (secondaryLabel) {
    labelSvg = '<text x="' + (w/2) + '" y="' + (h/2 - 2) + '" text-anchor="middle" '
      + 'font-size="12" font-weight="600" fill="var(--text)" pointer-events="none">'
      + esc(primaryLabel) + '</text>'
      + '<text x="' + (w/2) + '" y="' + (h/2 + 14) + '" text-anchor="middle" '
      + 'font-size="10" fill="' + secondaryColor + '" pointer-events="none">'
      + esc(secondaryLabel.slice(0, 22)) + '</text>';
  } else {
    labelSvg = '<text x="' + (w/2) + '" y="' + (h/2 + 4) + '" text-anchor="middle" '
      + 'font-size="12" fill="var(--text)" pointer-events="none">'
      + esc(primaryLabel) + '</text>';
  }
  // Icon — title now anchors the top-left of the body in tech mode,
  // so the small icon block is dropped (the colored top accent bar
  // already signals the node tier). Legacy theme keeps the glyph.
  var iconSvg;
  if (_techNd && nt.shape === 'rect') {
    iconSvg = '';
  } else if (_techNd && nt.shape === 'circle') {
    // The labelSvg branch above already drew the glyph centred — skip
    // the legacy small glyph at top-left (would double up).
    iconSvg = '';
  } else {
    iconSvg = (nt.shape === 'rect')
      ? '<text x="8" y="16" font-size="13" fill="' + nt.color + '" pointer-events="none">' + nt.icon + '</text>'
      : '';
  }
  // Anchor handles (for edge creation) — shown only on hover via opacity
  var anchors = ['top','right','bottom','left'].map(function(a) {
    var p = { top:[w/2,0], right:[w,h/2], bottom:[w/2,h], left:[0,h/2] }[a];
    return '<circle cx="' + p[0] + '" cy="' + p[1] + '" r="5" fill="var(--primary)" stroke="#fff" stroke-width="1.5" '
         + 'class="cv-anchor" data-node-id="' + n.id + '" data-anchor="' + a + '" '
         + 'style="opacity:0;cursor:crosshair" '
         + 'onmouseenter="this.style.opacity=1" '
         + 'onmouseleave="this.style.opacity=0"/>';
  }).join('');
  // Run-state badge (pending = nothing). Read from in-memory dict so
  // it survives SVG redraws; _canvasApplyRunState updates the dict
  // whenever a state event arrives.
  var nodeState = (_canvasState._nodeRunStates || {})[n.id];
  var badgeSvg = _canvasNodeStatusBadge(nodeState, w);
  return '<g data-node-id="' + n.id + '" transform="translate(' + n.x + ',' + n.y + ')" style="cursor:move">'
       + '<rect x="-2" y="-2" width="' + (w+4) + '" height="' + (h+4) + '" fill="transparent" '
       +   'onmouseenter="this.parentNode.querySelectorAll(\'.cv-anchor\').forEach(function(a){a.style.opacity=1})" '
       +   'onmouseleave="this.parentNode.querySelectorAll(\'.cv-anchor\').forEach(function(a){a.style.opacity=0})"/>'
       + shapeSvg + iconSvg + labelSvg + anchors + badgeSvg + '</g>';
}

// Returns the actual rendered {w,h} for a node, matching the logic in
// _canvasRenderNode. Edge math + hit-test must use the same dimensions
// or edges connect inside the card / drag offsets feel "off".
function _canvasNodeDims(n) {
  var nt = _NODE_TYPES[n.type] || _NODE_TYPES.agent;
  var _isTechCv = false;
  try { _isTechCv = localStorage.getItem('tudou_theme') === 'tech'; } catch (e) {}
  if (nt.shape === 'circle') return { w: _isTechCv ? 80 : 50, h: _isTechCv ? 80 : 50 };
  if (_isTechCv && nt.shape === 'rect') return { w: 200, h: 90 };
  return { w: _NODE_W, h: _NODE_H };
}

function _canvasRenderEdge(e) {
  var src = _findNode(e.from), tgt = _findNode(e.to);
  if (!src || !tgt) return '';
  // Pick anchors: use right/left for horizontal, top/bottom for vertical.
  // Heuristic: whichever pair gives the most direct line.
  var srcD = _canvasNodeDims(src);
  var tgtD = _canvasNodeDims(tgt);
  var srcW = srcD.w, srcH = srcD.h, tgtW = tgtD.w, tgtH = tgtD.h;
  var sx = src.x + srcW/2, sy = src.y + srcH/2;
  var tx = tgt.x + tgtW/2, ty = tgt.y + tgtH/2;
  var dx = tx - sx, dy = ty - sy;
  var p1, p2;
  if (Math.abs(dx) >= Math.abs(dy)) {
    p1 = (dx >= 0) ? { x: src.x + srcW, y: sy } : { x: src.x, y: sy };
    p2 = (dx >= 0) ? { x: tgt.x,        y: ty } : { x: tgt.x + tgtW, y: ty };
  } else {
    p1 = (dy >= 0) ? { x: sx, y: src.y + srcH } : { x: sx, y: src.y };
    p2 = (dy >= 0) ? { x: tx, y: tgt.y       } : { x: tx, y: tgt.y + tgtH };
  }
  // Cubic bezier with control points pulling outward from each end
  var cp1x = p1.x + (p2.x - p1.x) * 0.5;
  var cp1y = p1.y;
  var cp2x = p1.x + (p2.x - p1.x) * 0.5;
  var cp2y = p2.y;
  var d = 'M ' + p1.x + ' ' + p1.y + ' C ' + cp1x + ' ' + cp1y + ', ' + cp2x + ' ' + cp2y + ', ' + p2.x + ' ' + p2.y;
  var labelSvg = '';
  if (e.label) {
    var midX = (p1.x + p2.x) / 2;
    var midY = (p1.y + p2.y) / 2;
    labelSvg = '<rect x="' + (midX - 28) + '" y="' + (midY - 9) + '" width="56" height="18" rx="9" fill="var(--bg)" stroke="var(--border)"/>'
             + '<text x="' + midX + '" y="' + (midY + 4) + '" text-anchor="middle" font-size="10" fill="var(--text2)">' + esc(e.label.slice(0, 8)) + '</text>';
  }
  return '<g data-edge-id="' + e.id + '">'
       + '<path d="' + d + '" stroke="var(--text2)" stroke-width="2" fill="none" marker-end="url(#cv-arrow)" '
       + ' onclick="event.stopPropagation();_canvasDeleteEdge(\'' + e.id + '\')" '
       + ' style="cursor:pointer" />'
       + labelSvg + '</g>';
}

window._canvasDeleteEdge = function(eid) {
  if (!confirm('删除这条连线?')) return;
  _canvasState.current.edges = _canvasState.current.edges.filter(function(x) { return x.id !== eid; });
  _canvasRedrawSvg();
};

// ─────────── Drag from palette to canvas ───────────

window._canvasPaletteDragStart = function(e, nodeType) {
  e.dataTransfer.setData('text/canvas-node-type', nodeType);
  e.dataTransfer.effectAllowed = 'copy';
};

window._canvasDrop = function(e) {
  e.preventDefault();
  var t = e.dataTransfer.getData('text/canvas-node-type');
  if (!t || !_NODE_TYPES[t]) return;
  var svg = document.getElementById('canvas-svg');
  var rect = svg.getBoundingClientRect();
  var x = Math.max(0, e.clientX - rect.left - _NODE_W/2);
  var y = Math.max(0, e.clientY - rect.top - _NODE_H/2);
  var nid = 'n_' + Date.now().toString(36);
  _canvasState.current.nodes.push({
    id: nid, type: t, x: x, y: y,
    label: _NODE_TYPES[t].label, config: {},
  });
  _canvasState.selectedNodeId = nid;
  _canvasRedrawSvg();
  _canvasRenderConfigPanel();
};

// ─────────── Node drag (move within canvas) ───────────

function _canvasNodeMouseDown(e, nodeId) {
  if (e.button !== 0) return;
  // If user clicked an anchor circle, _canvasStartEdge already fired and
  // stopped propagation — we shouldn't see those events here.
  e.preventDefault();
  var n = _findNode(nodeId);
  if (!n) return;
  var svg = document.getElementById('canvas-svg');
  var rect = svg.getBoundingClientRect();
  _canvasState.drag = {
    nodeId: nodeId,
    startMouseX: e.clientX - rect.left,
    startMouseY: e.clientY - rect.top,
    originX: n.x, originY: n.y,
  };
}

function _canvasMouseMove(e) {
  var svg = document.getElementById('canvas-svg');
  var rect = svg.getBoundingClientRect();
  if (_canvasState.drag) {
    var d = _canvasState.drag;
    var n = _findNode(d.nodeId);
    if (!n) return;
    var dx = (e.clientX - rect.left) - d.startMouseX;
    var dy = (e.clientY - rect.top)  - d.startMouseY;
    n.x = Math.max(0, d.originX + dx);
    n.y = Math.max(0, d.originY + dy);
    _canvasRedrawSvg();
  } else if (_canvasState.pendingEdge) {
    _canvasState.pendingEdge.svgX = e.clientX - rect.left;
    _canvasState.pendingEdge.svgY = e.clientY - rect.top;
    _canvasRedrawSvg();
  }
}

function _canvasMouseUp(e) {
  if (_canvasState.drag) { _canvasState.drag = null; }
  if (_canvasState.pendingEdge) {
    // See if mouseup landed on a node — if so, create an edge
    var hit = e.target.closest('g[data-node-id]');
    var pe = _canvasState.pendingEdge;
    if (hit) {
      var toId = hit.getAttribute('data-node-id');
      if (toId !== pe.fromNodeId) {
        // Avoid duplicate edges between same pair (idempotent)
        var dup = (_canvasState.current.edges || []).some(function(x) {
          return x.from === pe.fromNodeId && x.to === toId;
        });
        if (!dup) {
          _canvasState.current.edges.push({
            id: 'e_' + Date.now().toString(36),
            from: pe.fromNodeId, to: toId, label: '', condition: '',
          });
        }
      }
    }
    _canvasState.pendingEdge = null;
    _canvasRedrawSvg();
  }
}

function _canvasStartEdge(fromNodeId, fromAnchor) {
  _canvasState.pendingEdge = {
    fromNodeId: fromNodeId, fromAnchor: fromAnchor,
    svgX: 0, svgY: 0,
  };
}

// ─────────── Selection + config panel ───────────

function _canvasSelectNode(nid) {
  _canvasState.selectedNodeId = nid;
  _canvasRedrawSvg();
  _canvasRenderConfigPanel();
}

// HANDOFF [H] — list output variables a given node type produces.
// Mirrors the dict shape returned by each _exec_* function in
// canvas_executor.py; if you add a node type or extend an existing
// executor's return dict, update this map too.
var _CANVAS_NODE_OUTPUT_KEYS = {
  start: ['started_at'],
  end:   ['finished_at'],
  agent: ['output', 'task_id', 'duration_s'],
  decision: ['branch', 'raw_result'],
  parallel: ['fanned_out_at'],
};

// HANDOFF [H] — collect every node id that can reach `targetId`
// transitively via edges. Used to populate the "available vars" panel:
// only upstream nodes have produced outputs by the time `targetId`
// runs, so they're the only legal sources.
function _canvasUpstreamNodes(targetId) {
  var wf = _canvasState.current;
  if (!wf) return [];
  var rev = {};   // dst -> [src, src, ...]
  (wf.edges || []).forEach(function(e) {
    if (!rev[e.to]) rev[e.to] = [];
    rev[e.to].push(e.from);
  });
  var seen = {};
  var stack = (rev[targetId] || []).slice();
  while (stack.length) {
    var nid = stack.pop();
    if (seen[nid]) continue;
    seen[nid] = true;
    (rev[nid] || []).forEach(function(s) { stack.push(s); });
  }
  return Object.keys(seen);
}

function _canvasRenderConfigPanel() {
  var box = document.getElementById('canvas-config-panel');
  if (!box) return;
  var nid = _canvasState.selectedNodeId;
  if (!nid) {
    box.innerHTML = '<div style="font-size:11px;color:var(--text3)">未选中节点</div>'
                  + '<div style="font-size:12px;color:var(--text3);margin-top:10px;line-height:1.5">点击画布上的节点查看 / 编辑属性</div>';
    return;
  }
  var n = _findNode(nid);
  if (!n) return;
  var nt = _NODE_TYPES[n.type] || _NODE_TYPES.agent;
  var typeFields = '';
  // Type-specific config fields
  if (n.type === 'agent') {
    // Build agent dropdown from cached list. If cache hasn't arrived
    // yet, the only option is the current value (so the existing
    // selection isn't lost) plus a "loading" hint; preload re-renders
    // the panel once the fetch lands.
    var agentList = _canvasState._agentsList;
    var curAgentId = n.config.agent_id || '';
    // Same-agent-in-parallel exclusion: drop agents that are already
    // assigned to a parallel-reachable sibling node (Layer 1 prevention,
    // matches the canvas validator's structural check).
    var parallelUsedAgents = (function() {
      var wf = _canvasState && _canvasState.current;
      if (!wf || !wf.nodes || !wf.edges || !nid) return new Set();
      function ancestors(start) {
        var seen = new Set();
        var stack = [start];
        while (stack.length) {
          var cur = stack.pop();
          (wf.edges || []).forEach(function(e) {
            if (e.to === cur && e.from && !seen.has(e.from)) {
              seen.add(e.from);
              stack.push(e.from);
            }
          });
        }
        return seen;
      }
      var myAncestors = ancestors(nid);
      var myDescendants = (function() {
        var seen = new Set();
        var stack = [nid];
        while (stack.length) {
          var cur = stack.pop();
          (wf.edges || []).forEach(function(e) {
            if (e.from === cur && e.to && !seen.has(e.to)) {
              seen.add(e.to);
              stack.push(e.to);
            }
          });
        }
        return seen;
      })();
      var blocked = new Set();
      (wf.nodes || []).forEach(function(other) {
        if (other.id === nid) return;
        if (other.type !== 'agent') return;
        // parallel-reachable = neither is ancestor of the other
        if (myAncestors.has(other.id) || myDescendants.has(other.id)) return;
        var oa = (other.config || {}).agent_id;
        if (oa) blocked.add(oa);
      });
      return blocked;
    })();
    var availableAgents = (agentList || []).filter(function(a) {
      // Always show the currently-selected agent (don't hide your own choice)
      if (a.id === curAgentId) return true;
      return !parallelUsedAgents.has(a.id);
    });
    var hiddenCount = (agentList || []).length - availableAgents.length;
    if (hiddenCount < 0) hiddenCount = 0;
    var agentOpts = '<option value=""' + (!curAgentId ? ' selected' : '') + '>— 任意空闲 agent —</option>';
    if (agentList && agentList.length) {
      availableAgents.forEach(function(a) {
        var sel = (a.id === curAgentId) ? ' selected' : '';
        var label = a.name + (a.role ? ' · ' + a.role : '') + ' [' + a.id.slice(0, 8) + ']';
        agentOpts += '<option value="' + esc(a.id) + '"' + sel + '>' + esc(label) + '</option>';
      });
    } else if (curAgentId) {
      // Cache empty but value exists — preserve it so a save round-trip
      // doesn't silently wipe the selection.
      agentOpts += '<option value="' + esc(curAgentId) + '" selected>(已选: ' + esc(curAgentId) + ' — 列表加载中…)</option>';
    } else if (!agentList) {
      agentOpts += '<option value="" disabled>(列表加载中…)</option>';
    }
    typeFields = ''
      + '<div style="margin-bottom:8px"><label style="font-size:11px;color:var(--text3)">绑定 Agent</label>'
      + '<select data-cfg="agent_id" style="width:100%;padding:6px 8px;border:1px solid var(--border);border-radius:4px;background:var(--bg);color:var(--text);font-size:12px">'
      +   agentOpts
      + '</select>'
      + (hiddenCount > 0 ? '<div style="font-size:10px;color:var(--text3);margin-top:4px;line-height:1.4">已隐藏 ' + hiddenCount + ' 个 agent (已在并行分支使用 — 同 agent 不能在并行分支同时跑)</div>' : '')
      + '</div>'
      + '<div style="margin-bottom:8px"><label style="font-size:11px;color:var(--text3)">提示词 (Prompt)</label>'
      + '<textarea data-cfg="prompt" placeholder="给 agent 的指令" style="width:100%;padding:6px 8px;border:1px solid var(--border);border-radius:4px;background:var(--bg);color:var(--text);font-size:12px;min-height:80px;resize:vertical">' + esc(n.config.prompt || '') + '</textarea></div>'
      + '<div style="display:flex;gap:6px;margin-bottom:8px">'
      + '<div style="flex:1"><label style="font-size:11px;color:var(--text3)">超时(s)</label>'
      + '<input data-cfg="timeout" type="number" value="' + (n.config.timeout || 300) + '" style="width:100%;padding:6px 8px;border:1px solid var(--border);border-radius:4px;background:var(--bg);color:var(--text);font-size:12px"></div>'
      + '<div style="flex:1"><label style="font-size:11px;color:var(--text3)">重试</label>'
      + '<input data-cfg="retry" type="number" value="' + (n.config.retry || 0) + '" min="0" max="5" style="width:100%;padding:6px 8px;border:1px solid var(--border);border-radius:4px;background:var(--bg);color:var(--text);font-size:12px"></div>'
      + '</div>'
      // success_when.file_glob — early-termination signal. When the
      // agent writes a matching file to its node subdir, the canvas
      // aborts the LLM and marks SUCCEEDED. Independent from the
      // deliverable variable, which always = the whole subdir.
      + '<div style="margin-bottom:4px"><label style="font-size:11px;color:var(--text3)">提前结束 — 交付文件名 (可选)</label>'
      + '<input data-cfg="success_when.file_glob" type="text" placeholder="e.g. report_*.md  或  AI热点*.md" value="' + esc(((n.config.success_when || {}).file_glob) || '') + '" style="width:100%;padding:6px 8px;border:1px solid var(--border);border-radius:4px;background:var(--bg);color:var(--text);font-size:12px"></div>'
      + '<div style="font-size:10px;color:var(--text3);line-height:1.4;margin-bottom:8px">填了就：节点子目录里出现匹配文件 → 立刻 abort LLM + 节点 SUCCEEDED（不等 LLM 自报完成）。<br>留空：走标准 LLM-COMPLETED + 兜底 timeout。<br>下游用 <code>{{节点id.deliverable}}</code> 永远拿到子目录路径，不论这里填没填。</div>';
  } else if (n.type === 'decision') {
    typeFields = ''
      + '<div style="margin-bottom:8px"><label style="font-size:11px;color:var(--text3)">Condition expression</label>'
      + '<textarea data-cfg="condition" placeholder="result.success == true / output.length > 0" style="width:100%;padding:6px 8px;border:1px solid var(--border);border-radius:4px;background:var(--bg);color:var(--text);font-size:12px;min-height:60px;resize:vertical">' + esc(n.config.condition || '') + '</textarea></div>'
      + '<div style="font-size:11px;color:var(--text3);line-height:1.5">The outgoing edge label (yes/no) decides which branch to take</div>';
  } else if (n.type === 'parallel') {
    typeFields = '<div style="font-size:12px;color:var(--text3);line-height:1.5">All outgoing edges run in parallel — flow continues only after every branch completes. No config needed.</div>';
  } else if (n.type === 'start' || n.type === 'end') {
    typeFields = '<div style="font-size:12px;color:var(--text3);line-height:1.5">' + esc(nt.label) + ' node — no config needed.</div>';
  }
  // HANDOFF [H] — Available-variables panel. Lists every output key
  // produced by an upstream node, click-to-copy as {{node_id.key}}.
  var upstream = _canvasUpstreamNodes(nid);
  var varsBlock = '';
  if (upstream.length > 0) {
    var varRows = '';
    upstream.forEach(function(uid) {
      var un = _findNode(uid);
      if (!un) return;
      var unt = _NODE_TYPES[un.type] || _NODE_TYPES.agent;
      var keys = _CANVAS_NODE_OUTPUT_KEYS[un.type] || ['output'];
      if (keys.length === 0) return;
      varRows += '<div style="margin-bottom:6px;font-size:11px">'
              +    '<div style="color:var(--text2);margin-bottom:2px"><span style="color:' + unt.color + '">' + unt.icon + '</span> ' + esc(un.label || un.id) + ' <span style="color:var(--text3);font-family:monospace">' + esc(uid) + '</span></div>'
              +    keys.map(function(k) {
                     var ref = '{{' + uid + '.' + k + '}}';
                     return '<button class="btn btn-ghost btn-xs" '
                          + 'onclick="_canvasCopyVar(\'' + ref.replace(/'/g, "\\'") + '\')" '
                          + 'title="点击复制" '
                          + 'style="margin:1px 2px;padding:1px 6px;font-size:10px;font-family:monospace;background:var(--bg);border:1px solid var(--border);border-radius:3px;cursor:pointer">'
                          + esc(ref) + '</button>';
                   }).join('')
              +  '</div>';
    });
    if (varRows) {
      varsBlock = '<div style="margin-top:14px;padding-top:10px;border-top:1px solid var(--border)">'
                + '<div style="font-size:10px;color:var(--text3);margin-bottom:6px;text-transform:uppercase;letter-spacing:0.05em">可用变量(上游节点输出)</div>'
                + varRows
                + '<div style="font-size:10px;color:var(--text3);margin-top:6px;line-height:1.4">在 prompt / 参数里粘贴 <code style="background:var(--bg);padding:0 3px;border-radius:2px">{{node_id.key}}</code> 引用上游输出</div>'
                + '</div>';
    }
  }

  // ── Run-result section (appears at top when this node has run state) ──
  var runResultBlock = _canvasRenderNodeRunResult(nid);

  box.innerHTML =
      '<div style="display:flex;align-items:center;gap:6px;margin-bottom:12px;padding-bottom:10px;border-bottom:1px solid var(--border)">'
    + '  <span style="color:' + nt.color + ';font-size:18px">' + nt.icon + '</span>'
    + '  <div style="font-weight:600;font-size:13px">' + esc(nt.label) + '</div>'
    + '  <span style="margin-left:auto;font-size:10px;color:var(--text3);font-family:monospace">' + esc(n.id) + '</span>'
    + '</div>'
    + runResultBlock
    + '<div style="margin-bottom:8px"><label style="font-size:11px;color:var(--text3)">显示标签</label>'
    + '<input data-cfg="__label" value="' + esc(n.label || '') + '" style="width:100%;padding:6px 8px;border:1px solid var(--border);border-radius:4px;background:var(--bg);color:var(--text);font-size:12px"></div>'
    + typeFields
    + '<div id="canvas-var-lint" style="font-size:11px;color:var(--error);margin-top:6px;line-height:1.5"></div>'
    + '<div style="display:flex;gap:6px;margin-top:14px">'
    + '  <button class="btn btn-sm" style="flex:1" onclick="_canvasApplyConfig()"><span class="material-symbols-outlined" style="font-size:14px">check</span> 应用</button>'
    + '  <button class="btn btn-sm" style="color:var(--error)" onclick="_canvasDeleteSelected()"><span class="material-symbols-outlined" style="font-size:14px">delete</span></button>'
    + '</div>'
    + varsBlock;

  // Wire live linting on the inputs/textareas — re-checks every
  // keystroke. Cheap (regex over a single field's value).
  document.querySelectorAll('#canvas-config-panel [data-cfg]').forEach(function(el) {
    el.addEventListener('input', _canvasLintVarRefs);
  });
  _canvasLintVarRefs();
}

// Per-node run-result block — appears at top of the config panel
// when this node has run state (running / succeeded / failed / skipped).
// Reads from _canvasState._nodeRunStates (current state) + ._currentRunState
// (full per-node started_at / finished_at / errors / vars from state.json).
function _canvasRenderNodeRunResult(nid) {
  var state = (_canvasState._nodeRunStates || {})[nid];
  if (!state) return '';   // node hasn't run / no state
  var rs = _canvasState._currentRunState || {};
  var startedAt = (rs.node_started || {})[nid];
  var finishedAt = (rs.node_finished || {})[nid];
  var nodeErr = (rs.node_errors || {})[nid];
  var dur = (startedAt && finishedAt) ? ((finishedAt - startedAt).toFixed(2) + 's') : null;
  var STATE_LABEL = {
    running: 'Running', succeeded: 'Success', failed: 'Failed', skipped: '跳过', pending: '等待',
  };
  var STATE_KIND = {
    running: 'warning', succeeded: 'success', failed: 'error', skipped: 'neutral', pending: 'neutral',
  };
  var chip = _ui.chip(STATE_LABEL[state] || state, STATE_KIND[state] || 'neutral');

  // Collect vars produced by this node — keys with prefix "{nid}."
  var prefix = nid + '.';
  var vars = rs.vars || {};
  var nodeVars = [];
  Object.keys(vars).forEach(function(k) {
    if (k.indexOf(prefix) === 0) {
      nodeVars.push({key: k.slice(prefix.length), value: vars[k]});
    }
  });

  var rows = '<div style="display:flex;align-items:center;gap:8px;margin-bottom:6px">'
    +   chip
    +   (dur ? '<span style="font-size:11px;color:var(--text3)">' + dur + '</span>' : '')
    + '</div>';

  if (startedAt) {
    rows += '<div style="font-size:10px;color:var(--text3);margin-bottom:2px">开始: '
         + new Date(startedAt * 1000).toLocaleTimeString('zh-CN', {hour12: false}) + '</div>';
  }
  if (finishedAt) {
    rows += '<div style="font-size:10px;color:var(--text3);margin-bottom:6px">完成: '
         + new Date(finishedAt * 1000).toLocaleTimeString('zh-CN', {hour12: false}) + '</div>';
  }

  if (nodeErr) {
    rows += '<div style="margin-top:6px;padding:6px 8px;background:var(--chip-error-bg);color:var(--chip-error-fg);border-radius:6px;font-size:11px;font-family:ui-monospace,SFMono-Regular,Menlo,monospace;word-break:break-word">'
         + esc(nodeErr) + '</div>';
  }

  if (nodeVars.length) {
    rows += '<div style="margin-top:8px"><div style="font-size:10px;color:var(--text3);text-transform:uppercase;letter-spacing:0.4px;margin-bottom:4px">输出变量 (' + nodeVars.length + ')</div>';
    nodeVars.slice(0, 10).forEach(function(v) {
      var vStr;
      if (typeof v.value === 'string') vStr = v.value;
      else { try { vStr = JSON.stringify(v.value); } catch(_) { vStr = String(v.value); } }
      var truncated = (vStr.length > 100) ? (vStr.slice(0, 100) + '…') : vStr;
      rows += '<div style="margin-bottom:4px;padding:5px 7px;background:var(--surface2,rgba(0,0,0,0.04));border-radius:4px;font-size:11px">'
        + '<div style="font-family:ui-monospace,SFMono-Regular,Menlo,monospace;color:var(--primary);font-weight:600">' + esc(v.key) + '</div>'
        + '<div style="font-family:ui-monospace,SFMono-Regular,Menlo,monospace;color:var(--text2);word-break:break-word;margin-top:1px">' + esc(truncated) + '</div>'
        + '</div>';
    });
    if (nodeVars.length > 10) {
      rows += '<div style="font-size:10px;color:var(--text3)">… + ' + (nodeVars.length - 10) + ' more (use {{ ' + esc(nid) + '.* }} substitution)</div>';
    }
    rows += '</div>';
  }

  return '<div style="margin-bottom:14px;padding:10px 12px;background:var(--surface);border:1px solid var(--border);border-radius:8px">'
    + '<div style="font-size:10px;color:var(--text3);text-transform:uppercase;letter-spacing:0.4px;margin-bottom:6px;font-weight:600">运行结果</div>'
    + rows
    + '</div>';
}

// HANDOFF [H] — copy a {{node_id.key}} reference to clipboard.
window._canvasCopyVar = function(ref) {
  try {
    navigator.clipboard.writeText(ref);
    _toast('Copied ' + ref, 'success');
  } catch (e) {
    // Older browsers — fall back to a temporary textarea
    var ta = document.createElement('textarea');
    ta.value = ref;
    document.body.appendChild(ta);
    ta.select();
    try { document.execCommand('copy'); _toast('Copied ' + ref, 'success'); }
    catch (_) { _toast('Copy failed, please select manually', 'error'); }
    document.body.removeChild(ta);
  }
};

// HANDOFF [H] — scan the visible config inputs for {{...}} patterns
// and warn about references to vars that don't exist on any upstream
// node. Catches typos like {{n_drwio.png_path}} (typo of n_drawio).
function _canvasLintVarRefs() {
  var nid = _canvasState.selectedNodeId;
  if (!nid) return;
  var lintBox = document.getElementById('canvas-var-lint');
  if (!lintBox) return;
  var upstream = _canvasUpstreamNodes(nid);
  // Build the set of legal {node_id.key} pairs from upstream node types.
  // Note: tool nodes can produce skill-specific custom keys we can't
  // enumerate, so we only WARN for unknown nodes (not unknown keys
  // on a known node — too noisy).
  var legalNodes = {};
  upstream.forEach(function(uid) {
    legalNodes[uid] = true;
  });
  var issues = [];
  var seen = {};
  document.querySelectorAll('#canvas-config-panel [data-cfg]').forEach(function(el) {
    var val = String(el.value || '');
    var re = /\{\{\s*([A-Za-z0-9_\-]+)\.([A-Za-z0-9_\-]+)\s*\}\}/g;
    var m;
    while ((m = re.exec(val)) !== null) {
      var srcNode = m[1];
      var key = m[2];
      var label = '{{' + srcNode + '.' + key + '}}';
      if (seen[label]) continue;
      seen[label] = true;
      if (!legalNodes[srcNode]) {
        // Special-case helpful message: is the node id known but
        // not upstream? Or genuinely unknown?
        var knownButNotUpstream = (_canvasState.current.nodes || [])
          .some(function(n) { return n.id === srcNode; });
        if (knownButNotUpstream) {
          issues.push(label + ' — 该节点存在但不是 ' + nid + ' 的上游');
        } else {
          issues.push(label + ' — 节点 id "' + srcNode + '" 不存在');
        }
      }
    }
  });
  if (issues.length) {
    lintBox.innerHTML = '<span class="material-symbols-outlined" style="font-size:13px;vertical-align:-2px">warning</span> 变量引用问题:<br>' + issues.map(esc).join('<br>');
  } else {
    lintBox.innerHTML = '';
  }
}

window._canvasApplyConfig = function() {
  var nid = _canvasState.selectedNodeId;
  var n = _findNode(nid);
  if (!n) return;
  document.querySelectorAll('#canvas-config-panel [data-cfg]').forEach(function(el) {
    var key = el.getAttribute('data-cfg');
    var val = el.value;
    if (key === '__label') {
      n.label = val;
      return;
    }
    // Dot-notation = nested dict key (e.g. "success_when.file_glob")
    if (key.indexOf('.') >= 0) {
      var parts = key.split('.');
      // Empty val → delete leaf + prune empty parent so the JSON stays
      // tidy (no `success_when: {}` with no real fields).
      if (val === '' || (typeof val === 'string' && val.trim() === '')) {
        var holder = n.config;
        for (var i = 0; i < parts.length - 1; i++) {
          if (!holder[parts[i]] || typeof holder[parts[i]] !== 'object') return;
          holder = holder[parts[i]];
        }
        delete holder[parts[parts.length - 1]];
        if (parts.length === 2 && Object.keys(n.config[parts[0]] || {}).length === 0) {
          delete n.config[parts[0]];
        }
        return;
      }
      var holder = n.config;
      for (var j = 0; j < parts.length - 1; j++) {
        if (!holder[parts[j]] || typeof holder[parts[j]] !== 'object') {
          holder[parts[j]] = {};
        }
        holder = holder[parts[j]];
      }
      holder[parts[parts.length - 1]] = (el.type === 'number') ? (parseInt(val, 10) || 0) : val;
      return;
    }
    // Try parsing JSON for the args field
    if (key === 'args' && val.trim()) {
      try { n.config[key] = JSON.parse(val); }
      catch (e) { n.config[key] = val; /* keep as string */ }
    } else if (el.type === 'number') {
      n.config[key] = parseInt(val, 10) || 0;
    } else {
      n.config[key] = val;
    }
  });
  _canvasRedrawSvg();
  _toast('Applied (not yet saved to server)', 'info');
};

window._canvasDeleteSelected = function() {
  var nid = _canvasState.selectedNodeId;
  if (!nid) return;
  if (!confirm('删除该节点及其所有连线?')) return;
  _canvasState.current.nodes = _canvasState.current.nodes.filter(function(n) { return n.id !== nid; });
  _canvasState.current.edges = _canvasState.current.edges.filter(function(e) { return e.from !== nid && e.to !== nid; });
  _canvasState.selectedNodeId = null;
  _canvasRedrawSvg();
  _canvasRenderConfigPanel();
};

// ─────────── Keyboard shortcuts ───────────

function _canvasBindKeyboard() {
  if (window._canvasKeyHandler) document.removeEventListener('keydown', window._canvasKeyHandler);
  window._canvasKeyHandler = function(e) {
    // Only act when canvas editor is the visible page
    if (!document.getElementById('canvas-svg')) return;
    var tag = (e.target.tagName || '').toLowerCase();
    if (tag === 'input' || tag === 'textarea') return;
    if ((e.key === 'Delete' || e.key === 'Backspace') && _canvasState.selectedNodeId) {
      e.preventDefault();
      _canvasDeleteSelected();
    }
  };
  document.addEventListener('keydown', window._canvasKeyHandler);
}

// ─────────── Save / export ───────────

window._canvasSave = async function() {
  // Apply current config-panel edits before save
  if (_canvasState.selectedNodeId) _canvasApplyConfig();
  var nameEl = document.getElementById('canvas-name');
  var wf = _canvasState.current;
  wf.name = (nameEl && nameEl.value || wf.name || 'Untitled').trim();
  try {
    var saved = await api('POST', '/api/portal/canvas-workflows', wf);
    _canvasState.current = saved;
    _toast('Saved ✓', 'success');
    // Refresh the visible id label in the toolbar
    _canvasRenderEditor();
  } catch (e) {
    _toast('Save failed:' + e, 'error');
  }
};

window._canvasExportJson = function() {
  var wf = _canvasState.current;
  var json = JSON.stringify(wf, null, 2);
  var blob = new Blob([json], { type: 'application/json' });
  var url = URL.createObjectURL(blob);
  var a = document.createElement('a');
  a.href = url;
  a.download = (wf.name || 'workflow').replace(/[^a-zA-Z0-9_一-龥-]/g, '_') + '.json';
  a.click();
  setTimeout(function() { URL.revokeObjectURL(url); }, 1000);
};


// ─────────── Run-state highlighting (HANDOFF [E]) ───────────
//
// Visual feedback on the canvas during a workflow execution. Per-node
// state classes are applied directly to the SVG shape inside each
// <g data-node-id> via inline style mutation (no external CSS file —
// portal_bundle.js owns its own styling).
//
// State → visual:
//   pending   → grey outline (default — what _canvasRedrawSvg already paints)
//   running   → yellow outline + pulsing animation
//   succeeded → green fill + green outline
//   failed    → red fill + red outline + brief flash
//   skipped   → muted grey + dashed outline (upstream broken)

// Inject the keyframe styles once. Idempotent.
function _canvasEnsureRunStyles() {
  if (document.getElementById('canvas-run-styles')) return;
  var s = document.createElement('style');
  s.id = 'canvas-run-styles';
  s.textContent = ''
    + '@keyframes _cvRunPulse { 0%,100% { opacity: 1 } 50% { opacity: 0.55 } }'
    + '@keyframes _cvFailFlash { 0% { fill-opacity: 0.7 } 50% { fill-opacity: 0.15 } 100% { fill-opacity: 0.5 } }'
    + '.cv-node-running > rect, .cv-node-running > circle, .cv-node-running > path:first-of-type { stroke: #f59e0b !important; stroke-width: 3 !important; fill: #fef3c7 !important; fill-opacity: 0.7 !important; animation: _cvRunPulse 1.4s ease-in-out infinite }'
    + '.cv-node-succeeded > rect, .cv-node-succeeded > circle, .cv-node-succeeded > path:first-of-type { stroke: #16a34a !important; stroke-width: 2.5 !important; fill: #bbf7d0 !important; fill-opacity: 0.5 !important }'
    + '.cv-node-failed > rect, .cv-node-failed > circle, .cv-node-failed > path:first-of-type { stroke: #dc2626 !important; stroke-width: 3 !important; fill: #fecaca !important; fill-opacity: 0.55 !important; animation: _cvFailFlash 0.6s ease-out 2 }'
    + '.cv-node-skipped > rect, .cv-node-skipped > circle, .cv-node-skipped > path:first-of-type { stroke: #94a3b8 !important; stroke-width: 1.5 !important; stroke-dasharray: 4 3 !important; fill-opacity: 0.1 !important }';
  document.head.appendChild(s);
}

// Apply per-node state classes from a runState dict ({nodeId: state, ...}).
// Mutates DOM directly without re-rendering the whole SVG (so user's
// drag position / selection / pending edge are preserved).
function _canvasApplyRunState(stateMap) {
  _canvasEnsureRunStyles();
  // Update the in-memory state dict so SVG redraws (drag, layout
  // refresh, edge add) keep showing the correct badges. This dict is
  // the source of truth; the CSS class on the <g> is just the visual
  // output computed FROM it.
  if (!_canvasState._nodeRunStates) _canvasState._nodeRunStates = {};
  Object.keys(stateMap || {}).forEach(function(nid) {
    var st = String(stateMap[nid] || 'pending');
    if (st === 'pending') {
      delete _canvasState._nodeRunStates[nid];
    } else {
      _canvasState._nodeRunStates[nid] = st;
    }
  });
  var svg = document.getElementById('canvas-svg');
  if (!svg) return;
  Object.keys(stateMap || {}).forEach(function(nid) {
    var g = svg.querySelector('g[data-node-id="' + nid + '"]');
    if (!g) return;
    var st = String(stateMap[nid] || 'pending');
    var cls = (g.getAttribute('class') || '')
      .split(/\s+/)
      .filter(function(c) { return c && c.indexOf('cv-node-') !== 0; });
    if (st !== 'pending') cls.push('cv-node-' + st);
    g.setAttribute('class', cls.join(' '));
    // Re-render the node's badge by replacing the existing badge group
    // (if any). Cheaper than full SVG redraw.
    var oldBadge = g.querySelector(':scope > .cv-node-badge');
    if (oldBadge) oldBadge.remove();
    if (st !== 'pending') {
      var nodeType = (function() {
        var n = _findNode(nid);
        return n ? n.type : 'agent';
      })();
      var nw = _canvasNodeDims({ type: nodeType }).w;
      var badgeStr = _canvasNodeStatusBadge(st, nw);
      if (badgeStr) {
        // SVG innerHTML doesn't accept fragments cleanly cross-browser;
        // use a temporary svg holder + appendChild.
        var tmp = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
        tmp.innerHTML = badgeStr;
        var badgeNode = tmp.firstElementChild;
        if (badgeNode) g.appendChild(badgeNode);
      }
    }
  });
  // If the config panel is open on a node whose state just changed,
  // refresh it so the run-result section reflects the new state.
  if (_canvasState.selectedNodeId && stateMap[_canvasState.selectedNodeId]) {
    _canvasRenderConfigPanel();
  }
}

// Reset all node visual state — called when starting a new run (so a
// previous run's red/green colors don't bleed in).
function _canvasResetRunState() {
  _canvasState._nodeRunStates = {};
  var svg = document.getElementById('canvas-svg');
  if (!svg) return;
  svg.querySelectorAll('g[data-node-id]').forEach(function(g) {
    var cls = (g.getAttribute('class') || '')
      .split(/\s+/)
      .filter(function(c) { return c && c.indexOf('cv-node-') !== 0; });
    g.setAttribute('class', cls.join(' '));
    var badge = g.querySelector(':scope > .cv-node-badge');
    if (badge) badge.remove();
  });
}

// Stop any in-flight EventSource — prevents leaking connections when
// the user navigates away from the editor mid-run.
function _canvasStopRunStream() {
  if (_canvasState._runStream) {
    try { _canvasState._runStream.close(); } catch (_) {}
    _canvasState._runStream = null;
  }
}

// Shared SSE handler — used by both _canvasStartRun (fresh run) and
// _canvasLoadRunLog (reattach to an in-flight run when the editor is
// re-opened). Closes any prior stream on the state object first, so
// repeat calls can't leak a connection.
function _canvasAttachRunStream(wfId, runId) {
  _canvasStopRunStream();
  var url = '/api/portal/canvas-workflows/' + encodeURIComponent(wfId) + '/runs/' + encodeURIComponent(runId) + '/events';
  var es = new EventSource(url);
  _canvasState._runStream = es;
  es.onmessage = function(msg) {
    var evt;
    try { evt = JSON.parse(msg.data); } catch (_) { return; }
    if (evt.type && evt.type !== 'done' && evt.type !== 'timeout') {
      _canvasAppendLogEvent(evt);
    }
    var t = evt.type || '';
    var d = evt.data || {};
    if (t === 'node_started') {
      var m = {}; m[d.node_id] = 'running'; _canvasApplyRunState(m);
    } else if (t === 'node_succeeded') {
      var m = {}; m[d.node_id] = 'succeeded'; _canvasApplyRunState(m);
      _canvasRefreshArtifactsList();
    } else if (t === 'node_failed') {
      var m = {}; m[d.node_id] = 'failed'; _canvasApplyRunState(m);
      _toast('Node failed:' + d.node_id + ' — ' + (d.error || '').slice(0, 80), 'error');
    } else if (t === 'node_skipped') {
      var m = {}; m[d.node_id] = 'skipped'; _canvasApplyRunState(m);
    } else if (t === 'run_succeeded') {
      _canvasSetRunStatus('succeeded', d);
      _toast('✓ 运行成功 (' + (d.duration_s || 0).toFixed(1) + 's)', 'success');
      _canvasStopRunStream();
      _canvasRenderEditor();   // refresh toolbar so 「运行」 re-enables
    } else if (t === 'run_failed') {
      _canvasSetRunStatus('failed', d);
      _toast('✗ 运行失败: ' + (d.error || '(unknown)').slice(0, 100), 'error');
      _canvasStopRunStream();
      _canvasRenderEditor();
    } else if (t === 'run_aborted') {
      _canvasSetRunStatus('aborted', d);
      _toast('◼ Aborted', 'info');
      _canvasStopRunStream();
      _canvasRenderEditor();
    } else if (t === 'done' || t === 'timeout') {
      _canvasStopRunStream();
      _canvasRenderEditor();
    }
  };
  es.onerror = function() {
    if (es.readyState === EventSource.CLOSED) {
      _canvasStopRunStream();
    }
  };
}

window._canvasStartRun = async function() {
  var wf = _canvasState.current;
  if (!wf || !wf.id) { _toast('Save workflow first', 'error'); return; }
  if (String(wf.executable_status || '') !== 'ready') {
    _toast('需要先标为"可执行"', 'error');
    return;
  }
  // Defense in depth: even if the toolbar button got rendered in its
  // enabled state somehow, refuse to fire a 2nd run while the 1st is
  // still going. This is the bug fix for "外面点了一次,进来又点了一次"
  // where two runs were spawned because the editor didn't know about
  // the run started from the overview card.
  var rs = _canvasState._runStatus;
  if (rs && (rs.status === 'running' || rs.status === 'queued')) {
    var ridShort = ((rs.payload || {}).run_id || '').slice(-8);
    if (!confirm('已有 run ' + ridShort + ' 在执行中。确定要并发再启动一次吗？\n（一般不需要 — 通常是上次点击没看到结果，请先等当前 run 完成）')) {
      return;
    }
  }
  _canvasStopRunStream();
  _canvasResetRunState();

  var run;
  try {
    run = await api('POST', '/api/portal/canvas-workflows/' + encodeURIComponent(wf.id) + '/runs', {});
  } catch (e) {
    _toast('Start failed:' + e, 'error');
    return;
  }
  _toast('▶ 运行已启动 (run ' + (run.id || '').slice(-8) + ')', 'info');

  _canvasState._runEvents = [];
  _canvasState._runArtifacts = [];
  _canvasState._nodeRunStates = {};
  _canvasState._currentRunState = null;
  _canvasState._logExpanded = true;
  _canvasRenderEditor();
  _canvasSetRunStatus('running', {run_id: run.id});
  _canvasUpdateArtifactsButton();
  _canvasAppendLogEvent({
    ts: Date.now()/1000,
    type: 'run_created',
    data: {run_id: run.id, workflow_name: wf.name},
  });

  var initial = {};
  (wf.nodes || []).forEach(function(n) { initial[n.id] = 'pending'; });
  _canvasApplyRunState(initial);

  _canvasAttachRunStream(wf.id, run.id);
};


// ============ Skill Categories — admin-curated taxonomy ============
//
// Two dimensions: "scenarios" (business job) and "agent_types" (which
// role typically uses it). Admin CRUD via /api/portal/skill-categories.
// The store filter UI consumes the same dictionary via /skill-store
// (it's bundled into the response to avoid a 2nd round-trip).
//
// Render flow:
//   renderSkillCategoriesAdmin → loadSkillCategoriesAdmin (fetch dict)
//                              → _renderCatColumn (per dimension)
//                              → _showCatEditModal (add / edit one row)

async function renderSkillCategoriesAdmin() {
  var c = document.getElementById('content');
  var _techScA = false;
  try { _techScA = localStorage.getItem('tudou_theme') === 'tech'; } catch (e) {}
  if (_techScA) {
    c.innerHTML = '' +
      '<div style="padding:var(--s-lg)">' +
        '<div style="margin-bottom:var(--s-lg)">' +
          '<div class="tc-mono-label" style="color:var(--primary);display:flex;align-items:center;gap:8px"><span>TAXONOMY ADMIN</span><span style="width:6px;height:6px;border-radius:50%;background:var(--secondary);animation:pulse-dot 2s infinite ease-in-out"></span></div>' +
          '<h2 style="font-family:var(--font-display);font-size:24px;font-weight:600;letter-spacing:-0.01em;color:var(--on-surface);margin:8px 0 6px">Skill Category Management</h2>' +
          '<p class="tc-text-dim" style="font-size:13px;line-height:1.55;max-width:680px">Admin-curated taxonomy for the skill marketplace — Business Scenarios + Agent Types. Edits apply instantly. Deleted categories silently expire on referencing skills; no migration required.</p>' +
        '</div>' +
        '<div id="cat-admin-content" class="tc-text-dim">Loading…</div>' +
      '</div>';
  } else {
    c.innerHTML = ''
      + '<div style="padding:18px">'
      + '  <div style="margin-bottom:14px"><h2 style="margin:0">Skill 分类管理</h2>'
      + '    <div style="font-size:12px;color:var(--text3);margin-top:4px">'
      + '      Admin 管理 skill 商店的两个分类维度。改完后立刻生效,不需要重启服务。'
      + '      已被 skill 引用但被删除的分类会自动失效,无需迁移。</div></div>'
      + '  <div id="cat-admin-content" style="color:var(--text3)">加载中…</div>'
      + '</div>';
  }
  await loadSkillCategoriesAdmin();
}

async function loadSkillCategoriesAdmin() {
  var box = document.getElementById('cat-admin-content');
  if (!box) return;
  try {
    var data = await api('GET', '/api/portal/skill-categories');
    box.innerHTML =
      '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(380px,1fr));gap:16px">'
      + _renderCatColumn('业务场景 (scenarios)', 'scenarios', data.scenarios || [])
      + _renderCatColumn('智能体类型 (agent_types)', 'agent_types', data.agent_types || [])
      + '</div>';
  } catch (e) {
    box.innerHTML = '<div style="color:var(--error);padding:16px">Load failed:' + esc(String(e)) + '</div>';
  }
}

function _renderCatColumn(label, dim, items) {
  var rows = items.map(function(c) {
    return ''
      + '<div style="display:flex;align-items:center;gap:8px;padding:8px 10px;border:1px solid var(--border);border-radius:6px;margin-bottom:6px;background:var(--surface)">'
      + '  <span style="font-size:18px;width:24px;text-align:center">' + esc(c.icon || '·') + '</span>'
      + '  <div style="flex:1;min-width:0">'
      + '    <div style="font-size:13px;font-weight:600;color:var(--text)">' + esc(c.name) + '</div>'
      + '    <div style="font-size:10px;color:var(--text3);font-family:monospace">' + esc(c.id) + '</div>'
      + (c.description ? '    <div style="font-size:11px;color:var(--text2);margin-top:2px">' + esc(c.description) + '</div>' : '')
      + '  </div>'
      + '  <span style="font-size:10px;color:var(--text3);min-width:30px;text-align:right">#' + (c.order || 0) + '</span>'
      + '  <button class="btn btn-ghost btn-sm" onclick="_showCatEditModal(\'' + dim + '\',' + JSON.stringify(c).replace(/'/g, "&#39;").replace(/"/g, '&quot;') + ')" title="编辑"><span class="material-symbols-outlined" style="font-size:16px">edit</span></button>'
      + '  <button class="btn btn-ghost btn-sm" onclick="_deleteCat(\'' + dim + '\',\'' + esc(c.id) + '\',\'' + esc(c.name) + '\')" title="删除" style="color:var(--error)"><span class="material-symbols-outlined" style="font-size:16px">delete</span></button>'
      + '</div>';
  }).join('');
  return ''
    + '<div style="padding:14px;border:1px solid var(--border);border-radius:8px;background:var(--bg)">'
    + '  <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px">'
    + '    <div style="font-size:14px;font-weight:700">' + esc(label) + '<span style="margin-left:6px;font-size:11px;color:var(--text3);font-weight:400">· ' + items.length + ' 项</span></div>'
    + '    <button class="btn btn-sm btn-primary" onclick="_showCatEditModal(\'' + dim + '\', null)"><span class="material-symbols-outlined" style="font-size:14px">add</span> 新增</button>'
    + '  </div>'
    + (items.length ? rows : '<div style="font-size:12px;color:var(--text3);text-align:center;padding:20px;border:1px dashed var(--border);border-radius:6px">暂无分类,点击"新增"添加第一个</div>')
    + '</div>';
}

window._showCatEditModal = function(dim, existing) {
  var isEdit = !!existing;
  var c = existing || { id: '', name: '', icon: '', order: 99, description: '' };
  var html = ''
    + '<div style="background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:24px;width:480px;max-width:95vw">'
    + '  <h3 style="margin:0 0 16px 0">' + (isEdit ? '编辑分类' : '新增分类') + ' · ' + esc(dim === 'scenarios' ? '业务场景' : 'Agent Type') + '</h3>'
    + '  <div style="display:flex;flex-direction:column;gap:10px">'
    + '    <div><label style="font-size:11px;color:var(--text3)">ID (slug, 仅小写字母/数字/-)</label>'
    + '      <input id="cat-edit-id" value="' + esc(c.id) + '" ' + (isEdit ? 'disabled' : '') + ' placeholder="legal, design-pro, ..." style="width:100%;padding:8px 10px;border:1px solid var(--border);border-radius:6px;background:var(--bg);color:var(--text);font-family:monospace;font-size:12px"></div>'
    + '    <div><label style="font-size:11px;color:var(--text3)">显示名 *</label>'
    + '      <input id="cat-edit-name" value="' + esc(c.name) + '" placeholder="法务合规" style="width:100%;padding:8px 10px;border:1px solid var(--border);border-radius:6px;background:var(--bg);color:var(--text)"></div>'
    + '    <div style="display:flex;gap:10px">'
    + '      <div style="flex:1"><label style="font-size:11px;color:var(--text3)">图标 (1 个 emoji)</label>'
    + '        <input id="cat-edit-icon" value="' + esc(c.icon) + '" placeholder="⚖️" maxlength="4" style="width:100%;padding:8px 10px;border:1px solid var(--border);border-radius:6px;background:var(--bg);color:var(--text);text-align:center;font-size:18px"></div>'
    + '      <div style="flex:1"><label style="font-size:11px;color:var(--text3)">排序 (越小越靠前)</label>'
    + '        <input id="cat-edit-order" type="number" value="' + (c.order || 99) + '" min="0" style="width:100%;padding:8px 10px;border:1px solid var(--border);border-radius:6px;background:var(--bg);color:var(--text)"></div>'
    + '    </div>'
    + '    <div><label style="font-size:11px;color:var(--text3)">说明 (选填)</label>'
    + '      <textarea id="cat-edit-desc" placeholder="什么时候用这个分类" style="width:100%;padding:8px 10px;border:1px solid var(--border);border-radius:6px;background:var(--bg);color:var(--text);min-height:60px;resize:vertical">' + esc(c.description) + '</textarea></div>'
    + '  </div>'
    + '  <div style="display:flex;justify-content:flex-end;gap:8px;margin-top:18px">'
    + '    <button class="btn btn-ghost btn-sm" onclick="closeModal()">Cancel</button>'
    + '    <button class="btn btn-primary btn-sm" onclick="_saveCatEdit(\'' + dim + '\')">保存</button>'
    + '  </div>'
    + '</div>';
  showCustomModal(html);
};

window._saveCatEdit = async function(dim) {
  var idEl = document.getElementById('cat-edit-id');
  var body = {
    dimension: dim,
    id:    (idEl.value || '').trim().toLowerCase().replace(/[^a-z0-9_-]/g, '-'),
    name:  (document.getElementById('cat-edit-name').value || '').trim(),
    icon:  (document.getElementById('cat-edit-icon').value || '').trim(),
    order: parseInt(document.getElementById('cat-edit-order').value || '99', 10),
    description: (document.getElementById('cat-edit-desc').value || '').trim(),
  };
  if (!body.id) return _toast('ID cannot be empty', 'error');
  if (!body.name) return _toast('Display name cannot be empty', 'error');
  try {
    await api('POST', '/api/portal/skill-categories', body);
    closeModal();
    _toast('Saved', 'success');
    await loadSkillCategoriesAdmin();
  } catch (e) {
    _toast('Save failed:' + e, 'error');
  }
};

// Open the per-skill category assignment modal. Uses the cached
// categoriesPayload from the last /skill-store call so it's instant; if
// for some reason the cache is empty, lazy-load the dictionary first.
window._openSkillCategoryAssignModal = async function(skillId, skillName) {
  var dict = _skillStoreState.categoriesPayload;
  if (!dict || (!dict.scenarios && !dict.agent_types)) {
    try { dict = await api('GET', '/api/portal/skill-categories'); }
    catch (e) { return _toast('Load category dictionary failed:' + e, 'error'); }
  }
  var current;
  try {
    current = await api('GET', '/api/portal/skill-pkgs/' + encodeURIComponent(skillId) + '/categories');
  } catch (e) { current = { scenarios: [], agent_types: [] }; }
  var sel = { scenarios: new Set(current.scenarios || []),
              agent_types: new Set(current.agent_types || []) };

  function chips(dim) {
    var items = dict[dim] || [];
    if (!items.length) return '<div style="font-size:11px;color:var(--text3);padding:6px">尚无分类,请先去"分类管理"创建</div>';
    return items.map(function(c) {
      var on = sel[dim].has(c.id);
      return '<span data-dim="' + dim + '" data-id="' + esc(c.id) + '" '
        + 'style="padding:4px 10px;font-size:12px;border-radius:14px;cursor:pointer;border:1px solid ' + (on ? 'var(--primary)' : 'var(--border)') + ';background:' + (on ? 'var(--primary)' : 'var(--surface3)') + ';color:' + (on ? '#fff' : 'var(--text2)') + '">'
        + (c.icon ? esc(c.icon) + ' ' : '') + esc(c.name) + '</span>';
    }).join('');
  }
  var html = ''
    + '<div style="background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:24px;width:560px;max-width:95vw;max-height:80vh;overflow:auto">'
    + '  <h3 style="margin:0 0 6px 0">管理分类</h3>'
    + '  <div style="font-size:12px;color:var(--text3);margin-bottom:14px">' + esc(skillName) + ' · ' + esc(skillId) + '</div>'
    + '  <div style="margin-bottom:14px">'
    + '    <div style="font-size:11px;color:var(--text3);margin-bottom:6px">业务场景 (scenarios)</div>'
    + '    <div id="assign-sc-chips" style="display:flex;flex-wrap:wrap;gap:6px">' + chips('scenarios') + '</div>'
    + '  </div>'
    + '  <div style="margin-bottom:14px">'
    + '    <div style="font-size:11px;color:var(--text3);margin-bottom:6px">Agent 类型 (agent_types)</div>'
    + '    <div id="assign-at-chips" style="display:flex;flex-wrap:wrap;gap:6px">' + chips('agent_types') + '</div>'
    + '  </div>'
    + '  <div style="display:flex;justify-content:flex-end;gap:8px">'
    + '    <button class="btn btn-ghost btn-sm" onclick="closeModal()">Cancel</button>'
    + '    <button class="btn btn-primary btn-sm" onclick="_saveSkillAssignments(\'' + esc(skillId) + '\')">保存</button>'
    + '  </div>'
    + '</div>';
  showCustomModal(html);

  // Wire up toggle behaviour. Click any chip to flip its selected state.
  // Restyle in place so users see the toggle without a re-render.
  document.querySelectorAll('#custom-modal-overlay span[data-dim]').forEach(function(span) {
    span.onclick = function() {
      var dim = span.getAttribute('data-dim');
      var cid = span.getAttribute('data-id');
      if (sel[dim].has(cid)) sel[dim].delete(cid); else sel[dim].add(cid);
      var on = sel[dim].has(cid);
      span.style.borderColor = on ? 'var(--primary)' : 'var(--border)';
      span.style.background  = on ? 'var(--primary)' : 'var(--surface3)';
      span.style.color       = on ? '#fff' : 'var(--text2)';
    };
  });

  // Stash sel onto window so the save button can read the latest state.
  window._currentSkillAssignSel = sel;
};

window._saveSkillAssignments = async function(skillId) {
  var sel = window._currentSkillAssignSel || { scenarios: new Set(), agent_types: new Set() };
  try {
    await api('PUT', '/api/portal/skill-pkgs/' + encodeURIComponent(skillId) + '/categories', {
      scenarios: Array.from(sel.scenarios),
      agent_types: Array.from(sel.agent_types),
    });
    closeModal();
    _toast('Saved', 'success');
    // Refresh the store list so badges update
    if (typeof loadSkillStore === 'function') loadSkillStore();
  } catch (e) {
    _toast('Save failed:' + e, 'error');
  }
};

window._deleteCat = async function(dim, catId, name) {
  if (!confirm('删除分类 "' + name + '" (id=' + catId + ')?\n\n已经引用这个分类的 skill 会自动失去这个标签 (无需迁移)。')) return;
  try {
    await api('DELETE', '/api/portal/skill-categories/' + encodeURIComponent(dim) + '/' + encodeURIComponent(catId));
    _toast('Deleted', 'success');
    await loadSkillCategoriesAdmin();
  } catch (e) {
    _toast('Delete failed:' + e, 'error');
  }
};

// Helper: minimal centered modal wrapper if portal doesn't already have one.
// Reuses .modal-overlay styles if present; falls back to inline styling.
window.showCustomModal = window.showCustomModal || function(innerHtml) {
  var existing = document.getElementById('custom-modal-overlay');
  if (existing) existing.remove();
  var ov = document.createElement('div');
  ov.id = 'custom-modal-overlay';
  ov.style.cssText = 'position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,0.5);z-index:9999;display:flex;align-items:center;justify-content:center';
  ov.onclick = function(e) { if (e.target === ov) closeModal(); };
  ov.innerHTML = innerHtml;
  document.body.appendChild(ov);
};
window.closeModal = window.closeModal || function() {
  var m = document.getElementById('custom-modal-overlay');
  if (m) m.remove();
};


// ============ Skill Store (Hub-level marketplace) ============
var _skillStoreState = { q: '', source: '', tag: '', entries: [], stats: null, allTags: [],
                         scenarios: [], agentTypes: [],
                         categoriesPayload: null, assignments: {} };

function _fmtSize(bytes) {
  if (!bytes) return '';
  if (bytes < 1024) return bytes + ' B';
  if (bytes < 1048576) return (bytes/1024).toFixed(1) + ' KB';
  return (bytes/1048576).toFixed(1) + ' MB';
}

async function renderSkillStore() {
  var c = document.getElementById('content');
  var _techSs = false;
  try { _techSs = localStorage.getItem('tudou_theme') === 'tech'; } catch (e) {}

  if (_techSs) {
    // Stitch_27 layout: large hero glass-panel with subtle data-flow
    // backdrop, inline action buttons (replaces "Quick Deploy / How It
    // Works" with our actual import flows). No category/tag filter
    // rows above the cards — those structured filters and the auto-
    // extracted tag list pollute chrome with low-signal chips. Search
    // + source select + sort sit in a compact row below the hero.
    c.innerHTML = '' +
      '<div style="padding:var(--s-lg);display:flex;flex-direction:column;gap:var(--s-lg)">' +
        // ── Hero ──
        '<section class="tc-card-glass" style="position:relative;overflow:hidden;padding:var(--s-xl);display:flex;flex-direction:column;gap:18px;border-top:1px solid rgba(255,255,255,0.10);min-height:240px">' +
          // Subtle decorative gradient on the right (data-flow vibe)
          '<div style="position:absolute;top:0;right:0;width:55%;height:100%;background:radial-gradient(ellipse at top right,rgba(137,206,255,0.10),transparent 60%),radial-gradient(ellipse at bottom right,rgba(192,193,255,0.08),transparent 55%);pointer-events:none"></div>' +
          '<div style="position:absolute;inset:0;background-image:linear-gradient(rgba(192,193,255,0.025) 1px,transparent 1px),linear-gradient(90deg,rgba(192,193,255,0.025) 1px,transparent 1px);background-size:24px 24px;pointer-events:none"></div>' +
          '<div style="position:relative;z-index:1;max-width:680px;display:flex;flex-direction:column;gap:14px">' +
            '<div class="tc-mono-label" style="color:var(--primary);display:flex;align-items:center;gap:8px">' +
              '<span>AETHER ECOSYSTEM</span>' +
              '<span style="width:6px;height:6px;border-radius:50%;background:var(--secondary);animation:pulse-dot 2s infinite ease-in-out"></span>' +
            '</div>' +
            '<h1 style="font-family:var(--font-display);font-size:36px;font-weight:600;letter-spacing:-0.02em;color:var(--on-surface);margin:0;line-height:1.1">Skill Marketplace</h1>' +
            '<p class="tc-text-dim" style="font-size:14px;line-height:1.6;margin:0">Empower your agents with advanced processing capabilities — Anthropic Agent Skills (SKILL.md) + TudouClaw manifest.yaml. Browse by trust tier, install, grant to agents.</p>' +
            '<div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:6px">' +
              '<button onclick="_showLocalImportModal()" style="background:var(--primary-fixed);color:var(--on-primary-fixed);padding:10px 20px;border-radius:var(--r-md);font-family:var(--font-mono);font-size:11px;letter-spacing:0.05em;text-transform:uppercase;font-weight:600;border:none;cursor:pointer;display:inline-flex;align-items:center;gap:8px;box-shadow:0 4px 14px rgba(192,193,255,0.20);transition:all 0.15s" onmouseover="this.style.filter=\'brightness(1.08)\'" onmouseout="this.style.filter=\'\'"><span class="material-symbols-outlined" style="font-size:16px">folder_open</span> Import Local</button>' +
              '<button onclick="_showRemoteScanModal()" style="background:rgba(255,255,255,0.04);color:var(--on-surface);padding:10px 20px;border-radius:var(--r-md);font-family:var(--font-mono);font-size:11px;letter-spacing:0.05em;text-transform:uppercase;font-weight:600;border:1px solid rgba(255,255,255,0.10);cursor:pointer;display:inline-flex;align-items:center;gap:8px;transition:all 0.15s" onmouseover="this.style.borderColor=\'rgba(192,193,255,0.30)\';this.style.background=\'rgba(255,255,255,0.06)\'" onmouseout="this.style.borderColor=\'rgba(255,255,255,0.10)\';this.style.background=\'rgba(255,255,255,0.04)\'"><span class="material-symbols-outlined" style="font-size:16px">cloud_download</span> Import URL</button>' +
              '<button onclick="rescanSkillStore()" style="background:rgba(255,255,255,0.04);color:var(--on-surface);padding:10px 20px;border-radius:var(--r-md);font-family:var(--font-mono);font-size:11px;letter-spacing:0.05em;text-transform:uppercase;font-weight:600;border:1px solid rgba(255,255,255,0.10);cursor:pointer;display:inline-flex;align-items:center;gap:8px;transition:all 0.15s" onmouseover="this.style.borderColor=\'rgba(192,193,255,0.30)\';this.style.background=\'rgba(255,255,255,0.06)\'" onmouseout="this.style.borderColor=\'rgba(255,255,255,0.10)\';this.style.background=\'rgba(255,255,255,0.04)\'"><span class="material-symbols-outlined" style="font-size:16px">refresh</span> Rescan</button>' +
            '</div>' +
          '</div>' +
        '</section>' +
        // ── Compact filter row: search + source ──
        '<div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center">' +
          '<input id="store-q" placeholder="Search name / description / tag…" style="flex:1;min-width:280px;padding:10px 14px;background:var(--surface-container-low);border:1px solid var(--outline-variant);border-radius:var(--r-md);color:var(--on-surface);font-size:13px;outline:none" oninput="_skillStoreState.q=this.value;_debouncedLoadStore()">' +
          '<select id="store-source" onchange="_skillStoreState.source=this.value;loadSkillStore()" style="padding:10px 14px;background:var(--surface-container-low);border:1px solid var(--outline-variant);border-radius:var(--r-md);color:var(--on-surface);font-size:13px;font-family:var(--font-mono);cursor:pointer">' +
            '<option value="">All sources</option>' +
            '<option value="official">Official</option>' +
            '<option value="maintainer">Maintainer</option>' +
            '<option value="community">Community</option>' +
            '<option value="agent">Agent-Authored</option>' +
            '<option value="local">Local</option>' +
          '</select>' +
        '</div>' +
        // Hidden category-filter / tag-filter slots — kept for handler
        // compatibility (they reference these IDs) but never visible
        // since structured/tag filtering is applied programmatically.
        '<div id="store-cat-filters" style="display:none"></div>' +
        '<div id="store-tag-filters" style="display:flex;flex-wrap:wrap;gap:6px"></div>' +
        '<div id="store-stats" class="tc-mono-label" style="color:var(--outline);font-size:10px;letter-spacing:0.05em"></div>' +
        '<div id="store-list" class="tc-text-dim">LOADING…</div>' +
      '</div>';
  } else {
    var ssHeader = '    <div><h2 style="margin:0">技能商店 / Skill Store</h2>' +
      '      <div style="font-size:12px;color:var(--text3);margin-top:4px">兼容 Anthropic Agent Skills 规范 (SKILL.md) 与 TudouClaw manifest.yaml。按信任分级浏览、安装、授权给 agent。</div>' +
      '    </div>';
    c.innerHTML = ''
      + '<div style="padding:18px">'
      + '  <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:14px;gap:12px">'
      + ssHeader
      + '    <div style="display:flex;gap:8px">'
      + '    <button class="btn btn-sm" onclick="_showLocalImportModal()"><span class="material-symbols-outlined" style="font-size:16px;vertical-align:middle">folder_open</span> 从本地导入</button>'
      + '    <button class="btn btn-sm" onclick="_showRemoteScanModal()"><span class="material-symbols-outlined" style="font-size:16px;vertical-align:middle">cloud_download</span> 从 URL 导入</button>'
      + '    <button class="btn btn-sm" onclick="rescanSkillStore()"><span class="material-symbols-outlined" style="font-size:16px;vertical-align:middle">refresh</span> Rescan</button>'
      + '    </div>'
      + '  </div>'
      + '  <div style="display:flex;gap:10px;margin-bottom:12px;flex-wrap:wrap">'
      + '    <input id="store-q" placeholder="搜索名称/描述/标签…" style="flex:1;min-width:260px;padding:8px 10px;border:1px solid var(--border);border-radius:6px;background:var(--bg);color:var(--text)" oninput="_skillStoreState.q=this.value;_debouncedLoadStore()">'
      + '    <select id="store-source" onchange="_skillStoreState.source=this.value;loadSkillStore()" style="padding:8px 10px;border:1px solid var(--border);border-radius:6px;background:var(--bg);color:var(--text)">'
      + '      <option value="">所有来源</option>'
      + '      <option value="official">official 官方</option>'
      + '      <option value="maintainer">maintainer 维护</option>'
      + '      <option value="community">community 社区</option>'
      + '      <option value="agent">agent Agent创建</option>'
      + '      <option value="local">local 本地</option>'
      + '    </select>'
      + '  </div>'
      + '  <div id="store-cat-filters" style="margin-bottom:10px"></div>'
      + '  <div id="store-tag-filters" style="display:flex;flex-wrap:wrap;gap:6px;margin-bottom:10px"></div>'
      + '  <div id="store-stats" style="font-size:11px;color:var(--text3);margin-bottom:10px"></div>'
      + '  <div id="store-list" style="color:var(--text3)">加载中…</div>'
      + '</div>';
  }
  loadSkillStore();
}

// Click a tag chip (on card or in filter bar) → toggle the filter.
window._skillStoreFilterByTag = function(tag) {
  var t = (tag || '').trim();
  if (!t) return;
  // Toggle: if already active, clear; else set.
  if ((_skillStoreState.tag || '').toLowerCase() === t.toLowerCase()) {
    _skillStoreState.tag = '';
  } else {
    _skillStoreState.tag = t;
  }
  loadSkillStore();
};

// Render the tag filter bar at the top of the store. Shows the most-used
// tags (top 30) so users can browse by category without typing search terms.
// Active tag gets a highlight; clicking again clears the filter.
function _renderTagFilterBar() {
  var bar = document.getElementById('store-tag-filters');
  if (!bar) return;
  // The two-row category filter (业务场景 + Agent 类型) above already
  // covers structured browsing. The auto-extracted tag list pollutes
  // the chrome with low-signal "·1" chips (e.g. "发邮件·1" /
  // "send email·1" / "email·1" being 3 names for the same concept).
  // Show ONLY when an active tag is filtering — as a status pill so
  // the user can clear it. Otherwise leave empty.
  var active = (_skillStoreState.tag || '').toLowerCase();
  if (!active) {
    bar.innerHTML = '';
    return;
  }
  bar.innerHTML = '<span style="padding:3px 10px;font-size:11px;border-radius:12px;background:var(--primary);color:#fff;cursor:pointer;border:1px solid var(--primary)" onclick="_skillStoreState.tag=\'\';loadSkillStore()" title="Clear tag filter">✕ Tag: ' + esc(active) + '</span>';
}

// ─────────── Skill category dual-dimension filter ───────────
// Two extra rows of chips (one per dimension) above the tag filter row.
// Multi-select within a dimension; dimensions combined with AND.
// State lives on _skillStoreState.scenarios / .agentTypes (csv arrays).
window._skillStoreFilterByCategory = function(dim, catId) {
  if (!dim || !catId) return;
  var key = (dim === 'scenarios') ? 'scenarios' : 'agentTypes';
  var cur = _skillStoreState[key] || [];
  var idx = cur.indexOf(catId);
  if (idx >= 0) cur.splice(idx, 1); else cur.push(catId);
  _skillStoreState[key] = cur;
  loadSkillStore();
};
function _renderCategoryFilterBars() {
  var bar = document.getElementById('store-cat-filters');
  if (!bar) return;
  // Tech mode: structured filtering happens via the hero search +
  // source select. Skip rendering the category chip rows (they're
  // hidden via display:none anyway, but no point computing).
  try {
    if (localStorage.getItem('tudou_theme') === 'tech') { bar.innerHTML = ''; return; }
  } catch (e) {}
  var cats = _skillStoreState.categoriesPayload || { scenarios: [], agent_types: [] };
  if ((cats.scenarios || []).length === 0 && (cats.agent_types || []).length === 0) {
    bar.innerHTML = ''; return;
  }
  function row(label, dim, items, active) {
    if (!items.length) return '';
    var chips = items.map(function(c) {
      var isOn = active.indexOf(c.id) >= 0;
      var st = isOn
        ? 'padding:3px 10px;font-size:11px;border-radius:12px;background:var(--primary);color:#fff;cursor:pointer;border:1px solid var(--primary)'
        : 'padding:3px 10px;font-size:11px;border-radius:12px;background:var(--surface3);color:var(--text2);cursor:pointer;border:1px solid var(--border)';
      return '<span style="' + st + '" onclick="_skillStoreFilterByCategory(\'' + dim + '\',\'' + esc(c.id) + '\')">'
              + (c.icon ? esc(c.icon) + ' ' : '') + esc(c.name) + '</span>';
    }).join('');
    var clearBtn = active.length
      ? '<span style="padding:3px 10px;font-size:11px;border-radius:12px;background:var(--surface3);color:var(--text3);cursor:pointer;border:1px solid var(--border)" onclick="_skillStoreState.' + (dim === 'scenarios' ? 'scenarios' : 'agentTypes') + '=[];loadSkillStore()" title="清除">✕</span>'
      : '';
    return '<div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin-bottom:6px">'
         + '<span style="font-size:11px;color:var(--text3);min-width:70px">' + label + '</span>'
         + chips + clearBtn + '</div>';
  }
  bar.innerHTML =
    row('业务场景', 'scenarios',  cats.scenarios   || [], _skillStoreState.scenarios   || []) +
    row('Agent Type', 'agent_types', cats.agent_types || [], _skillStoreState.agentTypes || []);
}

var _storeLoadTimer = null;
function _debouncedLoadStore() {
  if (_storeLoadTimer) clearTimeout(_storeLoadTimer);
  _storeLoadTimer = setTimeout(loadSkillStore, 250);
}

async function loadSkillStore() {
  var box = document.getElementById('store-list');
  if (!box) return;
  var params = [];
  if (_skillStoreState.q) params.push('q=' + encodeURIComponent(_skillStoreState.q));
  if (_skillStoreState.source) params.push('source=' + encodeURIComponent(_skillStoreState.source));
  if (_skillStoreState.tag) params.push('tag=' + encodeURIComponent(_skillStoreState.tag));
  // Two new dimensions — server accepts CSV
  if ((_skillStoreState.scenarios   || []).length) params.push('scenario='   + encodeURIComponent(_skillStoreState.scenarios.join(',')));
  if ((_skillStoreState.agentTypes  || []).length) params.push('agent_type=' + encodeURIComponent(_skillStoreState.agentTypes.join(',')));
  var qs = params.length ? ('?' + params.join('&')) : '';
  // Issue an UNFILTERED fetch in parallel (cheap — same handler) so we can
  // build the tag filter bar from ALL skills, not just the ones matching
  // the current filter (otherwise picking a tag would empty the bar).
  var unfilteredPromise = (_skillStoreState.q || _skillStoreState.source || _skillStoreState.tag)
    ? api('GET', '/api/portal/skill-store').catch(function(){ return null; })
    : null;
  try {
    var data = await api('GET', '/api/portal/skill-store' + qs);
    _skillStoreState.entries = data.entries || [];
    _skillStoreState.stats = data.stats || null;
    // Cache category dictionary + per-skill assignments for badge rendering
    _skillStoreState.categoriesPayload = data.categories || { scenarios: [], agent_types: [] };
    _skillStoreState.assignments = data.assignments || {};
    _renderCategoryFilterBars();
    // Aggregate tag counts from the unfiltered set (when filtered) or
    // current entries (when no filter active).
    var tagSource = data.entries || [];
    if (unfilteredPromise) {
      try {
        var allData = await unfilteredPromise;
        if (allData && allData.entries) tagSource = allData.entries;
      } catch (e) {}
    }
    var tagCounts = {};
    tagSource.forEach(function(e){
      (e.tags || []).forEach(function(t){
        var tl = String(t).trim();
        if (!tl) return;
        tagCounts[tl] = (tagCounts[tl] || 0) + 1;
      });
    });
    var allTags = Object.keys(tagCounts).map(function(t){ return {tag:t, count:tagCounts[t]}; });
    allTags.sort(function(a,b){ return b.count - a.count || a.tag.localeCompare(b.tag); });
    _skillStoreState.allTags = allTags;
    _renderTagFilterBar();
    var annMap = {};
    (data.annotations || []).forEach(function(a){ annMap[a.skill_id] = a; });
    var installedMap = data.installed || {};
    var s = data.stats || {};
    var stats = document.getElementById('store-stats');
    if (stats) {
      var by = s.by_source || {};
      var _techStats = false;
      try { _techStats = localStorage.getItem('tudou_theme') === 'tech'; } catch (e) {}
      if (_techStats) {
        // Compact mono-label stats line, no per-source pills (those just
        // duplicate the source dropdown filter below the hero).
        stats.innerHTML = (s.total||0) + ' SKILLS · ' + (s.installed||0) + ' INSTALLED';
      } else {
        var pill = function(k,v){ return '<span style="padding:2px 8px;border:1px solid var(--border);border-radius:10px;margin-right:6px">'+esc(k)+': '+v+'</span>'; };
        stats.innerHTML = '共 ' + (s.total||0) + ' 个 · 已安装 ' + (s.installed||0) + ' · '
          + Object.keys(by).map(function(k){ return pill(k, by[k]); }).join('');
      }
    }
    if (!_skillStoreState.entries.length) {
      box.innerHTML = '<div style="padding:20px;text-align:center">目录为空。把 SKILL.md 或 manifest.yaml 放到 data/skill_catalog/ 下再点"重新扫描"。</div>';
      return;
    }
    // ── Category inference (tag-based heuristic) ──
    // 每个 skill 落到一个类目；豆腐块按类目分段渲染
    function _skillCategory(e) {
      var bt = (e.metadata && e.metadata.bundle_type) || '';
      var tags = (e.tags || []).map(function(t){return String(t).toLowerCase();}).join(' ');
      var name = (e.name || '').toLowerCase();
      var all = tags + ' ' + name;
      if (bt === 'capability' || /tool-?bundle/.test(tags)) return {key:'bundle', label:'🧰 工具包 Tool Bundles', order:0};
      if (/ppt|pptx|doc|docx|excel|xlsx|office|word/.test(all)) return {key:'office', label:'📊 办公文档 Office', order:1};
      if (/web|http|browser|search|crawl|scrape/.test(all)) return {key:'web', label:'🌐 网络 Web', order:2};
      if (/memory|knowledge|rag|l3|embed/.test(all)) return {key:'memory', label:'🧠 记忆 Memory', order:3};
      if (/data|finance|stock|akshare|baostock|chart|plot|csv|json/.test(all)) return {key:'data', label:'📈 数据分析 Data', order:4};
      if (/image|screenshot|audio|video|voice|tts|ocr|media/.test(all)) return {key:'media', label:'🖼️ 多媒体 Media', order:5};
      if (/message|chat|notify|email|sms|slack/.test(all)) return {key:'msg', label:'💬 消息通讯 Messaging', order:6};
      if (/schedule|cron|time|timer/.test(all)) return {key:'sched', label:'⏰ 调度 Scheduling', order:7};
      if (/mcp|integration|connector|api/.test(all)) return {key:'integ', label:'🔌 集成 Integration', order:8};
      if (/code|coding|lint|test|debug|compile/.test(all)) return {key:'code', label:'💻 编码 Coding', order:9};
      return {key:'other', label:'🎨 其他 Other', order:99};
    }
    // Group entries by inferred category
    var groups = {};      // key -> {label, order, entries:[]}
    _skillStoreState.entries.forEach(function(e){
      var c = _skillCategory(e);
      if (!groups[c.key]) groups[c.key] = {label:c.label, order:c.order, entries:[]};
      groups[c.key].entries.push(e);
    });
    // Sort categories by defined order
    var orderedKeys = Object.keys(groups).sort(function(a,b){return groups[a].order - groups[b].order;});
    var _techCard = false;
    try { _techCard = localStorage.getItem('tudou_theme') === 'tech'; } catch (e) {}

    // 豆腐块 grid — responsive, 3-4 per row depending on viewport
    function _renderCard(e){
      var srcColor = e.source === 'official' ? '#10b981'
                   : e.source === 'maintainer' ? '#a78bfa'
                   : e.source === 'community' ? '#60a5fa'
                   : e.source === 'agent' ? '#f59e0b' : '#94a3b8';
      var ann = annMap[e.id] || annMap[e.installed_id];
      var annBadge = (ann && ann.notes && ann.notes.length)
        ? '<span title="Local notes" style="padding:1px 5px;font-size:10px;background:rgba(251,191,36,0.15);color:#f59e0b;border-radius:8px;margin-left:4px">💡'+ann.notes.length+'</span>'
        : '';
      // Special-case: pptx-author skill gets a theme gallery shortcut.
      var pptxThemeBtn = '';
      if (e.name === 'pptx-author' || e.id === 'pptx-author') {
        pptxThemeBtn = '<button class="btn btn-sm" title="Browse 10 PPT theme previews" onclick="event.stopPropagation();openPptxThemeGallery()">🎨</button>';
      }
      // Lifecycle actions
      var disabled = !!(e.metadata && e.metadata.disabled);
      var actions = '';
      if (_techCard) {
        // Tech action row — mono-label minimal pills, primary for the
        // main action (install / grant), ghost for secondary, error
        // tint for delete.
        var techBtn = function(label, icon, onclick, opts) {
          opts = opts || {};
          var bg = opts.primary ? 'var(--primary-fixed)'
                  : opts.danger ? 'rgba(255,180,171,0.06)'
                  : 'rgba(255,255,255,0.04)';
          var color = opts.primary ? 'var(--on-primary-fixed)'
                    : opts.danger ? 'var(--error)'
                    : 'var(--on-surface)';
          var border = opts.primary ? 'none'
                     : opts.danger ? '1px solid rgba(255,180,171,0.20)'
                     : '1px solid rgba(255,255,255,0.08)';
          var hoverBg = opts.primary ? '' : (opts.danger ? 'rgba(255,180,171,0.14)' : 'rgba(255,255,255,0.08)');
          var hoverOver = opts.primary
            ? "this.style.filter='brightness(1.08)'"
            : "this.style.background='" + hoverBg + "'";
          var hoverOut = opts.primary
            ? "this.style.filter=''"
            : "this.style.background='" + bg + "'";
          var styleStr = 'flex:' + (opts.flex || 'none') + ';padding:7px ' + (opts.iconOnly ? '8' : '12') + 'px;background:' + bg + ';color:' + color + ';border:' + border + ';border-radius:var(--r-md);font-family:var(--font-mono);font-size:10px;letter-spacing:0.05em;cursor:pointer;display:inline-flex;align-items:center;justify-content:center;gap:6px;transition:all 0.15s';
          return '<button title="' + esc(opts.title || label) + '" onclick="' + onclick + '" style="' + styleStr + '" onmouseover="' + hoverOver + '" onmouseout="' + hoverOut + '">' +
            (icon ? '<span class="material-symbols-outlined" style="font-size:13px">' + icon + '</span>' : '') +
            (opts.iconOnly ? '' : label) +
          '</button>';
        };
        // Edit button — available regardless of install state. Lets
        // admins tighten description / tags / scenarios in place.
        var editBtnTech = techBtn('', 'edit', "event.stopPropagation();_showSkillEditModal('"+esc(e.id)+"')", { iconOnly: true, title: 'Edit description / tags / scenarios' });
        if (e.installed) {
          actions = techBtn('GRANT', 'badge', "event.stopPropagation();openGrantModal('"+esc(e.installed_id)+"','"+esc(e.name)+"')", { primary: true, flex: 1 })
                  + (pptxThemeBtn ? techBtn('THEMES', 'palette', 'event.stopPropagation();openPptxThemeGallery()', {}) : '')
                  + editBtnTech
                  + techBtn('', 'edit_note', "event.stopPropagation();openAnnotateModal('"+esc(e.installed_id)+"','"+esc(e.name)+"')", { iconOnly: true, title: 'Notes' })
                  + techBtn('', 'remove_circle', "event.stopPropagation();uninstallStoreEntry('"+esc(e.id)+"')", { iconOnly: true, title: 'Uninstall (keep catalog)' })
                  + techBtn('', 'delete_forever', "event.stopPropagation();deleteCatalogEntry('"+esc(e.id)+"','"+esc(e.name)+"')", { iconOnly: true, danger: true, title: 'Hard-delete catalog dir' });
        } else {
          var disLabel = disabled ? 'Restore' : 'Hide';
          var disIcon = disabled ? 'visibility' : 'visibility_off';
          actions = techBtn('INSTALL', 'download', "event.stopPropagation();installStoreEntry('"+esc(e.id)+"')", { primary: true, flex: 1 })
                  + editBtnTech
                  + techBtn('', disIcon, "event.stopPropagation();toggleDisableCatalogEntry('"+esc(e.id)+"',"+(!disabled)+")", { iconOnly: true, title: disLabel })
                  + techBtn('', 'delete_forever', "event.stopPropagation();deleteCatalogEntry('"+esc(e.id)+"','"+esc(e.name)+"')", { iconOnly: true, danger: true, title: 'Hard-delete catalog dir' });
        }
      } else {
        var editBtnLegacy = '<button class="btn btn-sm" title="编辑元数据" onclick="event.stopPropagation();_showSkillEditModal(\''+esc(e.id)+'\')"><span class="material-symbols-outlined" style="font-size:14px">edit</span></button>';
        if (e.installed) {
          actions = '<button class="btn btn-sm" style="flex:1" onclick="event.stopPropagation();openGrantModal(\''+esc(e.installed_id)+'\',\''+esc(e.name)+'\')"><span class="material-symbols-outlined" style="font-size:14px;vertical-align:middle">badge</span> 授权</button>'
                  + pptxThemeBtn
                  + editBtnLegacy
                  + '<button class="btn btn-sm" title="笔记" onclick="event.stopPropagation();openAnnotateModal(\''+esc(e.installed_id)+'\',\''+esc(e.name)+'\')">📝</button>'
                  + '<button class="btn btn-sm" title="卸载 (保留目录)" style="color:var(--warning,#f59e0b)" onclick="event.stopPropagation();uninstallStoreEntry(\''+esc(e.id)+'\')"><span class="material-symbols-outlined" style="font-size:14px">remove_circle</span></button>'
                  + '<button class="btn btn-sm" title="彻底删除目录" style="color:var(--error)" onclick="event.stopPropagation();deleteCatalogEntry(\''+esc(e.id)+'\',\''+esc(e.name)+'\')"><span class="material-symbols-outlined" style="font-size:14px">delete_forever</span></button>';
        } else {
          var disableLabel = disabled ? 'Resume' : 'Expired';
          var disableIcon = disabled ? 'visibility' : 'visibility_off';
          actions = '<button class="btn btn-primary btn-sm" style="flex:1" onclick="event.stopPropagation();installStoreEntry(\''+esc(e.id)+'\')"><span class="material-symbols-outlined" style="font-size:14px;vertical-align:middle">download</span> 安装</button>'
                  + editBtnLegacy
                  + '<button class="btn btn-sm" title="'+disableLabel+'" onclick="event.stopPropagation();toggleDisableCatalogEntry(\''+esc(e.id)+'\','+(!disabled)+')"><span class="material-symbols-outlined" style="font-size:14px">'+disableIcon+'</span></button>'
                  + '<button class="btn btn-sm" title="彻底删除目录" style="color:var(--error)" onclick="event.stopPropagation();deleteCatalogEntry(\''+esc(e.id)+'\',\''+esc(e.name)+'\')"><span class="material-symbols-outlined" style="font-size:14px">delete_forever</span></button>';
        }
      }
      // Icon: from manifest metadata.emoji if present, else first char or 📦
      var emoji = (e.metadata && e.metadata.emoji) || e.icon || '';
      if (!emoji) {
        var tagsStr = (e.tags || []).join(' ').toLowerCase();
        emoji = /file|filesystem/.test(tagsStr) ? '📁'
              : /web|http/.test(tagsStr) ? '🌐'
              : /shell|bash/.test(tagsStr) ? '🖥️'
              : /memory|knowledge/.test(tagsStr) ? '🧠'
              : /message|chat/.test(tagsStr) ? '💬'
              : /ppt|office|doc/.test(tagsStr) ? '📊'
              : /screenshot|image/.test(tagsStr) ? '📷'
              : /schedule|time|cron/.test(tagsStr) ? '⏰'
              : /tool.?bundle|core/.test(tagsStr) ? '🧰'
              : '📦';
      }
      var desc = esc(e.description || '').slice(0, 110);
      if ((e.description || '').length > 110) desc += '…';

      if (_techCard) {
        // Stitch_27 bento card — same recipe as RAG / Wiki / Workflow.
        // Source tier becomes the accent (OFFICIAL = lime, others map
        // to indigo / cyan / orange). INSTALLED gets a glowing border.
        var srcRGB = e.source === 'official' ? '173,255,47'
                   : e.source === 'maintainer' ? '167,139,250'
                   : e.source === 'community' ? '96,165,250'
                   : e.source === 'agent' ? '245,158,11'
                   : '148,163,184';
        var statusLabel = e.installed ? 'INSTALLED'
                        : (disabled ? 'HIDDEN' : (e.source || 'CATALOG').toUpperCase());
        var statusColor = e.installed ? '#10b981' : srcColor;
        var sensitivePill = e.sensitive
          ? '<span class="tc-mono-label" style="padding:2px 7px;background:rgba(239,68,68,0.10);color:#ef4444;border:1px solid rgba(239,68,68,0.25);border-radius:9999px;font-size:9px;letter-spacing:0.05em">SENSITIVE</span>'
          : '';
        return '<div class="tc-card-glass" style="' +
                 'padding:var(--s-lg);display:flex;flex-direction:column;gap:14px;' +
                 'position:relative;overflow:hidden;border-top:1px solid rgba(255,255,255,0.15);' +
                 (e.installed ? 'box-shadow:0 0 15px -3px rgba(' + srcRGB + ',0.30);' : 'box-shadow:0 0 12px -3px rgba(' + srcRGB + ',0.08);') +
                 'transition:transform 0.15s,box-shadow 0.15s" ' +
                 'onmouseenter="this.style.transform=\'translateY(-2px)\';this.style.boxShadow=\'0 8px 24px -4px rgba(' + srcRGB + ',0.30)\'" ' +
                 'onmouseleave="this.style.transform=\'\';this.style.boxShadow=\'' + (e.installed ? '0 0 15px -3px rgba(' + srcRGB + ',0.30)' : '0 0 12px -3px rgba(' + srcRGB + ',0.08)') + '\'">' +
                 // Ghost icon — emoji at low opacity in upper-right
                 '<div style="position:absolute;top:0;right:0;padding:14px;pointer-events:none;font-size:64px;opacity:0.10;line-height:1">' + emoji + '</div>' +
                 // Header: small icon-square + status pill
                 '<div style="display:flex;justify-content:space-between;align-items:flex-start;position:relative">' +
                   '<div style="padding:8px;background:rgba(' + srcRGB + ',0.10);border:1px solid rgba(' + srcRGB + ',0.20);border-radius:var(--r-md);display:inline-flex;align-items:center;justify-content:center;font-size:22px;line-height:1;width:38px;height:38px;box-sizing:border-box">' +
                     emoji +
                   '</div>' +
                   '<div style="display:flex;align-items:center;gap:6px;background:var(--surface-container-high);padding:4px 10px;border-radius:9999px;border:1px solid rgba(255,255,255,0.05)">' +
                     '<span style="width:6px;height:6px;border-radius:50%;background:' + statusColor + ';' + (e.installed ? 'animation:pulse-dot 2s infinite ease-in-out;box-shadow:0 0 6px ' + statusColor + ';' : '') + '"></span>' +
                     '<span class="tc-mono-label" style="font-size:10px;color:var(--on-surface);letter-spacing:0.05em">' + esc(statusLabel) + '</span>' +
                   '</div>' +
                 '</div>' +
                 // Title row + version + sensitive
                 '<div style="position:relative">' +
                   '<div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap">' +
                     '<h3 style="font-family:var(--font-display);font-size:16px;font-weight:600;color:var(--on-surface);margin:0;letter-spacing:-0.01em;line-height:1.3;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:100%">' + esc(e.name) + '</h3>' +
                     annBadge +
                     sensitivePill +
                   '</div>' +
                   '<p class="tc-mono-label" style="font-size:10px;color:var(--on-surface-variant);margin:4px 0 0;font-family:var(--font-mono)">v' + esc(e.version) + ' · ' + esc((e.source || '').toUpperCase()) + '</p>' +
                   (desc ? '<p class="tc-text-dim" style="font-size:12px;line-height:1.5;margin:8px 0 0;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden">' + desc + '</p>' : '') +
                 '</div>' +
                 _renderTagChips(e) +
                 _renderCategoryBadges(e) +
                 '<div style="display:flex;gap:6px;margin-top:auto;flex-wrap:wrap">' + actions + '</div>' +
               '</div>';
      }

      // Legacy fallback (unchanged)
      var sensitive = e.sensitive ? '<span style="padding:1px 5px;font-size:10px;background:rgba(239,68,68,0.15);color:#ef4444;border-radius:8px;margin-left:4px">敏感</span>' : '';
      var installedBadge = e.installed ? '<span style="position:absolute;top:10px;right:10px;padding:2px 6px;font-size:10px;background:rgba(16,185,129,0.15);color:#10b981;border-radius:8px">✓ 已安装</span>' : '';
      return (
        '<div style="position:relative;border:1px solid var(--border);border-radius:12px;padding:16px;background:var(--surface);display:flex;flex-direction:column;gap:10px;transition:transform 0.15s,box-shadow 0.15s" '
        +  'onmouseenter="this.style.transform=\'translateY(-2px)\';this.style.boxShadow=\'0 4px 12px rgba(0,0,0,0.08)\'" '
        +  'onmouseleave="this.style.transform=\'\';this.style.boxShadow=\'\'" >'
        +  installedBadge
        +  '<div style="display:flex;align-items:flex-start;gap:12px">'
        +    '<div style="font-size:32px;line-height:1;flex-shrink:0;padding-top:2px">'+emoji+'</div>'
        +    '<div style="flex:1;min-width:0">'
        +      '<div style="font-weight:700;font-size:14px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+esc(e.name)+annBadge+sensitive+'</div>'
        +      '<div style="font-size:10px;color:var(--text3);margin-top:2px">v'+esc(e.version)+' · <span style="color:'+srcColor+'">'+esc(e.source)+'</span></div>'
        +    '</div>'
        +  '</div>'
        +  '<div style="font-size:12px;color:var(--text2);line-height:1.5;min-height:36px">'+desc+'</div>'
        +  _renderTagChips(e)
        +  _renderCategoryBadges(e)
        +  '<div style="display:flex;gap:6px;margin-top:auto">'+actions+'</div>'
        + '</div>'
      );
    }

    // Render the admin-assigned category badges for a skill (≠ free-text tags).
    // Lookup from the cached assignments + categoriesPayload bundled with the
    // /skill-store response, so this is a pure render — no extra requests.
    // Admin sees an inline "+ 管理" pill that opens the assignment modal.
    function _renderCategoryBadges(e) {
      var asg = (_skillStoreState.assignments || {})[e.id]
             || (_skillStoreState.assignments || {})[e.installed_id]
             || { scenarios: [], agent_types: [] };
      var dict = _skillStoreState.categoriesPayload || { scenarios: [], agent_types: [] };
      function lookupName(dim, cid) {
        var arr = dict[dim] || [];
        for (var i = 0; i < arr.length; i++) if (arr[i].id === cid) return arr[i];
        return null;
      }
      var badges = [];
      (asg.scenarios || []).forEach(function(cid) {
        var c = lookupName('scenarios', cid); if (!c) return;
        badges.push('<span title="业务场景" style="padding:1px 6px;font-size:10px;border-radius:8px;background:rgba(56,189,248,0.18);color:#0284c7;border:1px solid rgba(56,189,248,0.3)">'
          + (c.icon ? esc(c.icon) + ' ' : '') + esc(c.name) + '</span>');
      });
      (asg.agent_types || []).forEach(function(cid) {
        var c = lookupName('agent_types', cid); if (!c) return;
        badges.push('<span title="Agent 类型" style="padding:1px 6px;font-size:10px;border-radius:8px;background:rgba(168,85,247,0.18);color:#9333ea;border:1px solid rgba(168,85,247,0.3)">'
          + (c.icon ? esc(c.icon) + ' ' : '') + esc(c.name) + '</span>');
      });
      // Admin gets a "+ 管理" pill even when no categories are assigned yet.
      var adminBtn = '';
      if (typeof _isAdmin === 'function' && _isAdmin()) {
        adminBtn = '<span title="Manage Categories" style="padding:1px 6px;font-size:10px;border-radius:8px;background:var(--surface3);color:var(--text2);border:1px dashed var(--border);cursor:pointer" onclick="event.stopPropagation();_openSkillCategoryAssignModal(\'' + esc(e.id) + '\',\'' + esc(e.name) + '\')">+ Manage</span>';
      }
      if (!badges.length && !adminBtn) return '';
      return '<div style="display:flex;flex-wrap:wrap;gap:4px;margin-top:-2px">' + badges.join('') + adminBtn + '</div>';
    }

    // Render up to 5 tag chips on a card; click filters the store by that tag.
    // Active tag (matching _skillStoreState.tag) gets a highlighted style.
    function _renderTagChips(e) {
      var tags = e.tags || [];
      if (!tags.length) return '';
      var activeTag = (_skillStoreState.tag || '').toLowerCase();
      var shown = tags.slice(0, 5);
      var more = tags.length > 5 ? ('<span style="font-size:10px;color:var(--text3);padding:2px 4px">+'+(tags.length-5)+'</span>') : '';
      var chips = shown.map(function(t){
        var tl = String(t).toLowerCase();
        var active = (tl === activeTag);
        var style = active
          ? 'padding:2px 8px;font-size:10px;border-radius:10px;background:var(--primary);color:#fff;cursor:pointer;border:1px solid var(--primary)'
          : 'padding:2px 8px;font-size:10px;border-radius:10px;background:var(--surface3);color:var(--text2);cursor:pointer;border:1px solid var(--border)';
        return '<span style="'+style+'" onclick="event.stopPropagation();_skillStoreFilterByTag(\''+esc(String(t))+'\')" title="按此标签筛选">'+esc(String(t))+'</span>';
      }).join('');
      return '<div style="display:flex;flex-wrap:wrap;gap:4px">'+chips+more+'</div>';
    }
    // Render: one <section> per category with its own grid
    var sections = orderedKeys.map(function(k){
      var g = groups[k];
      var grid = g.entries.map(_renderCard).join('');
      return (
        '<section style="margin-bottom:20px">'
        + '<div style="display:flex;align-items:baseline;gap:8px;margin:4px 2px 10px;padding-bottom:6px;border-bottom:1px solid var(--border)">'
        +   '<h3 style="margin:0;font-size:14px;font-weight:600">'+esc(g.label)+'</h3>'
        +   '<span style="font-size:11px;color:var(--text3)">'+g.entries.length+' 个</span>'
        + '</div>'
        + '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:14px">'
        +   grid
        + '</div>'
        + '</section>'
      );
    }).join('');
    box.innerHTML = sections;
  } catch(err) {
    box.innerHTML = '<div style="color:var(--error);padding:20px">Load failed:'+esc(String(err))+'</div>';
  }
}

async function rescanSkillStore() {
  try {
    await api('POST', '/api/portal/skill-store', {action: 'rescan'});
    loadSkillStore();
  } catch(e) { alert('Scan failed:'+e); }
}

async function installStoreEntry(entryId) {
  try {
    var r = await api('POST', '/api/portal/skill-store', {action:'install', entry_id: entryId});
    if (r && r.ok) loadSkillStore();
    else alert('Install failed:' + JSON.stringify(r));
  } catch(e) { alert('Install failed:'+e); }
}

// ── Edit metadata modal ──────────────────────────────────────────
//
// Edit LLM-facing fields of a catalog skill (description, tags,
// applicable_roles, scenarios, languages). Backend caps description at
// 100 chars per project rule — long blurbs hurt prompt economy and the
// LLM uses description to decide WHEN to call a skill, not WHAT it is.
// Read-only fields (id/version/source/spec/runtime) shown for context.

var _SKILL_DESC_MAX = 100;

function _showSkillEditModal(entryId) {
  var entry = (_skillStoreState.entries || []).find(function(e){ return e.id === entryId; });
  if (!entry) {
    alert('Entry not found in current view; rescan and try again.');
    return;
  }
  var existing = document.getElementById('skill-edit-modal');
  if (existing) existing.remove();

  var modal = document.createElement('div');
  modal.id = 'skill-edit-modal';
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.55);z-index:9999;display:flex;align-items:center;justify-content:center';

  var roTr = function(label, value) {
    return '<tr><td style="padding:4px 10px 4px 0;color:var(--text3);font-size:11px;white-space:nowrap;vertical-align:top">' + esc(label) + '</td>'
         + '<td style="padding:4px 0;font-family:var(--font-mono),monospace;font-size:12px;color:var(--text2)">' + esc(value || '—') + '</td></tr>';
  };

  modal.innerHTML = '<div style="background:var(--bg);border:1px solid var(--border);border-radius:10px;padding:22px;max-width:640px;width:94%;max-height:88vh;overflow:auto;box-shadow:0 12px 40px rgba(0,0,0,0.4)">'
    + '<div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:14px">'
    +   '<div>'
    +     '<h3 style="margin:0;font-size:18px">Edit Skill Metadata</h3>'
    +     '<div style="font-size:11px;color:var(--text3);margin-top:4px">'
    +       'Only LLM-visible fields are editable. Structural fields '
    +       '(id / version / spec) are immutable; rescan refreshes after save.'
    +     '</div>'
    +   '</div>'
    +   '<button onclick="document.getElementById(\'skill-edit-modal\').remove()" style="background:transparent;border:none;font-size:20px;color:var(--text3);cursor:pointer;padding:0">✕</button>'
    + '</div>'
    + '<table style="width:100%;border-collapse:collapse;margin-bottom:14px;background:var(--surface);border:1px solid var(--border-light);border-radius:6px">'
    +   '<tbody>'
    +     roTr('name', entry.name)
    +     roTr('id', entry.id)
    +     roTr('version', entry.version)
    +     roTr('source', entry.source)
    +     roTr('spec', entry.spec)
    +     roTr('runtime', entry.runtime)
    +   '</tbody>'
    + '</table>'
    + '<div style="margin-bottom:14px">'
    +   '<div style="display:flex;justify-content:space-between;align-items:baseline;margin-bottom:4px">'
    +     '<label style="font-size:12px;font-weight:600">Description</label>'
    +     '<span id="skill-edit-desc-count" style="font-size:10px;color:var(--text3)">0 / ' + _SKILL_DESC_MAX + '</span>'
    +   '</div>'
    +   '<div style="font-size:11px;color:var(--text3);margin-bottom:6px">'
    +     'Describe <b>WHEN to call this skill</b> (not what it is). Max ' + _SKILL_DESC_MAX + ' chars.'
    +   '</div>'
    +   '<textarea id="skill-edit-desc" rows="3" maxlength="' + _SKILL_DESC_MAX + '" '
    +     'oninput="_skillEditDescUpdate()" '
    +     'style="width:100%;padding:8px 10px;border:1px solid var(--border);border-radius:6px;background:var(--bg);color:var(--text);font-size:13px;box-sizing:border-box;font-family:inherit;resize:vertical">'
    +     esc(entry.description || '')
    +   '</textarea>'
    + '</div>'
    + _renderSkillEditCsvField('tags', 'Tags', 'comma-separated, e.g. dev,review,qa', entry.tags)
    + _renderSkillEditCsvField('scenarios', 'Scenarios', 'comma-separated, e.g. new feature, bug fix', entry.scenarios)
    + _renderSkillEditCsvField('applicable_roles', 'Applicable Roles', 'comma-separated, e.g. coder, reviewer', entry.applicable_roles)
    + _renderSkillEditCsvField('languages', 'Languages', 'comma-separated, e.g. python, javascript', entry.languages)
    + '<div id="skill-edit-status" style="font-size:12px;margin-bottom:8px;display:none"></div>'
    + '<div style="display:flex;justify-content:flex-end;gap:8px">'
    +   '<button class="btn btn-sm" onclick="document.getElementById(\'skill-edit-modal\').remove()">Cancel</button>'
    +   '<button class="btn btn-primary btn-sm" id="skill-edit-save" onclick="_doSkillEdit(\'' + esc(entryId) + '\')">'
    +     '<span class="material-symbols-outlined" style="font-size:14px;vertical-align:middle">save</span> Save'
    +   '</button>'
    + '</div>'
    + '</div>';

  document.body.appendChild(modal);
  _skillEditDescUpdate();
  setTimeout(function(){
    var ta = document.getElementById('skill-edit-desc');
    if (ta) { ta.focus(); ta.setSelectionRange(ta.value.length, ta.value.length); }
  }, 0);
}

function _renderSkillEditCsvField(key, label, placeholder, currentList) {
  var val = (currentList && currentList.length) ? currentList.join(', ') : '';
  return '<div style="margin-bottom:12px">'
    + '<label style="display:block;font-size:12px;font-weight:600;margin-bottom:4px">' + esc(label) + '</label>'
    + '<input id="skill-edit-' + key + '" type="text" placeholder="' + esc(placeholder) + '" value="' + esc(val) + '" '
    +   'style="width:100%;padding:7px 10px;border:1px solid var(--border);border-radius:6px;background:var(--bg);color:var(--text);font-size:13px;box-sizing:border-box">'
    + '</div>';
}

function _skillEditDescUpdate() {
  var ta = document.getElementById('skill-edit-desc');
  var counter = document.getElementById('skill-edit-desc-count');
  if (!ta || !counter) return;
  var len = (ta.value || '').length;
  counter.textContent = len + ' / ' + _SKILL_DESC_MAX;
  counter.style.color = (len > _SKILL_DESC_MAX * 0.9)
    ? 'var(--warning, #ff9800)'
    : (len > _SKILL_DESC_MAX ? 'var(--error)' : 'var(--text3)');
}

async function _doSkillEdit(entryId) {
  var status = document.getElementById('skill-edit-status');
  var btn = document.getElementById('skill-edit-save');
  var desc = (document.getElementById('skill-edit-desc') || {}).value || '';
  if (desc.length > _SKILL_DESC_MAX) {
    status.style.display = 'block';
    status.style.color = 'var(--error)';
    status.innerHTML = 'Description exceeds ' + _SKILL_DESC_MAX + ' chars; please shorten.';
    return;
  }
  var updates = { description: desc.trim() };
  ['tags', 'scenarios', 'applicable_roles', 'languages'].forEach(function(key) {
    var el = document.getElementById('skill-edit-' + key);
    if (!el) return;
    var raw = (el.value || '').trim();
    updates[key] = raw ? raw.split(',').map(function(s){ return s.trim(); }).filter(Boolean) : [];
  });

  btn.disabled = true;
  btn.innerHTML = '<span class="material-symbols-outlined" style="font-size:14px;vertical-align:middle;animation:spin 1s linear infinite">progress_activity</span> Saving…';
  status.style.display = 'block';
  status.style.color = 'var(--text3)';
  status.innerHTML = 'Writing to disk…';

  try {
    var data = await api('POST', '/api/portal/skill-store', {
      action: 'edit_metadata',
      entry_id: entryId,
      updates: updates,
    });
    if (data && data.ok) {
      status.style.color = '#10b981';
      status.innerHTML = '✓ Saved' + (data.note ? ' (' + esc(data.note) + ')' : '');
      loadSkillStore();
      setTimeout(function(){
        var m = document.getElementById('skill-edit-modal');
        if (m) m.remove();
      }, 800);
    } else {
      status.style.color = 'var(--error)';
      status.innerHTML = 'Save failed: ' + esc((data && data.error) || JSON.stringify(data));
    }
  } catch(err) {
    status.style.color = 'var(--error)';
    status.innerHTML = 'Request failed: ' + esc(String(err));
  }
  btn.disabled = false;
  btn.innerHTML = '<span class="material-symbols-outlined" style="font-size:14px;vertical-align:middle">save</span> Save';
}

async function uninstallStoreEntry(entryId) {
  if (!await confirm('卸载这个技能？对 agent 的授权会同时撤销。')) return;
  try {
    var r = await api('POST', '/api/portal/skill-store', {action:'uninstall', entry_id: entryId});
    if (r && r.ok) loadSkillStore();
    else alert('卸载失败');
  } catch(e) { alert('Uninstall failed:'+e); }
}

// Soft-disable: hide from default list but keep on disk
async function toggleDisableCatalogEntry(entryId, disable) {
  var verb = disable ? 'Expired' : 'Resume';
  try {
    var r = await api('POST', '/api/portal/skill-store',
      {action:'disable', entry_id: entryId, disabled: !!disable});
    if (r && r.ok) {
      loadSkillStore();
      if (window._toast) window._toast(verb + 'Success', 'success');
    } else {
      alert(verb + 'Failed');
    }
  } catch(e) { alert(verb + '失败: '+e); }
}

// Hard-delete: remove the catalog directory entirely. Asks twice.
// Reusable confirmation modal that requires the user to type the
// resource name to confirm an irreversible action. Replaces native
// `confirm()` + `prompt()` pair which Chrome renders as a tiny attached
// dialog (and gets squished against the URL bar). Returns Promise<bool>.
//
// opts:
//   title:        modal heading
//   warning:      red warning text (multi-line OK, \n becomes <br>)
//   typeName:     the exact string the user must type to enable Confirm
//   confirmText:  Confirm button label (default "删除")
//   confirmColor: button color (default 'var(--error)')
function _confirmTypedDelete(opts) {
  return new Promise(function(resolve) {
    var name = String(opts.typeName || '');
    var ctaText = opts.confirmText || 'Delete';
    var ctaColor = opts.confirmColor || 'var(--error)';
    var html = ''
      + '<div style="padding:24px">'
      +   '<h3 style="margin:0 0 8px;font-size:16px;font-weight:700">' + esc(opts.title || '⚠️ 确认操作') + '</h3>'
      +   '<div style="font-size:13px;color:var(--text2);line-height:1.55;margin-bottom:14px">'
      +     esc(opts.warning || '').replace(/\n/g, '<br>')
      +   '</div>'
      +   '<div style="font-size:12px;color:var(--text3);margin-bottom:6px">'
      +     '请输入 <code style="background:var(--surface3);padding:2px 6px;border-radius:4px;color:var(--text);font-family:monospace">' + esc(name) + '</code> 以确认:'
      +   '</div>'
      +   '<input id="_ctd-input" type="text" autocomplete="off" placeholder="' + esc(name) + '" '
      +     'style="width:100%;padding:10px 12px;font-size:14px;background:var(--bg);border:1px solid var(--border);border-radius:8px;color:var(--text);font-family:monospace;outline:none;box-sizing:border-box">'
      +   '<div id="_ctd-hint" style="font-size:11px;color:var(--text3);margin-top:6px;min-height:14px"></div>'
      +   '<div style="display:flex;justify-content:flex-end;gap:8px;margin-top:18px">'
      +     '<button id="_ctd-cancel" class="btn btn-ghost btn-sm">Cancel</button>'
      +     '<button id="_ctd-ok" class="btn btn-sm" disabled '
      +       'style="background:' + ctaColor + ';color:#fff;opacity:0.4;cursor:not-allowed">'
      +       esc(ctaText)
      +     '</button>'
      +   '</div>'
      + '</div>';
    showModalHTML(html);

    var input = document.getElementById('_ctd-input');
    var hint  = document.getElementById('_ctd-hint');
    var ok    = document.getElementById('_ctd-ok');
    var cancel= document.getElementById('_ctd-cancel');
    if (!input || !ok || !cancel) { resolve(false); return; }

    setTimeout(function(){ input.focus(); }, 30);

    var resolved = false;
    function _close(val) {
      if (resolved) return;
      resolved = true;
      var overlay = document.getElementById('modal-overlay');
      if (overlay) overlay.remove();
      resolve(val);
    }

    input.oninput = function() {
      var v = input.value;
      var match = (v === name);
      ok.disabled = !match;
      ok.style.opacity = match ? '1' : '0.4';
      ok.style.cursor  = match ? 'pointer' : 'not-allowed';
      if (v && !match) {
        hint.textContent = '名称不匹配 — 必须完全一致(区分大小写)';
        hint.style.color = 'var(--warning, #f59e0b)';
      } else if (match) {
        hint.textContent = '✓ 名称匹配,可以确认';
        hint.style.color = 'var(--success, #22c55e)';
      } else {
        hint.textContent = '';
      }
    };
    input.onkeydown = function(e) {
      if (e.key === 'Enter' && !ok.disabled) { e.preventDefault(); _close(true); }
      else if (e.key === 'Escape') { e.preventDefault(); _close(false); }
    };
    ok.onclick     = function() { if (!ok.disabled) _close(true); };
    cancel.onclick = function() { _close(false); };
  });
}
window._confirmTypedDelete = _confirmTypedDelete;


async function deleteCatalogEntry(entryId, entryName) {
  var confirmed = await _confirmTypedDelete({
    title:    '⚠️ 彻底删除技能',
    warning:  '将永久删除技能 "' + entryName + '" 的目录。\n'
            + '此操作不可撤销 — 文件会从磁盘删除。\n'
            + '如果只是暂时不用,改用"失效"按钮即可。',
    typeName: entryName,
    confirmText: 'Delete',
  });
  if (!confirmed) return;

  try {
    var r = await api('POST', '/api/portal/skill-store',
      {action:'delete_catalog', entry_id: entryId});
    if (r && r.ok) {
      loadSkillStore();
      if (window._toast) window._toast('Permanently deleted ' + entryName, 'success');
      else alert('Deleted');
    } else {
      var msg = (r && (r.error || r.detail)) || '后端返回 ok=false (可能路径不在 catalog 根目录下,或 entry 已不存在)';
      alert('Delete failed:' + msg);
    }
  } catch(e) { alert('Delete failed:' + (e.message || e)); }
}

window.toggleDisableCatalogEntry = toggleDisableCatalogEntry;
window.deleteCatalogEntry = deleteCatalogEntry;

// ── PPTX Theme Gallery (pptx-author skill only) ──────────────────────────
// Shows 10 theme preview thumbnails + a keyword-based recommender. Agent
// can use any theme id in `render_from_md(prs, "<theme_id>/T<NN>_..." ...)`.
var _pptxThemeState = { themes: [], layouts: [], highlighted: {} };

async function openPptxThemeGallery() {
  // Create modal shell
  var modal = document.createElement('div');
  modal.id = 'pptx-theme-gallery-modal';
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.6);z-index:9999;display:flex;align-items:center;justify-content:center';
  modal.innerHTML =
    '<div style="background:var(--bg);border:1px solid var(--border);border-radius:12px;padding:24px;max-width:1200px;width:96%;max-height:92vh;overflow:auto">'
    + '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:16px">'
    +   '<h3 style="margin:0">🎨 PPT 主题画廊 · 10 套视觉风格</h3>'
    +   '<button class="btn btn-ghost btn-sm" onclick="document.getElementById(\'pptx-theme-gallery-modal\').remove()">✕</button>'
    + '</div>'
    + '<div id="pptx-recommend-box" style="display:flex;gap:8px;align-items:center;margin-bottom:12px;padding:10px 12px;background:var(--surface);border:1px solid var(--border);border-radius:8px">'
    +   '<span style="font-size:18px">🔍</span>'
    +   '<input id="pptx-recommend-query" placeholder="描述你的 PPT (如: AI 发布会 / 并购路演 / ESG 报告) —— 自动推荐主题" '
    +      'style="flex:1;padding:8px 10px;border:1px solid var(--border);border-radius:6px;background:var(--bg);color:var(--text);font-size:13px" '
    +      'oninput="_pptxRecommendDebounced()">'
    +   '<span id="pptx-recommend-status" style="font-size:11px;color:var(--text3)">输入关键词</span>'
    + '</div>'
    + '<div style="display:flex;gap:8px;margin-bottom:12px;border-bottom:1px solid var(--border)">'
    +   '<button id="pptx-tab-themes"  class="btn btn-sm" onclick="_switchPptxTab(\'themes\')" '
    +           'style="border-radius:6px 6px 0 0">主题视图 (10 套)</button>'
    +   '<button id="pptx-tab-layouts" class="btn btn-sm btn-ghost" onclick="_switchPptxTab(\'layouts\')" '
    +           'style="border-radius:6px 6px 0 0">版式视图 (15 个)</button>'
    + '</div>'
    + '<div id="pptx-theme-grid" style="display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:16px"></div>'
    + '<div id="pptx-layout-grid" style="display:none;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:16px"></div>'
    + '<div id="pptx-layouts-ref" style="margin-top:20px;padding:14px;background:var(--surface);border:1px solid var(--border);border-radius:8px;font-size:12px"></div>'
    + '</div>';
  document.body.appendChild(modal);

  // Load themes
  try {
    var data = await api('GET', '/api/portal/pptx-themes');
    _pptxThemeState.themes = data.themes || [];
    _pptxThemeState.layouts = data.layouts || [];
    _pptxThemeState.highlighted = {};
    _renderPptxThemeGrid();
    _renderPptxLayoutRef();
  } catch(e) {
    document.getElementById('pptx-theme-grid').innerHTML =
      '<div style="color:var(--error);padding:20px">Load failed:'+esc(String(e))+'</div>';
  }
}

// Tab switcher between theme view and layout view.
function _switchPptxTab(which) {
  var themeBtn  = document.getElementById('pptx-tab-themes');
  var layoutBtn = document.getElementById('pptx-tab-layouts');
  var themeGrid  = document.getElementById('pptx-theme-grid');
  var layoutGrid = document.getElementById('pptx-layout-grid');
  if (!themeGrid || !layoutGrid) return;
  if (which === 'layouts') {
    themeBtn.classList.add('btn-ghost');
    layoutBtn.classList.remove('btn-ghost');
    themeGrid.style.display = 'none';
    layoutGrid.style.display = 'grid';
    if (!layoutGrid.dataset.loaded) {
      _loadPptxLayoutGrid();
      layoutGrid.dataset.loaded = '1';
    }
  } else {
    themeBtn.classList.remove('btn-ghost');
    layoutBtn.classList.add('btn-ghost');
    themeGrid.style.display = 'grid';
    layoutGrid.style.display = 'none';
  }
}

// Layout grid: list all 15 layouts, each card shows 3 theme previews
// (corporate / tech_dark / minimal — picked as visual range).
async function _loadPptxLayoutGrid() {
  var grid = document.getElementById('pptx-layout-grid');
  if (!grid) return;
  grid.innerHTML = '<div style="grid-column:1/-1;text-align:center;'
    + 'color:var(--text3);padding:30px">⏳ 加载中...</div>';
  try {
    var data = await api('GET', '/api/portal/pptx-layouts');
  } catch (e) {
    grid.innerHTML = '<div style="grid-column:1/-1;color:var(--error);'
      + 'padding:20px">Load failed:' + esc(String(e)) + '</div>';
    return;
  }
  var layouts = data.layouts || [];
  if (!layouts.length) {
    grid.innerHTML = '<div style="grid-column:1/-1;padding:20px">'
      + '没有可用版式</div>';
    return;
  }
  // Each layout: card with name + 3 mini-previews (3 themes)
  var SAMPLE_THEMES = ['corporate', 'tech_dark', 'minimal'];
  grid.innerHTML = layouts.map(function(L){
    var nameZh = L.name_zh || L.name || L.id;
    var summary = L.summary || '';
    var inShow = L.in_showcase
      ? '<span style="position:absolute;top:8px;right:8px;padding:2px 8px;'
        + 'background:var(--success,#3a8e44);color:white;font-size:10px;'
        + 'border-radius:10px;font-weight:600">SHOWCASE</span>'
      : '';
    var thumbs = SAMPLE_THEMES.map(function(theme){
      var url = '/api/portal/pptx-layouts/' + encodeURIComponent(L.id)
        + '/preview.png?theme=' + encodeURIComponent(theme);
      return '<div style="flex:1;min-width:0">'
        + '<img src="' + esc(url) + '" alt="' + esc(theme) + '" '
        + 'loading="lazy" '
        + 'style="width:100%;aspect-ratio:16/9;object-fit:cover;'
        + 'border-radius:4px;border:1px solid var(--border-light);'
        + 'background:#f5f5f5;cursor:pointer" '
        + 'onclick="_enlargePptxSlide(\'' + esc(url) + '\')">'
        + '<div style="font-size:9px;color:var(--text3);text-align:center;'
        + 'margin-top:2px">' + esc(theme) + '</div>'
        + '</div>';
    }).join('');
    var copyArgs = "'" + esc(L.id) + "'";
    return '<div style="position:relative;border:1px solid var(--border);'
      + 'border-radius:10px;padding:12px;background:var(--surface);'
      + 'transition:transform 0.12s,box-shadow 0.12s" '
      + 'onmouseenter="this.style.transform=\'translateY(-2px)\';'
      + 'this.style.boxShadow=\'0 4px 12px rgba(0,0,0,0.1)\'" '
      + 'onmouseleave="this.style.transform=\'\';this.style.boxShadow=\'\'">'
      + inShow
      + '<div style="display:flex;justify-content:space-between;'
      + 'align-items:baseline;margin-bottom:8px">'
      +   '<div style="font-weight:700;font-size:14px">' + esc(nameZh) + '</div>'
      +   '<code style="font-size:10px;color:var(--text3);'
      + 'font-family:Menlo,monospace">' + esc(L.id) + '</code>'
      + '</div>'
      + '<div style="font-size:11px;color:var(--text2);line-height:1.5;'
      + 'min-height:34px;margin-bottom:10px">'
      + esc((summary || '').slice(0, 100))
      + '</div>'
      + '<div style="display:flex;gap:4px;margin-bottom:10px">' + thumbs + '</div>'
      + '<div style="display:flex;gap:6px">'
      +   '<button class="btn btn-sm" style="flex:1" '
      + 'onclick="_copyLayoutSnippet(' + copyArgs + ')" '
      + 'title="复制 render_from_md 调用片段"><span class="material-symbols-outlined" '
      + 'style="font-size:13px;vertical-align:middle">content_copy</span> '
      + '复制代码</button>'
      + '</div>'
      + '</div>';
  }).join('');
}

// Copy a render_from_md snippet for a chosen layout id.
function _copyLayoutSnippet(layoutId) {
  var snippet = "render_from_md(prs, \"corporate/" + layoutId + "\", params={\n"
    + "    # 用 describe_layout(\"" + layoutId + "\") 看完整参数 schema\n"
    + "    \"title\": \"...\",\n"
    + "})";
  try {
    navigator.clipboard.writeText(snippet);
    if (typeof toast === 'function') toast('已复制 render_from_md 片段');
    else console.log('Copied:', snippet);
  } catch (e) {
    console.warn('clipboard write failed', e);
  }
}

function _renderPptxThemeGrid() {
  var grid = document.getElementById('pptx-theme-grid');
  if (!grid) return;
  grid.innerHTML = _pptxThemeState.themes.map(function(t){
    var hi = _pptxThemeState.highlighted[t.id];
    var border = hi
      ? '2px solid var(--primary);box-shadow:0 0 0 3px rgba(99,102,241,0.15)'
      : '1px solid var(--border)';
    var badge = hi
      ? '<span style="position:absolute;top:8px;right:8px;padding:2px 8px;background:var(--primary);color:white;font-size:10px;border-radius:10px;font-weight:600">推荐 · '+hi.score+'</span>'
      : '';
    var matched = (hi && hi.matched && hi.matched.length)
      ? '<div style="margin-top:6px;font-size:10px;color:var(--primary)">匹配: '+hi.matched.map(esc).join(' · ')+'</div>'
      : '';
    var tags = (t.tags || []).slice(0,4).map(function(x){
      return '<span style="padding:1px 6px;font-size:10px;background:rgba(99,102,241,0.1);color:var(--primary);border-radius:6px;margin-right:4px">'+esc(x)+'</span>';
    }).join('');
    return (
      '<div style="position:relative;border:'+border+';border-radius:10px;padding:12px;background:var(--surface);transition:transform 0.12s,box-shadow 0.12s" '
      +  'onmouseenter="this.style.transform=\'translateY(-2px)\'" onmouseleave="this.style.transform=\'\'" >'
      +  badge
      +  '<img src="'+esc(t.preview_url)+'" alt="'+esc(t.name)+'" '
      +       'style="width:100%;aspect-ratio:16/9;object-fit:cover;border-radius:6px;border:1px solid var(--border-light);background:#f5f5f5">'
      +  '<div style="display:flex;justify-content:space-between;align-items:baseline;margin-top:10px">'
      +    '<div style="font-weight:700;font-size:14px">'+esc(t.name)+'</div>'
      +    '<code style="font-size:11px;color:var(--text3);font-family:Menlo,monospace">'+esc(t.id)+'</code>'
      +  '</div>'
      +  '<div style="font-size:11px;color:var(--text2);margin-top:4px;line-height:1.5;min-height:34px">'+esc((t.description||'').slice(0,120))+'</div>'
      +  '<div style="margin-top:8px">'+tags+'</div>'
      +  matched
      +  '<div style="display:flex;gap:6px;margin-top:10px">'
      +    '<button class="btn btn-sm" style="flex:1" onclick="_copyPptxSnippet(\''+esc(t.id)+'\')" title="复制这套主题的 python 示例代码到剪贴板"><span class="material-symbols-outlined" style="font-size:13px;vertical-align:middle">content_copy</span> 复制代码</button>'
      +    '<button class="btn btn-sm" style="flex:1" onclick="_viewPptxDemo(\''+esc(t.id)+'\',\''+esc(t.name)+'\')" title="查看这套主题的 8 页 demo 缩略图"><span class="material-symbols-outlined" style="font-size:13px;vertical-align:middle">preview</span> 查看 demo</button>'
      +  '</div>'
      + '</div>'
    );
  }).join('');
}

// ── Demo slides lightbox (shown when clicking "查看 demo" on a theme card) ──
async function _viewPptxDemo(themeId, themeName) {
  var old = document.getElementById('pptx-demo-modal');
  if (old) old.remove();

  var modal = document.createElement('div');
  modal.id = 'pptx-demo-modal';
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.85);z-index:10001;display:flex;flex-direction:column;padding:24px;overflow:auto';
  modal.innerHTML =
    '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px;color:white">'
    +   '<div>'
    +     '<h3 style="margin:0;font-size:18px">📺 ' + esc(themeName) + ' · 完整 demo</h3>'
    +     '<div style="font-size:12px;opacity:0.7;margin-top:4px">id: <code>'+esc(themeId)+'</code> · 缩略图为 PIL 简化渲染，实际细节见下方 .pptx</div>'
    +   '</div>'
    +   '<div style="display:flex;gap:8px">'
    +     '<a class="btn btn-sm" href="/api/portal/pptx-themes/'+esc(themeId)+'/demo.pptx" download style="text-decoration:none"><span class="material-symbols-outlined" style="font-size:14px;vertical-align:middle">download</span> 下载 .pptx</a>'
    +     '<button class="btn btn-sm" onclick="document.getElementById(\'pptx-demo-modal\').remove()">✕ 关闭</button>'
    +   '</div>'
    + '</div>'
    + '<div id="pptx-demo-grid" style="display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:12px"></div>';
  document.body.appendChild(modal);

  try {
    var data = await api('GET', '/api/portal/pptx-themes/' + encodeURIComponent(themeId) + '/demo');
    var grid = document.getElementById('pptx-demo-grid');
    if (!data.slides || !data.slides.length) {
      grid.innerHTML = '<div style="color:white;padding:20px">demo 尚未生成</div>';
      return;
    }
    grid.innerHTML = data.slides.map(function(s){
      return (
        '<div style="background:white;border-radius:6px;overflow:hidden;cursor:pointer" onclick="_enlargePptxSlide(\''+esc(s.url)+'\')">'
        + '<img src="'+esc(s.url)+'" alt="slide '+s.index+'" style="width:100%;aspect-ratio:16/9;object-fit:contain;background:#f5f5f5">'
        + '<div style="padding:6px 10px;font-size:11px;color:var(--text2);background:#f9f9f9;border-top:1px solid #eee">Slide '+s.index+' / '+data.slide_count+'</div>'
        + '</div>'
      );
    }).join('');
  } catch(e) {
    document.getElementById('pptx-demo-grid').innerHTML =
      '<div style="color:#fca5a5;padding:20px">加载 demo 失败: '+esc(String(e))+'</div>';
  }
}

function _enlargePptxSlide(url) {
  var old = document.getElementById('pptx-slide-lightbox');
  if (old) old.remove();
  var lb = document.createElement('div');
  lb.id = 'pptx-slide-lightbox';
  lb.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.92);z-index:10002;display:flex;align-items:center;justify-content:center;cursor:pointer;padding:40px';
  lb.innerHTML = '<img src="'+esc(url)+'" style="max-width:100%;max-height:100%;object-fit:contain;border-radius:4px;box-shadow:0 4px 20px rgba(0,0,0,0.5)">';
  lb.onclick = function(){ lb.remove(); };
  document.body.appendChild(lb);
}

// Preview an arbitrary pptx path (e.g., agent-produced file in workspace).
// Takes the full file path, gets a data: URL back for each slide, renders
// in a modal. Exposed as window.previewPptxFile for on-demand usage.
async function previewPptxFile(pptxPath, title) {
  var old = document.getElementById('pptx-file-preview-modal');
  if (old) old.remove();

  var modal = document.createElement('div');
  modal.id = 'pptx-file-preview-modal';
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.85);z-index:10001;display:flex;flex-direction:column;padding:24px;overflow:auto';
  modal.innerHTML =
    '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px;color:white">'
    +   '<div>'
    +     '<h3 style="margin:0;font-size:16px">📺 ' + esc(title || '预览 PPT') + '</h3>'
    +     '<div style="font-size:11px;opacity:0.7;margin-top:4px;font-family:Menlo,monospace">'+esc(pptxPath)+'</div>'
    +   '</div>'
    +   '<button class="btn btn-sm" onclick="document.getElementById(\'pptx-file-preview-modal\').remove()">✕ 关闭</button>'
    + '</div>'
    + '<div id="pptx-file-preview-grid" style="display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:12px">'
    +   '<div style="color:white;padding:20px;text-align:center">正在渲染…</div>'
    + '</div>';
  document.body.appendChild(modal);

  try {
    var data = await api('POST', '/api/portal/pptx-preview', {path: pptxPath, width: 480});
    var grid = document.getElementById('pptx-file-preview-grid');
    if (!data) {
      grid.innerHTML = '<div style="color:#fca5a5;padding:20px">后端无响应 — 请检查 uvicorn 是否重启</div>';
      return;
    }
    if (!data.slides || !data.slides.length) {
      // Helpful diagnostics — show what backend actually returned
      grid.innerHTML =
        '<div style="color:white;padding:20px">'
        + '<div style="font-size:16px;margin-bottom:10px">⚠️ 没有拿到页面</div>'
        + '<div style="font-size:12px;opacity:0.8;margin-bottom:8px">后端返回 slide_count=' + (data.slide_count || 0) + '</div>'
        + '<div style="font-size:11px;opacity:0.6;font-family:Menlo,monospace;background:rgba(0,0,0,0.3);padding:10px;border-radius:4px;white-space:pre-wrap">'
        + esc(JSON.stringify(data, null, 2).slice(0, 600))
        + '</div>'
        + '<div style="font-size:11px;margin-top:10px;opacity:0.7">常见原因: 后端 skills 路径配置错误,uvicorn 未重启加载新代码,或 _template_loader.py 加载失败。</div>'
        + '</div>';
      return;
    }
    grid.innerHTML = data.slides.map(function(s){
      return (
        '<div style="background:white;border-radius:6px;overflow:hidden;cursor:pointer" onclick="_enlargePptxSlide(\''+esc(s.data_url)+'\')">'
        + '<img src="'+esc(s.data_url)+'" alt="slide '+s.index+'" style="width:100%;aspect-ratio:16/9;object-fit:contain;background:#f5f5f5">'
        + '<div style="padding:6px 10px;font-size:11px;color:var(--text2);background:#f9f9f9;border-top:1px solid #eee">Slide '+s.index+' / '+data.slide_count+'</div>'
        + '</div>'
      );
    }).join('');
  } catch(e) {
    // Distinguish 503 (service unavailable — usually means loader path wrong)
    // from other errors, and show the raw message so user can debug.
    var msg = String((e && e.message) || e);
    var hint = '';
    if (/503|unavailable|not installed/i.test(msg)) {
      hint = '<div style="font-size:12px;margin-top:10px;opacity:0.8">提示: 后端找不到 pptx-author skill 模块。通常是 uvicorn 未重启加载新代码,或 _template_loader.py 路径错误。</div>';
    } else if (/404/.test(msg)) {
      hint = '<div style="font-size:12px;margin-top:10px;opacity:0.8">提示: 文件路径不存在或无权访问。</div>';
    } else if (/413/.test(msg) || /too large/i.test(msg)) {
      hint = '<div style="font-size:12px;margin-top:10px;opacity:0.8">提示: 文件超过 10 MB 预览上限。</div>';
    }
    document.getElementById('pptx-file-preview-grid').innerHTML =
      '<div style="color:#fca5a5;padding:20px">'
      + '<div style="font-size:14px;margin-bottom:6px">预览失败</div>'
      + '<div style="font-size:12px;font-family:Menlo,monospace;opacity:0.8">'+esc(msg)+'</div>'
      + hint
      + '</div>';
  }
}
window.previewPptxFile = previewPptxFile;

// ── Generic document preview (md / pdf / docx / txt) ──────────────────
// Opens a modal with rendered content. Fetches via /api/portal/file-preview
// which returns {kind, text|html|url} depending on the format.
async function previewFile(filePath, title, expectedKind) {
  var old = document.getElementById('doc-preview-modal');
  if (old) old.remove();

  var modal = document.createElement('div');
  modal.id = 'doc-preview-modal';
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.8);z-index:10001;display:flex;flex-direction:column;padding:24px;overflow:auto';
  var kindLabelMap = {md:'📝 Markdown', pdf:'📄 PDF', docx:'📘 Word', text:'📄 Text'};
  var titleLabel = (expectedKind && kindLabelMap[expectedKind]) || '📄 文档预览';
  modal.innerHTML =
    '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px;color:white">'
    +   '<div>'
    +     '<h3 style="margin:0;font-size:16px">' + titleLabel + ' · ' + esc(title || filePath.split(/[/\\\\]/).pop()) + '</h3>'
    +     '<div style="font-size:11px;opacity:0.6;margin-top:4px;font-family:Menlo,monospace">'+esc(filePath)+'</div>'
    +   '</div>'
    +   '<button class="btn btn-sm" onclick="document.getElementById(\'doc-preview-modal\').remove()">✕ 关闭</button>'
    + '</div>'
    + '<div id="doc-preview-body" style="flex:1;background:white;border-radius:8px;padding:24px;overflow:auto;min-height:400px">正在加载…</div>';
  document.body.appendChild(modal);

  try {
    var data = await api('POST', '/api/portal/file-preview', {path: filePath});
    var body = document.getElementById('doc-preview-body');
    if (!body) return;
    if (data.kind === 'markdown') {
      // Reuse existing markdown renderer — same style as chat bubbles.
      body.innerHTML = '<div class="md-preview">' + _renderSimpleMarkdown(data.text || '', null) + '</div>';
      body.style.padding = '32px 48px';
      body.style.lineHeight = '1.7';
      body.style.color = '#1a1a1a';
    } else if (data.kind === 'text') {
      // Plain text — <pre> for monospace / wrap
      var pre = document.createElement('pre');
      pre.style.cssText = 'white-space:pre-wrap;word-break:break-word;font-family:Menlo,Monaco,monospace;font-size:12px;margin:0;color:#1a1a1a';
      pre.textContent = data.text || '';
      body.innerHTML = '';
      body.appendChild(pre);
    } else if (data.kind === 'html') {
      // Server-rendered docx HTML — trust it (we generated it ourselves).
      body.innerHTML = '<div class="docx-preview">' + data.html + '</div>';
      body.style.padding = '32px 48px';
      body.style.lineHeight = '1.6';
      body.style.color = '#1a1a1a';
    } else if (data.kind === 'iframe') {
      // PDF: browser-native viewer via iframe.
      body.style.padding = '0';
      body.innerHTML = '<iframe src="'+esc(data.url)+'" style="width:100%;height:80vh;border:0;border-radius:8px" title="'+esc(title||'pdf')+'"></iframe>';
    } else if (data.kind === 'delegate') {
      // Server asked us to route to another endpoint (e.g. pptx → previewPptxFile)
      body.innerHTML = '<div style="padding:20px">此文件类型请使用专门预览入口。</div>';
    } else if (data.kind === 'unsupported') {
      body.innerHTML = '<div style="padding:20px;color:#666">不支持的格式: <code>'+esc(data.suffix||'?')+'</code></div>';
    } else {
      body.innerHTML = '<div style="padding:20px;color:#666">返回格式异常</div>';
    }
  } catch(e) {
    var body2 = document.getElementById('doc-preview-body');
    if (body2) {
      body2.innerHTML = '<div style="color:#b91c1c;padding:20px">Load failed:'+esc(String(e))+'</div>';
    }
  }
}
window.previewFile = previewFile;

function _renderPptxLayoutRef() {
  var box = document.getElementById('pptx-layouts-ref');
  if (!box) return;
  var rows = _pptxThemeState.layouts.map(function(l){
    return '<tr>'
      + '<td style="padding:4px 10px 4px 0"><code style="font-family:Menlo,monospace;color:var(--primary)">'+esc(l.id)+'</code></td>'
      + '<td style="padding:4px 10px 4px 0;font-weight:600">'+esc(l.name_zh || l.name)+'</td>'
      + '<td style="padding:4px 0;color:var(--text2)">'+esc(l.summary||'')+'</td>'
      + '</tr>';
  }).join('');
  box.innerHTML =
    '<div style="font-weight:600;margin-bottom:6px">📐 可用版式（所有主题共享）</div>'
    + '<table style="width:100%;font-size:11px;line-height:1.6">' + rows + '</table>';
}

var _pptxRecommendTimer = null;
function _pptxRecommendDebounced() {
  clearTimeout(_pptxRecommendTimer);
  _pptxRecommendTimer = setTimeout(_pptxRecommend, 350);
}

async function _pptxRecommend() {
  var q = (document.getElementById('pptx-recommend-query') || {}).value || '';
  q = q.trim();
  var status = document.getElementById('pptx-recommend-status');
  if (!q) {
    _pptxThemeState.highlighted = {};
    _renderPptxThemeGrid();
    if (status) status.textContent = '输入关键词';
    return;
  }
  if (status) status.textContent = '正在匹配…';
  try {
    var r = await api('POST', '/api/portal/pptx-themes/recommend', {query: q, top_k: 3});
    _pptxThemeState.highlighted = {};
    (r.results || []).forEach(function(x){
      if (x.score > 0) _pptxThemeState.highlighted[x.id] = x;
    });
    _renderPptxThemeGrid();
    var hits = Object.keys(_pptxThemeState.highlighted).length;
    if (status) status.textContent = hits ? (hits + ' 个匹配') : '无关键词命中';
  } catch(e) {
    if (status) status.textContent = 'Request failed';
  }
}

function _copyPptxSnippet(themeId) {
  var snippet =
    'from pptx.util import Inches\n' +
    'from _pptx_helpers import new_deck, verify_slides\n' +
    'from _template_loader import render_from_md\n\n' +
    'prs = new_deck()\n\n' +
    '# 封面\n' +
    'render_from_md(prs, "' + themeId + '/T01_cover", params={\n' +
    '    "title": "标题",\n' +
    '    "subtitle": "副标题",\n' +
    '    "tag": "2026 Q2 | 报告",\n' +
    '})\n\n' +
    '# 3 列要点\n' +
    'render_from_md(prs, "' + themeId + '/T02_three_column", params={\n' +
    '    "title": "三大支柱",\n' +
    '    "columns": [\n' +
    '        {"icon":"users", "heading":"...", "body":"..."},\n' +
    '        {"icon":"zap",   "heading":"...", "body":"..."},\n' +
    '        {"icon":"shield","heading":"...", "body":"..."},\n' +
    '    ],\n' +
    '})\n\n' +
    '# 收尾\n' +
    'render_from_md(prs, "' + themeId + '/T19_qa_closing", params={\n' +
    '    "title": "Q & A",\n' +
    '    "cta": "核心主张",\n' +
    '    "contact": "contact@example.com",\n' +
    '})\n\n' +
    'prs.save("out.pptx")\n' +
    'verify_slides("out.pptx")\n';
  navigator.clipboard.writeText(snippet).then(function(){
    if (window._toast) window._toast('Copied ' + themeId + ' 示例代码', 'success');
    else alert('Copied ' + themeId + ' 示例代码');
  }).catch(function(e){
    alert('Copy failed:' + e);
  });
}

