function _permRenderList(admins, allAgents, allNodes) {
  var list = document.getElementById('perm-user-list');
  if (!list) return;
  var _techPmList = false;
  try { _techPmList = localStorage.getItem('tudou_theme') === 'tech'; } catch (e) {}
  if (!admins.length) {
    list.innerHTML = '<div style="padding:16px;color:var(--' + (_techPmList ? 'on-surface-variant' : 'text3') + ');text-align:center;font-size:12px">'
      + window.t('common.noData', 'No data') + '</div>';
    return;
  }
  var roleChip = function(role) {
    if (_techPmList) {
      // Tech mode — use tc-chip with role-color variants
      var cls = 'tc-chip';
      if (role === 'superAdmin') cls += ' tc-chip-primary';
      else if (role === 'admin') cls += ' tc-chip-success';
      // user → plain tc-chip
      return '<span class="' + cls + '" style="font-size:9px;padding:2px 8px;letter-spacing:0.05em">'
        + (role === 'superAdmin' ? 'SUPER' : (role === 'admin' ? 'ADMIN' : 'USER'))
        + '</span>';
    }
    var bg, fg, label;
    if (role === 'superAdmin') {
      bg = 'var(--primary-tint-15)'; fg = 'var(--primary)';
      label = 'superAdmin';
    } else if (role === 'admin') {
      bg = 'color-mix(in srgb, var(--secondary) 20%, transparent)';
      fg = 'var(--secondary)';
      label = 'admin';
    } else {
      bg = 'var(--overlay-8)'; fg = 'var(--text2)';
      label = 'user';
    }
    return '<span style="font-size:10px;padding:2px 6px;border-radius:4px;background:'
      + bg + ';color:' + fg + ';font-weight:600">' + label + '</span>';
  };
  if (_techPmList) {
    list.innerHTML = admins.map(function(a) {
      return '<div onclick="_permSelectUser(\'' + esc(a.user_id) + '\')" '
        + 'class="tc-card-clickable" '
        + 'style="padding:10px 12px;border-radius:var(--r-md);cursor:pointer;'
        + 'display:flex;align-items:center;gap:10px;margin-bottom:4px;'
        + 'background:transparent;border:1px solid transparent;transition:all 0.15s" '
        + 'onmouseenter="this.style.background=\'var(--surface-container)\';this.style.borderColor=\'var(--outline-variant)\'" '
        + 'onmouseleave="this.style.background=\'transparent\';this.style.borderColor=\'transparent\'">'
        + '<div style="width:32px;height:32px;border-radius:50%;background:var(--surface-container-high);display:flex;align-items:center;justify-content:center;flex-shrink:0">'
        +   '<span class="material-symbols-outlined" style="font-size:18px;color:var(--on-surface-variant)">account_circle</span>'
        + '</div>'
        + '<div style="flex:1;min-width:0">'
        +   '<div style="font-size:13px;font-weight:600;color:var(--on-surface);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">' + esc(a.display_name || a.username) + '</div>'
        +   '<div class="tc-mono-label" style="font-size:9px;margin-top:2px;text-transform:none">@' + esc(a.username) + '</div>'
        + '</div>'
        + roleChip(a.role)
        + '</div>';
    }).join('');
  } else {
    list.innerHTML = admins.map(function(a) {
      return '<div onclick="_permSelectUser(\'' + esc(a.user_id) + '\')" '
        + 'style="padding:10px 12px;border-radius:8px;cursor:pointer;display:flex;'
        + 'align-items:center;gap:8px;margin-bottom:4px" '
        + 'onmouseenter="this.style.background=\'var(--surface2)\'" '
        + 'onmouseleave="this.style.background=\'none\'">'
        + '<span class="material-symbols-outlined" style="font-size:20px;color:var(--text3)">account_circle</span>'
        + '<div style="flex:1;min-width:0">'
        +   '<div style="font-size:13px;font-weight:600">' + esc(a.display_name || a.username) + '</div>'
        +   '<div style="font-size:10px;color:var(--text3);margin-top:1px">' + esc(a.username) + '</div>'
        + '</div>'
        + roleChip(a.role)
        + '</div>';
    }).join('');
  }
  // Stash for the selector
  window._permAdmins = admins;
  window._permAgents = allAgents;
  window._permNodes = allNodes;
}

function _permSelectUser(uid) {
  var detail = document.getElementById('perm-detail');
  if (!detail) return;
  var a = (window._permAdmins || []).find(function(x) { return x.user_id === uid; });
  if (!a) return;
  var nodes = window._permNodes || [];
  var allAgents = window._permAgents || [];
  var delegatedNodes = new Set(a.node_ids || []);
  var isSuper = a.role === 'superAdmin';
  var isUser  = a.role === 'user';
  var isAdmin = a.role === 'admin';
  var _techPmDetail = false;
  try { _techPmDetail = localStorage.getItem('tudou_theme') === 'tech'; } catch (e) {}

  // Header (common to all three roles) — tech variant uses avatar
  // chip + role badge styling consistent with the rest of the panel.
  var header;
  if (_techPmDetail) {
    var roleBadgeCls = 'tc-chip';
    if (a.role === 'superAdmin') roleBadgeCls += ' tc-chip-primary';
    else if (a.role === 'admin') roleBadgeCls += ' tc-chip-success';
    header = ''
      + '<div style="display:flex;align-items:center;gap:14px;margin-bottom:var(--s-lg);padding-bottom:var(--s-md);border-bottom:1px solid var(--outline-variant)">'
      +   '<div style="width:48px;height:48px;border-radius:50%;background:var(--surface-container-high);display:flex;align-items:center;justify-content:center;flex-shrink:0">'
      +     '<span class="material-symbols-outlined" style="font-size:26px;color:var(--primary)">manage_accounts</span>'
      +   '</div>'
      +   '<div style="flex:1;min-width:0">'
      +     '<div style="font-family:var(--font-display);font-size:20px;font-weight:600;color:var(--on-surface);letter-spacing:-0.01em">' + esc(a.display_name || a.username) + '</div>'
      +     '<div class="tc-row-sm" style="margin-top:4px;gap:8px">'
      +       '<span class="tc-mono-label" style="font-size:10px;text-transform:none">@' + esc(a.username) + '</span>'
      +       '<span class="' + roleBadgeCls + '" style="font-size:9px;padding:2px 8px;letter-spacing:0.05em">'
      +         (a.role === 'superAdmin' ? 'SUPER' : (a.role === 'admin' ? 'ADMIN' : 'USER'))
      +       '</span>'
      +       (a.active ? '' : '<span class="tc-chip" style="font-size:9px;padding:2px 8px;color:var(--error);border-color:rgba(255,180,171,0.30)">DISABLED</span>')
      +     '</div>'
      +   '</div>'
      + '</div>';
  } else {
    header = ''
      + '<div style="display:flex;align-items:center;gap:10px;margin-bottom:16px">'
      +   '<span class="material-symbols-outlined" style="font-size:24px;color:var(--primary)">manage_accounts</span>'
      +   '<div style="flex:1">'
      +     '<div style="font-size:16px;font-weight:700">' + esc(a.display_name || a.username) + '</div>'
      +     '<div style="font-size:11px;color:var(--text3)">@' + esc(a.username) + ' · ' + esc(a.role)
      +       (a.active ? '' : ' · <span style="color:var(--error)">disabled</span>') + '</div>'
      +   '</div>'
      + '</div>';
  }

  // Role-specific body
  var body = '';
  if (isSuper) {
    body = _techPmDetail
      ? '<div class="tc-card-glass" style="padding:var(--s-md) var(--s-lg);font-size:13px;color:var(--primary);margin-bottom:var(--s-lg);border-color:rgba(192,193,255,0.30);box-shadow:0 0 12px -3px rgba(137,206,255,0.15)">'
        + '<div class="tc-row-sm" style="gap:8px">'
        +   '<span class="material-symbols-outlined" style="font-size:18px">verified_user</span>'
        +   '<span><b>superAdmin</b> — ' + window.t('perm.superNote', 'has all permissions; no delegation needed.') + '</span>'
        + '</div>'
      + '</div>'
      : '<div style="padding:10px 12px;background:var(--primary-tint-8);border-radius:8px;font-size:12px;color:var(--primary);margin-bottom:16px">'
        + '<b>superAdmin</b> ' + window.t('perm.superNote', '拥有全部权限，无需授权。')
      + '</div>';
  } else if (isUser) {
    // User: agent-level binding only. Superadmin picks a subset of agents
    // this user can USE (view + chat). Empty = has access to none.
    var delegatedAgents = new Set(a.agent_ids || []);
    var agentRows = (allAgents && allAgents.length)
      ? allAgents.map(function(ag) {
          var aid = ag.id || ag.agent_id;
          if (!aid) return '';
          var checked = delegatedAgents.has(aid) ? 'checked' : '';
          var name = ag.name || ag.display_name || aid;
          var role = ag.role || '';
          var node = ag.node_id || ag.node_name || '';
          return '<label style="display:flex;align-items:center;gap:8px;padding:4px 6px;cursor:pointer;font-size:12px">'
            + '<input type="checkbox" class="perm-agent-cb" value="' + esc(aid) + '" ' + checked + '>'
            + '<span style="flex:1">' + esc(name) + '</span>'
            + (role ? '<span style="font-size:10px;padding:1px 5px;border-radius:3px;background:var(--overlay-8);color:var(--text3)">' + esc(role) + '</span>' : '')
            + (node ? '<span style="font-size:10px;color:var(--text3)">' + esc(node) + '</span>' : '')
            + '</label>';
        }).join('')
      : '<div style="padding:8px;color:var(--text3);font-size:12px">' + window.t('common.noData', 'No data') + '</div>';
    var userNoteBox = _techPmDetail
      ? '<div class="tc-card-glass" style="padding:var(--s-md) var(--s-lg);font-size:12px;color:var(--on-surface-variant);margin-bottom:var(--s-lg)">'
        + window.t('perm.userNote', 'Users can only USE delegated agents, not manage them. Tick the agents this user is allowed to use.')
      + '</div>'
      : '<div style="padding:10px 12px;background:var(--overlay-8);border-radius:8px;font-size:12px;color:var(--text2);margin-bottom:16px">'
        + window.t('perm.userNote', 'user 只能使用被授权的 agent，不能管理。勾选允许此用户使用的 agent。')
      + '</div>';
    var userListContainerStyle = _techPmDetail
      ? 'max-height:320px;overflow-y:auto;border:1px solid var(--outline-variant);border-radius:var(--r-md);padding:6px;background:var(--surface-container-low)'
      : 'max-height:320px;overflow-y:auto;border:1px solid var(--border-light);border-radius:8px;padding:4px';
    var userBtnCls = _techPmDetail ? 'tc-btn tc-btn-ghost' : 'btn btn-ghost btn-sm';
    body = ''
      + userNoteBox
      + '<div style="margin-bottom:var(--s-lg)">'
      +   '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:6px">'
      +     '<div class="tc-mono-label" style="font-size:10px;letter-spacing:0.10em">'
      +       window.t('perm.allowedAgents', 'Allowed Agents') + ' (' + delegatedAgents.size + '/' + (allAgents || []).length + ')'
      +     '</div>'
      +     '<div style="display:flex;gap:6px">'
      +       '<button class="' + userBtnCls + '" style="font-size:11px;padding:4px 10px" onclick="_permUserToggleAll(true)">'
      +         window.t('perm.selectAll', 'Select all') + '</button>'
      +       '<button class="' + userBtnCls + '" style="font-size:11px;padding:4px 10px" onclick="_permUserToggleAll(false)">'
      +         window.t('perm.clearAll', 'Clear') + '</button>'
      +     '</div>'
      +   '</div>'
      +   '<div class="tc-text-dim" style="font-size:11px;margin-bottom:8px">'
      +     window.t('perm.userScopeHint', 'After login, users only see/use the agents ticked here.')
      +   '</div>'
      +   '<div style="' + userListContainerStyle + '">'
      +     agentRows
      +   '</div>'
      + '</div>';
  } else if (isAdmin) {
    // Admin: node delegation only (admin's agent access derives from node ownership)
    var nodeRows = nodes.length === 0
      ? '<div style="padding:8px;color:var(--text3);font-size:12px">' + window.t('common.noData', 'No data') + '</div>'
      : nodes.map(function(n) {
          var nid = n.node_id || n.id;
          var checked = delegatedNodes.has(nid) ? 'checked' : '';
          return '<label style="display:flex;align-items:center;gap:8px;padding:4px 6px;cursor:pointer;font-size:12px">'
            + '<input type="checkbox" class="perm-node-cb" value="' + esc(nid) + '" ' + checked + '>'
            + '<span style="flex:1">' + esc(n.name || nid) + '</span>'
            + '<span style="font-size:10px;color:var(--text3)">' + esc(n.url || '') + '</span>'
            + '</label>';
        }).join('');
    var adminListContainerStyle = _techPmDetail
      ? 'max-height:320px;overflow-y:auto;border:1px solid var(--outline-variant);border-radius:var(--r-md);padding:6px;background:var(--surface-container-low)'
      : 'max-height:320px;overflow-y:auto;border:1px solid var(--border-light);border-radius:8px;padding:4px';
    body = ''
      + '<div style="margin-bottom:var(--s-lg)">'
      +   '<div class="tc-mono-label" style="font-size:10px;letter-spacing:0.10em;margin-bottom:4px">'
      +     window.t('perm.delegatedNodes', 'Delegated Nodes') + ' (' + delegatedNodes.size + '/' + nodes.length + ')'
      +   '</div>'
      +   '<div class="tc-text-dim" style="font-size:11px;margin-bottom:8px">'
      +     window.t('perm.nodeScopeHint', 'admin gets full management rights over agents on delegated nodes plus those nodes\' config.')
      +   '</div>'
      +   '<div style="' + adminListContainerStyle + '">'
      +     nodeRows
      +   '</div>'
      + '</div>';
  }

  // Actions row (common: reset pw + disable/enable + delete; save for admin+user)
  var primaryBtnCls = _techPmDetail ? 'tc-btn tc-btn-primary' : 'btn btn-primary btn-sm';
  var ghostBtnCls = _techPmDetail ? 'tc-btn tc-btn-ghost' : 'btn btn-ghost btn-sm';
  var actionsRowStyle = _techPmDetail
    ? 'display:flex;gap:8px;padding-top:var(--s-md);border-top:1px solid var(--outline-variant)'
    : 'display:flex;gap:8px';
  var actions = '<div style="' + actionsRowStyle + '">'
    + ((isAdmin || isUser)
        ? '<button class="' + primaryBtnCls + '" onclick="_permSaveDelegation(\'' + esc(uid) + '\',\'' + esc(a.role) + '\')">'
          + '<span class="material-symbols-outlined" style="font-size:16px">save</span> '
          + window.t('action.save', 'Save') + '</button>'
        : '')
    + '<button class="' + ghostBtnCls + '" onclick="_permResetPassword(\'' + esc(uid) + '\')">'
    +   '<span class="material-symbols-outlined" style="font-size:16px">lock_reset</span> '
    +   window.t('perm.resetPassword', 'Reset password') + '</button>'
    + (isSuper ? '' :
        '<button class="' + ghostBtnCls + '" style="color:var(--error);margin-left:auto" onclick="_permToggleActive(\'' + esc(uid) + '\',' + (!a.active) + ')">'
        + '<span class="material-symbols-outlined" style="font-size:16px">' + (a.active ? 'block' : 'check_circle') + '</span> '
        + (a.active ? window.t('perm.disable', '禁用账号') : window.t('perm.enable', '启用账号')) + '</button>')
    + (isSuper ? '' :
        '<button class="' + ghostBtnCls + '" style="color:var(--error)" onclick="_permDeleteUser(\'' + esc(uid) + '\',\'' + esc(a.username) + '\')">'
        + '<span class="material-symbols-outlined" style="font-size:16px">delete</span> '
        + window.t('action.delete', 'Delete') + '</button>')
    + '</div>';

  detail.innerHTML = header + body + actions;
}

async function _permSaveDelegation(uid, role) {
  try {
    if (role === 'user') {
      // User-role: bind agent_ids (what agents they can USE).
      var agentIds = Array.from(document.querySelectorAll('.perm-agent-cb:checked')).map(function(x){return x.value;});
      await api('POST', '/api/portal/admins/bind', {user_id: uid, agent_ids: agentIds});
    } else {
      // Admin-role: bind node_ids (what nodes they can MANAGE;
      // agent access derives from node ownership).
      var nodeIds = Array.from(document.querySelectorAll('.perm-node-cb:checked')).map(function(x){return x.value;});
      await api('POST', '/api/portal/admins/bind-nodes', {user_id: uid, node_ids: nodeIds});
    }
    window._toast(window.t('perm.saved', '权限已更新'), 'success');
    // Refresh the whole panel so lists reflect the saved state.
    renderPermissionsPanel();
  } catch (e) {
    alert(window.t('perm.saveFailed', '保存失败') + ': ' + (e && e.message || e));
  }
}

function _permUserToggleAll(select) {
  var boxes = document.querySelectorAll('.perm-agent-cb');
  for (var i = 0; i < boxes.length; i++) boxes[i].checked = !!select;
}

// Create-user modal: opened from the "+ 新建用户" button at the top of
// the Permissions panel. Supports all three roles (superAdmin / admin /
// user). Admin-role accounts get delegated nodes afterwards via the
// detail panel (not in this modal — keeps creation simple).
function _permShowCreateUserModal() {
  var html =
    '<div style="max-width:440px">' +
      '<h3 style="margin:0 0 16px">' + window.t('perm.newUser', '新建用户') + '</h3>' +
      '<div class="form-group">' +
        '<label>' + window.t('login.username', '用户名') + '</label>' +
        '<input id="perm-new-username" placeholder="' + window.t('login.usernamePh', '输入管理员用户名') + '" />' +
      '</div>' +
      '<div class="form-group">' +
        '<label>' + window.t('agent.name', 'Name') + '</label>' +
        '<input id="perm-new-display" placeholder="" />' +
      '</div>' +
      '<div class="form-group">' +
        '<label>' + window.t('login.password', '密码') + '</label>' +
        '<input id="perm-new-password" type="password" placeholder="min 6 chars" />' +
      '</div>' +
      '<div class="form-group">' +
        '<label>' + window.t('perm.role', 'Role') + '</label>' +
        '<select id="perm-new-role" style="width:100%;padding:8px;border:1px solid var(--border);border-radius:6px;background:var(--bg);color:var(--text)">' +
          '<option value="user">user ' + window.t('perm.roleUserHint', '（只能使用 agent）') + '</option>' +
          '<option value="admin">admin ' + window.t('perm.roleAdminHint', '（管理被授权节点上的 agent 与配置）') + '</option>' +
          '<option value="superAdmin">superAdmin ' + window.t('perm.roleSuperHint', '（管理一切）') + '</option>' +
        '</select>' +
      '</div>' +
      '<div class="form-actions" style="margin-top:16px">' +
        '<button class="btn btn-ghost" onclick="closeModal()">' + window.t('action.cancel', 'Cancel') + '</button>' +
        '<button class="btn btn-primary" onclick="_permCreateUser()">' + window.t('action.create', 'New') + '</button>' +
      '</div>' +
    '</div>';
  showCustomModal(html);
}

async function _permCreateUser() {
  var username = (document.getElementById('perm-new-username') || {}).value || '';
  var password = (document.getElementById('perm-new-password') || {}).value || '';
  var display = (document.getElementById('perm-new-display') || {}).value || '';
  var role = (document.getElementById('perm-new-role') || {}).value || 'user';
  username = String(username).trim();
  password = String(password).trim();
  display = String(display).trim();
  if (!username || !password) {
    alert(window.t('perm.usernamePasswordRequired', '用户名和密码不能为空'));
    return;
  }
  if (password.length < 6) {
    alert(window.t('perm.passwordTooShort', '密码至少 6 位'));
    return;
  }
  try {
    var r = await api('POST', '/api/portal/admins/create', {
      username: username, password: password,
      display_name: display || username, role: role,
    });
    if (r && r.ok) {
      closeModal();
      window._toast(window.t('perm.userCreated', '用户已创建'), 'success');
      renderPermissionsPanel();
    } else {
      alert(window.t('perm.createFailed', 'Create failed') + ': ' + ((r && r.error) || 'unknown'));
    }
  } catch (e) {
    alert(window.t('perm.createFailed', 'Create failed') + ': ' + (e && e.message || e));
  }
}

async function _permDeleteUser(uid, username) {
  var msg = window.t('perm.confirmDelete', '确认删除用户 "{name}"？此操作不可恢复。').replace('{name}', username || uid);
  if (!confirm(msg)) return;
  try {
    var r = await api('POST', '/api/portal/admins/delete', {user_id: uid});
    if (r && r.ok) {
      window._toast(window.t('perm.userDeleted', '用户已删除'), 'success');
      renderPermissionsPanel();
    } else {
      alert(window.t('perm.deleteFailed', 'Delete failed') + ': ' + ((r && r.error) || 'unknown'));
    }
  } catch (e) {
    alert(window.t('perm.deleteFailed', 'Delete failed') + ': ' + (e && e.message || e));
  }
}

async function _permResetPassword(uid) {
  var pw = prompt(window.t('perm.resetPasswordPrompt', '输入新密码（至少 6 位）：'));
  if (!pw || pw.length < 6) return;
  try {
    await api('POST', '/api/portal/admins/update', {user_id: uid, password: pw});
    window._toast(window.t('perm.passwordReset', '密码已重置'), 'success');
  } catch (e) {
    alert(window.t('perm.saveFailed', '操作失败') + ': ' + (e && e.message || e));
  }
}

async function _permToggleActive(uid, toActive) {
  var confirmMsg = toActive
    ? window.t('perm.confirmEnable', '启用该账号？')
    : window.t('perm.confirmDisable', '禁用该账号？用户将无法登录。');
  if (!confirm(confirmMsg)) return;
  try {
    await api('POST', '/api/portal/admins/update', {user_id: uid, active: !!toActive});
    window._toast(toActive ? window.t('perm.enabled', '已启用') : window.t('perm.disabled', '已禁用'), 'success');
    renderPermissionsPanel();
  } catch (e) {
    alert(window.t('perm.saveFailed', '操作失败') + ': ' + (e && e.message || e));
  }
}

// ============ Node Switcher (topbar global) ============
var _globalNodeFilter = '';
function onNodeSwitch(nodeId) {
  _globalNodeFilter = nodeId;
  renderCurrentView();
}
function _refreshNodeSwitcher() {
  var sel = document.getElementById('global-node-switcher');
  if (!sel || !nodes) return;
  var current = sel.value;
  var html = '<option value="">所有节点</option>';
  nodes.forEach(function(n) {
    var label = (n.name || n.node_id) + (n.is_self ? ' (Local)' : '')
      + (n.project_count ? ' · ' + n.project_count + 'p' : '');
    html += '<option value="'+esc(n.node_id||'')+'">'+esc(label)+'</option>';
  });
  sel.innerHTML = html;
  if (current) sel.value = current;
}

function renderSettingsPage() {
  var c = document.getElementById('content');
  var tabs = [
    { id: 'branding',   label: window.t('tab.settings.branding',     '品牌'),          icon: 'workspaces' },
    { id: 'rules',      label: window.t('tab.settings.rules',        '规则引擎'),     icon: 'gavel' },
    { id: 'system',     label: window.t('tab.settings.system',       '系统配置'),     icon: 'tune' },
    { id: 'providers',  label: window.t('tab.settings.providers',    'LLM Providers'), icon: 'dns' },
    // RAG providers — moved here from K&M hub 2026-05-10 per user
    // direction "RAG Providers 挪到 setting 下面"
    { id: 'rag_providers', label: 'RAG Providers', icon: 'cable' },
    // 'llm_tiers' tab hidden — replaced by per-agent LLM Router
    // (extra_llms + auto_route). Tier backend still exists but no UI
    // entry. See agent settings → "额外 LLM" for routing config.
    { id: 'mcpconfig',  label: window.t('tab.settings.mcp',          'MCP'),           icon: 'hub' },
    { id: 'config',     label: window.t('tab.settings.globalConfig', 'Global Config'), icon: 'settings' },
    { id: 'nodeconfig', label: window.t('tab.settings.nodeConfig',   'Node Config'),   icon: 'tune' },
    { id: 'nodes',      label: window.t('tab.settings.nodes',        'Nodes'),         icon: 'device_hub' },
    { id: 'channels',   label: window.t('tab.settings.channels',     'Channels'),      icon: 'cable' },
    { id: 'templates',  label: window.t('tab.settings.domains',      '专业领域'),      icon: 'library_books' },
    // 'specialty_templates' tab moved to top-level "专家养成" page in
    // the left sidebar 2026-05-10. The renderSpecialtyTemplates function
    // is still exposed (called from cultivation hub's 模板库 sub-tab).
    { id: 'policy',     label: window.t('tab.settings.policy',       '审批策略'),      icon: 'shield' },
    { id: 'tokens',     label: window.t('tab.settings.apiTokens',    'API Tokens'),    icon: 'key' },
  ];

  var tabsHtml = tabs.map(function(t) {
    var active = _settingsSubTab === t.id;
    return '<button onclick="_settingsSubTab=\''+t.id+'\';renderSettingsPage()" style="padding:8px 16px;border:none;background:'+(active?'var(--surface2)':'none')+';color:'+(active?'var(--primary)':'var(--text3)')+';font-size:12px;font-weight:'+(active?'700':'500')+';cursor:pointer;border-radius:8px;display:flex;align-items:center;gap:6px;font-family:inherit;white-space:nowrap;transition:all 0.15s"><span class="material-symbols-outlined" style="font-size:16px">'+t.icon+'</span>'+t.label+'</button>';
  }).join('');

  c.innerHTML = '<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:20px;padding:8px;background:var(--surface);border-radius:12px;border:1px solid var(--border-light)">'+tabsHtml+'</div><div id="settings-content"></div>';

  var sc = document.getElementById('settings-content');
  var actionsEl = document.getElementById('topbar-actions');
  var _tabActions = {
    // 'providers' / 'nodes': button moved into the page header inside
    // renderProviders / renderNodes (matches Permissions pattern).
    'mcpconfig':  '<button class="btn btn-primary btn-sm" onclick="showAddMCP()"><span class="material-symbols-outlined" style="font-size:16px">add</span> Add MCP</button>',
    'channels':   '<button class="btn btn-primary btn-sm" onclick="showModal(\'add-channel\')"><span class="material-symbols-outlined" style="font-size:16px">add</span> Add Channel</button>',
    'tokens':     '<button class="btn btn-primary btn-sm" onclick="showModal(\'create-token\')"><span class="material-symbols-outlined" style="font-size:16px">add</span> Create Token</button>',
    'templates':  '<button class="btn btn-primary btn-sm" onclick="showCreateTemplate()"><span class="material-symbols-outlined" style="font-size:16px">add</span> New Template</button>',
  };
  if (actionsEl) actionsEl.innerHTML = _tabActions[_settingsSubTab] || '';
  switch(_settingsSubTab) {
    case 'branding': renderBrandingSettings(sc); break;
    case 'rules': renderRuleEngine(sc); break;
    case 'system': renderSystemSettings(sc); break;
    case 'providers': renderProviders(sc); break;
    case 'llm_tiers': renderLLMTiers(sc); break;
    case 'roles_v2': renderRolePresetsV2(sc); break;
    case 'mcpconfig': renderMCPConfig(sc); break;
    case 'config': renderConfig(sc); break;
    case 'nodeconfig': renderNodeConfig(sc); break;
    case 'nodes': renderNodes(sc); break;
    case 'channels': renderChannels(sc); break;
    case 'templates': renderTemplateLibrary(sc); break;
    case 'rag_providers': _renderKmRagProviders(); break;
    case 'policy': renderPolicyConfig(sc); break;
    case 'tokens': renderTokens(sc); break;
    default: sc.innerHTML = '<div style="color:var(--text3);padding:20px">Select a settings tab</div>';
  }
}

// ============ Agent 专家养成系统 — top-level hub ============
// Promoted to left-sidebar core feature 2026-05-10. Replaces the
// per-agent toolbar entry. Three tabs:
//   1. 我的专家 — cultivated agents, click → per-agent pipeline drill
//   2. 模板库   — specialty templates (create / list / delete)
//   3. 待养成   — uncultivated agents, click → pick a template to start
//
// Click a 段位条 chip in any agent's chat header → navigates here with
// that agent pre-selected for the pipeline drill.
let _cultHubTab = 'cultivated';   // 'cultivated' | 'templates' | 'uncultivated'

async function renderCultivationHub(container) {
  var c = container || document.getElementById('content');
  c.innerHTML = '<div style="color:var(--text3);padding:20px">加载养成系统…</div>';

  var tabs = [
    { id: 'cultivated',   icon: 'school',          label: '我的专家' },
    { id: 'templates',    icon: 'menu_book',       label: '模板库' },
    // Merged from K&M hub 2026-05-10 per user direction:
    //   "1 (Knowledge Bases) 融合养成里面" + "3 (Wiki) 是否也可以融合"
    { id: 'knowledge',    icon: 'database',        label: '知识库' },
    { id: 'wiki',         icon: 'auto_stories',    label: 'Wiki / 经验库' },
    { id: 'uncultivated', icon: 'add_circle',      label: '待养成' },
  ];

  function tabBtn(t) {
    var active = _cultHubTab === t.id;
    return '<button onclick="_cultHubTab=\'' + t.id + '\';renderCultivationHub()" '
      + 'style="padding:8px 16px;border:none;background:' + (active ? 'var(--surface2)' : 'none') + ';'
      + 'color:' + (active ? 'var(--cyber-magenta,#ff7adb)' : 'var(--text3)') + ';'
      + 'font-size:12px;font-weight:' + (active ? '700' : '500') + ';cursor:pointer;'
      + 'border-radius:8px;display:inline-flex;align-items:center;gap:6px;'
      + 'font-family:inherit;white-space:nowrap;transition:all 0.15s">'
      + '<span class="material-symbols-outlined" style="font-size:16px">' + t.icon + '</span>'
      + esc(t.label) + '</button>';
  }

  // Header + tabs
  c.innerHTML = ''
    + '<div style="margin-bottom:18px;padding:18px 22px;background:linear-gradient(135deg,'
    +     'rgba(255,122,219,0.08) 0%,rgba(74,252,255,0.06) 100%);'
    +     'border:1px solid rgba(255,122,219,0.25);border-radius:12px">'
    + '  <div style="display:flex;align-items:center;gap:12px;margin-bottom:6px">'
    + '    <span class="material-symbols-outlined" '
    +         'style="font-size:28px;color:var(--cyber-magenta,#ff7adb)">school</span>'
    + '    <span style="font-size:18px;font-weight:600">Agent 专家养成系统</span>'
    + '  </div>'
    + '  <div style="font-size:12px;color:var(--text3);line-height:1.6;max-width:760px">'
    +     '把通用 agent 养成某领域专家:选模板 → 装 packs/skills → 喂语料 → 用真实问答累积反馈 →'
    +     '准确率达标自动推进段位(见习/熟手/专家/大师)。后期可触发 LoRA 训练把答题质量沉淀进权重。'
    + '  </div>'
    + '</div>'
    + '<div style="display:flex;gap:6px;margin-bottom:18px;padding:6px;background:var(--surface);'
    +     'border-radius:10px;border:1px solid var(--border-light);width:fit-content">'
    +     tabs.map(tabBtn).join('')
    + '</div>'
    + '<div id="cult-hub-body"></div>';

  var body = document.getElementById('cult-hub-body');
  // Merged-in renderers from K&M hub look for different container ids
  // depending on theme:
  //   legacy → document.getElementById('km-content')
  //   tech   → document.getElementById('tech-hub-km-body') THEN
  //            falls back to document.getElementById('content') ←
  //            this fallback was nuking the whole hub (tabs gone).
  // Bridge: rename the hub's body to whichever id the renderer wants.
  // Since renderCultivationHub() rebuilds #content from scratch on
  // every tab switch, we don't need to restore the id — it'll come
  // back as 'cult-hub-body' next time the user switches tabs.
  function _withKmContainer(fn) {
    var isTech = false;
    try { isTech = localStorage.getItem('tudou_theme') === 'tech'; } catch (e) {}
    body.id = isTech ? 'tech-hub-km-body' : 'km-content';
    fn();
  }
  if (_cultHubTab === 'cultivated')        await _cultHubRenderCultivated(body);
  else if (_cultHubTab === 'templates')    renderSpecialtyTemplates(body);
  else if (_cultHubTab === 'uncultivated') await _cultHubRenderUncultivated(body);
  else if (_cultHubTab === 'knowledge')    _withKmContainer(function(){ _renderKmPrivate(); });
  else if (_cultHubTab === 'wiki')         _withKmContainer(function(){ _renderKmWiki(); });
}
window.renderCultivationHub = renderCultivationHub;

async function _cultHubRenderCultivated(body) {
  body.innerHTML = '<div style="color:var(--text3);padding:14px">加载…</div>';
  // Pull all agents + filter to cultivated
  var allAgents = (typeof agents !== 'undefined' && agents) || [];
  var cultivated = allAgents.filter(function(a){ return !!a.expert_specialty; });
  if (cultivated.length === 0) {
    body.innerHTML = ''
      + '<div style="padding:40px;text-align:center;background:var(--surface);'
      +     'border:1px dashed var(--border);border-radius:10px;color:var(--text3)">'
      + '  <div style="font-size:32px;margin-bottom:8px">🌱</div>'
      + '  <div style="font-size:13px">尚无已养成的专家 agent</div>'
      + '  <div style="font-size:11px;margin-top:6px">'
      +     '切到「待养成」tab 选一个 agent + 模板开始'
      + '  </div></div>';
    return;
  }
  // Fetch /stats per agent in parallel for level computation
  var stats = await Promise.all(cultivated.map(function(a){
    return api('GET', '/api/portal/agent/' + a.id + '/expert/stats')
      .catch(function(){ return null; });
  }));
  var rows = '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(360px,1fr));gap:14px">';
  cultivated.forEach(function(a, i) {
    var s = stats[i] || {};
    var levelKey = (typeof _cultLevelFromStats === 'function')
      ? _cultLevelFromStats(s) : 'novice';
    var lvl = (typeof _cultLevelMeta === 'function') ? _cultLevelMeta(levelKey)
              : { label: '🌱 见习', pct: 25, color: 'var(--cyber-blue,#4afcff)' };
    var fbTotal = (s.feedback_counts && (s.feedback_counts.up + s.feedback_counts.down)) || 0;
    var fbUp = (s.feedback_counts && s.feedback_counts.up) || 0;
    var posPct = fbTotal > 0 ? Math.round((fbUp / fbTotal) * 100) : 0;
    rows += ''
      + '<div style="background:var(--surface);border:1px solid ' + lvl.color + ';border-radius:10px;'
      +     'padding:16px;display:flex;flex-direction:column;gap:10px">'
      + '  <div style="display:flex;align-items:center;gap:10px">'
      + '    <span style="font-size:24px">' + (lvl.label || '🌱').split(' ')[0] + '</span>'
      + '    <div style="flex:1;min-width:0">'
      + '      <div style="font-size:13px;font-weight:600">' + esc(a.name) + '</div>'
      + '      <div style="font-size:10px;color:var(--text3);font-family:var(--font-mono,monospace)">'
      +         esc(a.expert_specialty) + ' · ' + esc(a.expert_level || 'novice') + '</div>'
      + '    </div>'
      + '    <span style="color:' + lvl.color + ';font-weight:600;font-size:12px">' + lvl.pct + '%</span>'
      + '  </div>'
      + '  <div style="height:5px;background:rgba(255,255,255,0.08);border-radius:3px;overflow:hidden">'
      + '    <div style="height:100%;width:' + lvl.pct + '%;background:' + lvl.color + '"></div>'
      + '  </div>'
      + '  <div style="font-size:11px;color:var(--text2);font-family:var(--font-mono,monospace);display:flex;gap:14px">'
      + '    <span>👍 ' + fbUp + ' / 👎 ' + (fbTotal - fbUp) + '</span>'
      + '    <span>' + (fbTotal > 0 ? (posPct + '% 准确率') : '尚无评分') + '</span>'
      + '    <span style="margin-left:auto">trace: ' + (s.trace_count || 0) + '</span>'
      + '  </div>'
      + '  <div style="display:flex;gap:8px;border-top:1px solid var(--overlay-5);padding-top:10px;margin-top:auto">'
      + '    <button class="btn btn-sm" onclick="openCultivationModal(\'' + esc(a.id) + '\')" '
      +         'style="font-size:11px;flex:1">'
      +         '<span class="material-symbols-outlined" style="font-size:14px;vertical-align:middle">timeline</span> Pipeline</button>'
      + '    <button class="btn btn-sm btn-ghost" onclick="showAgentView(\'' + esc(a.id) + '\')" '
      +         'style="font-size:11px"><span class="material-symbols-outlined" style="font-size:14px">chat</span></button>'
      + '  </div>'
      + '</div>';
  });
  rows += '</div>';
  body.innerHTML = rows;
}

async function _cultHubRenderUncultivated(body) {
  body.innerHTML = ''
    + '<div class="tc-mono-label" style="color:var(--outline);padding:14px;letter-spacing:0.05em">'
    + 'LOADING…</div>';
  var allAgents = (typeof agents !== 'undefined' && agents) || [];
  var uncultivated = allAgents.filter(function(a){ return !a.expert_specialty; });

  // Header — tech-style mono-label + status dot, matches cultivated tab
  var headerHtml = ''
    + '<div style="display:flex;justify-content:space-between;align-items:center;'
    +     'margin-bottom:18px;flex-wrap:wrap;gap:12px">'
    + '  <div>'
    + '    <div class="tc-mono-label" style="color:var(--primary);display:flex;'
    +         'align-items:center;gap:8px;font-size:11px;letter-spacing:0.05em">'
    + '      <span>UNCULTIVATED AGENTS</span>'
    + '      <span style="width:6px;height:6px;border-radius:50%;background:var(--outline);'
    +             'animation:pulse-dot 2s infinite ease-in-out"></span>'
    + '    </div>'
    + '    <div style="font-size:12px;color:var(--text3);margin-top:6px;line-height:1.55">'
    +     'Generic agents — pick a specialty template to start cultivation. '
    +     'Cultivation makes them experts in a domain through prompt packs / '
    +     'corpus / RAG / LoRA pipeline.'
    + '    </div>'
    + '  </div>'
    + '  <div class="tc-mono-label" style="color:var(--outline);font-size:10px">'
    +     uncultivated.length + ' AVAILABLE'
    + '  </div>'
    + '</div>';

  if (uncultivated.length === 0) {
    body.innerHTML = headerHtml
      + '<div class="tc-card tc-text-dim" style="text-align:center;padding:60px 20px;border-style:dashed">'
      +   '<span class="material-symbols-outlined" style="font-size:48px;color:var(--outline)">verified</span>'
      +   '<div style="font-size:14px;color:var(--on-surface-variant);margin-top:14px;margin-bottom:8px">所有 agent 都已养成</div>'
      +   '<div class="tc-text-dim" style="font-size:12px;line-height:1.55">'
      +     'Switch to "我的专家" tab to inspect their pipelines, or use Templates to create a new specialty.'
      +   '</div>'
      + '</div>';
    return;
  }

  // Tech-style cards — glass surface + mono-label sections + uppercase
  // accent. Avatar uses agent.robot_avatar if available, else 'smart_toy'.
  var cards = uncultivated.map(function(a) {
    var avatar = (typeof _robotIconUrl === 'function' && a.robot_avatar)
      ? '<img src="' + _robotIconUrl(a.robot_avatar) + '" '
        + 'style="width:36px;height:36px;border-radius:8px;object-fit:cover" '
        + 'onerror="this.outerHTML=\'<span class=&quot;material-symbols-outlined&quot; style=&quot;font-size:24px;color:var(--primary)&quot;>memory</span>\'">'
      : '<span class="material-symbols-outlined" style="font-size:24px;color:var(--primary)">memory</span>';
    return ''
      + '<div class="tc-card" style="display:flex;flex-direction:column;gap:12px;padding:18px;'
      +     'background:var(--surface);border:1px solid var(--outline-variant);border-radius:var(--r-lg,12px);'
      +     'transition:border-color 0.15s,transform 0.1s" '
      +     'onmouseover="this.style.borderColor=\'var(--secondary)\';this.style.transform=\'translateY(-1px)\'" '
      +     'onmouseout="this.style.borderColor=\'var(--outline-variant)\';this.style.transform=\'\'">'
      // Avatar + name row
      + '  <div style="display:flex;align-items:center;gap:12px">'
      + '    <div style="width:42px;height:42px;border-radius:8px;background:rgba(192,193,255,0.08);'
      +         'border:1px solid var(--outline-variant);display:flex;align-items:center;justify-content:center">'
      +         avatar
      + '    </div>'
      + '    <div style="flex:1;min-width:0">'
      + '      <div style="font-size:14px;font-weight:600;color:var(--on-surface)">'
      +         esc(a.name) + '</div>'
      + '      <div class="tc-mono-label" style="font-size:9px;color:var(--outline);'
      +         'letter-spacing:0.05em;margin-top:2px">'
      +         esc((a.role || 'GENERAL').toUpperCase()) + ' · GENERIC AGENT'
      + '      </div>'
      + '    </div>'
      + '    <span class="tc-mono-label" style="padding:2px 7px;border-radius:4px;'
      +       'background:rgba(192,193,255,0.10);color:var(--outline);font-size:9px;'
      +       'border:1px solid rgba(192,193,255,0.20);letter-spacing:0.05em">UNTRAINED</span>'
      + '  </div>'
      // Spec section — what cultivation will give this agent
      + '  <div style="padding:10px 12px;background:rgba(255,122,219,0.04);'
      +       'border:1px solid rgba(255,122,219,0.20);border-radius:6px">'
      + '    <div class="tc-mono-label" style="font-size:9px;color:var(--cyber-magenta,#ff7adb);'
      +         'letter-spacing:0.05em;margin-bottom:6px">CULTIVATION TARGET</div>'
      + '    <div style="font-size:11px;color:var(--text2);line-height:1.55">'
      +       'pick a specialty → bind packs/skills → ingest corpus → '
      +       'agent answers grounded in domain knowledge'
      + '    </div>'
      + '  </div>'
      // Action — uses tc-btn-primary look
      + '  <button class="tc-btn tc-btn-primary tc-btn-sm" '
      +         'onclick="openCultivationModal(\'' + esc(a.id) + '\')" '
      +         'style="background:var(--cyber-magenta,#ff7adb);'
      +         'border:1px solid var(--cyber-magenta,#ff7adb);color:#000;'
      +         'font-family:var(--font-mono,monospace);font-size:11px;'
      +         'letter-spacing:0.05em;text-transform:uppercase;font-weight:600">'
      + '    <span class="material-symbols-outlined" style="font-size:14px">school</span>'
      + '    START CULTIVATION'
      + '  </button>'
      + '</div>';
  }).join('');

  body.innerHTML = headerHtml
    + '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(360px,1fr));gap:14px">'
    + cards
    + '</div>';
}

// ============ Specialty Templates (养成模板) ============
// Lists / creates / deletes the YAML templates that drive specialty
// cultivation. Lives in System Settings → 养成模板. Per-template UI is
// the cultivation modal (separate); this is the catalog admin view.
async function renderSpecialtyTemplates(container) {
  var c = container || document.getElementById('content');
  c.innerHTML = '<div style="color:var(--text3);padding:20px">加载养成模板…</div>';
  try {
    var data = await api('GET', '/api/portal/specialty-templates');
    var templates = (data && data.templates) || [];
    // Existing templates grid + a card-style "+" add affordance at the
    // end. User direction (2026-05-10): "所有的添加按钮,做成卡片示添加".
    // Pattern matches the Worker Nodes "+ CONNECT NODE" dashed card.
    var addCard = ''
      + '<div onclick="showCreateSpecialtyTemplate()" '
      +      'onmouseover="this.style.borderColor=\'rgba(255,122,219,0.50)\';this.style.background=\'rgba(255,122,219,0.05)\'" '
      +      'onmouseout="this.style.borderColor=\'\';this.style.background=\'transparent\'" '
      +      'style="display:flex;flex-direction:column;align-items:center;justify-content:center;'
      +             'gap:10px;min-height:200px;border:2px dashed rgba(255,122,219,0.30);'
      +             'border-radius:10px;background:transparent;cursor:pointer;'
      +             'transition:all 0.18s;padding:18px;text-align:center">'
      + '  <div style="width:42px;height:42px;border-radius:9999px;background:rgba(255,122,219,0.10);'
      +       'border:1px solid rgba(255,122,219,0.40);'
      +       'display:flex;align-items:center;justify-content:center">'
      + '    <span class="material-symbols-outlined" style="color:var(--cyber-magenta,#ff7adb);font-size:22px">add</span>'
      + '  </div>'
      + '  <div style="color:var(--cyber-magenta,#ff7adb);font-size:12px;font-weight:600;'
      +       'text-transform:uppercase;letter-spacing:0.05em">新建养成模板</div>'
      + '  <div style="color:var(--text3);font-size:11px;line-height:1.5;max-width:220px">'
      +       '定义一个新专家"配方":需要哪些 prompt packs / skills / 知识库 / 训练参数</div>'
      + '</div>';

    var rows = '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:14px">';
    templates.forEach(function(t){
      var iconHtml = (typeof _cultIconHTML === 'function')
        ? _cultIconHTML(t.icon, 28)
        : esc(t.icon || '🎓');
      rows += '<div style="background:var(--surface);border:1px solid var(--border);'
        +     'border-radius:10px;padding:18px;display:flex;flex-direction:column;gap:10px">'
        + '  <div style="display:flex;align-items:center;gap:12px">'
        + '    <div style="width:42px;height:42px;background:rgba(255,122,219,0.1);'
        +       'border:1px solid rgba(255,122,219,0.4);border-radius:10px;'
        +       'display:flex;align-items:center;justify-content:center;color:var(--cyber-magenta,#ff7adb);font-size:20px">'
        +       iconHtml + '</div>'
        + '    <div style="flex:1;min-width:0">'
        + '      <div style="font-size:14px;font-weight:600">' + esc(t.name) + '</div>'
        + '      <div style="font-size:10px;color:var(--text3);font-family:var(--font-mono,monospace);margin-top:2px">'
        +         esc(t.id) + ' · ' + esc(t.specialty) + ' · v' + esc(t.version) + '</div>'
        + '    </div>'
        + '  </div>'
        + '  <div style="font-size:12px;color:var(--text2);line-height:1.55;flex:1;min-height:36px">'
        +       esc(t.description || '(no description)') + '</div>'
        + '  <div style="display:flex;gap:6px;flex-wrap:wrap;font-size:10px;color:var(--text3);font-family:var(--font-mono,monospace)">'
        + '    <span title="prompt packs">📝 ' + (t.required_packs_count || 0) + ' packs</span>'
        + '    <span title="skills">🛠 ' + (t.required_skills_count || 0) + ' skills</span>'
        + '    <span title="levels">🎯 ' + (t.level_count || 0) + ' levels</span>'
        + '  </div>'
        + '  <div style="display:flex;gap:6px;border-top:1px solid var(--overlay-5);padding-top:12px">'
        + '    <button class="btn btn-sm btn-ghost" onclick="_specTemplateView(\'' + esc(t.id) + '\')" '
        +         'style="font-size:11px"><span class="material-symbols-outlined" style="font-size:14px">visibility</span> 查看</button>'
        + '    <button class="btn btn-sm btn-ghost" onclick="_specTemplateEdit(\'' + esc(t.id) + '\')" '
        +         'style="font-size:11px"><span class="material-symbols-outlined" style="font-size:14px">edit</span> 编辑</button>'
        + '    <button class="btn btn-sm btn-ghost" '
        +         'onclick="_specTemplateDelete(\'' + esc(t.id) + '\',\'' + esc(t.name) + '\')" '
        +         'style="font-size:11px;margin-left:auto;color:var(--error)">'
        +         '<span class="material-symbols-outlined" style="font-size:14px">delete</span> 删除</button>'
        + '  </div>'
        + '</div>';
    });
    rows += addCard + '</div>';
    c.innerHTML = ''
      + '<div style="margin-bottom:16px;padding:14px 18px;background:rgba(255,122,219,0.04);'
      +     'border:1px solid rgba(255,122,219,0.20);border-radius:8px">'
      + '  <div style="display:flex;align-items:center;gap:8px;margin-bottom:6px">'
      + '    <span class="material-symbols-outlined" style="color:var(--cyber-magenta,#ff7adb)">school</span>'
      + '    <span style="font-size:13px;font-weight:600">专家养成模板</span>'
      + '    <span style="margin-left:auto;color:var(--text3);font-size:11px">总计 ' + templates.length + ' 个</span>'
      + '  </div>'
      + '  <div style="font-size:11px;color:var(--text3);line-height:1.6">'
      +     '模板 = 把一个 agent 培育成某领域专家的"配方":定义需要哪些 prompt packs / skills / 知识库 / 评测 / 训练参数。'
      +     '<br>YAML 存放在 <code>app/data/specialty_templates/&lt;id&gt;.yaml</code>,可手工编辑或用此处的 [新建] 按钮生成。'
      + '  </div>'
      + '</div>'
      + rows;
  } catch (e) {
    c.innerHTML = '<div style="color:var(--error);padding:20px">加载失败: ' + esc(e.message || String(e)) + '</div>';
  }
}
window.renderSpecialtyTemplates = renderSpecialtyTemplates;

function _specTemplateView(id) {
  api('GET', '/api/portal/specialty-templates/' + encodeURIComponent(id))
    .then(function(t){
      var yamlPreview = JSON.stringify(t, null, 2);
      showModalHTMLLarge(
        '<div style="width:780px;max-width:92vw;max-height:85vh;overflow-y:auto;'
        +     'background:var(--surface);border-radius:12px;padding:0">'
        + '  <div style="padding:14px 20px;border-bottom:1px solid var(--border-light);'
        +       'display:flex;justify-content:space-between;align-items:center">'
        + '    <div style="font-size:14px;font-weight:600">'
        +       '<span class="material-symbols-outlined" style="vertical-align:middle;color:var(--cyber-magenta,#ff7adb)">visibility</span> '
        +       esc(t.name) + ' <span style="font-size:11px;color:var(--text3);font-family:var(--font-mono,monospace)">' + esc(t.id) + '</span></div>'
        + '    <button class="btn btn-sm btn-ghost" onclick="closeModal()" style="padding:4px 10px">'
        +       '<span class="material-symbols-outlined" style="font-size:16px">close</span></button>'
        + '  </div>'
        + '  <pre style="margin:0;padding:18px 20px;font-family:var(--font-mono,monospace);font-size:11px;'
        +       'color:var(--text2);background:var(--bg);overflow-x:auto;line-height:1.5">'
        +       esc(yamlPreview) + '</pre>'
        + '</div>'
      );
    })
    .catch(function(e){ alert('加载失败: ' + (e.message || e)); });
}
window._specTemplateView = _specTemplateView;

function _specTemplateDelete(id, name) {
  if (!confirm('确定删除模板 "' + name + '" (' + id + ') ?\n\n此操作不可撤销。')) return;
  api('DELETE', '/api/portal/specialty-templates/' + encodeURIComponent(id))
    .then(function(r){
      if (typeof _toast === 'function') _toast('已删除: ' + id, 'success');
      renderSpecialtyTemplates();
    })
    .catch(function(e){ alert('删除失败: ' + (e.message || e)); });
}
window._specTemplateDelete = _specTemplateDelete;

// Edit existing template: fetch + open the same modal, pre-filled.
// Submit goes through PUT instead of POST. We track the mode via
// window._specEditingId — _specTemplateSubmit reads it.
function _specTemplateEdit(id) {
  api('GET', '/api/portal/specialty-templates/' + encodeURIComponent(id))
    .then(function(t){
      window._specEditingId = id;
      showCreateSpecialtyTemplate();   // builds the form
      // Wait one tick so the form DOM exists, then prefill
      setTimeout(function(){
        function set(key, val) {
          var el = document.getElementById('ct-spec-' + key);
          if (el) el.value = val == null ? '' : String(val);
        }
        set('id',          t.id);
        set('specialty',   t.specialty);
        set('name',        t.name);
        set('icon',        t.icon || '');
        set('version',     t.version || '1.0');
        set('description', t.description || '');
        set('required-packs',           (t.required_packs || []).join(', '));
        set('required-anthropic-packs', (t.required_anthropic_packs || []).join(', '));
        set('required-skills',          (t.required_skills || []).join(', '));
        // Update header to indicate edit mode
        var header = document.querySelector('#modal-overlay .material-symbols-outlined + span, '
                                          + '#modal-overlay span:first-child + span');
        // Find the modal title element by content text "新建专家养成模板" → "编辑"
        var titles = document.querySelectorAll('#modal-overlay div');
        titles.forEach(function(el){
          if (el.textContent && el.textContent.indexOf('新建专家养成模板') >= 0) {
            el.innerHTML = el.innerHTML.replace('新建专家养成模板', '编辑专家养成模板 · ' + esc(id));
          }
        });
        // Submit button label
        var btn = document.querySelector('#modal-overlay button[onclick="_specTemplateSubmit()"]');
        if (btn) btn.innerHTML = '✏️ 保存修改';
        // Lock id field (filename change is messy across mid-edit)
        var idEl = document.getElementById('ct-spec-id');
        if (idEl) {
          idEl.readOnly = true;
          idEl.style.opacity = '0.6';
          idEl.title = '编辑模式下不能改 id (文件名)';
        }
      }, 30);
    })
    .catch(function(e){ alert('加载失败: ' + (e.message || e)); });
}
window._specTemplateEdit = _specTemplateEdit;

